'use strict';
// Adapted UniTools World Recipes v2.0.0. CC BY-SA 4.0; see data/meal-recipes-source.md.
(function(root){const recipes=[{"id":"ut-spaghetti-carbonara","name":"Спагетти карбонара","country":"Италия","category":"main","diets":[],"slots":["lunch","dinner"],"time":25,"baseServings":2,"portionNutrition":{"k":690,"p":32,"f":34,"c":62},"details":[{"name":"Спагетти","quantity":200,"unit":"g","note":""},{"name":"Гуанчале","quantity":100,"unit":"g","note":"нарезать брусочками; можно панчетту"},{"name":"Яичные желтки","quantity":3,"unit":"piece","note":""},{"name":"Яйцо целиком","quantity":1,"unit":"piece","note":""},{"name":"Пекорино романо","quantity":60,"unit":"g","note":"натереть мелко"},{"name":"Чёрный перец","quantity":1,"unit":"tsp","note":"крупного помола"},{"name":"Соль для воды","quantity":null,"unit":"toTaste","note":""}],"steps":"Поставьте кастрюлю с водой на сильный огонь и посолите её как следует — это единственная соль в блюде, сыр и гуанчале солёные сами по себе.\nВыложите гуанчале на холодную сковороду и включите средний огонь. Жир должен вытопиться постепенно, а кусочки — стать золотистыми и хрустящими по краям, минут за 6–8.\nПока топится жир, разотрите желтки, целое яйцо, тёртый пекорино и перец в густую пасту. Она должна быть комнатной температуры, иначе свернётся от горячей пасты.\nОтварите спагетти на минуту меньше, чем написано на упаковке. Перед тем как сливать, отлейте стакан воды от варки — без неё соус не соберётся.\nСнимите сковороду с огня, переложите в неё пасту и перемешайте с жиром. Дайте сковороде остыть секунд двадцать: она должна быть тёплой, а не горячей.\nВлейте яичную смесь и энергично мешайте, подливая воду от пасты по ложке, пока соус не станет гладким и не обволочёт каждую нить. Подавайте сразу.","source":"UniTools"},{"id":"ut-risotto-alla-milanese","name":"Ризотто по-милански","country":"Италия","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":560,"p":15,"f":22,"c":71},"details":[{"name":"Рис карнароли","quantity":320,"unit":"g","note":""},{"name":"Бульон","quantity":1.2,"unit":"l","note":"горячий"},{"name":"Лук","quantity":1,"unit":"piece","note":"мелко нарезать"},{"name":"Сухое белое вино","quantity":120,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":"холодное"},{"name":"Пармезан","quantity":80,"unit":"g","note":"натереть"},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте шафран половником горячего бульона и оставьте настаиваться. Остальной бульон держите на слабом огне: холодный бульон останавливает варку.\nРастопите половину масла и потомите лук на слабом огне до мягкости и прозрачности, не давая ему подрумяниться, минут восемь.\nВсыпьте рис и мешайте пару минут, пока зёрна не станут по краям прозрачными, а в середине — молочно-белыми. Это тостатура, она держит форму зерна.\nВлейте вино и дайте ему полностью выпариться — запах спирта должен уйти.\nПодливайте бульон по половнику, помешивая, и ждите, пока рис почти впитает его перед следующим. Так минут восемнадцать, пока зерно не станет мягким снаружи и чуть упругим внутри.\nВлейте шафрановый настой, снимите с огня и вбейте холодное масло с пармезаном, энергично встряхивая сковороду. Ризотто должно медленно растекаться по тарелке.","source":"UniTools"},{"id":"ut-ratatouille","name":"Рататуй","country":"Франция","category":"main","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":65,"baseServings":4,"portionNutrition":{"k":240,"p":5,"f":16,"c":20},"details":[{"name":"Баклажан","quantity":1,"unit":"piece","note":"кубиками 2 см"},{"name":"Кабачок","quantity":2,"unit":"piece","note":"кубиками"},{"name":"Сладкий перец","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":600,"unit":"g","note":"спелые, очистить"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Оливковое масло","quantity":6,"unit":"tbsp","note":""},{"name":"Тимьян","quantity":3,"unit":"sprig","note":""},{"name":"Базилик","quantity":1,"unit":"pinch","note":"в конце"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте баклажан на сильном огне в двух ложках масла до румяных граней и отложите. Баклажан впитывает масло мгновенно — не добавляйте ещё, он отдаст его обратно.\nВ той же сковороде обжарьте кабачок до золотистого цвета, минуты четыре, и отложите к баклажану. Он должен остаться упругим.\nОбжарьте перец до мягкости и лёгких подпалин и тоже отложите.\nНа оставшемся масле потомите лук до мягкости, добавьте чеснок и тимьян и держите на огне полминуты, до запаха.\nПоложите помидоры и уваривайте на среднем огне до густого соуса, минут двадцать. Он должен держаться на ложке, а не стекать.\nВерните овощи в сковороду, посолите и прогрейте вместе десять минут на слабом огне. Снимите с огня, добавьте базилик и дайте постоять — рататуй вкуснее тёплым, чем горячим.","source":"UniTools"},{"id":"ut-french-onion-soup","name":"Луковый суп","country":"Франция","category":"soup","diets":[],"slots":["lunch","dinner"],"time":75,"baseServings":4,"portionNutrition":{"k":430,"p":17,"f":21,"c":40},"details":[{"name":"Лук","quantity":1,"unit":"kg","note":"тонкими полукольцами"},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Мука","quantity":1,"unit":"tbsp","note":""},{"name":"Сухое белое вино","quantity":150,"unit":"ml","note":""},{"name":"Говяжий бульон","quantity":1.2,"unit":"l","note":""},{"name":"Багет","quantity":8,"unit":"slice","note":"подсушить"},{"name":"Грюйер","quantity":150,"unit":"g","note":"натереть"},{"name":"Тимьян","quantity":2,"unit":"sprig","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Растопите масло в толстостенной кастрюле, положите лук и щепотку соли и держите на среднем огне, помешивая каждые несколько минут. Первые двадцать минут лук будет отдавать воду.\nДальше начинается собственно карамелизация: лук темнеет до цвета крепкого чая ещё за двадцать пять минут. Если начинает пригорать — убавьте огонь и подлейте ложку воды.\nВсыпьте муку и прогрейте пару минут, чтобы ушёл сырой привкус.\nВлейте вино и соскребите лопаткой всё, что прилипло ко дну. Дайте выпариться наполовину.\nДобавьте бульон и тимьян, доведите до кипения и варите на слабом огне двадцать минут. Посолите и поперчите в конце — бульон мог быть солёным.\nРазлейте по жаропрочным мискам, положите сверху ломтик багета, засыпьте сыром и поставьте под гриль до пузырящейся корочки, минуты на три.","source":"UniTools"},{"id":"ut-borscht","name":"Борщ","country":"Россия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":320,"p":18,"f":14,"c":30},"details":[{"name":"Говядина на кости","quantity":700,"unit":"g","note":""},{"name":"Свёкла","quantity":2,"unit":"piece","note":"натереть соломкой"},{"name":"Капуста","quantity":300,"unit":"g","note":"нашинковать"},{"name":"Картофель","quantity":4,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Уксус 9 %","quantity":1,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Сметана","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте мясо холодной водой, доведите до кипения и снимите пену. Варите на слабом огне полтора часа: бульон должен едва подрагивать, иначе он помутнеет.\nТушите свёклу на сковороде с ложкой масла, томатной пастой и уксусом минут двадцать под крышкой. Именно уксус здесь и сохраняет цвет.\nОтдельно обжарьте лук с морковью до мягкости и золотистого цвета.\nДостаньте мясо, разберите на куски и верните в бульон. Заложите картофель и варите десять минут — до того, как в кастрюлю попадёт кислота.\nДобавьте капусту, через пять минут — свёклу и зажарку. Проварите ещё пять минут, положите лавровый лист и чеснок и сразу снимите с огня.\nДайте настояться под крышкой хотя бы двадцать минут. Подавайте со сметаной — она смягчает кислоту и связывает вкус.","source":"UniTools"},{"id":"ut-khachapuri-imeruli","name":"Хачапури имеретинский","country":"Грузия","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":110,"baseServings":4,"portionNutrition":{"k":620,"p":28,"f":30,"c":58},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Мацони или кефир","quantity":200,"unit":"ml","note":"комнатной температуры"},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":"растопить"},{"name":"Сухие дрожжи","quantity":1,"unit":"tsp","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""},{"name":"Сулугуни","quantity":250,"unit":"g","note":"натереть"},{"name":"Адыгейский сыр","quantity":250,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Разведите дрожжи с сахаром в тёплом мацони и оставьте на десять минут до пены. Если пены нет, дрожжи мёртвые — начинайте заново.\nДобавьте яйцо, растопленное масло, соль и муку. Вымесите мягкое тесто: оно должно чуть липнуть к рукам, муки больше не добавляйте.\nНакройте и оставьте в тепле на час — тесто должно вырасти вдвое.\nСмешайте оба сыра руками в однородную массу и разделите на четыре шара. Тесто тоже разделите на четыре.\nРаскатайте каждый кусок теста в лепёшку, положите шар сыра в центр, соберите края к середине и защипните. Переверните швом вниз и аккуратно раскатайте до толщины сантиметр.\nЖарьте на сухой сковороде на среднем огне по четыре минуты с каждой стороны, до тёмных пятен. Готовый хачапури смажьте сливочным маслом.","source":"UniTools"},{"id":"ut-miso-soup","name":"Мисо-суп","country":"Япония","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":20,"baseServings":4,"portionNutrition":{"k":110,"p":9,"f":4,"c":8},"details":[{"name":"Вода","quantity":800,"unit":"ml","note":""},{"name":"Комбу","quantity":10,"unit":"g","note":"не мыть, протереть"},{"name":"Кацуобуси","quantity":15,"unit":"g","note":""},{"name":"Паста мисо","quantity":4,"unit":"tbsp","note":""},{"name":"Тофу","quantity":200,"unit":"g","note":"кубиками"},{"name":"Вакамэ сушёная","quantity":1,"unit":"tbsp","note":""},{"name":"Зелёный лук","quantity":2,"unit":"piece","note":""}],"steps":"Залейте комбу холодной водой и поставьте на слабый огонь. Доводите до состояния «вот-вот закипит» минут десять и выньте водоросль до появления пузырей.\nДоведите воду до кипения, всыпьте кацуобуси, сразу снимите с огня и дайте настояться две минуты, пока стружка не осядет.\nПроцедите бульон через сито, не отжимая стружку: отжатая даёт горечь.\nЗамочите вакамэ в холодной воде на пять минут: она вырастет в несколько раз.\nПрогрейте даси, положите тофу и вакамэ и держите на слабом огне пару минут.\nРазведите мисо в половнике горячего бульона до однородности, влейте обратно и сразу снимите с огня. Посыпьте зелёным луком.","source":"UniTools"},{"id":"ut-guacamole","name":"Гуакамоле","country":"Мексика","category":"snack","diets":["vegetarian","vegan","gluten-free"],"slots":["snack"],"time":15,"baseServings":4,"portionNutrition":{"k":230,"p":3,"f":20,"c":12},"details":[{"name":"Авокадо","quantity":3,"unit":"piece","note":"спелые"},{"name":"Лайм","quantity":1,"unit":"piece","note":"сок"},{"name":"Красный лук","quantity":0.5,"unit":"piece","note":"мелко нарезать"},{"name":"Халапеньо","quantity":1,"unit":"piece","note":"без семян"},{"name":"Кинза","quantity":3,"unit":"sprig","note":""},{"name":"Помидор","quantity":1,"unit":"piece","note":"без семян, кубиками"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разрежьте авокадо, выньте косточку и ложкой достаньте мякоть в миску. Авокадо должно поддаваться под пальцем, но не проваливаться.\nСразу полейте соком лайма и посолите. Кислота должна попасть на мякоть до того, как та начнёт темнеть.\nРазомните вилкой до крупной неоднородной массы. Куски авокадо должны остаться — это и есть правильная текстура.\nВмешайте лук, халапеньо и кинзу, попробуйте и добавьте соли или лайма. Помидор кладите последним и аккуратно, чтобы он не пустил сок.\nПодавайте сразу. Если нужно подержать, накройте плёнкой в контакт с поверхностью — воздух и есть причина потемнения.","source":"UniTools"},{"id":"ut-tom-yum-goong","name":"Том ям с креветками","country":"Таиланд","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":190,"p":24,"f":4,"c":12},"details":[{"name":"Креветки","quantity":400,"unit":"g","note":"с головами, панцири сохранить"},{"name":"Вода или бульон","quantity":1,"unit":"l","note":""},{"name":"Лемонграсс","quantity":2,"unit":"piece","note":"отбить и нарезать"},{"name":"Галангал","quantity":5,"unit":"slice","note":""},{"name":"Листья кафрского лайма","quantity":5,"unit":"piece","note":""},{"name":"Шампиньоны","quantity":200,"unit":"g","note":""},{"name":"Перец чили","quantity":3,"unit":"piece","note":""},{"name":"Рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Сок лайма","quantity":3,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":1,"unit":"tsp","note":""},{"name":"Кинза","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите креветки, оставив хвосты. Панцири и головы не выбрасывайте — на них и держится бульон.\nОбжарьте панцири в кастрюле пару минут до ярко-оранжевого цвета, залейте водой и варите пятнадцать минут. Процедите.\nВерните бульон на огонь, положите лемонграсс, галангал и листья лайма и дайте настояться пять минут на слабом кипении.\nДобавьте грибы и раздавленный чили, через две минуты — креветки. Они готовы, как только свернутся в букву «С»: дальше станут резиновыми.\nСнимите с огня. Влейте рыбный соус, сок лайма и сахар, перемешайте и попробуйте. Правьте по одной ложке, пока кислое, солёное и острое не встанут на место.\nРазлейте по тарелкам и посыпьте кинзой. Лемонграсс и галангал оставьте в кастрюле или предупредите, что их не едят.","source":"UniTools"},{"id":"ut-dal-tadka","name":"Дал тадка","country":"Индия","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":340,"p":16,"f":12,"c":42},"details":[{"name":"Чечевица тур дал","quantity":200,"unit":"g","note":"промыть"},{"name":"Куркума","quantity":0.5,"unit":"tsp","note":""},{"name":"Топлёное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Семена горчицы","quantity":0.5,"unit":"tsp","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":"тонкими пластинами"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Помидор","quantity":2,"unit":"piece","note":""},{"name":"Сушёный красный чили","quantity":2,"unit":"piece","note":""},{"name":"Асафетида","quantity":1,"unit":"pinch","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте чечевицу тремя стаканами воды, добавьте куркуму и варите под крышкой тридцать минут, пока зёрна не разварятся в мягкую массу.\nРазомните часть чечевицы ложкой прямо в кастрюле и посолите. Консистенция должна быть как у густого супа.\nОтдельно обжарьте лук до золотистого цвета, добавьте помидоры и потушите, пока они не разойдутся в соус. Переложите в чечевицу.\nРазогрейте топлёное масло в маленькой сковороде почти до дымка. Всыпьте семена горчицы: они должны затрещать за несколько секунд.\nСразу добавьте зиру, через десять секунд — чеснок и чили, ещё через двадцать — асафетиду. Всё это занимает меньше минуты, и отходить нельзя.\nВылейте раскалённую тадку прямо в кастрюлю с чечевицей — она должна зашипеть. Перемешайте и подавайте с рисом или лепёшкой.","source":"UniTools"},{"id":"ut-paella-valenciana","name":"Паэлья валенсиана","country":"Испания","category":"main","diets":[],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":620,"p":38,"f":24,"c":62},"details":[{"name":"Рис бомба или другой круглый","quantity":320,"unit":"g","note":""},{"name":"Курица, кусочками","quantity":400,"unit":"g","note":""},{"name":"Кролик, кусочками","quantity":300,"unit":"g","note":"можно заменить курицей"},{"name":"Плоская зелёная фасоль","quantity":200,"unit":"g","note":""},{"name":"Крупная белая фасоль","quantity":100,"unit":"g","note":"варёная"},{"name":"Помидор","quantity":1,"unit":"piece","note":"натереть на тёрке"},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Сладкая паприка","quantity":1,"unit":"tsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Розмарин","quantity":1,"unit":"sprig","note":""},{"name":"Куриный бульон или вода","quantity":900,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разогрейте масло на широкой сковороде и обжарьте курицу с кроликом до румяной корочки со всех сторон. Это не пять минут: на это уходит четверть часа, и торопиться здесь бессмысленно — весь вкус блюда закладывается тут.\nСдвиньте мясо к краям, положите в центр зелёную фасоль и обжарьте пару минут. Добавьте тёртый помидор и паприку и жарьте, пока помидор не потемнеет и не перестанет пахнуть сырым.\nВлейте бульон, положите розмарин, шафран и белую фасоль, посолите заметно сильнее, чем кажется нужным, и дайте покипеть десять минут. Сейчас последний момент, когда можно поправить соль.\nВсыпьте рис ровным слоем и распределите его один раз ложкой. Больше не трогайте сковороду до конца готовки — ни мешать, ни разравнивать.\nВарите на сильном огне десять минут, потом убавьте до среднего и держите ещё восемь, пока бульон не уйдёт. Рис должен виднеться над поверхностью.\nДобавьте огня на полминуты и слушайте: как только появится сухой треск, а не бульканье, снимайте. Это сокаррат. Накройте полотенцем и дайте постоять пять минут.","source":"UniTools"},{"id":"ut-tortilla-espanola","name":"Испанская тортилья","country":"Испания","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":430,"p":15,"f":28,"c":30},"details":[{"name":"Картофель","quantity":600,"unit":"g","note":"нарезать тонкими ломтиками"},{"name":"Лук","quantity":1,"unit":"piece","note":"тонкими полукольцами"},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":400,"unit":"ml","note":"почти всё сольёте обратно"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разогрейте масло в глубокой сковороде до негорячего состояния — картофель, брошенный внутрь, должен лениво зашипеть, а не затрещать. Положите картофель с луком и посолите.\nТомите двадцать минут, изредка переворачивая лопаткой. Готово, когда ломтик легко разламывается о край сковороды. Слейте масло через дуршлаг, картофель оставьте.\nВзбейте яйца с щепоткой соли и вмешайте в них тёплый картофель. Дайте постоять десять минут: картофель отдаст крахмал, и тортилья будет держать форму.\nНа сковороде диаметром 24 см с ложкой масла вылейте смесь и жарьте на среднем огне четыре минуты, подводя края лопаткой к центру.\nНакройте тарелкой, переверните одним движением и верните в сковороду сырой стороной вниз. Ещё три минуты — и центр останется чуть влажным, как и полагается.","source":"UniTools"},{"id":"ut-moussaka","name":"Мусака","country":"Греция","category":"main","diets":[],"slots":["lunch","dinner"],"time":115,"baseServings":6,"portionNutrition":{"k":580,"p":28,"f":36,"c":34},"details":[{"name":"Баклажаны","quantity":3,"unit":"piece","note":"ломтиками в сантиметр"},{"name":"Картофель","quantity":2,"unit":"piece","note":"тонкими кружками"},{"name":"Фарш из баранины или говядины","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Помидоры в собственном соку","quantity":400,"unit":"g","note":""},{"name":"Красное сухое вино","quantity":120,"unit":"ml","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Мука","quantity":80,"unit":"g","note":""},{"name":"Молоко","quantity":700,"unit":"ml","note":""},{"name":"Желтки","quantity":2,"unit":"piece","note":""},{"name":"Кефалотири или пармезан","quantity":80,"unit":"g","note":"натереть"},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Соль, перец, мускатный орех","quantity":null,"unit":"toTaste","note":""}],"steps":"Посолите ломтики баклажанов и оставьте на полчаса в дуршлаге, потом обсушите. Смажьте маслом и запеките при 200 °C двадцать минут до мягкости и золотистого цвета.\nОбжарьте лук до мягкости, добавьте фарш и жарьте, разбивая комки, пока не выпарится вся вода и мясо не начнёт румяниться. Влейте вино и дайте ему уйти.\nДобавьте чеснок, помидоры и корицу и тушите двадцать минут на слабом огне. Соус должен стать густым: ложка, проведённая по дну, оставляет след.\nРастопите масло, вмешайте муку и прогрейте минуту. Влейте тёплое молоко тонкой струйкой, непрерывно мешая, и варите до густоты сметаны. Снимите с огня, добавьте мускат, желтки и половину сыра.\nВыложите слоями: картофель, баклажаны, мясной соус, снова баклажаны. Залейте бешамелем, посыпьте оставшимся сыром.\nЗапекайте при 180 °C сорок пять минут до золотой корочки. Обязательно дайте постоять полчаса перед нарезкой — горячая мусака не режется, а расползается.","source":"UniTools"},{"id":"ut-horiatiki-salata","name":"Хориатики","country":"Греция","category":"salad","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":15,"baseServings":4,"portionNutrition":{"k":320,"p":10,"f":27,"c":11},"details":[{"name":"Спелые помидоры","quantity":4,"unit":"piece","note":"крупными дольками"},{"name":"Огурец","quantity":1,"unit":"piece","note":"толстыми полукольцами"},{"name":"Красный лук","quantity":1,"unit":"piece","note":"тонкими кольцами"},{"name":"Зелёный перец","quantity":1,"unit":"piece","note":""},{"name":"Фета","quantity":200,"unit":"g","note":"одним куском"},{"name":"Оливки каламата","quantity":80,"unit":"g","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Сушёный орегано","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте помидоры крупными дольками и посолите прямо в миске. Оставьте на пять минут — они пустят сок, который станет основой заправки.\nДобавьте огурец, перец и лук. Перемешайте руками, а не ложкой: так овощи не ломаются.\nРазложите сверху оливки, положите кусок феты и полейте маслом всё вместе. Посыпьте орегано прямо по фете — от масла он раскроется.","source":"UniTools"},{"id":"ut-pho-bo","name":"Фо бо","country":"Вьетнам","category":"soup","diets":[],"slots":["lunch","dinner"],"time":270,"baseServings":4,"portionNutrition":{"k":520,"p":34,"f":14,"c":62},"details":[{"name":"Говяжьи кости с мозгом","quantity":1.5,"unit":"kg","note":""},{"name":"Грудинка","quantity":500,"unit":"g","note":""},{"name":"Вырезка","quantity":200,"unit":"g","note":"нарезать почти прозрачно"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Имбирь","quantity":80,"unit":"g","note":""},{"name":"Бадьян","quantity":4,"unit":"piece","note":""},{"name":"Палочка корицы","quantity":1,"unit":"piece","note":""},{"name":"Гвоздика","quantity":4,"unit":"piece","note":""},{"name":"Семена кориандра","quantity":1,"unit":"tbsp","note":""},{"name":"Рыбный соус","quantity":60,"unit":"ml","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Рисовая лапша","quantity":400,"unit":"g","note":""},{"name":"Кинза, зелёный лук, базилик","quantity":null,"unit":"toTaste","note":""},{"name":"Лайм и чили","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте кости холодной водой, доведите до кипения и проварите десять минут. Слейте всё, кости промойте под краном, кастрюлю вымойте. Этот шаг и даёт прозрачность.\nРазрежьте лук и имбирь пополам и обожгите срезами на сухой сковороде или прямо на конфорке до чёрных пятен.\nПрогрейте специи на сухой сковороде до запаха и завяжите в марлю. Верните кости в чистую кастрюлю, добавьте грудинку, лук, имбирь и специи, залейте водой на три пальца выше.\nВарите три часа на самом слабом огне: поверхность должна едва подрагивать. Пену снимайте первые полчаса. Грудинку выньте через полтора часа и остудите.\nПроцедите бульон через мелкое сито, приправьте рыбным соусом и сахаром. Пробуйте: он должен быть чуть солонее, чем приятно пить, — лапша заберёт своё.\nОтварите лапшу, разложите по мискам. Сверху — ломтики грудинки и сырая вырезка. Залейте кипящим бульоном так, чтобы он накрыл мясо, и подавайте с зеленью, лаймом и чили отдельно.","source":"UniTools"},{"id":"ut-banh-mi","name":"Бань ми","country":"Вьетнам","category":"snack","diets":[],"slots":["snack"],"time":40,"baseServings":4,"portionNutrition":{"k":560,"p":28,"f":24,"c":58},"details":[{"name":"Багет","quantity":4,"unit":"piece","note":"короткие, по 20 см"},{"name":"Свиная шея","quantity":400,"unit":"g","note":"тонкими ломтиками"},{"name":"Куриный паштет","quantity":120,"unit":"g","note":""},{"name":"Майонез","quantity":4,"unit":"tbsp","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":"тонкой соломкой"},{"name":"Дайкон","quantity":200,"unit":"g","note":"тонкой соломкой"},{"name":"Рисовый уксус","quantity":100,"unit":"ml","note":""},{"name":"Сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Рыбный соус","quantity":2,"unit":"tbsp","note":""},{"name":"Огурец","quantity":1,"unit":"piece","note":"длинными полосками"},{"name":"Кинза","quantity":null,"unit":"toTaste","note":""},{"name":"Свежий чили","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте уксус, сахар и щепотку соли с 100 мл тёплой воды до растворения. Залейте морковь с дайконом и оставьте на час при комнатной температуре.\nЗамаринуйте свинину в рыбном соусе с ложкой сахара на двадцать минут, затем обжарьте на сильном огне по три минуты с каждой стороны — до карамельных краёв.\nПрогрейте багеты в духовке при 200 °C пять минут, чтобы корка снова стала хрусткой. Разрежьте вдоль, не до конца.\nНамажьте паштет на одну половину, майонез на другую. Уложите свинину, отжатые маринованные овощи, огурец, кинзу и чили. Прижмите ладонью и сразу подавайте.","source":"UniTools"},{"id":"ut-pesto-alla-genovese","name":"Песто алла дженовезе","country":"Италия","category":"sauce","diets":["vegetarian","gluten-free"],"slots":[],"time":20,"baseServings":4,"portionNutrition":{"k":340,"p":8,"f":34,"c":3},"details":[{"name":"Листья базилика","quantity":60,"unit":"g","note":""},{"name":"Кедровые орехи","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":1,"unit":"clove","note":""},{"name":"Пармезан","quantity":50,"unit":"g","note":"натереть мелко"},{"name":"Пекорино","quantity":25,"unit":"g","note":"натереть мелко"},{"name":"Оливковое масло экстра вирджин","quantity":100,"unit":"ml","note":""},{"name":"Крупная соль","quantity":1,"unit":"pinch","note":""}],"steps":"Промойте базилик и обсушите досуха: капли воды не дадут маслу связаться с листьями. Ступку и пестик подержите в холодильнике.\nРастолките чеснок с крупной солью в пасту. Соль работает абразивом — без неё чеснок будет скользить.\nДобавьте кедровые орехи и разотрите до кремовой массы, потом порциями закладывайте базилик. Движение — круговое, прижимающее, а не толкущее: листья нужно раздавить о стенку, а не разбить.\nВмешайте оба сыра, затем тонкой струйкой влейте масло, продолжая растирать. Соус должен стать однородным и густым.","source":"UniTools"},{"id":"ut-tacos-al-pastor","name":"Такос аль пастор","country":"Мексика","category":"main","diets":[],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":610,"p":36,"f":26,"c":55},"details":[{"name":"Свиная шея","quantity":700,"unit":"g","note":"тонкими ломтиками"},{"name":"Сушёный чили гуахильо","quantity":4,"unit":"piece","note":""},{"name":"Сушёный чили анчо","quantity":2,"unit":"piece","note":""},{"name":"Ананас","quantity":200,"unit":"g","note":""},{"name":"Паста ачиоте","quantity":30,"unit":"g","note":"или чайная ложка молотого аннато"},{"name":"Белый уксус","quantity":60,"unit":"ml","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Мексиканский орегано","quantity":1,"unit":"tsp","note":""},{"name":"Кукурузные тортильи","quantity":12,"unit":"piece","note":""},{"name":"Лук и кинза","quantity":null,"unit":"toTaste","note":""},{"name":"Лайм","quantity":null,"unit":"toTaste","note":""}],"steps":"Удалите из чили семена, прогрейте на сухой сковороде до запаха — секунд двадцать на сторону, не дольше, иначе они станут горькими. Залейте кипятком на пятнадцать минут.\nПробейте размоченные чили с половиной ананаса, ачиоте, уксусом, чесноком, зирой и орегано в гладкую пасту. Посолите.\nЗалейте свинину маринадом и оставьте минимум на два часа, лучше на ночь. Дольше суток не держите: ананас размягчит мясо до состояния каши.\nРаскалите сковороду докрасна и обжаривайте мясо порциями по две минуты с каждой стороны. Не перемешивайте, пока не появятся тёмные края.\nОставшийся ананас обжарьте на той же сковороде и нарежьте кубиком. Мясо нарубите крупно, прогрейте тортильи по двадцать секунд с каждой стороны и собирайте: мясо, ананас, лук, кинза, лайм.","source":"UniTools"},{"id":"ut-menemen","name":"Менемен","country":"Турция","category":"breakfast","diets":["vegetarian","gluten-free"],"slots":["breakfast"],"time":30,"baseServings":2,"portionNutrition":{"k":310,"p":16,"f":22,"c":12},"details":[{"name":"Спелые помидоры","quantity":4,"unit":"piece","note":"очистить и нарезать"},{"name":"Длинный зелёный перец","quantity":2,"unit":"piece","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":20,"unit":"g","note":""},{"name":"Оливковое масло","quantity":1,"unit":"tbsp","note":""},{"name":"Хлопья пул бибер","quantity":1,"unit":"tsp","note":""},{"name":"Сушёный орегано","quantity":1,"unit":"tsp","note":""},{"name":"Брынза","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте перец кольцами и обжарьте в смеси масел три-четыре минуты, пока края не начнут темнеть.\nДобавьте помидоры, посолите и тушите на среднем огне десять минут. Ждать нужно до того момента, когда масло отделится и начнёт блестеть по краям — это признак, что вода ушла.\nУбавьте огонь, вбейте яйца прямо в соус и посыпьте хлопьями перца. Мешайте медленно и всего два-три раза, оставляя разводы желтка.\nСнимите с огня, когда белок схватился, а желток ещё влажный — на сковороде яйца дойдут сами. Посыпьте орегано и брынзой.","source":"UniTools"},{"id":"ut-mercimek-corbasi","name":"Мерджимек чорбасы","country":"Турция","category":"soup","diets":["vegetarian"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":330,"p":16,"f":10,"c":45},"details":[{"name":"Красная чечевица","quantity":250,"unit":"g","note":"промыть"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Картофель","quantity":1,"unit":"piece","note":""},{"name":"Томатная паста","quantity":1,"unit":"tbsp","note":""},{"name":"Вода или бульон","quantity":1.4,"unit":"l","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Сушёная мята","quantity":1,"unit":"tsp","note":""},{"name":"Сладкая паприка","quantity":1,"unit":"tsp","note":""},{"name":"Лимон","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук с морковью в ложке масла до мягкости, добавьте томатную пасту и жарьте ещё минуту, пока она не потемнеет.\nДобавьте чечевицу, картофель и воду, доведите до кипения и варите двадцать пять минут на слабом огне, пока чечевица не разварится полностью.\nПробейте блендером до полной гладкости. Суп должен получиться плотным, но текучим — если густо, добавьте кипятка.\nРастопите оставшееся масло, снимите с огня и вмешайте мяту с паприкой. Разлейте суп, полейте маслом и подайте с долькой лимона.","source":"UniTools"},{"id":"ut-khinkali","name":"Хинкали","country":"Грузия","category":"main","diets":[],"slots":["lunch","dinner"],"time":75,"baseServings":4,"portionNutrition":{"k":480,"p":26,"f":18,"c":52},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода для теста","quantity":220,"unit":"ml","note":""},{"name":"Говядина","quantity":400,"unit":"g","note":"порубить ножом"},{"name":"Свинина","quantity":200,"unit":"g","note":"порубить ножом"},{"name":"Лук","quantity":2,"unit":"piece","note":"очень мелко"},{"name":"Ледяная вода в фарш","quantity":200,"unit":"ml","note":""},{"name":"Кинза","quantity":1,"unit":"sprig","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Чёрный перец","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, воды и щепотки соли. Оно должно получиться заметно круче пельменного — таким, что месить тяжело. Заверните в плёнку и оставьте на сорок минут.\nПорубите мясо ножом на кусочки в несколько миллиметров. Смешайте с луком, кинзой, зирой, солью и перцем.\nВливайте ледяную воду в фарш порциями, вымешивая рукой, пока масса не станет вязкой и не перестанет впитывать. Уберите в холод на двадцать минут.\nРаскатайте кружки диаметром 12 см, толщиной около двух миллиметров. Положите столовую ложку фарша и соберите края складками по кругу — их должно быть не меньше восемнадцати. Скрутите верх и защипните.\nОпускайте в большую кастрюлю подсоленного кипятка, помешивая воду шумовкой перед закладкой, чтобы не прилипли. Варите семь-восемь минут после всплытия.","source":"UniTools"},{"id":"ut-murgh-makhani","name":"Курица масала в сливочном соусе","country":"Индия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":640,"p":42,"f":42,"c":18},"details":[{"name":"Куриное бедро без кости","quantity":700,"unit":"g","note":""},{"name":"Густой йогурт","quantity":150,"unit":"g","note":""},{"name":"Имбирь","quantity":20,"unit":"g","note":"натереть"},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Гарам масала","quantity":2,"unit":"tsp","note":""},{"name":"Кашмирский чили молотый","quantity":1,"unit":"tsp","note":""},{"name":"Куркума","quantity":0.5,"unit":"tsp","note":""},{"name":"Помидоры в собственном соку","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Сливки 30 %","quantity":120,"unit":"ml","note":""},{"name":"Кешью","quantity":40,"unit":"g","note":"замочить в кипятке"},{"name":"Касури мети","quantity":1,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте йогурт с половиной имбиря, чеснока и специй, посолите и замаринуйте курицу минимум на час, лучше на ночь.\nЗапеките курицу при 220 °C двадцать минут или обжарьте на раскалённой сковороде до тёмных подпалин. Внутри она может остаться слегка недоготовленной — дойдёт в соусе.\nРастопите масло, обжарьте лук с остатком имбиря и чеснока до золотистого цвета. Добавьте помидоры и специи, тушите пятнадцать минут.\nПробейте соус блендером вместе с размоченным кешью до полной гладкости и верните в сковороду. Именно кешью, а не мука, дают соусу плотность.\nВерните курицу в соус, влейте сливки и прогрейте пять минут, не доводя до кипения. Разотрите касури мети в ладонях, вмешайте и снимите с огня.","source":"UniTools"},{"id":"ut-katsudon","name":"Кацудон","country":"Япония","category":"main","diets":[],"slots":["lunch","dinner"],"time":40,"baseServings":2,"portionNutrition":{"k":780,"p":42,"f":32,"c":78},"details":[{"name":"Свиная корейка","quantity":2,"unit":"piece","note":"по 150 г, отбить"},{"name":"Мука","quantity":40,"unit":"g","note":""},{"name":"Яйцо для панировки","quantity":1,"unit":"piece","note":""},{"name":"Панко","quantity":80,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":"тонкими полукольцами"},{"name":"Даси","quantity":200,"unit":"ml","note":""},{"name":"Соевый соус","quantity":3,"unit":"tbsp","note":""},{"name":"Мирин","quantity":3,"unit":"tbsp","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Яйца в соус","quantity":3,"unit":"piece","note":""},{"name":"Варёный рис","quantity":400,"unit":"g","note":""},{"name":"Масло для жарки","quantity":500,"unit":"ml","note":""}],"steps":"Надрежьте жировую кромку котлет в нескольких местах, чтобы они не свернулись, посолите и обваляйте по очереди в муке, яйце и панко.\nОбжарьте во фритюре при 170 °C по три минуты с каждой стороны до золотистого цвета. Выложите на решётку, а не на бумагу: снизу панировка должна остаться хрустящей.\nНарежьте котлеты полосками в полтора сантиметра, не сдвигая их — форма пригодится при подаче.\nВ небольшой сковороде доведите даси с соевым соусом, мирином и сахаром до кипения, положите лук и варите три минуты до мягкости.\nПереложите котлету в соус, влейте две трети слегка взболтанного яйца по кругу и накройте на минуту. Влейте остаток, накройте ещё на двадцать секунд и снимите с огня — верхний слой яйца должен остаться жидким.\nСдвиньте всё содержимое сковороды на рис одним движением, вместе с соусом.","source":"UniTools"},{"id":"ut-syrniki","name":"Сырники","country":"Россия","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":30,"baseServings":4,"portionNutrition":{"k":340,"p":22,"f":16,"c":26},"details":[{"name":"Творог 5–9 %","quantity":500,"unit":"g","note":"сухой, отвешенный"},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Мука","quantity":3,"unit":"tbsp","note":"плюс немного для рук"},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Ванильный сахар","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""},{"name":"Масло для жарки","quantity":30,"unit":"g","note":""},{"name":"Сметана и варенье","quantity":null,"unit":"toTaste","note":""}],"steps":"Протрите творог через сито или пробейте блендером. Зернистый творог даёт зернистые сырники — этот шаг пропускать нельзя.\nВмешайте яйцо, сахар, ваниль и соль, затем муку. Тесто останется липким — так и должно быть.\nМокрыми или подпылёнными мукой руками сформуйте шайбы толщиной около полутора сантиметров. Толще — не прожарятся, тоньше — пересохнут.\nЖарьте на среднем огне под крышкой по три-четыре минуты с каждой стороны. Крышка здесь важнее масла: она пропаривает середину.","source":"UniTools"},{"id":"ut-pad-thai","name":"Пад тай","country":"Таиланд","category":"main","diets":[],"slots":["lunch","dinner"],"time":40,"baseServings":2,"portionNutrition":{"k":690,"p":34,"f":24,"c":82},"details":[{"name":"Рисовая лапша 5 мм","quantity":200,"unit":"g","note":""},{"name":"Креветки","quantity":200,"unit":"g","note":""},{"name":"Плотный тофу","quantity":100,"unit":"g","note":"кубиком"},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Тамариндовая паста","quantity":3,"unit":"tbsp","note":""},{"name":"Рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Шалот","quantity":2,"unit":"piece","note":""},{"name":"Ростки маша","quantity":150,"unit":"g","note":""},{"name":"Зелёный лук","quantity":50,"unit":"g","note":""},{"name":"Арахис","quantity":50,"unit":"g","note":"порубить"},{"name":"Лайм","quantity":null,"unit":"toTaste","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""}],"steps":"Замочите лапшу в тёплой воде на двадцать минут. Она должна гнуться, но при укусе оставаться жёсткой.\nРастворите пальмовый сахар в тамаринде и рыбном соусе, прогрев их вместе минуту. Попробуйте: должно быть одинаково кисло, солёно и сладко.\nРаскалите вок, обжарьте тофу до корочки, добавьте чеснок с шалотом, через полминуты — креветки. Готовьте до розового цвета и сдвиньте к краю.\nРазбейте яйца в освободившееся место, дайте схватиться и разбейте лопаткой. Положите откинутую лапшу и влейте соус.\nЖарьте, всё время подбрасывая, две минуты, пока лапша не впитает соус и не станет мягкой. Добавьте ростки и зелёный лук, перемешайте один раз и снимайте.","source":"UniTools"},{"id":"ut-tiramisu","name":"Тирамису","country":"Италия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":30,"baseServings":6,"portionNutrition":{"k":520,"p":10,"f":34,"c":42},"details":[{"name":"Маскарпоне","quantity":500,"unit":"g","note":"холодный"},{"name":"Желтки","quantity":4,"unit":"piece","note":""},{"name":"Белки","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Савоярди","quantity":300,"unit":"g","note":""},{"name":"Крепкий эспрессо","quantity":350,"unit":"ml","note":"остудить"},{"name":"Марсала","quantity":2,"unit":"tbsp","note":"по желанию"},{"name":"Какао-порошок","quantity":null,"unit":"toTaste","note":""}],"steps":"Взбейте желтки с половиной сахара над кастрюлей с кипящей водой, не касаясь воды, до светлой густой массы — примерно семь минут. Снимите и остудите до комнатной температуры.\nВмешайте холодный маскарпоне в остывшие желтки ложкой, а не миксером. Миксер разбивает жир, и крем становится зернистым — это первая точка, где тирамису обычно портят.\nВзбейте белки с оставшимся сахаром до устойчивых пиков и вмешайте в крем в три приёма движением снизу вверх.\nСмешайте кофе с марсалой. Окунайте савоярди на одну секунду каждой стороной и укладывайте плотным слоем в форму.\nВыложите половину крема, разровняйте, повторите слой печенья и крема. Затяните плёнкой и уберите в холодильник минимум на шесть часов, лучше на ночь.\nПосыпьте какао через сито непосредственно перед подачей. Если сделать это заранее, какао впитает влагу и станет пятнистым.","source":"UniTools"},{"id":"ut-gazpacho","name":"Гаспачо","country":"Испания","category":"soup","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":20,"baseServings":4,"portionNutrition":{"k":220,"p":4,"f":16,"c":17},"details":[{"name":"Спелые помидоры","quantity":1,"unit":"kg","note":""},{"name":"Огурец","quantity":1,"unit":"piece","note":"очистить"},{"name":"Зелёный перец","quantity":0.5,"unit":"piece","note":""},{"name":"Чеснок","quantity":1,"unit":"clove","note":""},{"name":"Чёрствый белый хлеб","quantity":80,"unit":"g","note":"мякиш, размочить"},{"name":"Оливковое масло экстра вирджин","quantity":80,"unit":"ml","note":""},{"name":"Хересный уксус","quantity":2,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Размочите мякиш в холодной воде десять минут и отожмите досуха.\nПробейте в блендере помидоры, огурец, перец, чеснок и хлеб до полной гладкости. Это займёт дольше, чем кажется: минуты две на максимуме.\nНе выключая блендер, влейте масло тонкой струйкой. Суп посветлеет и загустеет — это и есть та самая эмульсия.\nДобавьте уксус и соль, попробуйте и досолите. Протрите через сито, если хотите шелковистую текстуру, и охладите не меньше двух часов.","source":"UniTools"},{"id":"ut-croquetas-de-jamon","name":"Крокеты с хамоном","country":"Испания","category":"snack","diets":[],"slots":["snack"],"time":55,"baseServings":4,"portionNutrition":{"k":480,"p":18,"f":30,"c":34},"details":[{"name":"Хамон серрано","quantity":150,"unit":"g","note":"мелким кубиком"},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Оливковое масло","quantity":2,"unit":"tbsp","note":""},{"name":"Лук","quantity":0.5,"unit":"piece","note":"очень мелко"},{"name":"Мука","quantity":100,"unit":"g","note":""},{"name":"Молоко","quantity":700,"unit":"ml","note":"тёплое"},{"name":"Мускатный орех","quantity":1,"unit":"pinch","note":""},{"name":"Яйца для панировки","quantity":2,"unit":"piece","note":""},{"name":"Панировочные сухари","quantity":150,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":700,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Растопите сливочное масло с оливковым, обжарьте лук до прозрачности, добавьте хамон и прогрейте минуту — жир вытопится и заберёт вкус.\nВсыпьте муку и жарьте, помешивая, четыре-пять минут, пока она не запахнет орехами и слегка не потемнеет.\nВливайте тёплое молоко по половнику, каждый раз размешивая до гладкости, прежде чем добавить следующий. Варите ещё десять минут: масса должна отходить от стенок.\nПриправьте мускатом и солью, выложите в форму слоем в два сантиметра, накройте плёнкой в контакт и охладите минимум четыре часа.\nСформуйте цилиндры влажными руками, обваляйте в яйце и сухарях. Для крепкой корочки повторите панировку дважды.\nОбжарьте во фритюре при 180 °C по две минуты небольшими партиями. В переполненном масле температура падает, и крокеты впитывают жир вместо того, чтобы покрыться корочкой.","source":"UniTools"},{"id":"ut-ceviche","name":"Севиче","country":"Перу","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":20,"baseServings":4,"portionNutrition":{"k":290,"p":34,"f":3,"c":30},"details":[{"name":"Белая рыба для сырого потребления","quantity":600,"unit":"g","note":"кубиком 2 см"},{"name":"Лайм","quantity":10,"unit":"piece","note":"сок"},{"name":"Красный лук","quantity":1,"unit":"piece","note":"очень тонкими перьями"},{"name":"Перец ахи лимо или рокото","quantity":1,"unit":"piece","note":""},{"name":"Кинза","quantity":4,"unit":"sprig","note":""},{"name":"Батат","quantity":1,"unit":"piece","note":"отварной"},{"name":"Кукуруза чокло","quantity":150,"unit":"g","note":"отварная"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите нарезанный лук в ледяной воде на десять минут и обсушите — уйдёт резкость, останется вкус.\nВыжмите лайм руками, не соковыжималкой: давление на кожуру выпускает горькие масла.\nПосолите рыбу, перемешайте с рубленым ахи и кинзой, залейте соком лайма и оставьте ровно на три-пять минут. Края кубиков побелеют, середина останется прозрачной.\nДобавьте лук, перемешайте один раз и сразу подавайте с бататом и кукурузой. Сок из миски разлейте по стопкам.","source":"UniTools"},{"id":"ut-lomo-saltado","name":"Ломо сальтадо","country":"Перу","category":"main","diets":[],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":720,"p":42,"f":26,"c":76},"details":[{"name":"Говяжья вырезка","quantity":600,"unit":"g","note":"полосками"},{"name":"Красный лук","quantity":2,"unit":"piece","note":"крупными перьями"},{"name":"Помидоры","quantity":3,"unit":"piece","note":"дольками"},{"name":"Ахи амарильо","quantity":1,"unit":"piece","note":""},{"name":"Соевый соус","quantity":4,"unit":"tbsp","note":""},{"name":"Красный винный уксус","quantity":2,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Картофель фри","quantity":600,"unit":"g","note":""},{"name":"Варёный рис","quantity":400,"unit":"g","note":""},{"name":"Кинза","quantity":null,"unit":"toTaste","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""}],"steps":"Замаринуйте мясо в соевом соусе с уксусом и чесноком на пятнадцать минут, потом обсушите — влажная поверхность не даст подпалин.\nРаскалите сковороду до дыма и обжарьте мясо двумя партиями по полторы минуты, не перемешивая первые сорок секунд. Выложите на тарелку.\nВ той же сковороде обжарьте лук и ахи полторы минуты — лук должен остаться хрустящим внутри.\nВерните мясо, влейте остатки маринада, добавьте помидоры и прогрейте полминуты. Снимите с огня, вмешайте кинзу.\nПодавайте с горячим картофелем фри — часть его перемешивают прямо в сковороде, чтобы он взял соус, — и отдельной порцией риса.","source":"UniTools"},{"id":"ut-mapo-tofu","name":"Мапо тофу","country":"Китай","category":"main","diets":[],"slots":["lunch","dinner"],"time":30,"baseServings":4,"portionNutrition":{"k":380,"p":24,"f":26,"c":12},"details":[{"name":"Мягкий тофу","quantity":500,"unit":"g","note":"кубиком 2 см"},{"name":"Свиной фарш","quantity":150,"unit":"g","note":""},{"name":"Доубаньцзян","quantity":2,"unit":"tbsp","note":""},{"name":"Ферментированные чёрные бобы","quantity":1,"unit":"tbsp","note":"порубить"},{"name":"Сычуаньский перец","quantity":1,"unit":"tsp","note":"смолоть"},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Имбирь","quantity":15,"unit":"g","note":""},{"name":"Куриный бульон","quantity":250,"unit":"ml","note":""},{"name":"Крахмал","quantity":1,"unit":"tbsp","note":""},{"name":"Зелёный лук","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""}],"steps":"Опустите тофу в подсоленную воду при слабом кипении на три минуты и аккуратно откиньте.\nОбжарьте фарш до румяности и вытопленного жира, отодвиньте к краю. Добавьте доубаньцзян и жарьте минуту, пока масло не станет красным.\nДобавьте чеснок, имбирь и чёрные бобы, прогрейте полминуты и влейте бульон. Дайте закипеть.\nОпустите тофу и тушите три минуты, не мешая ложкой — только покачивая сковороду, иначе кубики развалятся.\nРазведите крахмал холодной водой и влейте в два приёма, каждый раз давая соусу закипеть. Снимите с огня, посыпьте молотым сычуаньским перцем и зелёным луком.","source":"UniTools"},{"id":"ut-gong-bao-chicken","name":"Курица гунбао","country":"Китай","category":"main","diets":[],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":470,"p":38,"f":24,"c":22},"details":[{"name":"Куриное филе","quantity":500,"unit":"g","note":"кубиком 2 см"},{"name":"Яичный белок","quantity":1,"unit":"piece","note":""},{"name":"Крахмал","quantity":2,"unit":"tbsp","note":""},{"name":"Жареный арахис","quantity":80,"unit":"g","note":""},{"name":"Сушёный чили целиком","quantity":8,"unit":"piece","note":""},{"name":"Сычуаньский перец","quantity":1,"unit":"tsp","note":""},{"name":"Чёрный уксус чжэньцзян","quantity":3,"unit":"tbsp","note":""},{"name":"Соевый соус","quantity":2,"unit":"tbsp","note":""},{"name":"Сахар","quantity":2,"unit":"tsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Имбирь","quantity":15,"unit":"g","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""}],"steps":"Смешайте курицу с яичным белком, ложкой крахмала, ложкой соевого соуса и щепоткой соли и оставьте на двадцать минут.\nСоберите соус заранее: уксус, оставшийся соевый соус, сахар и оставшийся крахмал с двумя ложками воды. Держите под рукой — времени мешать его в процессе не будет.\nРаскалите масло и обжарьте чили с сычуаньским перцем двадцать секунд, до тёмного цвета, но не до чёрного. Горелый чили горчит.\nДобавьте курицу и жарьте, не трогая, минуту, потом перемешайте и доведите до готовности — ещё две минуты.\nВсыпьте чеснок, имбирь и белую часть зелёного лука, через полминуты влейте соус. Он загустеет за секунды. Снимите с огня, добавьте арахис и зелёную часть лука.","source":"UniTools"},{"id":"ut-coq-au-vin","name":"Кок-о-вен","country":"Франция","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":4,"portionNutrition":{"k":680,"p":48,"f":38,"c":16},"details":[{"name":"Курица, разделанная на куски","quantity":1.5,"unit":"kg","note":""},{"name":"Красное сухое вино","quantity":750,"unit":"ml","note":""},{"name":"Копчёная грудинка","quantity":150,"unit":"g","note":"брусочками"},{"name":"Шампиньоны","quantity":300,"unit":"g","note":""},{"name":"Мелкий лук","quantity":250,"unit":"g","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Куриный бульон","quantity":300,"unit":"ml","note":""},{"name":"Тимьян и лавровый лист","quantity":3,"unit":"sprig","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте курицу вином с морковью, чесноком и травами и оставьте в холоде на ночь. Утром выньте мясо и обсушите, вино сохраните.\nВытопите бекон в сотейнике, выньте его шумовкой. В этом жире обжарьте курицу до тёмной корочки со всех сторон, партиями.\nПрисыпьте мукой, перемешайте и прогрейте две минуты. Влейте маринад вместе с овощами и бульон, доведите до кипения и снимите пену.\nТушите под крышкой на слабом огне или в духовке при 160 °C час. Соус должен едва подрагивать.\nПока тушится, обжарьте лук в масле до золотистого цвета, отдельно — грибы на сильном огне до румяности.\nДобавьте лук, грибы и бекон в сотейник, дайте всему постоять на слабом огне десять минут и попробуйте соус на соль.","source":"UniTools"},{"id":"ut-creme-brulee","name":"Крем-брюле","country":"Франция","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":65,"baseServings":4,"portionNutrition":{"k":490,"p":6,"f":42,"c":24},"details":[{"name":"Сливки 33 %","quantity":500,"unit":"ml","note":""},{"name":"Желтки","quantity":5,"unit":"piece","note":""},{"name":"Сахар в крем","quantity":80,"unit":"g","note":""},{"name":"Стручок ванили","quantity":1,"unit":"piece","note":""},{"name":"Сахар для корочки","quantity":4,"unit":"tsp","note":""}],"steps":"Разрежьте ваниль вдоль, выскоблите семена и прогрейте со сливками почти до кипения. Снимите и дайте настояться пятнадцать минут.\nРазотрите желтки с сахаром без пены — воздух здесь не нужен. Влейте тёплые сливки тонкой струйкой, непрерывно мешая.\nПроцедите через сито и снимите пену с поверхности. Разлейте по формам и поставьте их в глубокий противень.\nНалейте в противень кипяток до половины высоты форм и запекайте при 150 °C сорок минут. Центр должен подрагивать.\nПолностью остудите и держите в холодильнике не меньше четырёх часов. Только потом посыпьте сахаром и сожгите горелкой.","source":"UniTools"},{"id":"ut-kaesespaetzle","name":"Кезешпецле","country":"Германия","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":720,"p":30,"f":32,"c":78},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Вода или молоко","quantity":150,"unit":"ml","note":""},{"name":"Эмменталь или бергкезе","quantity":250,"unit":"g","note":"натереть"},{"name":"Лук","quantity":3,"unit":"piece","note":"тонкими кольцами"},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Мускатный орех","quantity":1,"unit":"pinch","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте муку, яйца, воду, соль и мускат и бейте тесто ложкой минут пять, пока по поверхности не пойдут пузыри и оно не начнёт тянуться за ложкой.\nПока тесто отдыхает, обжарьте лук в масле на среднем огне до тёмно-золотого цвета. Это двадцать минут, а не пять: за это время сахар в луке карамелизуется.\nПродавите тесто в кипящую подсоленную воду через шпецле-тёрку или дуршлаг с крупными отверстиями. Готовые шпецле всплывают через минуту — вынимайте шумовкой.\nВыкладывайте в горячую форму слоями: шпецле, сыр, шпецле, сыр. Тепло самой лапши расплавит сыр — духовка не нужна.\nЗасыпьте жареным луком и подавайте сразу. Классический гарнир — зелёный салат с уксусной заправкой, и он здесь не украшение, а противовес.","source":"UniTools"},{"id":"ut-rinderrouladen","name":"Руладен","country":"Германия","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":4,"portionNutrition":{"k":640,"p":52,"f":34,"c":14},"details":[{"name":"Говядина тонкими пластами","quantity":800,"unit":"g","note":"по 150-200 г, отбить"},{"name":"Горчица средней остроты","quantity":4,"unit":"tbsp","note":""},{"name":"Копчёный бекон","quantity":120,"unit":"g","note":""},{"name":"Корнишоны","quantity":4,"unit":"piece","note":"вдоль на четверти"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Томатная паста","quantity":1,"unit":"tbsp","note":""},{"name":"Красное сухое вино","quantity":200,"unit":"ml","note":""},{"name":"Говяжий бульон","quantity":500,"unit":"ml","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Масло для жарки","quantity":2,"unit":"tbsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отбейте мясо до пяти миллиметров, посолите и поперчите, намажьте горчицей. Разложите бекон, полоски лука и корнишон вдоль короткой стороны.\nСверните рулетом, подгибая края внутрь, и закрепите шпажкой или ниткой. Плотно, но не туго: начинка расширится.\nОбжарьте рулеты со всех сторон до тёмной корочки и выньте. В том же жире обжарьте оставшийся лук с морковью, добавьте томатную пасту и прогрейте минуту.\nВлейте вино, дайте выпариться наполовину, добавьте бульон и лавровый лист. Верните рулеты, накройте и тушите на слабом огне полтора часа.\nВыньте рулеты, снимите шпажки. Соус пробейте блендером прямо в сотейнике или разотрите толкушкой и уварите до нужной густоты.","source":"UniTools"},{"id":"ut-bibimbap","name":"Пибимпап","country":"Корея","category":"main","diets":[],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":640,"p":34,"f":22,"c":76},"details":[{"name":"Варёный короткозёрный рис","quantity":600,"unit":"g","note":""},{"name":"Говядина","quantity":250,"unit":"g","note":"тонкой соломкой"},{"name":"Шпинат","quantity":200,"unit":"g","note":""},{"name":"Ростки сои","quantity":150,"unit":"g","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":"соломкой"},{"name":"Грибы шиитаке","quantity":150,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Кочхуджан","quantity":4,"unit":"tbsp","note":""},{"name":"Кунжутное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Соевый соус","quantity":2,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Кунжут","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте говядину в соевом соусе с чесноком и ложкой кунжутного масла на двадцать минут.\nБланшируйте шпинат тридцать секунд, отожмите и приправьте кунжутным маслом с щепоткой соли. Ростки отварите три минуты и приправьте так же, но с чесноком.\nОбжарьте по отдельности морковь и грибы — по паре минут каждую, солите отдельно. Мыть сковороду между ними не нужно.\nОбжарьте мясо на сильном огне две минуты. Отдельно пожарьте яйца так, чтобы желток остался жидким.\nРазложите горячий рис по мискам, уложите овощи и мясо секторами, сверху — яйцо и ложку кочхуджана. Перемешивать будет каждый сам.","source":"UniTools"},{"id":"ut-kimchi-jjigae","name":"Кимчхи чиге","country":"Корея","category":"soup","diets":[],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":470,"p":28,"f":32,"c":16},"details":[{"name":"Перекисшее кимчи","quantity":400,"unit":"g","note":"с соком"},{"name":"Свиная грудинка","quantity":300,"unit":"g","note":"ломтиками"},{"name":"Тофу","quantity":300,"unit":"g","note":"толстыми ломтями"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Кочхукару","quantity":1,"unit":"tbsp","note":""},{"name":"Кочхуджан","quantity":1,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Вода или анчоусный бульон","quantity":700,"unit":"ml","note":""},{"name":"Зелёный лук","quantity":3,"unit":"piece","note":""},{"name":"Кунжутное масло","quantity":1,"unit":"tbsp","note":""}],"steps":"Обжарьте свинину в кунжутном масле на среднем огне до вытопленного жира и румяности — минут пять.\nДобавьте кимчи и жарьте пять минут, пока края не потемнеют. Этот шаг убирает сырую кислоту и делает вкус круглым.\nВмешайте кочхукару, кочхуджан и чеснок, влейте сок кимчи и воду. Доведите до кипения.\nВарите двадцать минут на среднем огне, добавьте лук и тофу и дайте покипеть ещё пять. Тофу не мешайте — он развалится.\nСнимите с огня, посыпьте зелёным луком и подавайте прямо в кастрюле, с отдельной миской риса.","source":"UniTools"},{"id":"ut-souvlaki","name":"Сувлаки","country":"Греция","category":"main","diets":[],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":660,"p":46,"f":38,"c":32},"details":[{"name":"Свиная шея","quantity":800,"unit":"g","note":"кубиками 3 см"},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":"сок и цедра"},{"name":"Сушёный орегано","quantity":2,"unit":"tsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Питы","quantity":4,"unit":"piece","note":""},{"name":"Густой йогурт","quantity":200,"unit":"g","note":""},{"name":"Огурец","quantity":0.5,"unit":"piece","note":"натереть и отжать"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте масло, сок и цедру лимона, орегано, тёртый чеснок, соль и перец. Залейте мясо и оставьте на два часа, но не дольше четырёх.\nПока маринуется, сделайте дзадзики: смешайте йогурт с отжатым огурцом, зубчиком чеснока, ложкой масла и солью.\nНанижите мясо на шпажки неплотно — между кусками должен проходить жар. Плотно набитая шпажка внутри останется сырой.\nГотовьте на раскалённом гриле или сковороде-гриль по три минуты с каждой из четырёх сторон. Мясо должно потемнеть, а не побледнеть.\nДайте мясу отдохнуть пять минут, прогрейте питы по тридцать секунд и подавайте с дзадзики и лимоном.","source":"UniTools"},{"id":"ut-chicken-biryani","name":"Бирьяни с курицей","country":"Индия","category":"main","diets":[],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":720,"p":42,"f":26,"c":82},"details":[{"name":"Басмати","quantity":500,"unit":"g","note":"замочить на 30 минут"},{"name":"Курица на кости","quantity":1,"unit":"kg","note":""},{"name":"Густой йогурт","quantity":250,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":"тонкими кольцами"},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Гарам масала","quantity":2,"unit":"tsp","note":""},{"name":"Молотый чили","quantity":1,"unit":"tsp","note":""},{"name":"Куркума","quantity":0.5,"unit":"tsp","note":""},{"name":"Кардамон, гвоздика, корица, лавр","quantity":1,"unit":"tbsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Тёплое молоко","quantity":60,"unit":"ml","note":""},{"name":"Мята и кинза","quantity":1,"unit":"sprig","note":""},{"name":"Гхи или масло","quantity":60,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук в гхи до тёмно-золотого цвета — двадцать минут на среднем огне. Половину отложите: это и есть бириста, главный вкус бирьяни.\nЗамаринуйте курицу в йогурте с имбирём, чесноком, специями, половиной жареного лука, мятой и солью. Держите час, лучше три.\nОтварите рис в большом количестве подсоленной воды с целыми специями ровно пять минут и откиньте. Зерно должно ломаться, но оставаться белым в середине.\nВыложите маринованную курицу на дно тяжёлой кастрюли, сверху — рис ровным слоем. Полейте шафрановым молоком пятнами, посыпьте оставшимся луком и зеленью.\nЗакройте крышкой как можно плотнее — при желании обмотайте фольгой. Держите на сильном огне пять минут, потом на самом слабом сорок. Крышку не открывайте ни разу.\nДайте постоять десять минут и перемешайте один раз снизу вверх, поднимая курицу к рису, а не размешивая всё в кашу.","source":"UniTools"},{"id":"ut-shoyu-ramen","name":"Сёю рамен","country":"Япония","category":"soup","diets":[],"slots":["lunch","dinner"],"time":210,"baseServings":4,"portionNutrition":{"k":780,"p":44,"f":30,"c":82},"details":[{"name":"Куриные каркасы","quantity":1.5,"unit":"kg","note":""},{"name":"Свиная грудинка","quantity":500,"unit":"g","note":""},{"name":"Комбу","quantity":10,"unit":"g","note":""},{"name":"Сушёные шиитаке","quantity":20,"unit":"g","note":""},{"name":"Соевый соус","quantity":200,"unit":"ml","note":""},{"name":"Мирин","quantity":60,"unit":"ml","note":""},{"name":"Сакэ","quantity":60,"unit":"ml","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Лапша для рамена","quantity":500,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Кунжутное масло","quantity":2,"unit":"tbsp","note":""}],"steps":"Залейте каркасы холодной водой, доведите до кипения, проварите десять минут и слейте. Промойте кости и кастрюлю — от этого зависит чистота бульона.\nЗалейте заново, добавьте имбирь и чеснок и варите три часа на слабом огне. Комбу опустите за двадцать минут до конца и выньте до кипения — при кипячении она даёт горечь.\nДля тарэ уварите соевый соус с мирином, сакэ и шиитаке до трети объёма. Получится густая тёмная жидкость — по две ложки на миску.\nСварите яйца шесть с половиной минут, охладите в ледяной воде, очистите и оставьте в оставшемся тарэ на два часа.\nОтварите лапшу отдельно строго по времени на упаковке, откиньте и сразу разложите по мискам с тарэ на дне.\nЗалейте горячим бульоном, размешайте один раз, чтобы тарэ разошёлся, и уложите свинину, яйцо и зелёный лук. Полейте кунжутным маслом.","source":"UniTools"},{"id":"ut-pierogi-ruskie","name":"Пероги руске","country":"Польша","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":590,"p":20,"f":20,"c":82},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Кипяток","quantity":200,"unit":"ml","note":""},{"name":"Растительное масло","quantity":2,"unit":"tbsp","note":""},{"name":"Картофель","quantity":500,"unit":"g","note":"отварной"},{"name":"Сухой творог","quantity":250,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Сметана","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте муку кипятком с маслом и солью, замесите ложкой, а когда остынет — руками, минут восемь. Накройте и дайте отдохнуть полчаса.\nОбжарьте два луковицы в масле до тёмно-золотого цвета. Половину вмешайте в начинку, половину оставьте для подачи.\nРазомните тёплый картофель с творогом и жареным луком, посолите и поперчите щедро. Начинка должна быть плотной, чтобы держала форму.\nРаскатайте тесто в два миллиметра, вырежьте кружки стаканом, положите чайную ложку начинки и защипните края насухо — мокрое тесто не склеится.\nВарите партиями в широкой кастрюле подсоленной воды. Через минуту после всплытия вынимайте шумовкой.\nПодавайте с оставшимся жареным луком и сметаной. Многие обжаривают варёные пероги на сливочном масле — так тоже правильно.","source":"UniTools"},{"id":"ut-zurek","name":"Журек","country":"Польша","category":"soup","diets":[],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":540,"p":26,"f":38,"c":22},"details":[{"name":"Ржаной заквас","quantity":400,"unit":"ml","note":"готовый или домашний"},{"name":"Белая колбаса","quantity":500,"unit":"g","note":""},{"name":"Копчёная грудинка","quantity":100,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Майоран сушёный","quantity":2,"unit":"tsp","note":""},{"name":"Овощной или мясной бульон","quantity":1,"unit":"l","note":""},{"name":"Сливки 20 %","quantity":100,"unit":"ml","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":"варёные вкрутую"},{"name":"Хрен","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Вытопите бекон в кастрюле, обжарьте в нём лук до мягкости, добавьте чеснок и майоран и прогрейте полминуты.\nВлейте бульон, опустите колбасу целиком и варите на слабом огне тридцать минут. Не протыкайте её — весь сок уйдёт в бульон раньше времени.\nВыньте колбасу, нарежьте кружками и верните в кастрюлю. Взболтайте заквас в банке и влейте, помешивая.\nПрогрейте пять минут, не доводя до бурного кипения, вмешайте сливки и попробуйте. Если кисло слабо — добавьте закваса, соль в конце.\nРазлейте по тарелкам, положите половинку варёного яйца и подавайте с хреном. В Польше журек часто подают в хлебной буханке.","source":"UniTools"},{"id":"ut-sauerbraten","name":"Заурбратен","country":"Германия","category":"main","diets":[],"slots":["lunch","dinner"],"time":180,"baseServings":6,"portionNutrition":{"k":610,"p":54,"f":26,"c":26},"details":[{"name":"Говяжий огузок","quantity":1.5,"unit":"kg","note":""},{"name":"Красный винный уксус","quantity":400,"unit":"ml","note":""},{"name":"Красное сухое вино","quantity":400,"unit":"ml","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Корень сельдерея","quantity":150,"unit":"g","note":""},{"name":"Гвоздика, можжевельник, лавр, перец горошком","quantity":1,"unit":"tbsp","note":""},{"name":"Имбирные пряники","quantity":80,"unit":"g","note":"раскрошить"},{"name":"Изюм","quantity":50,"unit":"g","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Масло для жарки","quantity":2,"unit":"tbsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Прокипятите уксус с вином, овощами и специями, полностью остудите и залейте мясо. Держите в холоде три-пять дней, переворачивая раз в сутки.\nВыньте мясо, обсушите бумажным полотенцем и обжарьте в раскалённом сотейнике до тёмной корочки со всех сторон. Маринад процедите, овощи сохраните.\nОбжарьте маринованные овощи в том же жире, добавьте сахар и дайте ему слегка карамелизоваться. Влейте маринад и доведите до кипения.\nВерните мясо, накройте и тушите на слабом огне два часа, переворачивая через час. Вилка должна входить без сопротивления.\nВыньте мясо и держите в тепле. Вмешайте в соус раскрошенные пряники и изюм и варите пятнадцать минут — пряники разойдутся и соус загустеет сам.\nПробейте соус блендером до гладкости, попробуйте на баланс кислого и сладкого. Нарежьте мясо поперёк волокон и залейте соусом.","source":"UniTools"},{"id":"ut-schwaebischer-kartoffelsalat","name":"Швабский картофельный салат","country":"Германия","category":"salad","diets":["vegetarian"],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":290,"p":5,"f":14,"c":36},"details":[{"name":"Восковой картофель","quantity":800,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":"очень мелко"},{"name":"Горячий овощной бульон","quantity":250,"unit":"ml","note":""},{"name":"Винный уксус","quantity":3,"unit":"tbsp","note":""},{"name":"Горчица","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":4,"unit":"tbsp","note":""},{"name":"Зелёный лук","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите картофель в мундире до готовности — двадцать минут после закипания. Проверяйте ножом: он должен входить, но не проваливаться.\nПока варится картофель, прогрейте бульон с луком, уксусом, горчицей, солью и перцем, не доводя до кипения.\nОчистите картофель горячим — держите вилкой — и нарежьте ломтиками в три-четыре миллиметра прямо в миску.\nЗалейте горячей заправкой и оставьте на двадцать минут, перемешав один раз. Картофель впитает почти всю жидкость.\nВлейте масло, перемешайте ещё раз и попробуйте. Салат должен быть чуть кислее, чем кажется правильным, — вкус выровняется, пока он стоит.","source":"UniTools"},{"id":"ut-bucatini-all-amatriciana","name":"Аматричана","country":"Италия","category":"main","diets":[],"slots":["lunch","dinner"],"time":30,"baseServings":4,"portionNutrition":{"k":610,"p":24,"f":24,"c":74},"details":[{"name":"Букатини","quantity":400,"unit":"g","note":""},{"name":"Гуанчале","quantity":150,"unit":"g","note":"брусочками"},{"name":"Помидоры сан-марцано","quantity":400,"unit":"g","note":""},{"name":"Пекорино романо","quantity":80,"unit":"g","note":"мелко натереть"},{"name":"Сушёный перчик чили","quantity":1,"unit":"piece","note":""},{"name":"Белое сухое вино","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Положите гуанчале в холодную сухую сковороду и включите средний огонь. Медленный старт вытапливает жир целиком; на раскалённой сковороде он подгорит снаружи, оставшись жёстким внутри.\nКогда кусочки станут стеклянными и золотыми по краям, выньте половину — они пойдут сверху. Влейте вино и дайте ему выпариться.\nРазомните помидоры руками, добавьте с чили и тушите десять минут. Соус должен загустеть, но не потерять красный цвет.\nОтварите букатини на минуту меньше указанного, переложите в соус с половником воды от варки и доведите на огне полминуты.\nСнимите с огня, вмешайте пекорино и разложите. Сверху — отложенный гуанчале и ещё немного сыра.","source":"UniTools"},{"id":"ut-shakshuka","name":"Шакшука","country":"Израиль","category":"breakfast","diets":["vegetarian","gluten-free"],"slots":["breakfast"],"time":40,"baseServings":4,"portionNutrition":{"k":340,"p":18,"f":22,"c":18},"details":[{"name":"Помидоры в собственном соку","quantity":800,"unit":"g","note":""},{"name":"Красный перец","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Копчёная паприка","quantity":1,"unit":"tsp","note":""},{"name":"Хариса","quantity":1,"unit":"tsp","note":""},{"name":"Оливковое масло","quantity":3,"unit":"tbsp","note":""},{"name":"Фета и кинза","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук с перцем в масле десять минут, пока перец не станет мягким и сладким.\nДобавьте чеснок, зиру, паприку и харису и прогрейте минуту — до запаха, но не до горелого.\nВлейте помидоры, разомните и тушите пятнадцать минут. Соус готов, когда ложка оставляет след на дне.\nСделайте ложкой углубления и разбейте в каждое яйцо. Накройте крышкой и держите пять-семь минут: белок должен схватиться, желток остаться жидким.\nПосыпьте фетой и кинзой и подавайте прямо в сковороде с хлебом.","source":"UniTools"},{"id":"ut-hummus","name":"Хумус","country":"Израиль","category":"snack","diets":["vegetarian","vegan","gluten-free"],"slots":["snack"],"time":110,"baseServings":6,"portionNutrition":{"k":320,"p":12,"f":20,"c":26},"details":[{"name":"Сухой нут","quantity":250,"unit":"g","note":"замочить на ночь"},{"name":"Сода пищевая","quantity":1,"unit":"tsp","note":""},{"name":"Тахини","quantity":150,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":"сок"},{"name":"Чеснок","quantity":2,"unit":"clove","note":""},{"name":"Ледяная вода","quantity":80,"unit":"ml","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Оливковое масло","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Слейте воду с замоченного нута, залейте свежей с содой и варите час-полтора до полного разваливания. Пену и всплывшую кожицу снимайте.\nОткиньте, оставив стакан отвара. Перетрите нут между ладонями под холодной водой — оставшаяся кожица всплывёт.\nПробейте тахини с чесноком, лимонным соком и солью в блендере — паста побелеет и загустеет. Влейте ледяную воду и взбейте ещё раз: она станет светлой и воздушной.\nДобавьте тёплый нут с зирой и взбивайте не меньше трёх минут, подливая отвар до нужной густоты. Три минуты — не преувеличение, именно они дают текстуру.\nВыложите в тарелку, разгоните ложкой по кругу, залейте оливковым маслом и посыпьте зирой.","source":"UniTools"},{"id":"ut-feijoada","name":"Фейжоада","country":"Бразилия","category":"main","diets":[],"slots":["lunch","dinner"],"time":220,"baseServings":8,"portionNutrition":{"k":780,"p":46,"f":38,"c":62},"details":[{"name":"Чёрная фасоль","quantity":700,"unit":"g","note":"замочить на ночь"},{"name":"Солёная свинина","quantity":400,"unit":"g","note":"вымочить 12 часов"},{"name":"Копчёные рёбрышки","quantity":500,"unit":"g","note":""},{"name":"Копчёная колбаса","quantity":300,"unit":"g","note":""},{"name":"Свиная грудинка","quantity":300,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Апельсин","quantity":2,"unit":"piece","note":""},{"name":"Капуста кале","quantity":300,"unit":"g","note":"тонкой соломкой"},{"name":"Варёный рис","quantity":600,"unit":"g","note":""},{"name":"Растительное масло","quantity":2,"unit":"tbsp","note":""}],"steps":"Отварите солёное мясо в свежей воде двадцать минут и слейте — это последний шаг избавления от соли.\nЗалейте фасоль водой на три пальца выше, добавьте лавровый лист, рёбрышки и солёное мясо и варите полтора часа на слабом огне.\nДобавьте грудинку и колбасу и варите ещё час. Фасоль должна разваливаться, а бульон — загустеть сам собой.\nОбжарьте лук с чесноком до золотистого цвета, добавьте половник фасоли, разомните и верните в кастрюлю. Это загустит блюдо и добавит глубины.\nОбжарьте капусту на сильном огне две минуты с чесноком — она должна остаться ярко-зелёной и хрустящей.\nПодавайте фасоль с мясом, отдельно рис, капусту и дольки апельсина. Каждый собирает тарелку сам.","source":"UniTools"},{"id":"ut-pao-de-queijo","name":"Пан-ди-кейжу","country":"Бразилия","category":"bread","diets":["vegetarian","gluten-free"],"slots":["breakfast","snack"],"time":50,"baseServings":6,"portionNutrition":{"k":380,"p":12,"f":20,"c":40},"details":[{"name":"Тапиоковый крахмал","quantity":500,"unit":"g","note":""},{"name":"Молоко","quantity":250,"unit":"ml","note":""},{"name":"Вода","quantity":100,"unit":"ml","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Пармезан","quantity":200,"unit":"g","note":"натереть"},{"name":"Моцарелла","quantity":100,"unit":"g","note":"натереть"},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Доведите молоко с водой, маслом и солью почти до кипения.\nВылейте всю горячую жидкость в крахмал разом и размешайте лопаткой. Масса будет комковатой и странной — так и должно быть. Дайте остыть до тёплого.\nВмешайте яйца по одному, а затем оба сыра. Вымешивайте до однородной липкой массы — руками проще, чем ложкой.\nМокрыми руками скатайте шарики размером с грецкий орех и разложите на противне с зазором в три сантиметра.\nВыпекайте при 200 °C двадцать минут до золотого цвета. Дверцу не открывайте первые пятнадцать: пар выйдет и шарики осядут.","source":"UniTools"},{"id":"ut-pad-krapow-moo","name":"Пад кра пао","country":"Таиланд","category":"main","diets":[],"slots":["lunch","dinner"],"time":18,"baseServings":2,"portionNutrition":{"k":680,"p":36,"f":34,"c":56},"details":[{"name":"Свиной фарш","quantity":300,"unit":"g","note":"крупного помола"},{"name":"Священный базилик","quantity":40,"unit":"g","note":""},{"name":"Тайский чили","quantity":5,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Устричный соус","quantity":2,"unit":"tbsp","note":""},{"name":"Рыбный соус","quantity":1,"unit":"tbsp","note":""},{"name":"Тёмный соевый соус","quantity":1,"unit":"tsp","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Варёный рис","quantity":300,"unit":"g","note":""},{"name":"Растительное масло","quantity":4,"unit":"tbsp","note":""}],"steps":"Растолките чеснок с чили в ступке до грубой пасты. Ступка здесь даёт другой результат, чем нож: сок выходит наружу и попадает в масло.\nСмешайте устричный соус, рыбный, соевый и сахар в чашке — на жарке времени не будет.\nРаскалите вок с двумя ложками масла, бросьте пасту и жарьте двадцать секунд до запаха.\nВыложите фарш и не трогайте минуту, потом разбейте лопаткой и жарьте ещё две. Влейте соус и дайте ему обволочь мясо.\nСнимите с огня и вмешайте базилик — от остаточного тепла он опадёт за секунды. На той же сковороде обжарьте яйца в оставшемся масле до кружевных краёв.","source":"UniTools"},{"id":"ut-gyudon","name":"Гюдон","country":"Япония","category":"main","diets":[],"slots":["lunch","dinner"],"time":25,"baseServings":2,"portionNutrition":{"k":640,"p":34,"f":18,"c":82},"details":[{"name":"Говядина","quantity":300,"unit":"g","note":"нарезать почти прозрачно"},{"name":"Лук","quantity":1,"unit":"piece","note":"тонкими полукольцами"},{"name":"Даси","quantity":200,"unit":"ml","note":""},{"name":"Соевый соус","quantity":3,"unit":"tbsp","note":""},{"name":"Мирин","quantity":3,"unit":"tbsp","note":""},{"name":"Сакэ","quantity":2,"unit":"tbsp","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Имбирь","quantity":10,"unit":"g","note":""},{"name":"Варёный рис","quantity":400,"unit":"g","note":""},{"name":"Маринованный имбирь бени сёга","quantity":null,"unit":"toTaste","note":""}],"steps":"Доведите даси с соевым соусом, мирином, сакэ, сахаром и тёртым имбирём до кипения в широкой сковороде.\nПоложите лук и варите пять минут на среднем огне, пока он не станет полупрозрачным.\nРазложите мясо по поверхности отдельными ломтиками, не кучей, и варите две-три минуты. Пену снимайте.\nСнимите с огня, как только мясо потеряет розовый цвет. Передержанное станет жёстким за минуту.\nРазложите рис по мискам, сверху мясо с луком и две-три ложки бульона. Подавайте с маринованным имбирём.","source":"UniTools"},{"id":"ut-solyanka","name":"Солянка мясная сборная","country":"Россия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":145,"baseServings":6,"portionNutrition":{"k":420,"p":32,"f":26,"c":12},"details":[{"name":"Говядина на кости","quantity":500,"unit":"g","note":""},{"name":"Копчёные рёбрышки","quantity":200,"unit":"g","note":""},{"name":"Варёная колбаса","quantity":150,"unit":"g","note":"соломкой"},{"name":"Ветчина","quantity":150,"unit":"g","note":"соломкой"},{"name":"Солёные огурцы","quantity":4,"unit":"piece","note":"соломкой"},{"name":"Огуречный рассол","quantity":150,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Оливки и каперсы","quantity":100,"unit":"g","note":""},{"name":"Лимон","quantity":null,"unit":"toTaste","note":""},{"name":"Сметана и зелень","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Сварите бульон из говядины и копчёных рёбрышек: полтора часа на слабом огне, снимая пену. Мясо выньте и разберите.\nОбжарьте лук до мягкости, добавьте томатную пасту и жарьте три минуты, пока она не потемнеет и не перестанет пахнуть сырой.\nДобавьте огурцы и потушите пять минут с зажаркой — так они не будут жёсткими в готовом супе.\nЗаложите в бульон зажарку, разобранное мясо, колбасу и ветчину, влейте рассол и варите пятнадцать минут.\nДобавьте оливки с каперсами, прогрейте пять минут и снимите с огня. Пробуйте на соль только сейчас: рассол и копчёности уже посолили суп.\nВ тарелку — кружок лимона, сметана и зелень. Лимон кладут именно в тарелку: проваренный, он даст горечь.","source":"UniTools"},{"id":"ut-tagine-de-poulet","name":"Тажин с курицей и лимоном","country":"Марокко","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":95,"baseServings":4,"portionNutrition":{"k":560,"p":44,"f":36,"c":12},"details":[{"name":"Курица, разделанная","quantity":1.4,"unit":"kg","note":""},{"name":"Солёный лимон","quantity":2,"unit":"piece","note":"только кожура"},{"name":"Зелёные оливки","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":"тонкими полукольцами"},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Молотый имбирь","quantity":1,"unit":"tsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Кинза и петрушка","quantity":6,"unit":"sprig","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Вода","quantity":200,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разотрите чеснок, имбирь, куркуму, шафран, рубленую зелень, масло, соль и перец в пасту. Обмажьте ею курицу и оставьте на час.\nВыложите лук ровным слоем на дно тажина или тяжёлого сотейника — он не даст курице пригореть и станет частью соуса.\nУложите курицу кожей вверх, влейте воду по краю, накройте и томите на слабом огне сорок минут, не открывая.\nДобавьте кожуру солёного лимона полосками и оливки, накройте и держите ещё двадцать минут.\nСнимите крышку и выпарьте соус пять минут до густоты, если он остался жидким. Пробуйте на соль в самом конце: лимон и оливки уже солёные.","source":"UniTools"},{"id":"ut-harira","name":"Харира","country":"Марокко","category":"soup","diets":[],"slots":["lunch","dinner"],"time":115,"baseServings":6,"portionNutrition":{"k":380,"p":22,"f":12,"c":46},"details":[{"name":"Баранина","quantity":300,"unit":"g","note":"мелким кубиком"},{"name":"Нут","quantity":150,"unit":"g","note":"замочить на ночь"},{"name":"Зелёная чечевица","quantity":100,"unit":"g","note":""},{"name":"Помидоры","quantity":600,"unit":"g","note":"натереть"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Стебель сельдерея","quantity":2,"unit":"piece","note":""},{"name":"Кинза и петрушка","quantity":60,"unit":"g","note":""},{"name":"Молотый имбирь","quantity":1,"unit":"tsp","note":""},{"name":"Корица","quantity":0.5,"unit":"tsp","note":""},{"name":"Мука","quantity":4,"unit":"tbsp","note":""},{"name":"Вермишель","quantity":60,"unit":"g","note":""},{"name":"Лимон","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте баранину с луком, имбирём и корицей пять минут, добавьте рубленые сельдерей и зелень и прогрейте ещё две.\nДобавьте тёртые помидоры и нут, залейте двумя литрами воды и варите час на слабом огне, пока нут не станет мягким.\nЗаложите чечевицу и варите ещё двадцать минут.\nРазмешайте муку в стакане холодной воды до полной гладкости и влейте тонкой струйкой, непрерывно помешивая. Варите пять минут — суп загустеет и станет матовым.\nВсыпьте вермишель и варите до готовности. Подавайте с лимоном и финиками — эта пара не случайна: сладкое и кислое разом.","source":"UniTools"},{"id":"ut-goulash","name":"Гуляш","country":"Венгрия","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":170,"baseServings":6,"portionNutrition":{"k":520,"p":42,"f":24,"c":32},"details":[{"name":"Говяжья голяшка или лопатка","quantity":1,"unit":"kg","note":"кубиком 3 см"},{"name":"Лук","quantity":1,"unit":"kg","note":"мелко нарезать"},{"name":"Сладкая паприка","quantity":3,"unit":"tbsp","note":""},{"name":"Тмин","quantity":1,"unit":"tsp","note":""},{"name":"Сладкий перец","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Смалец или масло","quantity":3,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Томите лук в смальце на слабом огне двадцать минут до мягкости и золотистого цвета. Это долго и кажется бессмысленным, но именно здесь появляется сладость соуса.\nСнимите с огня, всыпьте паприку и тмин и размешайте. Через полминуты верните на огонь и добавьте мясо.\nТушите мясо с луком под крышкой полчаса, не добавляя воды: оно даст сок сам. Только потом влейте воду вровень с мясом.\nВарите на слабом огне полтора часа. Добавьте перец, помидоры и чеснок за сорок минут до конца, картофель — за двадцать пять.\nПосолите в самом конце и дайте постоять пятнадцать минут перед подачей.","source":"UniTools"},{"id":"ut-langos","name":"Лангош","country":"Венгрия","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":110,"baseServings":4,"portionNutrition":{"k":640,"p":18,"f":32,"c":68},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Картофель","quantity":150,"unit":"g","note":"отварной, размять"},{"name":"Тёплое молоко","quantity":200,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Сметана","quantity":200,"unit":"g","note":""},{"name":"Твёрдый сыр","quantity":150,"unit":"g","note":"натереть"},{"name":"Масло для фритюра","quantity":700,"unit":"ml","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Распустите дрожжи с сахаром в тёплом молоке и оставьте на десять минут до пены.\nСмешайте муку, размятый картофель, соль и опару и вымешивайте восемь минут до гладкого мягкого теста. Оно останется липковатым — так и надо.\nНакройте и дайте подойти час в тепле — тесто должно увеличиться вдвое.\nРазделите на четыре части, растяните каждую руками в круг сантиметров двадцать, оставляя края толще.\nЖарьте во фритюре при 175 °C по полторы минуты с каждой стороны. Лепёшка вздуется — так и должно быть, придавливать не нужно.\nГорячую лепёшку натрите разрезанной долькой чеснока, намажьте сметаной и засыпьте сыром.","source":"UniTools"},{"id":"ut-fish-and-chips","name":"Фиш-энд-чипс","country":"Великобритания","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":890,"p":46,"f":40,"c":88},"details":[{"name":"Филе трески","quantity":800,"unit":"g","note":"кусками по 200 г"},{"name":"Картофель","quantity":1,"unit":"kg","note":"брусками 1,5 см"},{"name":"Мука","quantity":200,"unit":"g","note":""},{"name":"Кукурузный крахмал","quantity":50,"unit":"g","note":""},{"name":"Светлое пиво","quantity":300,"unit":"ml","note":"ледяное"},{"name":"Разрыхлитель","quantity":1,"unit":"tsp","note":""},{"name":"Масло для фритюра","quantity":1.5,"unit":"l","note":""},{"name":"Солодовый уксус","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте нарезанный картофель от крахмала, обсушите досуха и обжарьте при 140 °C шесть минут. Он должен стать мягким, но остаться бледным. Выложите остывать.\nСмешайте муку, крахмал и разрыхлитель. Влейте ледяное пиво и размешайте венчиком буквально несколько раз — комочки допустимы, перемешанный кляр становится жёстким.\nОбсушите рыбу, обваляйте в сухой муке и стряхните излишки. Без этого шага кляр соскользнёт при жарке.\nРазогрейте масло до 190 °C. Окуните рыбу в кляр, дайте лишнему стечь и опустите, придерживая пару секунд, чтобы кусок не прилип ко дну. Жарьте шесть минут.\nВыньте рыбу и в том же масле дожарьте картофель три минуты до золотого цвета. Посолите сразу, пока горячий.","source":"UniTools"},{"id":"ut-shepherds-pie","name":"Пастуший пирог","country":"Великобритания","category":"main","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":620,"p":34,"f":32,"c":48},"details":[{"name":"Фарш из баранины","quantity":700,"unit":"g","note":""},{"name":"Картофель","quantity":1,"unit":"kg","note":"рассыпчатый"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Зелёный горошек","quantity":150,"unit":"g","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Вустерский соус","quantity":2,"unit":"tbsp","note":""},{"name":"Мясной бульон","quantity":300,"unit":"ml","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Молоко","quantity":120,"unit":"ml","note":""},{"name":"Тимьян","quantity":3,"unit":"sprig","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте фарш на сильном огне, не перемешивая первую минуту, до тёмных подпалин. Выложите, слив лишний жир.\nВ том же сотейнике обжарьте лук с морковью восемь минут, добавьте муку и томатную пасту и прогрейте две минуты.\nВерните мясо, влейте бульон и вустерский соус, добавьте тимьян и тушите двадцать минут без крышки, пока соус не станет густым.\nОтварите картофель, разомните с маслом и горячим молоком до гладкости, посолите щедро. Пюре должно быть плотным, а не текучим.\nВмешайте горошек в мясо, переложите в форму, накройте пюре и разровняйте вилкой, оставив бороздки.\nЗапекайте при 200 °C двадцать пять минут до румяной корочки. Дайте постоять десять минут перед тем, как резать.","source":"UniTools"},{"id":"ut-wiener-schnitzel","name":"Венский шницель","country":"Австрия","category":"main","diets":[],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":680,"p":44,"f":38,"c":38},"details":[{"name":"Телячий эскалоп","quantity":4,"unit":"piece","note":"по 150 г"},{"name":"Мука","quantity":80,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Панировочные сухари","quantity":200,"unit":"g","note":"мелкие, из белого хлеба"},{"name":"Топлёное масло или смалец","quantity":400,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отбейте мясо между двумя листами плёнки до трёх миллиметров. Бейте плоской стороной молотка, а не зубчатой: зубцы рвут волокна.\nВзбейте яйца вилкой до однородности, но без пены. Посолите мясо и обваляйте по очереди в муке, яйце и сухарях.\nСухари прижимать нельзя. Панировка должна лежать свободно — только тогда она отойдёт и вздуется.\nРазогрейте жир слоем в сантиметр до 170 °C и опустите шницель. Жарьте две минуты, всё время покачивая сковороду, чтобы жир набегал сверху.\nПереверните и жарьте ещё полторы минуты до золотого цвета. Выложите на решётку и подавайте немедленно с долькой лимона.","source":"UniTools"},{"id":"ut-apfelstrudel","name":"Яблочный штрудель","country":"Австрия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":105,"baseServings":8,"portionNutrition":{"k":420,"p":5,"f":16,"c":66},"details":[{"name":"Мука высокобелковая","quantity":250,"unit":"g","note":""},{"name":"Тёплая вода","quantity":125,"unit":"ml","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Кислые яблоки","quantity":1,"unit":"kg","note":"тонкими ломтиками"},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Корица","quantity":2,"unit":"tsp","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Панировочные сухари","quantity":80,"unit":"g","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":"сок и цедра"}],"steps":"Замесите тесто из муки, тёплой воды, масла и щепотки соли и вымешивайте десять минут — оно должно стать гладким и очень эластичным. Смажьте маслом, накройте и оставьте на час.\nОбжарьте сухари в половине масла до золотистого цвета. Яблоки смешайте с сахаром, корицей, изюмом, соком и цедрой лимона.\nРасстелите на столе полотенце, присыпьте мукой и растяните тесто тыльной стороной ладоней от центра к краям, пока оно не станет прозрачным. Толстые края обрежьте.\nСмажьте тесто растопленным маслом, посыпьте сухарями треть поверхности и выложите на них яблоки, отступив от краёв.\nЗаверните рулетом, поднимая полотенце, — руками тесто порвётся. Подверните края, переложите швом вниз и смажьте маслом.\nВыпекайте при 190 °C сорок минут, смазывая маслом дважды за это время. Подавайте тёплым с сахарной пудрой.","source":"UniTools"},{"id":"ut-bacalhau-a-bras","name":"Бакаляу а браш","country":"Португалия","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":610,"p":42,"f":34,"c":34},"details":[{"name":"Солёная треска","quantity":500,"unit":"g","note":"вымочить сутки"},{"name":"Картофель","quantity":700,"unit":"g","note":"тонкой соломкой"},{"name":"Яйца","quantity":8,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":"тонкими полукольцами"},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Чёрные оливки","quantity":80,"unit":"g","note":""},{"name":"Петрушка","quantity":6,"unit":"sprig","note":""},{"name":"Масло для фритюра","quantity":600,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите вымоченную треску пять минут, остудите и разберите руками на волокна, выбрасывая кожу и кости. Руками, а не вилкой: так чувствуешь мелкие косточки.\nОбжарьте картофельную соломку во фритюре при 180 °C до золотистого хруста, партиями. Выложите на решётку и посолите.\nВ широкой сковороде томите лук в оливковом масле десять минут до мягкости и сладости, добавьте чеснок на последнюю минуту.\nДобавьте треску и прогрейте три минуты, затем всыпьте картофель и перемешайте.\nСнимите сковороду с огня, влейте взбитые яйца и мешайте непрерывно полминуты, пока они не станут кремовыми. Посыпьте петрушкой и оливками.","source":"UniTools"},{"id":"ut-pastel-de-nata","name":"Паштел де ната","country":"Португалия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":55,"baseServings":12,"portionNutrition":{"k":290,"p":4,"f":16,"c":33},"details":[{"name":"Слоёное тесто","quantity":400,"unit":"g","note":""},{"name":"Молоко","quantity":250,"unit":"ml","note":""},{"name":"Сливки 33 %","quantity":250,"unit":"ml","note":""},{"name":"Сахар","quantity":200,"unit":"g","note":""},{"name":"Вода","quantity":100,"unit":"ml","note":""},{"name":"Мука","quantity":40,"unit":"g","note":""},{"name":"Желтки","quantity":6,"unit":"piece","note":""},{"name":"Палочка корицы","quantity":1,"unit":"piece","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""}],"steps":"Сварите сироп из сахара и воды до 100 °C и снимите. Отдельно доведите молоко со сливками, корицей и цедрой почти до кипения.\nРазмешайте муку в небольшом количестве холодного молока до гладкости и вмешайте в горячее. Варите, помешивая, до густоты сметаны.\nВлейте горячий сироп тонкой струйкой в молочную основу, снимите с огня и вмешайте желтки. Процедите и полностью остудите.\nСверните тесто в плотный рулет, нарежьте шайбами по два сантиметра и вдавите каждую в форму большими пальцами, поднимая стенки выше края.\nРазогрейте духовку до максимума, минимум 250 °C. Налейте крем на три четверти и выпекайте двенадцать-пятнадцать минут до чёрных пятен.","source":"UniTools"},{"id":"ut-empanadas-argentinas","name":"Аргентинские эмпанадас","country":"Аргентина","category":"snack","diets":[],"slots":["snack"],"time":75,"baseServings":6,"portionNutrition":{"k":520,"p":26,"f":28,"c":42},"details":[{"name":"Говядина","quantity":600,"unit":"g","note":"порубить ножом"},{"name":"Лук","quantity":4,"unit":"piece","note":"мелким кубиком"},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":"варёные, рубленые"},{"name":"Зелёные оливки","quantity":80,"unit":"g","note":""},{"name":"Сладкая паприка","quantity":2,"unit":"tsp","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Хлопья чили","quantity":1,"unit":"tsp","note":""},{"name":"Тесто для эмпанадас","quantity":24,"unit":"piece","note":""},{"name":"Смалец или масло","quantity":3,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук в смальце на среднем огне пятнадцать минут до мягкости и прозрачности, не давая ему темнеть.\nДобавьте рубленое мясо, паприку, зиру и чили и жарьте пять минут — мясо должно только потерять розовый цвет, не более.\nПосолите, снимите с огня и полностью остудите, затем уберите в холодильник минимум на четыре часа.\nВмешайте в холодную начинку рубленые яйца, оливки и зелёный лук.\nНа кружок теста положите столовую ложку начинки, смочите край водой, сложите пополам и защипните косичкой репульге, подворачивая уголки внахлёст.\nСмажьте желтком и выпекайте при 220 °C двадцать минут до румяного цвета.","source":"UniTools"},{"id":"ut-chimichurri","name":"Чимичурри","country":"Аргентина","category":"sauce","diets":["vegetarian","vegan","gluten-free"],"slots":[],"time":15,"baseServings":8,"portionNutrition":{"k":190,"p":1,"f":20,"c":2},"details":[{"name":"Петрушка","quantity":60,"unit":"g","note":"мелко порубить"},{"name":"Сушёный орегано","quantity":2,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Хлопья чили","quantity":1,"unit":"tsp","note":""},{"name":"Красный винный уксус","quantity":60,"unit":"ml","note":""},{"name":"Оливковое масло","quantity":180,"unit":"ml","note":""},{"name":"Тёплая вода","quantity":60,"unit":"ml","note":""},{"name":"Крупная соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите соль в тёплой воде — так она разойдётся равномерно, а не осядет на дно банки.\nРазотрите сушёный орегано между ладонями и залейте уксусом на пять минут — он размягчится и отдаст аромат.\nМелко порубите петрушку и чеснок ножом. Чеснок именно рубят, а не давят: давленый даёт резкость, которая не уйдёт.\nСмешайте всё, влейте масло и размешайте. Дайте постоять два часа при комнатной температуре.","source":"UniTools"},{"id":"ut-nasi-goreng","name":"Наси горенг","country":"Индонезия","category":"main","diets":[],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":620,"p":34,"f":22,"c":70},"details":[{"name":"Варёный рис","quantity":600,"unit":"g","note":"вчерашний, холодный"},{"name":"Куриное филе","quantity":250,"unit":"g","note":"кубиком"},{"name":"Креветки","quantity":150,"unit":"g","note":""},{"name":"Шалот","quantity":4,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Красный чили","quantity":3,"unit":"piece","note":""},{"name":"Креветочная паста терази","quantity":1,"unit":"tsp","note":""},{"name":"Кечап манис","quantity":3,"unit":"tbsp","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Капуста","quantity":150,"unit":"g","note":"нашинковать"},{"name":"Огурец и жареный лук","quantity":null,"unit":"toTaste","note":""},{"name":"Растительное масло","quantity":4,"unit":"tbsp","note":""}],"steps":"Растолките шалот, чеснок, чили и терази в ступке в пасту. Она должна пахнуть резко — так и должно быть, при жарке запах смягчится.\nРаскалите вок, обжарьте пасту в масле две минуты до тёмного цвета и глубокого аромата.\nДобавьте курицу и жарьте три минуты, затем креветки и капусту — ещё две.\nВсыпьте холодный рис, разбивая комки лопаткой, влейте кечап манис и жарьте на сильном огне три минуты, постоянно подбрасывая.\nОтдельно пожарьте яйца до кружевных краёв и жидкого желтка. Подавайте рис с яйцом сверху, ломтиками огурца и жареным луком.","source":"UniTools"},{"id":"ut-rendang","name":"Ренданг","country":"Индонезия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":270,"baseServings":6,"portionNutrition":{"k":720,"p":46,"f":52,"c":14},"details":[{"name":"Говяжья голяшка","quantity":1.2,"unit":"kg","note":"крупным кубиком"},{"name":"Кокосовое молоко","quantity":1.2,"unit":"l","note":""},{"name":"Шалот","quantity":8,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Сушёный чили","quantity":10,"unit":"piece","note":""},{"name":"Галангал","quantity":40,"unit":"g","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Свежая куркума","quantity":20,"unit":"g","note":""},{"name":"Лемонграсс","quantity":3,"unit":"piece","note":""},{"name":"Листья кафрского лайма","quantity":6,"unit":"piece","note":""},{"name":"Обжаренная кокосовая стружка","quantity":60,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите сушёный чили в кипятке на пятнадцать минут, затем пробейте с шалотом, чесноком, галангалом, имбирём и куркумой в гладкую пасту.\nОбжарьте кокосовую стружку на сухой сковороде до тёмно-коричневого цвета и растолките в маслянистую массу — это керисик, он даст ореховую глубину.\nОбжарьте пасту в широкой кастрюле пять минут, добавьте мясо, кокосовое молоко, отбитый лемонграсс и листья лайма. Доведите до кипения.\nВарите на слабом огне без крышки два с половиной часа, помешивая каждые двадцать минут. Соус будет постепенно густеть и темнеть.\nВмешайте керисик и продолжайте на среднем огне ещё час, помешивая всё чаще. Молоко расслоится, выделится масло, и мясо начнёт жариться.\nГотово, когда мясо тёмно-коричневое и почти сухое, а масло прозрачное. Посолите и дайте постоять.","source":"UniTools"},{"id":"ut-adobo","name":"Адобо","country":"Филиппины","category":"main","diets":[],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":580,"p":44,"f":26,"c":42},"details":[{"name":"Куриные бёдра","quantity":1,"unit":"kg","note":""},{"name":"Соевый соус","quantity":120,"unit":"ml","note":""},{"name":"Тростниковый или рисовый уксус","quantity":120,"unit":"ml","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Лавровый лист","quantity":4,"unit":"piece","note":""},{"name":"Чёрный перец горошком","quantity":1,"unit":"tsp","note":""},{"name":"Тростниковый сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Вода","quantity":200,"unit":"ml","note":""},{"name":"Растительное масло","quantity":2,"unit":"tbsp","note":""},{"name":"Варёный рис","quantity":400,"unit":"g","note":""}],"steps":"Замаринуйте курицу в соевом соусе с раздавленным чесноком и перцем на тридцать минут.\nВыньте курицу, обсушите и обжарьте кожей вниз до румяной корочки. Маринад сохраните.\nВлейте маринад, воду и уксус, добавьте лавровый лист и сахар. Доведите до кипения и не мешайте и не накрывайте десять минут.\nНакройте и тушите на слабом огне двадцать пять минут, перевернув курицу один раз.\nСнимите крышку и уварите соус пять-десять минут до густоты, поливая им курицу. Подавайте с рисом.","source":"UniTools"},{"id":"ut-sinigang","name":"Синиганг","country":"Филиппины","category":"soup","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":6,"portionNutrition":{"k":460,"p":34,"f":26,"c":24},"details":[{"name":"Свиные рёбрышки","quantity":800,"unit":"g","note":""},{"name":"Тамариндовая паста","quantity":4,"unit":"tbsp","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Дайкон","quantity":200,"unit":"g","note":"кружками"},{"name":"Таро или картофель","quantity":300,"unit":"g","note":""},{"name":"Стручковая фасоль","quantity":150,"unit":"g","note":""},{"name":"Баклажан","quantity":1,"unit":"piece","note":""},{"name":"Канконг или шпинат","quantity":150,"unit":"g","note":""},{"name":"Зелёный чили","quantity":2,"unit":"piece","note":""},{"name":"Рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Вода","quantity":2,"unit":"l","note":""}],"steps":"Залейте рёбрышки водой, доведите до кипения, снимите пену и варите час на слабом огне с луком и помидорами.\nРазомните разварившиеся помидоры прямо в кастрюле — они дадут телу супа густоту.\nДобавьте тамариндовую пасту и рыбный соус, попробуйте. Кислота должна быть отчётливой, а не намёком.\nЗаложите таро и дайкон, варите десять минут, потом баклажан и фасоль — ещё пять.\nБросьте зелень и чили, снимите с огня через тридцать секунд. Зелень должна остаться яркой.","source":"UniTools"},{"id":"ut-borshch-ukrainskyi","name":"Украинский борщ с пампушками","country":"Украина","category":"soup","diets":[],"slots":["lunch","dinner"],"time":160,"baseServings":6,"portionNutrition":{"k":480,"p":26,"f":28,"c":32},"details":[{"name":"Свиные рёбрышки","quantity":700,"unit":"g","note":""},{"name":"Свёкла","quantity":3,"unit":"piece","note":"соломкой"},{"name":"Капуста","quantity":400,"unit":"g","note":""},{"name":"Картофель","quantity":4,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Белая фасоль","quantity":150,"unit":"g","note":"варёная"},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Старое сало","quantity":80,"unit":"g","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Укроп и петрушка","quantity":6,"unit":"sprig","note":""},{"name":"Уксус","quantity":1,"unit":"tbsp","note":""},{"name":"Сметана","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Сварите бульон на рёбрышках: полтора часа на слабом огне со снятой пеной. Мясо выньте и разберите.\nТушите свёклу отдельно с ложкой масла, томатной пастой и уксусом двадцать минут под крышкой. Уксус здесь и удерживает цвет.\nОбжарьте лук с морковью до мягкости. Заложите в бульон картофель и варите десять минут — до того, как в кастрюлю попадёт кислота.\nДобавьте капусту, через пять минут — свёклу, зажарку и фасоль. Проварите пять минут.\nРазотрите сало с чесноком и зеленью в ступке до пасты и вмешайте в кастрюлю. Сразу снимите с огня и дайте настояться двадцать минут под крышкой.","source":"UniTools"},{"id":"ut-varenyky-z-vyshnyamy","name":"Вареники с вишней","country":"Украина","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":65,"baseServings":4,"portionNutrition":{"k":520,"p":12,"f":12,"c":92},"details":[{"name":"Мука","quantity":450,"unit":"g","note":""},{"name":"Кефир","quantity":250,"unit":"ml","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Сода","quantity":0.5,"unit":"tsp","note":""},{"name":"Вишня без косточек","quantity":600,"unit":"g","note":""},{"name":"Сахар","quantity":120,"unit":"g","note":""},{"name":"Крахмал","quantity":3,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Сметана","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Смешайте кефир с содой и оставьте на пять минут — пойдут пузыри. Добавьте яйцо, соль и муку и вымешивайте восемь минут.\nНакройте тесто и дайте отдохнуть полчаса. За это время дайте вишне стечь на дуршлаге.\nСмешайте крахмал с сахаром и обваляйте в них вишню непосредственно перед лепкой.\nРаскатайте тесто в два миллиметра, вырежьте кружки, положите по три-четыре ягоды и защипните край насухо, выпуская воздух.\nВарите в широкой кастрюле подсоленного кипятка партиями. Через две минуты после всплытия вынимайте шумовкой и сразу смазывайте маслом.","source":"UniTools"},{"id":"ut-svickova","name":"Свичкова","country":"Чехия","category":"main","diets":[],"slots":["lunch","dinner"],"time":190,"baseServings":6,"portionNutrition":{"k":680,"p":48,"f":42,"c":24},"details":[{"name":"Говяжья вырезка или огузок","quantity":1.2,"unit":"kg","note":""},{"name":"Копчёное сало","quantity":80,"unit":"g","note":"для шпигования"},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Корень сельдерея","quantity":200,"unit":"g","note":""},{"name":"Корень петрушки","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сливки 33 %","quantity":250,"unit":"ml","note":""},{"name":"Винный уксус","quantity":3,"unit":"tbsp","note":""},{"name":"Душистый перец, тимьян, лавр","quantity":1,"unit":"tbsp","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Брусничный соус","quantity":null,"unit":"toTaste","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""}],"steps":"Нашпигуйте мясо полосками копчёного сала, уложив их вдоль волокон. Обложите тёртыми кореньями со специями и уксусом и держите в холоде сутки.\nОбсушите мясо и обжарьте в масле со всех сторон до тёмной корочки. Выньте.\nВ том же сотейнике обжарьте коренья из маринада с луком двадцать минут — они должны заметно потемнеть, это даёт соусу цвет.\nВерните мясо, влейте маринад и воду вровень с овощами и тушите под крышкой два часа на слабом огне.\nВыньте мясо, удалите лавровый лист и пробейте овощи с бульоном блендером до гладкости. Протрите через сито — это тот шаг, который отличает домашнюю свичкову от ресторанной.\nВмешайте сливки, сок лимона и сахар, прогрейте не доводя до кипения и попробуйте. Мясо нарежьте поперёк волокон и подайте с соусом, брусникой и долькой лимона.","source":"UniTools"},{"id":"ut-trdelnik","name":"Трдельник","country":"Чехия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":110,"baseServings":6,"portionNutrition":{"k":470,"p":9,"f":18,"c":68},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Тёплое молоко","quantity":220,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Сахар в тесто","quantity":60,"unit":"g","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":"мягкое"},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Сахар для обваливания","quantity":150,"unit":"g","note":""},{"name":"Грецкие орехи","quantity":100,"unit":"g","note":"мелко порубить"},{"name":"Корица","quantity":2,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Распустите дрожжи с ложкой сахара в тёплом молоке, дайте вспениться десять минут.\nЗамесите тесто из муки, опары, яиц, сахара и соли, вымешивайте десять минут, затем вмешивайте мягкое масло по кусочку. Дайте подойти час.\nРаскатайте тесто и нарежьте полосками шириной два сантиметра. Смажьте валики маслом и обваляйте в сахаре.\nНамотайте полоску на валик внахлёст на треть ширины, слегка натягивая. Прокатайте по столу, чтобы слои сцепились.\nСмажьте маслом, обваляйте в смеси сахара с орехами и корицей и запекайте при 190 °C восемнадцать минут, поворачивая каждые пять.\nДайте остыть три минуты и снимите с валика, провернув. Горячий трдельник рвётся, полностью остывший прилипает.","source":"UniTools"},{"id":"ut-koettbullar","name":"Шведские фрикадельки","country":"Швеция","category":"main","diets":[],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":690,"p":38,"f":48,"c":24},"details":[{"name":"Говяжий фарш","quantity":400,"unit":"g","note":""},{"name":"Свиной фарш","quantity":200,"unit":"g","note":""},{"name":"Белый хлеб","quantity":60,"unit":"g","note":"без корок"},{"name":"Сливки","quantity":300,"unit":"ml","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":"очень мелко"},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Душистый перец молотый","quantity":0.5,"unit":"tsp","note":""},{"name":"Говяжий бульон","quantity":300,"unit":"ml","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Соевый соус","quantity":1,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Брусничное варенье","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите хлеб в ста миллилитрах сливок на десять минут и разомните в кашицу.\nОбжарьте лук в масле до мягкости и полностью остудите — тёплый лук начнёт готовить фарш.\nСмешайте оба фарша с панадой, луком, яйцом, душистым перцем и солью и вымешивайте пять минут до липкости.\nСкатайте шарики размером с грецкий орех мокрыми руками и обжарьте в масле партиями, встряхивая сковороду, чтобы они катались и румянились равномерно.\nВ той же сковороде размешайте муку с оставшимся жиром, влейте бульон и остальные сливки, добавьте соевый соус и варите пять минут до густоты.\nВерните фрикадельки в соус и прогрейте пять минут. Подавайте с картофельным пюре, брусникой и солёным огурцом.","source":"UniTools"},{"id":"ut-kanelbullar","name":"Кулебяка с корицей","country":"Швеция","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":135,"baseServings":12,"portionNutrition":{"k":380,"p":6,"f":16,"c":54},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Молоко","quantity":300,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сахар в тесто","quantity":80,"unit":"g","note":""},{"name":"Кардамон","quantity":2,"unit":"tsp","note":"смолоть из зёрен"},{"name":"Масло в тесто","quantity":100,"unit":"g","note":""},{"name":"Масло в начинку","quantity":120,"unit":"g","note":"мягкое"},{"name":"Сахар в начинку","quantity":100,"unit":"g","note":""},{"name":"Корица","quantity":2,"unit":"tbsp","note":""},{"name":"Яйцо для смазки","quantity":1,"unit":"piece","note":""},{"name":"Жемчужный сахар","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Прогрейте молоко до тридцати семи градусов, распустите дрожжи. Смешайте с мукой, сахаром, солью и кардамоном и вымешивайте десять минут.\nВмешивайте мягкое масло по кусочку, пока тесто не станет гладким и блестящим. Дайте подойти час.\nРазотрите масло с сахаром и корицей в пасту. Раскатайте тесто прямоугольником в полсантиметра и намажьте начинкой по всей поверхности.\nСложите пласт втрое, нарежьте полосками в два сантиметра, скрутите каждую и завяжите узлом. Разложите на противне.\nДайте расстояться сорок минут, смажьте яйцом и посыпьте жемчужным сахаром.\nВыпекайте при 220 °C двенадцать минут. Коротко и горячо — так середина остаётся влажной.","source":"UniTools"},{"id":"ut-koshari","name":"Кушари","country":"Египет","category":"main","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":640,"p":22,"f":18,"c":100},"details":[{"name":"Круглый рис","quantity":300,"unit":"g","note":""},{"name":"Коричневая чечевица","quantity":200,"unit":"g","note":""},{"name":"Мелкие макароны","quantity":200,"unit":"g","note":""},{"name":"Нут","quantity":200,"unit":"g","note":"варёный"},{"name":"Лук","quantity":4,"unit":"piece","note":"тонкими кольцами"},{"name":"Помидоры в собственном соку","quantity":800,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Белый уксус","quantity":4,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Хлопья чили","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":200,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук в масле на среднем огне двадцать пять минут до тёмно-коричневого цвета, помешивая. Выложите на бумагу — он дойдёт до хруста остывая.\nОтварите чечевицу двадцать минут до мягкости, но не до распада, и откиньте.\nСварите рис на луковом масле: обжарьте его две минуты, залейте водой один к полутора и варите под крышкой пятнадцать минут.\nОтварите макароны и откиньте. Для соуса обжарьте чеснок в ложке масла до золотистого цвета, влейте уксус и дайте выпариться наполовину.\nДобавьте помидоры, зиру и чили и варите двадцать минут до густоты. Посолите.\nСобирайте в тарелке слоями: рис, чечевица, макароны, нут, соус, жареный лук. Перемешивают уже за столом.","source":"UniTools"},{"id":"ut-ful-medames","name":"Фуль медамес","country":"Египет","category":"breakfast","diets":["vegetarian","vegan","gluten-free"],"slots":["breakfast"],"time":255,"baseServings":4,"portionNutrition":{"k":420,"p":22,"f":18,"c":46},"details":[{"name":"Сухие бобы фава","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Помидор","quantity":2,"unit":"piece","note":"кубиком"},{"name":"Петрушка","quantity":6,"unit":"sprig","note":""},{"name":"Хлопья чили","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Слейте воду с замоченных бобов, залейте свежей на три пальца выше и доведите до кипения. Снимите пену.\nУбавьте до самого слабого огня и томите три-четыре часа под крышкой, пока бобы не станут разваливаться. Воду подливайте по мере надобности.\nРазомните толкушкой примерно половину бобов прямо в кастрюле, оставив остальные целыми.\nВмешайте раздавленный чеснок и посолите. Разложите по тарелкам.\nВ каждую тарелку — оливковое масло щедро, сок лимона, зира, помидор, петрушка и чили по вкусу. Подавайте с лепёшкой.","source":"UniTools"},{"id":"ut-tabbouleh","name":"Табуле","country":"Ливан","category":"salad","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":25,"baseServings":4,"portionNutrition":{"k":210,"p":5,"f":14,"c":19},"details":[{"name":"Петрушка","quantity":200,"unit":"g","note":"три больших пучка"},{"name":"Мята","quantity":30,"unit":"g","note":""},{"name":"Мелкий булгур","quantity":40,"unit":"g","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":"мелким кубиком"},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":"сок"},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Душистый перец молотый","quantity":0.5,"unit":"tsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте булгур и залейте соком одного лимона. Оставьте набухать пятнадцать минут.\nВымойте петрушку заранее и обсушите досуха — лучше час на полотенце. Оборвите толстые стебли и рубите ножом мелко, но без фанатизма.\nНарежьте помидоры мелким кубиком и посолите отдельно — они пустят сок, который пойдёт в булгур.\nСмешайте всё вместе с соком второго лимона, маслом и душистым перцем. Дайте постоять десять минут перед подачей.","source":"UniTools"},{"id":"ut-kibbeh-nayyeh","name":"Киббе нейе","country":"Ливан","category":"main","diets":[],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":380,"p":30,"f":22,"c":16},"details":[{"name":"Мелкий булгур","quantity":120,"unit":"g","note":""},{"name":"Свежайшая баранина","quantity":500,"unit":"g","note":"вырезка или нога, зачищенные"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Смесь семи специй","quantity":1,"unit":"tsp","note":""},{"name":"Сушёная мята","quantity":1,"unit":"tsp","note":""},{"name":"Ледяная вода","quantity":100,"unit":"ml","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":"для подачи"},{"name":"Мята и белый лук для подачи","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте булгур холодной водой на десять минут, откиньте и отожмите досуха. Миску с булгуром поставьте в холодильник — всё для нейе должно быть холодным.\nЗачистите баранину от жира и плёнок до чистого мускула и нарежьте кубиками. Пробейте в комбайне с луком до гладкой пасты, не давая чаше нагреться.\nДобавьте булгур, специи, мяту и соль. Вымешивайте, смачивая руки ледяной водой, пока паста не станет однородной и блестящей.\nРаспределите пасту по холодному блюду слоем в полтора сантиметра, продавите бороздки тыльной стороной ложки и щедро залейте оливковым маслом.\nПодавайте сразу — с листьями мяты, дольками белого лука и лепёшками. Нейе не хранят: остатки в тот же вечер обжаривают котлетками.","source":"UniTools"},{"id":"ut-ghormeh-sabzi","name":"Гормэ сабзи","country":"Иран","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":190,"baseServings":6,"portionNutrition":{"k":640,"p":42,"f":32,"c":46},"details":[{"name":"Баранина","quantity":800,"unit":"g","note":"кубиком 3 см"},{"name":"Петрушка","quantity":300,"unit":"g","note":""},{"name":"Кинза","quantity":200,"unit":"g","note":""},{"name":"Зелёный лук или лук-порей","quantity":200,"unit":"g","note":""},{"name":"Сушёный пажитник","quantity":1,"unit":"tbsp","note":""},{"name":"Красная фасоль","quantity":200,"unit":"g","note":"замочить на ночь"},{"name":"Сушёный лайм","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Варёный рис","quantity":600,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук с куркумой до золотистого цвета, добавьте мясо и обжарьте до корочки со всех сторон.\nЗалейте водой вровень, добавьте фасоль и варите час на слабом огне.\nПока варится, мелко порубите всю зелень и жарьте её в масле двадцать минут, помешивая. Она уменьшится вчетверо и потемнеет — так и должно быть. В конце добавьте пажитник на две минуты.\nВмешайте зелень в кастрюлю, проколите сушёные лаймы вилкой и опустите целиком. Варите ещё час на слабом огне.\nРазомните лаймы о стенку кастрюли, посолите и дайте постоять пятнадцать минут. Соус должен быть тёмным и густым, с отделившимся маслом сверху.","source":"UniTools"},{"id":"ut-tahdig","name":"Тахдиг","country":"Иран","category":"side","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":420,"p":8,"f":14,"c":66},"details":[{"name":"Басмати","quantity":500,"unit":"g","note":"замочить на час"},{"name":"Картофель","quantity":2,"unit":"piece","note":"кружками в 5 мм"},{"name":"Густой йогурт","quantity":3,"unit":"tbsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис до прозрачной воды и замочите в солёной воде на час. Это убирает лишний крахмал и даёт зёрнам вырасти длиннее.\nОтварите рис в большом количестве кипящей солёной воды пять-семь минут: зерно должно гнуться, но ломаться при нажатии. Откиньте и промойте тёплой водой.\nРастолките шафран и распустите в двух ложках горячей воды. Смешайте пару ложек риса с йогуртом и шафраном — это будет корка.\nРазогрейте масло в кастрюле, выложите кружки картофеля вплотную, сверху рисово-йогуртовую смесь, затем остальной рис горкой.\nПроделайте ручкой ложки пять отверстий до дна — через них пойдёт пар. Полейте растопленным маслом.\nНакройте крышкой, обёрнутой полотенцем, и держите на сильном огне пять минут, потом на самом слабом сорок пять. Крышку не открывайте.\nПоставьте дно кастрюли в холодную воду на минуту — корка отойдёт. Переверните на блюдо одним движением.","source":"UniTools"},{"id":"ut-plov-uzbekskiy","name":"Узбекский плов","country":"Узбекистан","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":130,"baseServings":6,"portionNutrition":{"k":780,"p":38,"f":34,"c":82},"details":[{"name":"Баранина с косточкой","quantity":800,"unit":"g","note":""},{"name":"Курдючный жир","quantity":100,"unit":"g","note":"или растительное масло"},{"name":"Рис девзира или другой плотный","quantity":700,"unit":"g","note":""},{"name":"Жёлтая и красная морковь","quantity":700,"unit":"g","note":"брусочками"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Чеснок головками","quantity":2,"unit":"piece","note":""},{"name":"Зира","quantity":1,"unit":"tbsp","note":""},{"name":"Барбарис","quantity":2,"unit":"tbsp","note":""},{"name":"Нут","quantity":100,"unit":"g","note":"замочить на ночь"},{"name":"Стручок острого перца","quantity":1,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис до прозрачной воды и залейте тёплой солёной водой на время готовки зирвака.\nВытопите курдючный жир в казане до шкварок, выньте их. Обжарьте мясо на сильном огне до тёмной корочки.\nДобавьте лук и жарьте до золотистого цвета, потом морковь — и не мешайте пять минут, дайте ей схватиться. Затем перемешайте и жарьте ещё десять.\nВлейте кипяток вровень с продуктами, добавьте нут, зиру, барбарис, чили и головки чеснока целиком. Варите на слабом огне сорок минут — это зирвак.\nПосолите зирвак заметно сильнее, чем нужно: рис заберёт соль. Выложите рис ровным слоем шумовкой, не перемешивая, и залейте кипятком на два пальца выше риса.\nВарите на сильном огне без крышки, пока вода не уйдёт под уровень риса. Соберите рис горкой, проткните до дна в нескольких местах, накройте и держите двадцать минут на самом слабом огне.","source":"UniTools"},{"id":"ut-samsa","name":"Самса","country":"Узбекистан","category":"snack","diets":[],"slots":["snack"],"time":125,"baseServings":6,"portionNutrition":{"k":580,"p":24,"f":34,"c":46},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Тёплая вода","quantity":250,"unit":"ml","note":""},{"name":"Курдючный жир","quantity":150,"unit":"g","note":"растопить"},{"name":"Баранина","quantity":500,"unit":"g","note":"порубить ножом"},{"name":"Лук","quantity":500,"unit":"g","note":"мелким кубиком"},{"name":"Зира","quantity":2,"unit":"tsp","note":""},{"name":"Яйцо для смазки","quantity":1,"unit":"piece","note":""},{"name":"Кунжут","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, тёплой воды и соли, вымешивайте десять минут и оставьте под плёнкой на полчаса.\nРаскатайте тесто в тонкий пласт, смажьте растопленным жиром, сверните плотным рулетом и уберите в холод на полчаса.\nСмешайте рубленое мясо с луком, зирой и перцем. Солите непосредственно перед лепкой, не раньше.\nНарежьте рулет шайбами в два сантиметра, каждую положите срезом вверх и раскатайте в кружок — слои останутся видны.\nПоложите начинку и защипните треугольником, плотно прижимая швы. Уложите швом вниз, смажьте яйцом и посыпьте кунжутом.\nВыпекайте при 220 °C десять минут, затем убавьте до 190 °C и держите ещё двадцать пять до тёмно-золотого цвета.","source":"UniTools"},{"id":"ut-clam-chowder","name":"Новоанглийский клэм-чаудер","country":"США","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":520,"p":28,"f":30,"c":34},"details":[{"name":"Моллюски","quantity":1.5,"unit":"kg","note":"в раковинах"},{"name":"Копчёный бекон","quantity":120,"unit":"g","note":"кубиком"},{"name":"Восковой картофель","quantity":500,"unit":"g","note":"кубиком 1,5 см"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Стебель сельдерея","quantity":2,"unit":"piece","note":""},{"name":"Сливки 20 %","quantity":300,"unit":"ml","note":""},{"name":"Молоко","quantity":300,"unit":"ml","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Тимьян","quantity":3,"unit":"sprig","note":""},{"name":"Лавровый лист","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Солёные крекеры","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте моллюсков и проварите в стакане воды под крышкой пять минут, пока не раскроются. Нераскрывшихся выбросьте. Бульон процедите через марлю — в нём остаётся песок.\nДостаньте мясо из раковин и порубите крупно. Отложите — оно вернётся в самом конце.\nВытопите бекон в кастрюле, добавьте масло, лук и сельдерей и томите восемь минут до мягкости.\nВсыпьте муку, прогрейте две минуты, влейте процеженный бульон от моллюсков и молоко, добавьте картофель, тимьян и лавровый лист.\nВарите пятнадцать минут до мягкости картофеля. Разомните несколько кусочков о стенку — суп станет гуще без лишней муки.\nВлейте сливки, верните моллюсков и прогрейте две минуты, не доводя до кипения. Попробуйте на соль и подавайте с крекерами.","source":"UniTools"},{"id":"ut-buffalo-wings","name":"Куриные крылья баффало","country":"США","category":"snack","diets":["gluten-free"],"slots":["snack"],"time":65,"baseServings":4,"portionNutrition":{"k":620,"p":42,"f":48,"c":3},"details":[{"name":"Куриные крылья","quantity":1.2,"unit":"kg","note":"разделить по суставу"},{"name":"Разрыхлитель","quantity":1,"unit":"tbsp","note":""},{"name":"Острый перечный соус","quantity":150,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Белый уксус","quantity":1,"unit":"tbsp","note":""},{"name":"Чесночный порошок","quantity":1,"unit":"tsp","note":""},{"name":"Стебли сельдерея","quantity":null,"unit":"toTaste","note":""},{"name":"Соус из голубого сыра","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обсушите крылья бумажным полотенцем, посолите и оставьте на решётке в холодильнике открытыми минимум четыре часа, лучше ночь.\nОбсыпьте разрыхлителем и перемешайте, чтобы покрытие было тонким и ровным. Слишком много даст мыльный привкус.\nРазложите на решётке над противнем и запекайте при 120 °C двадцать минут — жир вытопится.\nПоднимите температуру до 220 °C и запекайте ещё двадцать пять минут до тёмно-золотого цвета и хруста.\nРастопите масло, снимите с огня и вбейте венчиком перечный соус, уксус и чесночный порошок до однородной эмульсии.\nПеремешайте горячие крылья с соусом в миске и подавайте немедленно с сельдереем и соусом из голубого сыра.","source":"UniTools"},{"id":"ut-pizza-margherita","name":"Пицца маргарита","country":"Италия","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":720,"p":30,"f":26,"c":92},"details":[{"name":"Мука типа 00","quantity":500,"unit":"g","note":""},{"name":"Вода","quantity":325,"unit":"ml","note":""},{"name":"Свежие дрожжи","quantity":1,"unit":"g","note":""},{"name":"Соль в тесто","quantity":12,"unit":"g","note":""},{"name":"Помидоры сан-марцано","quantity":400,"unit":"g","note":""},{"name":"Моцарелла фиор ди латте","quantity":300,"unit":"g","note":"нарезать и обсушить"},{"name":"Базилик","quantity":20,"unit":"g","note":""},{"name":"Оливковое масло","quantity":4,"unit":"tbsp","note":""}],"steps":"Растворите дрожжи в воде, добавьте муку и мешайте до грубого теста. Дайте постоять двадцать минут, потом вмешайте соль и вымешивайте десять минут до гладкости.\nОставьте на два часа при комнатной температуре, затем разделите на четыре шара и уберите в холодильник на сутки.\nДостаньте тесто за три часа до выпечки. Разомните помидоры руками с щепоткой соли — соус готов.\nРазогрейте духовку с камнем или сталью на максимуме не меньше часа. Это дольше, чем кажется нужным, и это обязательно.\nРастяните шар пальцами от центра к краям, оставляя бортик нетронутым. Скалку не берите: она выдавит воздух из бортика, и он не поднимется.\nНанесите тонкий слой соуса, разложите моцареллу, сбрызните маслом. Выпекайте семь-девять минут до пятнистого бортика и добавьте базилик уже на готовую.","source":"UniTools"},{"id":"ut-lasagne-alla-bolognese","name":"Лазанья болоньезе","country":"Италия","category":"main","diets":[],"slots":["lunch","dinner"],"time":260,"baseServings":8,"portionNutrition":{"k":780,"p":42,"f":42,"c":58},"details":[{"name":"Говяжий фарш","quantity":500,"unit":"g","note":""},{"name":"Свиной фарш","quantity":300,"unit":"g","note":""},{"name":"Панчетта","quantity":100,"unit":"g","note":""},{"name":"Лук, морковь, сельдерей","quantity":300,"unit":"g","note":"мелким кубиком"},{"name":"Молоко","quantity":300,"unit":"ml","note":""},{"name":"Белое сухое вино","quantity":200,"unit":"ml","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Бульон","quantity":500,"unit":"ml","note":""},{"name":"Листы для лазаньи","quantity":400,"unit":"g","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Мука","quantity":80,"unit":"g","note":""},{"name":"Молоко в бешамель","quantity":1,"unit":"l","note":""},{"name":"Пармезан","quantity":150,"unit":"g","note":"натереть"},{"name":"Мускатный орех","quantity":1,"unit":"pinch","note":""}],"steps":"Вытопите панчетту, добавьте софритто и томите двадцать минут на слабом огне до полной мягкости. Спешить здесь нельзя — овощи должны раствориться.\nДобавьте оба фарша и жарьте на сильном огне, разбивая комки, пока не выпарится вся вода и мясо не начнёт румяниться.\nВлейте молоко и дайте выпариться полностью — минут двадцать. Потом вино, тоже до полного выпаривания.\nДобавьте томатную пасту и бульон, доведите до кипения и томите три часа на минимальном огне, подливая воду по мере надобности.\nСделайте бешамель: растопите масло, вмешайте муку, прогрейте минуту и влейте тёплое молоко тонкой струйкой, непрерывно мешая. Варите до густоты сливок, приправьте мускатом.\nСоберите слоями: бешамель, тесто, рагу, бешамель, пармезан — и так шесть раз. Верхний слой — бешамель с пармезаном.\nЗапекайте при 180 °C сорок минут, последние десять без фольги. Дайте постоять двадцать минут перед нарезкой.","source":"UniTools"},{"id":"ut-palak-paneer","name":"Палак панир","country":"Индия","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":420,"p":22,"f":30,"c":16},"details":[{"name":"Шпинат","quantity":600,"unit":"g","note":""},{"name":"Панир","quantity":300,"unit":"g","note":"кубиком 2 см"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Помидор","quantity":2,"unit":"piece","note":""},{"name":"Имбирь","quantity":20,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Зелёный чили","quantity":2,"unit":"piece","note":""},{"name":"Семена зиры","quantity":1,"unit":"tsp","note":""},{"name":"Гарам масала","quantity":1,"unit":"tsp","note":""},{"name":"Сливки","quantity":60,"unit":"ml","note":""},{"name":"Гхи","quantity":3,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Опустите шпинат в кипяток на девяносто секунд и сразу переложите в ледяную воду. Отожмите и пробейте с чили в пюре.\nПрогрейте панир в горячей подсоленной воде десять минут, потом откиньте.\nОбжарьте зиру в гхи до потрескивания, добавьте лук и жарьте до золотистого цвета, затем имбирь с чесноком на минуту.\nДобавьте помидоры и тушите семь минут, пока они не разойдутся и масло не начнёт отделяться по краям.\nВмешайте шпинатное пюре, гарам масалу и соль, прогрейте ровно минуту. Добавьте панир и сливки, снимите с огня.","source":"UniTools"},{"id":"ut-samosa","name":"Самоса","country":"Индия","category":"snack","diets":["vegetarian","vegan"],"slots":["snack"],"time":90,"baseServings":6,"portionNutrition":{"k":380,"p":8,"f":20,"c":44},"details":[{"name":"Мука","quantity":300,"unit":"g","note":""},{"name":"Гхи в тесто","quantity":60,"unit":"g","note":""},{"name":"Аджван","quantity":1,"unit":"tsp","note":""},{"name":"Холодная вода","quantity":100,"unit":"ml","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":"отварной"},{"name":"Зелёный горошек","quantity":150,"unit":"g","note":""},{"name":"Семена зиры","quantity":1,"unit":"tsp","note":""},{"name":"Молотый кориандр","quantity":2,"unit":"tsp","note":""},{"name":"Амчур или лимонный сок","quantity":1,"unit":"tsp","note":""},{"name":"Гарам масала","quantity":1,"unit":"tsp","note":""},{"name":"Зелёный чили","quantity":2,"unit":"piece","note":""},{"name":"Масло для фритюра","quantity":700,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Вотрите гхи в муку с аджваном и солью до состояния влажного песка — сжатая в кулаке смесь должна держать форму.\nДобавляйте холодную воду понемногу до плотного, тугого теста. Оно должно быть жёстче пельменного. Накройте и оставьте на полчаса.\nОбжарьте зиру в ложке масла, добавьте чили, специи, горошек и крупно размятый картофель. Прогрейте пять минут и остудите.\nРазделите тесто на шарики, раскатайте каждый в овал и разрежьте пополам. Из половинки сверните конус, смочив прямой край водой.\nНаполните конус, защипните верх плотно и уложите швом вверх. Слабый шов раскроется во фритюре.\nОпустите в масло при 150 °C и жарьте двенадцать-пятнадцать минут, поднимая температуру к концу до 180 °C. Тесто должно покрыться мелкими пузырьками, а не крупными.","source":"UniTools"},{"id":"ut-jiaozi","name":"Цзяоцзы","country":"Китай","category":"main","diets":[],"slots":["lunch","dinner"],"time":75,"baseServings":4,"portionNutrition":{"k":580,"p":26,"f":24,"c":62},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Тёплая вода","quantity":200,"unit":"ml","note":""},{"name":"Свиной фарш","quantity":400,"unit":"g","note":"жирный"},{"name":"Пекинская капуста","quantity":400,"unit":"g","note":"мелко нашинковать"},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Имбирь","quantity":20,"unit":"g","note":""},{"name":"Соевый соус","quantity":2,"unit":"tbsp","note":""},{"name":"Кунжутное масло","quantity":1,"unit":"tbsp","note":""},{"name":"Холодный бульон","quantity":80,"unit":"ml","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Чёрный уксус для соуса","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки и тёплой воды, вымешивайте восемь минут и оставьте под плёнкой на полчаса.\nПосолите нашинкованную капусту и оставьте на пятнадцать минут, потом отожмите руками досуха.\nВымешивайте фарш с имбирём, соевым соусом и кунжутным маслом в одну сторону, подливая бульон, пока масса не станет вязкой. Вмешайте капусту и зелёный лук.\nРаскатайте кружки диаметром восемь сантиметров, тоньше по краям и толще в центре. Положите начинку и защипните складками с одной стороны.\nРазогрейте масло в сковороде, выложите пельмени швом вверх и жарьте три минуты до золотого дна.\nВлейте сто миллилитров воды и сразу накройте крышкой. Через семь минут снимите крышку и дайте воде выпариться до хруста.","source":"UniTools"},{"id":"ut-yangzhou-fried-rice","name":"Янчжоуский жареный рис","country":"Китай","category":"main","diets":[],"slots":["lunch","dinner"],"time":25,"baseServings":4,"portionNutrition":{"k":540,"p":26,"f":18,"c":68},"details":[{"name":"Варёный рис","quantity":600,"unit":"g","note":"вчерашний, холодный"},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Креветки","quantity":150,"unit":"g","note":""},{"name":"Варёная ветчина","quantity":100,"unit":"g","note":"мелким кубиком"},{"name":"Зелёный горошек","quantity":100,"unit":"g","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":"мелким кубиком"},{"name":"Зелёный лук","quantity":3,"unit":"piece","note":""},{"name":"Шаосинское вино","quantity":1,"unit":"tbsp","note":""},{"name":"Светлый соевый соус","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Соль и белый перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отделите два желтка и перемешайте с холодным рисом руками, пока каждое зерно не покроется плёнкой. Оставшиеся яйца взбейте отдельно.\nРаскалите вок с ложкой масла до дыма, вылейте взбитые яйца, дайте схватиться и разбейте лопаткой на кусочки. Выложите.\nОбжарьте креветки полторы минуты, добавьте ветчину, морковь и горошек и жарьте ещё минуту. Выложите к яйцам.\nВлейте оставшееся масло, выложите рис и жарьте три минуты на максимальном огне, всё время подбрасывая. Зёрна должны прыгать по воку, а не лежать.\nВерните всё в вок, влейте вино по краю и соевый соус, приправьте и подбросьте ещё тридцать секунд. Посыпьте зелёным луком.","source":"UniTools"},{"id":"ut-chiles-en-nogada","name":"Чиле рельено","country":"Мексика","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":520,"p":24,"f":36,"c":24},"details":[{"name":"Перец поблано","quantity":6,"unit":"piece","note":""},{"name":"Сыр оахака или моцарелла","quantity":350,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Мука","quantity":80,"unit":"g","note":""},{"name":"Помидоры","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":2,"unit":"clove","note":""},{"name":"Мексиканский орегано","quantity":1,"unit":"tsp","note":""},{"name":"Масло для жарки","quantity":400,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обожгите перцы на открытом огне или под грилем до чёрных пузырей по всей поверхности, сложите в пакет на десять минут и снимите кожу.\nСделайте продольный надрез, аккуратно выньте семена, оставив плодоножку. Набейте сыром и защипните зубочисткой.\nДля соуса пробейте помидоры с луком и чесноком, обжарьте пюре в ложке масла десять минут с орегано и посолите.\nВзбейте белки до устойчивых пиков, добавьте щепотку соли и по одному вмешайте желтки, стараясь не осадить массу.\nОбваляйте перец в муке, окуните в кляр и опустите в масло при 180 °C. Жарьте по две минуты с каждой стороны, поливая маслом сверху.\nВыложите на решётку, выньте зубочистки и подавайте в тарелке с горячим томатным соусом снизу, а не сверху.","source":"UniTools"},{"id":"ut-pozole-rojo","name":"Посоле рохо","country":"Мексика","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":210,"baseServings":8,"portionNutrition":{"k":560,"p":38,"f":26,"c":44},"details":[{"name":"Свиная лопатка","quantity":1.2,"unit":"kg","note":""},{"name":"Кукуруза посоле","quantity":800,"unit":"g","note":"консервированная"},{"name":"Чили гуахильо","quantity":6,"unit":"piece","note":""},{"name":"Чили анчо","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Мексиканский орегано","quantity":1,"unit":"tbsp","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Редис, капуста, лайм, лук","quantity":null,"unit":"toTaste","note":""},{"name":"Тостады","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте свинину водой, добавьте половину лука, три зубчика чеснока и лавровый лист и варите два часа на слабом огне, снимая пену.\nУдалите из чили семена, прогрейте на сухой сковороде двадцать секунд с каждой стороны и залейте кипятком на двадцать минут.\nПробейте чили с оставшимся луком, чесноком и стаканом бульона в блендере и обязательно процедите через сито.\nОбжарьте процеженный соус в ложке жира пять минут — он потемнеет и загустеет. Влейте в кастрюлю с мясом.\nДобавьте промытую кукурузу и орегано и варите ещё сорок минут. Мясо разберите на волокна и верните.\nПодавайте с мисками нарезанного редиса, капусты, лука, дольками лайма, орегано и тостадами. Каждый собирает свою тарелку.","source":"UniTools"},{"id":"ut-nihari","name":"Нихари","country":"Пакистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":330,"baseServings":6,"portionNutrition":{"k":720,"p":52,"f":46,"c":20},"details":[{"name":"Говяжья голяшка","quantity":1.2,"unit":"kg","note":""},{"name":"Мозговые кости","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":"тонкими кольцами"},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Семена фенхеля","quantity":1,"unit":"tbsp","note":""},{"name":"Кашмирский чили молотый","quantity":2,"unit":"tsp","note":""},{"name":"Корица, кардамон, гвоздика, бадьян","quantity":1,"unit":"tbsp","note":""},{"name":"Пшеничная мука","quantity":4,"unit":"tbsp","note":""},{"name":"Гхи","quantity":120,"unit":"g","note":""},{"name":"Лимон, имбирь, кинза, чили","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук в гхи до тёмно-золотого цвета — двадцать минут. Половину отложите на подачу.\nДобавьте имбирь с чесноком, специи и чили, прогрейте минуту, затем мясо и кости и обжарьте до потери сырого цвета.\nЗалейте водой на три пальца выше, доведите до кипения, снимите пену и томите на самом слабом огне четыре-пять часов. Мясо должно распадаться от прикосновения.\nРазмешайте муку в стакане холодной воды до гладкости и влейте тонкой струйкой, непрерывно помешивая. Варите десять минут — соус загустеет и станет глянцевым.\nВыньте кости, выложите мозг отдельно. Подавайте с жареным луком, соломкой имбиря, кинзой, зелёным чили и лимоном — каждый добавляет своё.","source":"UniTools"},{"id":"ut-chapli-kebab","name":"Чапли кебаб","country":"Пакистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":560,"p":34,"f":40,"c":16},"details":[{"name":"Говяжий фарш","quantity":600,"unit":"g","note":"жирный"},{"name":"Кукурузная мука","quantity":60,"unit":"g","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":"мелким кубиком"},{"name":"Лук","quantity":1,"unit":"piece","note":"мелко нарезать"},{"name":"Семена кориандра","quantity":2,"unit":"tbsp","note":"раздавить крупно"},{"name":"Семена граната сушёные","quantity":1,"unit":"tbsp","note":""},{"name":"Зелёный чили","quantity":3,"unit":"piece","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Кинза","quantity":8,"unit":"sprig","note":""},{"name":"Топлёное масло для жарки","quantity":120,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте фарш с кукурузной мукой, яйцом, луком, чили, кинзой, раздавленным кориандром, гранатовыми семенами и солью.\nВмешайте помидоры в последнюю очередь, чтобы они не пустили сок раньше времени, и уберите в холод на двадцать минут.\nМокрыми руками сформуйте плоские котлеты диаметром двенадцать сантиметров и толщиной в сантиметр.\nРазогрейте топлёное масло слоем в полсантиметра и жарьте по три-четыре минуты с каждой стороны на среднем огне, не накрывая.\nПодавайте с лепёшкой, кольцами лука и лимоном. Традиционно поверх каждой котлеты разбивают яйцо прямо на сковороде.","source":"UniTools"},{"id":"ut-laksa-lemak","name":"Лакса лемак","country":"Малайзия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":720,"p":32,"f":40,"c":62},"details":[{"name":"Рисовая лапша","quantity":400,"unit":"g","note":""},{"name":"Креветки","quantity":300,"unit":"g","note":""},{"name":"Жареный тофу","quantity":150,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":500,"unit":"ml","note":""},{"name":"Креветочный или куриный бульон","quantity":800,"unit":"ml","note":""},{"name":"Лемонграсс","quantity":3,"unit":"piece","note":""},{"name":"Галангал","quantity":30,"unit":"g","note":""},{"name":"Сушёный чили","quantity":8,"unit":"piece","note":""},{"name":"Шалот","quantity":6,"unit":"piece","note":""},{"name":"Креветочная паста белачан","quantity":1,"unit":"tbsp","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Ростки маша, огурец, лайм","quantity":null,"unit":"toTaste","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""}],"steps":"Замочите сушёный чили в кипятке пятнадцать минут, затем пробейте с шалотом, лемонграссом, галангалом, куркумой и белачаном в гладкую пасту.\nОбжаривайте пасту в масле на среднем огне пятнадцать минут, помешивая. Готово, когда масло начнёт отделяться и всплывать по краям.\nВлейте бульон, доведите до кипения и варите десять минут. Добавьте креветки и тофу на три минуты.\nВлейте кокосовое молоко и прогрейте, не доводя до бурного кипения. Посолите.\nРазложите отваренную лапшу по мискам, залейте бульоном и подайте с ростками, огурцом и лаймом отдельно.","source":"UniTools"},{"id":"ut-roti-canai","name":"Роти чанай","country":"Малайзия","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":50,"baseServings":6,"portionNutrition":{"k":420,"p":8,"f":20,"c":52},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Тёплая вода","quantity":280,"unit":"ml","note":""},{"name":"Сгущённое молоко","quantity":2,"unit":"tbsp","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Гхи или маргарин","quantity":120,"unit":"g","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":"для отдыха теста"},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Замесите тесто из муки, воды, яйца, сгущёнки и соли и вымешивайте пятнадцать минут — оно должно стать очень эластичным и гладким.\nРазделите на шары, обмажьте каждый маслом и уложите в миску, залив маслом. Оставьте минимум на четыре часа.\nНа смазанном маслом столе расплющите шар и растягивайте от центра, хлопая по нему ладонями, пока лист не станет прозрачным.\nСмажьте лист гхи, сложите края к центру и скатайте в тугую спираль. Дайте полежать десять минут.\nРасплющите спираль в круг и жарьте на среднем огне по две минуты с каждой стороны на гхи до золотистых пятен.\nСразу со сковороды сомните лепёшку ладонями с двух сторон — слои разойдутся. Подавайте с далом или карри.","source":"UniTools"},{"id":"ut-stamppot","name":"Стамппот","country":"Нидерланды","category":"main","diets":[],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":780,"p":30,"f":46,"c":62},"details":[{"name":"Рассыпчатый картофель","quantity":1.2,"unit":"kg","note":""},{"name":"Кудрявая капуста","quantity":500,"unit":"g","note":"нашинковать мелко"},{"name":"Копчёная колбаса рокворст","quantity":500,"unit":"g","note":""},{"name":"Копчёный бекон","quantity":150,"unit":"g","note":"кубиком"},{"name":"Молоко","quantity":150,"unit":"ml","note":"горячее"},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Горчица","quantity":1,"unit":"tbsp","note":""},{"name":"Мясная подлива","quantity":200,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите картофель в подсоленной воде двадцать минут. За семь минут до конца заложите сверху капусту — она дойдёт на пару.\nПока варится, прогрейте колбасу в кипятке двадцать минут, не давая кипеть, — кожура лопнет и весь жир уйдёт в воду.\nВытопите бекон до хруста и отложите, жир сохраните.\nСлейте воду, разомните картофель с капустой толкушкой, добавляя горячее молоко, масло, беконный жир и горчицу.\nВмешайте шкварки, разложите по тарелкам, сделайте ямку и налейте в неё подливу. Колбасу нарежьте и положите сверху.","source":"UniTools"},{"id":"ut-poffertjes","name":"Поффертьес","country":"Нидерланды","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":90,"baseServings":4,"portionNutrition":{"k":420,"p":11,"f":18,"c":54},"details":[{"name":"Гречневая мука","quantity":125,"unit":"g","note":""},{"name":"Пшеничная мука","quantity":125,"unit":"g","note":""},{"name":"Тёплое молоко","quantity":400,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Распустите дрожжи с сахаром в половине тёплого молока и дайте вспениться десять минут.\nСмешайте обе муки с солью, влейте опару, яйцо и остальное молоко и размешайте венчиком до гладкости.\nНакройте и оставьте на час в тепле. Тесто станет пузырчатым и увеличится примерно вдвое.\nРазогрейте сковороду для поффертьес или обычную, смажьте маслом и налейте тесто в углубления, не перемешивая его в миске.\nЧерез минуту, когда края схватятся, переверните вилкой и жарьте ещё сорок секунд.\nПодавайте горячими с кусочком сливочного масла сверху и щедрой сахарной пудрой.","source":"UniTools"},{"id":"ut-doro-wat","name":"Доро уот","country":"Эфиопия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":145,"baseServings":6,"portionNutrition":{"k":620,"p":46,"f":40,"c":18},"details":[{"name":"Курица, разделанная","quantity":1.4,"unit":"kg","note":""},{"name":"Лук","quantity":1,"unit":"kg","note":"очень мелко нарезать"},{"name":"Бербере","quantity":3,"unit":"tbsp","note":""},{"name":"Топлёное масло нитер киббе","quantity":120,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":"варёные вкрутую"},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Красное вино или тедж","quantity":120,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте курицу в соке лимона с солью на полчаса.\nТомите лук в сухой кастрюле на среднем огне сорок минут, помешивая. Он даст сок, уварится и превратится в тёмную пасту. Масла и воды не добавлять.\nДобавьте нитер киббе, чеснок и имбирь, прогрейте пять минут, затем всыпьте бербере и жарьте ещё пять — специи должны раскрыться в жире.\nВлейте вино и стакан воды, положите курицу и тушите под крышкой сорок минут на слабом огне.\nНадрежьте варёные яйца в нескольких местах и опустите в соус на последние десять минут.\nПодавайте с инджерой. Соус должен быть густым, тёмно-красным, с отделившимся маслом сверху.","source":"UniTools"},{"id":"ut-misir-wat","name":"Мисир уот","country":"Эфиопия","category":"main","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":85,"baseServings":4,"portionNutrition":{"k":420,"p":20,"f":18,"c":48},"details":[{"name":"Красная чечевица","quantity":300,"unit":"g","note":"промыть"},{"name":"Лук","quantity":600,"unit":"g","note":"очень мелко нарезать"},{"name":"Бербере","quantity":2,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Томатная паста","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Вода","quantity":900,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Томите лук в сухой кастрюле тридцать минут на среднем огне, помешивая, пока он не станет тёмной пастой.\nВлейте масло, добавьте чеснок с имбирём и прогрейте три минуты.\nВсыпьте бербере и томатную пасту и обжаривайте пять минут — смесь потемнеет и станет ароматной.\nДобавьте чечевицу, залейте водой и варите двадцать пять минут на слабом огне, помешивая, пока чечевица не разойдётся.\nПосолите в конце, доведите до густоты каши и подавайте с инджерой или лепёшкой.","source":"UniTools"},{"id":"ut-ropa-vieja","name":"Ропа вьеха","country":"Куба","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":175,"baseServings":6,"portionNutrition":{"k":620,"p":46,"f":26,"c":48},"details":[{"name":"Говяжья пашина","quantity":1.2,"unit":"kg","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":"тонкими полукольцами"},{"name":"Сладкий перец","quantity":3,"unit":"piece","note":"соломкой"},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Помидоры в собственном соку","quantity":400,"unit":"g","note":""},{"name":"Зелёные оливки","quantity":100,"unit":"g","note":""},{"name":"Каперсы","quantity":2,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Сушёный орегано","quantity":1,"unit":"tbsp","note":""},{"name":"Белое сухое вино","quantity":150,"unit":"ml","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Варёный рис","quantity":600,"unit":"g","note":""}],"steps":"Отварите мясо целым куском в подсоленной воде с луковицей полтора часа, пока оно не станет разбираться на волокна. Бульон сохраните.\nОстудите и разберите руками вдоль волокон на тонкие полоски.\nТомите лук с перцем в оливковом масле двадцать минут до полной мягкости, потом добавьте чеснок, зиру и орегано на минуту.\nВлейте вино, дайте выпариться наполовину, добавьте помидоры и стакан бульона. Тушите десять минут.\nВерните мясо, добавьте оливки и каперсы и тушите ещё двадцать минут на слабом огне. Подавайте с рисом и жареным подорожником.","source":"UniTools"},{"id":"ut-moros-y-cristianos","name":"Морос и кристианос","country":"Куба","category":"side","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":460,"p":15,"f":11,"c":76},"details":[{"name":"Чёрная фасоль","quantity":300,"unit":"g","note":"замочить на ночь"},{"name":"Длиннозёрный рис","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Зелёный перец","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Орегано","quantity":1,"unit":"tsp","note":""},{"name":"Винный уксус","quantity":1,"unit":"tbsp","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите фасоль в трёх литрах воды с лавровым листом час, до состояния почти готовой. Отвар не сливайте — он и есть основа блюда.\nОбжарьте лук с перцем в оливковом масле пятнадцать минут до мягкости, добавьте чеснок, зиру и орегано на минуту.\nОтмерьте фасолевый отвар: на каждую часть риса нужно две части жидкости по объёму. Не хватит — долейте воды.\nСмешайте рис, фасоль, отвар, половину софрито и уксус, посолите и доведите до кипения.\nУбавьте огонь, накройте и варите двадцать минут, не открывая крышку. Дайте постоять десять минут, вмешайте остаток софрито вилкой.","source":"UniTools"},{"id":"ut-jerk-chicken","name":"Курица джерк","country":"Ямайка","category":"main","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":560,"p":48,"f":36,"c":10},"details":[{"name":"Курица, разделанная","quantity":1.6,"unit":"kg","note":""},{"name":"Перец скотч-боннет","quantity":3,"unit":"piece","note":""},{"name":"Душистый перец","quantity":2,"unit":"tbsp","note":""},{"name":"Зелёный лук","quantity":6,"unit":"piece","note":""},{"name":"Тимьян","quantity":8,"unit":"sprig","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Соевый соус","quantity":60,"unit":"ml","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Тростниковый сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Мускатный орех и корица","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""}],"steps":"Пробейте в блендере чили, душистый перец, зелёный лук, тимьян, имбирь, чеснок, соевый соус, сок лайма, сахар, мускат и масло в густую пасту.\nСделайте на курице глубокие надрезы до кости и вотрите маринад руками в перчатках, заполняя надрезы.\nОставьте в холодильнике минимум на восемь часов, лучше на сутки.\nРазложите угли в одну сторону мангала, бросьте на них замоченные ягоды душистого перца и щепу. Курицу положите на противоположную сторону, вдали от прямого жара.\nГотовьте под крышкой при 150–160 °C полтора часа, переворачивая раз в полчаса и подбрасывая щепу.\nПоследние десять минут переложите на прямой жар для корочки. Подавайте с лаймом и лепёшкой фестиваль.","source":"UniTools"},{"id":"ut-ackee-and-saltfish","name":"Аки с солёной рыбой","country":"Ямайка","category":"breakfast","diets":["pescatarian","gluten-free"],"slots":["breakfast"],"time":45,"baseServings":4,"portionNutrition":{"k":380,"p":28,"f":24,"c":14},"details":[{"name":"Аки консервированный","quantity":540,"unit":"g","note":"откинуть"},{"name":"Солёная треска","quantity":300,"unit":"g","note":"вымочить ночь"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Сладкий перец","quantity":1,"unit":"piece","note":""},{"name":"Помидор","quantity":2,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":3,"unit":"piece","note":""},{"name":"Тимьян","quantity":4,"unit":"sprig","note":""},{"name":"Скотч-боннет","quantity":1,"unit":"piece","note":"целиком, не разрезая"},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Чёрный перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите вымоченную треску двадцать минут, слейте воду, остудите и разберите на волокна, выбрасывая кожу и кости.\nОбжарьте лук с перцем в масле восемь минут, добавьте тимьян и целый скотч-боннет — он даст аромат без остроты, если его не резать.\nДобавьте треску и помидоры и прогрейте пять минут.\nВсыпьте аки, поперчите и прогрейте две минуты, только покачивая сковороду. Лопаткой не мешать.\nВыньте перец и подавайте с жареным подорожником, лепёшкой или варёной ямсовой смесью.","source":"UniTools"},{"id":"ut-jollof-rice","name":"Джоллоф рис","country":"Нигерия","category":"main","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":80,"baseServings":6,"portionNutrition":{"k":520,"p":10,"f":18,"c":80},"details":[{"name":"Длиннозёрный рис","quantity":500,"unit":"g","note":"промыть"},{"name":"Помидоры","quantity":600,"unit":"g","note":""},{"name":"Красный сладкий перец","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Порошок карри","quantity":2,"unit":"tsp","note":""},{"name":"Сушёный тимьян","quantity":1,"unit":"tsp","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Куриный бульон","quantity":600,"unit":"ml","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Пробейте помидоры, перец, одну луковицу и скотч-боннет в блендере до гладкости.\nОбжарьте вторую луковицу в масле до мягкости, добавьте томатную пасту и жарьте пять минут, пока она не потемнеет.\nВлейте пюре и уваривайте двадцать пять минут на среднем огне, помешивая. Соус потемнеет, загустеет, и масло начнёт отделяться по краям.\nДобавьте карри, тимьян, лавровый лист и бульон, посолите и доведите до кипения.\nВсыпьте промытый рис, перемешайте один раз, накройте фольгой и крышкой и варите на самом слабом огне двадцать пять минут. Не открывайте и не мешайте.\nСнимите с огня и дайте постоять десять минут. Перемешайте вилкой снизу вверх, поднимая нижний слой.","source":"UniTools"},{"id":"ut-suya","name":"Суйя","country":"Нигерия","category":"snack","diets":["gluten-free"],"slots":["snack"],"time":55,"baseServings":4,"portionNutrition":{"k":520,"p":42,"f":34,"c":12},"details":[{"name":"Говяжья вырезка","quantity":600,"unit":"g","note":"тонкими полосками"},{"name":"Жареный арахис","quantity":150,"unit":"g","note":""},{"name":"Молотый имбирь","quantity":2,"unit":"tsp","note":""},{"name":"Чесночный порошок","quantity":2,"unit":"tsp","note":""},{"name":"Кайенский перец","quantity":2,"unit":"tsp","note":""},{"name":"Паприка","quantity":2,"unit":"tsp","note":""},{"name":"Бульонный кубик","quantity":1,"unit":"piece","note":""},{"name":"Растительное масло","quantity":4,"unit":"tbsp","note":""},{"name":"Лук, помидор, капуста для подачи","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Смелите арахис в мелкую крошку, заверните в полотенце и отожмите как следует — на ткани останется масло, а порошок станет сухим.\nСмешайте арахисовый порошок с имбирём, чесноком, кайенским перцем, паприкой, раскрошенным кубиком и солью — это ясуйя.\nСмажьте полоски мяса маслом и обваляйте в половине обсыпки. Оставьте на полчаса.\nНанижите мясо на шпажки волной, чтобы жар проходил между складками, и жарьте на сильном огне по две-три минуты с каждой стороны.\nГорячее мясо посыпьте второй половиной обсыпки и подавайте с кольцами лука, помидором и капустой.","source":"UniTools"},{"id":"ut-arepas","name":"Арепас","country":"Колумбия","category":"bread","diets":["vegetarian","gluten-free"],"slots":["breakfast","snack"],"time":40,"baseServings":4,"portionNutrition":{"k":380,"p":12,"f":14,"c":52},"details":[{"name":"Предварённая кукурузная мука","quantity":250,"unit":"g","note":""},{"name":"Тёплая вода","quantity":320,"unit":"ml","note":""},{"name":"Свежий белый сыр","quantity":150,"unit":"g","note":"натереть"},{"name":"Сливочное масло","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":2,"unit":"tbsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите соль в тёплой воде и всыпьте муку, размешивая рукой. Добавьте масло и сыр.\nВымешивайте три минуты и дайте постоять пять. Тесто должно перестать липнуть и легко скатываться в шар.\nСформуйте лепёшки диаметром десять сантиметров и толщиной полтора. Края разгладьте мокрыми пальцами — трещины разойдутся при жарке.\nОбжарьте на сухой сковороде с каплей масла по четыре минуты с каждой стороны до плотной корочки.\nДоведите в духовке при 180 °C десять минут. Готовая арепа звучит глухо, если постучать.\nРазрежьте горячей вдоль, не до конца, и набейте начинкой: сыром, авокадо, тушёным мясом или яйцом.","source":"UniTools"},{"id":"ut-ajiaco-bogotano","name":"Ахиако","country":"Колумбия","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":100,"baseServings":6,"portionNutrition":{"k":520,"p":38,"f":20,"c":48},"details":[{"name":"Куриные грудки на кости","quantity":800,"unit":"g","note":""},{"name":"Мелкий жёлтый картофель","quantity":500,"unit":"g","note":""},{"name":"Восковой картофель","quantity":400,"unit":"g","note":"кружками"},{"name":"Рассыпчатый картофель","quantity":400,"unit":"g","note":"крупными кусками"},{"name":"Кукуруза початками","quantity":3,"unit":"piece","note":"разрезать пополам"},{"name":"Гуаскас сушёные","quantity":3,"unit":"tbsp","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Кинза","quantity":6,"unit":"sprig","note":""},{"name":"Сливки","quantity":200,"unit":"ml","note":""},{"name":"Каперсы","quantity":4,"unit":"tbsp","note":""},{"name":"Авокадо","quantity":2,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Сварите курицу в двух с половиной литрах воды с зелёным луком и кинзой сорок минут. Выньте и разберите на волокна, бульон процедите.\nВерните бульон в кастрюлю, заложите мелкий жёлтый картофель и варите двадцать минут, пока он полностью не разварится и не загустит суп.\nДобавьте два других сорта картофеля и кукурузу и варите ещё двадцать минут.\nВсыпьте гуаскас за пять минут до конца — при долгой варке они горчат.\nВерните курицу, посолите и подавайте, поставив на стол миски со сливками, каперсами и нарезанным авокадо.","source":"UniTools"},{"id":"ut-quiche-lorraine","name":"Киш лорен","country":"Франция","category":"main","diets":[],"slots":["lunch","dinner"],"time":100,"baseServings":6,"portionNutrition":{"k":580,"p":20,"f":44,"c":28},"details":[{"name":"Мука","quantity":250,"unit":"g","note":""},{"name":"Сливочное масло","quantity":125,"unit":"g","note":"холодное, кубиком"},{"name":"Яйцо в тесто","quantity":1,"unit":"piece","note":""},{"name":"Ледяная вода","quantity":2,"unit":"tbsp","note":""},{"name":"Копчёная грудинка","quantity":250,"unit":"g","note":"брусочками"},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Сливки 33 %","quantity":200,"unit":"ml","note":""},{"name":"Молоко","quantity":100,"unit":"ml","note":""},{"name":"Мускатный орех","quantity":1,"unit":"pinch","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Порубите холодное масло с мукой и щепоткой соли в крошку, добавьте яйцо и ледяную воду и соберите тесто, не вымешивая. Уберите в холод на час.\nРаскатайте тесто, выложите в форму, наколите вилкой и снова уберите в холод на двадцать минут — это защищает от усадки.\nНакройте пергаментом с грузом и выпекайте вслепую при 190 °C пятнадцать минут, потом снимите груз и допеките пять минут до сухого дна.\nВытопите грудинку до румяности и обсушите на бумаге — лишний жир расслоит заливку.\nВзбейте яйца со сливками и молоком без пены, приправьте мускатом и перцем. Соль почти не нужна — грудинка солёная.\nРазложите грудинку по основе, залейте и выпекайте при 170 °C тридцать пять минут. Центр должен чуть подрагивать, когда вынимаете.","source":"UniTools"},{"id":"ut-croissant","name":"Круассан","country":"Франция","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":200,"baseServings":8,"portionNutrition":{"k":420,"p":8,"f":26,"c":40},"details":[{"name":"Мука высокобелковая","quantity":500,"unit":"g","note":""},{"name":"Холодное молоко","quantity":280,"unit":"ml","note":""},{"name":"Свежие дрожжи","quantity":15,"unit":"g","note":""},{"name":"Сахар","quantity":55,"unit":"g","note":""},{"name":"Соль","quantity":11,"unit":"g","note":""},{"name":"Масло в тесто","quantity":40,"unit":"g","note":"мягкое"},{"name":"Масло для слоения","quantity":280,"unit":"g","note":"82 % жирности"},{"name":"Яйцо для смазки","quantity":1,"unit":"piece","note":""}],"steps":"Замесите тесто из муки, холодного молока, дрожжей, сахара, соли и мягкого масла пять минут. Не перемешивайте дольше: сильная клейковина помешает раскатке.\nРасплющите тесто в прямоугольник, заверните и уберите в холодильник минимум на четыре часа, лучше на ночь.\nОтбейте холодное масло скалкой в квадрат толщиной в сантиметр и держите в холоде. Оно должно гнуться, но не ломаться и не таять.\nРаскатайте тесто вдвое больше масляного квадрата, положите масло по центру и заверните края конвертом, защипнув швы.\nРаскатайте в длинный прямоугольник и сложите втрое. Уберите в холод на сорок минут. Повторите ещё два раза — всего три сложения.\nРаскатайте пласт толщиной четыре миллиметра, нарежьте треугольниками с основанием десять сантиметров и сверните от основания к вершине, слегка натягивая.\nРасстаивайте два часа при 25 °C — не теплее, иначе масло вытечет. Смажьте яйцом и выпекайте при 200 °C восемнадцать минут.","source":"UniTools"},{"id":"ut-tempura","name":"Темпура","country":"Япония","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":520,"p":24,"f":26,"c":48},"details":[{"name":"Крупные креветки","quantity":12,"unit":"piece","note":""},{"name":"Батат, баклажан, тыква, перец","quantity":500,"unit":"g","note":"ломтиками"},{"name":"Мука","quantity":150,"unit":"g","note":""},{"name":"Кукурузный крахмал","quantity":50,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":"холодное"},{"name":"Ледяная вода","quantity":250,"unit":"ml","note":""},{"name":"Даси для соуса","quantity":200,"unit":"ml","note":""},{"name":"Соевый соус","quantity":50,"unit":"ml","note":""},{"name":"Мирин","quantity":50,"unit":"ml","note":""},{"name":"Тёртый дайкон","quantity":null,"unit":"toTaste","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""}],"steps":"Надрежьте креветки с внутренней стороны в трёх местах и слегка распрямите — так они не свернутся кольцом при жарке.\nСмешайте даси, соевый соус и мирин, доведите до кипения и снимите — это соус тэнцую. Подавайте с тёртым дайконом.\nРазогрейте масло до 180 °C. Только когда оно готово, замешивайте кляр — не раньше.\nВзбейте холодное яйцо с ледяной водой, всыпьте муку с крахмалом и перемешайте палочками пять-шесть движений. Комки оставьте.\nОбваляйте продукты в сухой муке, окуните в кляр и опускайте в масло по три-четыре штуки. Жарьте полторы-две минуты.\nВыкладывайте на решётку, никогда на бумагу. Между партиями снимайте с масла всплывшие кусочки кляра — они горят и портят вкус.","source":"UniTools"},{"id":"ut-okonomiyaki","name":"Окономияки","country":"Япония","category":"main","diets":[],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":560,"p":24,"f":32,"c":44},"details":[{"name":"Капуста","quantity":500,"unit":"g","note":"квадратиками 1 см"},{"name":"Мука","quantity":150,"unit":"g","note":""},{"name":"Ямс нагаимо","quantity":100,"unit":"g","note":"натереть"},{"name":"Даси","quantity":120,"unit":"ml","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Свиная грудинка","quantity":200,"unit":"g","note":"тонкими ломтиками"},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Тэнкасу — крошка от темпуры","quantity":40,"unit":"g","note":""},{"name":"Соус окономи","quantity":null,"unit":"toTaste","note":""},{"name":"Японский майонез","quantity":null,"unit":"toTaste","note":""},{"name":"Кацуобуси и аонори","quantity":null,"unit":"toTaste","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""}],"steps":"Смешайте муку, тёртый ямс и даси и оставьте на полчаса в холодильнике — тесто станет однороднее.\nВмешайте яйца в тесто, потом капусту, зелёный лук и тэнкасу. Мешайте снизу вверх и недолго — капуста не должна пустить сок.\nВыложите на разогретую сковороду четверть массы горкой диаметром пятнадцать сантиметров и не приплющивайте — воздух внутри нужен.\nРазложите сверху ломтики грудинки и жарьте пять минут под крышкой на среднем огне.\nПереверните двумя лопатками одним решительным движением и жарьте ещё пять минут, теперь уже не накрывая.\nСмажьте соусом окономи, начертите майонезом полосы и проведите по ним зубочисткой поперёк. Посыпьте кацуобуси и аонори.","source":"UniTools"},{"id":"ut-lahmacun","name":"Лахмаджун","country":"Турция","category":"main","diets":[],"slots":["lunch","dinner"],"time":80,"baseServings":6,"portionNutrition":{"k":420,"p":22,"f":16,"c":48},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Тёплая вода","quantity":240,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":5,"unit":"g","note":""},{"name":"Бараний фарш","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Красный перец","quantity":1,"unit":"piece","note":""},{"name":"Помидор","quantity":1,"unit":"piece","note":""},{"name":"Перечная паста бибер сальчасы","quantity":2,"unit":"tbsp","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Хлопья пул бибер","quantity":1,"unit":"tsp","note":""},{"name":"Лимон и зелень для подачи","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, воды, дрожжей и соли, вымешивайте восемь минут и дайте подойти час.\nПробейте лук, перец и помидор в блендере, отожмите через сито — лишняя вода не нужна.\nСмешайте фарш с овощной пастой, бибер сальчасы, рубленой петрушкой, хлопьями перца и солью. Масса должна быть густой, как паштет.\nРазогрейте духовку с камнем на максимуме сорок минут.\nРаскатайте шарики теста до толщины бумаги, диаметром двадцать пять сантиметров, и намажьте начинкой тонким слоем до самых краёв.\nВыпекайте на камне три-четыре минуты. Края должны подрумяниться, а середина остаться мягкой — лахмаджун сворачивают в трубочку.","source":"UniTools"},{"id":"ut-baklava","name":"Пахлава","country":"Турция","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":120,"baseServings":12,"portionNutrition":{"k":490,"p":8,"f":28,"c":54},"details":[{"name":"Тесто юфка или фило","quantity":500,"unit":"g","note":""},{"name":"Фисташки","quantity":400,"unit":"g","note":"порубить крупно"},{"name":"Топлёное масло","quantity":300,"unit":"g","note":""},{"name":"Сахар","quantity":500,"unit":"g","note":""},{"name":"Вода","quantity":400,"unit":"ml","note":""},{"name":"Лимонный сок","quantity":1,"unit":"tbsp","note":""}],"steps":"Сварите сироп: сахар с водой довести до кипения, варить пятнадцать минут, добавить лимонный сок и полностью остудить.\nРастопите масло и дайте отстояться — используйте только прозрачный верхний слой, осадок вылейте.\nУложите в смазанную форму двадцать листов, смазывая каждый маслом. Посыпьте фисташками ровным слоем.\nНакройте ещё двадцатью листами, так же смазывая каждый. Верхний слой смажьте особенно щедро.\nРазрежьте острым ножом на ромбы до самого дна формы.\nВыпекайте при 170 °C час до глубокого золотого цвета. Достаньте и сразу залейте холодным сиропом по надрезам.\nОставьте на шесть часов, лучше на ночь. Резать и подавать раньше бессмысленно: сироп не дошёл до нижних слоёв.","source":"UniTools"},{"id":"ut-spanakopita","name":"Спанакопита","country":"Греция","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":90,"baseServings":8,"portionNutrition":{"k":480,"p":16,"f":32,"c":34},"details":[{"name":"Шпинат","quantity":1,"unit":"kg","note":""},{"name":"Фета","quantity":300,"unit":"g","note":"раскрошить"},{"name":"Тесто фило","quantity":450,"unit":"g","note":""},{"name":"Зелёный лук","quantity":6,"unit":"piece","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":150,"unit":"ml","note":""},{"name":"Мускатный орех","quantity":1,"unit":"pinch","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарубите шпинат, посолите и оставьте на двадцать минут. Отожмите руками горстями досуха — воды выйдет больше, чем кажется возможным.\nОбжарьте зелёный лук в ложке масла до мягкости и остудите.\nСмешайте шпинат с луком, фетой, укропом, яйцами, мускатом и перцем. Соль пробуйте: фета уже солёная.\nУложите в форму семь листов фило, смазывая каждый оливковым маслом и оставляя края свисать.\nВыложите начинку, заверните свисающие края внутрь и накройте ещё шестью листами, смазывая каждый.\nНадрежьте верх на порции, не доходя до начинки, сбрызните водой и выпекайте при 180 °C пятьдесят минут до тёмно-золотого цвета.","source":"UniTools"},{"id":"ut-patatas-bravas","name":"Пататас бравас","country":"Испания","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":50,"baseServings":4,"portionNutrition":{"k":420,"p":6,"f":22,"c":48},"details":[{"name":"Картофель","quantity":800,"unit":"g","note":"кубиком 3 см"},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Сладкая паприка","quantity":2,"unit":"tsp","note":""},{"name":"Острая паприка","quantity":1,"unit":"tsp","note":""},{"name":"Куриный или овощной бульон","quantity":300,"unit":"ml","note":""},{"name":"Хересный уксус","quantity":1,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":2,"unit":"clove","note":""},{"name":"Оливковое масло в соус","quantity":3,"unit":"tbsp","note":""},{"name":"Масло для фритюра","quantity":800,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте картофель неровными кусками — сколотые грани дают больше хрустящей поверхности. Промойте от крахмала и обсушите досуха.\nОбжарьте при 140 °C восемь минут до мягкости, не давая подрумяниться. Выложите остывать минимум на десять минут.\nДля соуса обжарьте чеснок в оливковом масле, снимите с огня, всыпьте муку и обе паприки и размешайте. Паприка на огне сгорит за секунды.\nВерните на слабый огонь, влейте бульон тонкой струйкой, помешивая, и варите пять минут до густоты соуса. Добавьте уксус и соль.\nПоднимите масло до 190 °C и обжарьте картофель ещё три минуты до тёмно-золотой корочки. Посолите сразу.\nВыложите на блюдо и залейте горячим соусом непосредственно перед подачей.","source":"UniTools"},{"id":"ut-momo","name":"Момо","country":"Непал","category":"main","diets":[],"slots":["lunch","dinner"],"time":80,"baseServings":4,"portionNutrition":{"k":560,"p":30,"f":20,"c":62},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Холодная вода","quantity":200,"unit":"ml","note":""},{"name":"Говядина или курица","quantity":500,"unit":"g","note":"порубить ножом"},{"name":"Лук","quantity":300,"unit":"g","note":"мелким кубиком"},{"name":"Имбирь","quantity":25,"unit":"g","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Кинза","quantity":20,"unit":"g","note":""},{"name":"Сычуаньский перец тимур","quantity":1,"unit":"tsp","note":""},{"name":"Помидоры для ачара","quantity":400,"unit":"g","note":""},{"name":"Сушёный чили","quantity":3,"unit":"piece","note":""},{"name":"Кунжут","quantity":2,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, холодной воды и щепотки соли, вымешивайте восемь минут и оставьте под плёнкой на полчаса.\nСмешайте рубленое мясо с луком, имбирём, чесноком, кинзой, тимуром, ложкой масла и солью. Не вымешивайте до пасты — куски должны остаться.\nОбожгите помидоры на открытом огне до чёрных пятен, обжарьте чили и кунжут на сухой сковороде и пробейте всё вместе с солью в соус.\nРаскатайте кружки диаметром восемь сантиметров, тоньше по краям. Положите ложку начинки и защипните складками по кругу, скрутив верх.\nСмажьте пароварку маслом и готовьте момо десять минут на сильном пару, не давая им соприкасаться.","source":"UniTools"},{"id":"ut-dal-bhat","name":"Дал бхат","country":"Непал","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":65,"baseServings":4,"portionNutrition":{"k":620,"p":22,"f":16,"c":98},"details":[{"name":"Жёлтая чечевица","quantity":250,"unit":"g","note":""},{"name":"Рис","quantity":400,"unit":"g","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Гхи","quantity":3,"unit":"tbsp","note":""},{"name":"Аджван","quantity":1,"unit":"tsp","note":""},{"name":"Семена зиры","quantity":1,"unit":"tsp","note":""},{"name":"Сушёный чили","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Картофель и цветная капуста","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Шпинат или горчичная зелень","quantity":200,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте чечевицу и варите в литре воды с куркумой тридцать минут, пока она полностью не разойдётся. Снимайте пену первые пять минут.\nПоставьте рис. Пока варится, обжарьте лук, добавьте картофель с цветной капустой, немного куркумы и воды и тушите пятнадцать минут — это таркари.\nОбжарьте шпинат с чесноком на сильном огне две минуты — он должен остаться ярким.\nДля джхане раскалите гхи, бросьте аджван, зиру, сушёный чили и чеснок и жарьте двадцать секунд до запаха.\nВылейте раскалённое масло со специями прямо в дал — он зашипит. Размешайте, посолите и сразу подавайте.\nСоберите тарелку: рис в центре, дал в мисочке, таркари и зелень вокруг, ачар с краю.","source":"UniTools"},{"id":"ut-kottu-roti","name":"Котту роти","country":"Шри-Ланка","category":"main","diets":[],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":640,"p":32,"f":28,"c":66},"details":[{"name":"Лепёшки роти или паратха","quantity":6,"unit":"piece","note":"вчерашние"},{"name":"Варёная курица","quantity":300,"unit":"g","note":"разобрать"},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Лук-порей","quantity":1,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":"соломкой"},{"name":"Капуста","quantity":200,"unit":"g","note":"нашинковать"},{"name":"Куриное карри с соусом","quantity":200,"unit":"ml","note":""},{"name":"Зелёный чили","quantity":3,"unit":"piece","note":""},{"name":"Порошок карри","quantity":2,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":4,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте лепёшки полосками в сантиметр — так их проще рубить дальше.\nРаскалите большую сковороду с маслом, обжарьте лук, порей и чили две минуты, добавьте морковь с капустой и жарьте ещё три.\nСдвиньте овощи, разбейте яйца в свободное место, дайте схватиться и разбейте лопаткой.\nДобавьте курицу, порошок карри и полоски роти и начинайте рубить двумя лопатками, перемешивая. Три минуты активной работы.\nВлейте соус карри по краю и продолжайте рубить ещё минуту. Масса должна быть влажной, но не мокрой.","source":"UniTools"},{"id":"ut-pol-sambol","name":"Пол самбол","country":"Шри-Ланка","category":"sauce","diets":["gluten-free"],"slots":[],"time":15,"baseServings":6,"portionNutrition":{"k":240,"p":5,"f":21,"c":9},"details":[{"name":"Тёртый кокос","quantity":250,"unit":"g","note":"свежий или размороженный"},{"name":"Хлопья чили","quantity":2,"unit":"tbsp","note":""},{"name":"Красный лук","quantity":1,"unit":"piece","note":"очень мелко"},{"name":"Мальдивская рыба","quantity":2,"unit":"tbsp","note":""},{"name":"Лайм","quantity":1,"unit":"piece","note":"сок"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разотрите хлопья чили с солью и мальдивской рыбой в ступке в грубую пасту.\nДобавьте лук и продолжайте растирать — он должен пустить сок и окрасить пасту.\nВмешайте кокос руками, перетирая массу между ладонями, пока она не станет равномерно красной.\nВлейте сок лайма, перемешайте и попробуйте. Самбол должен быть острым, кислым и солёным одновременно.","source":"UniTools"},{"id":"ut-cevapi","name":"Чевапи","country":"Сербия","category":"main","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":680,"p":44,"f":42,"c":30},"details":[{"name":"Говяжий фарш","quantity":500,"unit":"g","note":""},{"name":"Бараний фарш","quantity":300,"unit":"g","note":""},{"name":"Свиной фарш","quantity":200,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Пищевая сода","quantity":1,"unit":"tsp","note":""},{"name":"Ледяная вода","quantity":100,"unit":"ml","note":""},{"name":"Сладкая паприка","quantity":1,"unit":"tsp","note":""},{"name":"Лук для подачи","quantity":2,"unit":"piece","note":"мелко нарезать"},{"name":"Лепёшки сомун","quantity":4,"unit":"piece","note":""},{"name":"Каймак или сметана","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте все три фарша с раздавленным чесноком, содой, паприкой, солью и перцем.\nВымешивайте руками десять минут, подливая ледяную воду понемногу, пока масса не станет липкой и однородной.\nНакройте плёнкой в контакт и уберите в холодильник минимум на двенадцать часов.\nМокрыми руками скатайте колбаски длиной восемь сантиметров и толщиной с большой палец.\nЖарьте на раскалённых углях или сковороде-гриль по три минуты с каждой стороны, переворачивая один раз.\nРазрежьте тёплый сомун, вложите чевапи, добавьте гору сырого лука и каймак.","source":"UniTools"},{"id":"ut-ajvar","name":"Айвар","country":"Сербия","category":"sauce","diets":["vegetarian","vegan","gluten-free"],"slots":[],"time":150,"baseServings":10,"portionNutrition":{"k":180,"p":2,"f":15,"c":11},"details":[{"name":"Красный мясистый перец","quantity":3,"unit":"kg","note":""},{"name":"Баклажаны","quantity":600,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Растительное масло","quantity":250,"unit":"ml","note":""},{"name":"Винный уксус","quantity":3,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Запеките перец и баклажаны при 220 °C или на открытом огне до чёрных пузырей по всей поверхности.\nСложите горячими в закрытую кастрюлю на двадцать минут — пар отделит кожу сам.\nОчистите от кожи и семян и оставьте мякоть в дуршлаге на два-три часа. Не отжимайте — вода должна стечь сама.\nПропустите через мясорубку или порубите ножом — не в блендере: нужна грубая текстура, а не пюре.\nУваривайте в кастрюле с половиной масла на слабом огне час, помешивая каждые десять минут.\nДобавьте чеснок, уксус, соль и оставшееся масло и варите ещё полчаса, пока масло не начнёт отделяться. Разложите горячим по стерильным банкам.","source":"UniTools"},{"id":"ut-frikadeller","name":"Фрикаделлер","country":"Дания","category":"main","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":620,"p":36,"f":34,"c":42},"details":[{"name":"Свиной фарш","quantity":400,"unit":"g","note":""},{"name":"Телячий фарш","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":"натереть"},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Мука","quantity":3,"unit":"tbsp","note":""},{"name":"Молоко","quantity":150,"unit":"ml","note":""},{"name":"Душистый перец молотый","quantity":0.5,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Отварной картофель","quantity":800,"unit":"g","note":""},{"name":"Красная капуста","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте оба фарша с тёртым луком, яйцом, мукой, солью, перцем и душистым перцем.\nВымешивайте пять минут, подливая молоко порциями. Масса должна стать вязкой и тянуться за ложкой.\nУберите в холодильник на полчаса — холодный фарс держит форму лучше.\nРастопите масло на среднем огне. Столовой ложкой, смоченной в воде, набирайте фарш и выкладывайте на сковороду, приплющивая.\nЖарьте по шесть минут с каждой стороны до тёмно-коричневой корочки. Не торопитесь — цвет и есть вкус.\nПодавайте с отварным картофелем, маринованной красной капустой и подливой из сковороды.","source":"UniTools"},{"id":"ut-smorrebrod","name":"Смёрребрёд","country":"Дания","category":"snack","diets":["pescatarian"],"slots":["snack"],"time":25,"baseServings":4,"portionNutrition":{"k":480,"p":26,"f":28,"c":32},"details":[{"name":"Ржаной хлеб ругбрёд","quantity":8,"unit":"slice","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":"мягкое"},{"name":"Маринованная сельдь","quantity":200,"unit":"g","note":""},{"name":"Мелкие креветки","quantity":200,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":"варёные"},{"name":"Листья салата","quantity":8,"unit":"piece","note":""},{"name":"Красный лук","quantity":1,"unit":"piece","note":"тонкими кольцами"},{"name":"Майонез","quantity":4,"unit":"tbsp","note":""},{"name":"Укроп","quantity":20,"unit":"g","note":""},{"name":"Каперсы и лимон","quantity":null,"unit":"toTaste","note":""}],"steps":"Намажьте каждый ломоть маслом до самых краёв. Слой должен быть заметным на глаз, а не прозрачным.\nДля сельди: лист салата, сверху кусочки сельди, кольца лука и каперсы. Салат отделяет маринад от хлеба.\nДля креветок: выложите их плотно рядами внахлёст, сверху ложка майонеза, ломтик лимона и укроп.\nДля яйца: кружки варёного яйца внахлёст, майонез полосой, укроп и щепотка соли сверху.\nПодавайте сразу, ножом и вилкой. Смёрребрёд не берут руками — он для этого не сконструирован.","source":"UniTools"},{"id":"ut-sarmale","name":"Сармале","country":"Румыния","category":"main","diets":[],"slots":["lunch","dinner"],"time":240,"baseServings":8,"portionNutrition":{"k":520,"p":30,"f":30,"c":32},"details":[{"name":"Квашеная капуста кочаном","quantity":1,"unit":"piece","note":""},{"name":"Свиной фарш","quantity":800,"unit":"g","note":""},{"name":"Круглый рис","quantity":150,"unit":"g","note":"сырой"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Копчёные рёбрышки","quantity":300,"unit":"g","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Чабер и тимьян","quantity":2,"unit":"tsp","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Сметана и мамалыга","quantity":null,"unit":"toTaste","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разберите кочан на листья, срежьте толстые прожилки. Слишком кислые листья промойте, слишком солёные вымочите двадцать минут.\nОбжарьте мелко нарезанный лук в масле до мягкости, добавьте томатную пасту и прогрейте две минуты. Полностью остудите.\nСмешайте фарш с рисом, остывшим луком, чабером, солью и перцем.\nКладите столовую ложку начинки на лист, заворачивайте рулетом и подгибайте края внутрь пальцем. Голубцы должны получиться небольшими, с два пальца.\nВыложите на дно кастрюли рубленую капусту и рёбрышки, сверху голубцы плотными слоями, между ними лавровый лист. Накройте оставшейся капустой и листьями.\nЗалейте водой вровень с верхним слоем и томите три часа на самом слабом огне или в духовке при 150 °C.","source":"UniTools"},{"id":"ut-mamaliga","name":"Мамалыга","country":"Румыния","category":"side","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":45,"baseServings":6,"portionNutrition":{"k":380,"p":12,"f":16,"c":48},"details":[{"name":"Кукурузная крупа среднего помола","quantity":300,"unit":"g","note":""},{"name":"Вода","quantity":1.2,"unit":"l","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Брынза","quantity":200,"unit":"g","note":"раскрошить"},{"name":"Сметана","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":2,"unit":"tsp","note":""}],"steps":"Доведите подсоленную воду до кипения. Отложите горсть крупы — она пригодится в конце.\nВсыпайте крупу тонкой струйкой, непрерывно мешая венчиком. Не переставайте, пока вся не войдёт.\nУбавьте огонь до минимума и варите тридцать минут, помешивая деревянной ложкой каждые три-четыре минуты. Масса будет отходить от стенок.\nВсыпьте отложенную горсть крупы и вмешайте — она даст лёгкую зернистость, которая в мамалыге ценится.\nВмешайте масло, переверните на доску и дайте постоять пять минут. Режьте ниткой на ломти и подавайте с брынзой и сметаной.","source":"UniTools"},{"id":"ut-shopska-salata","name":"Шопский салат","country":"Болгария","category":"salad","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":30,"baseServings":4,"portionNutrition":{"k":290,"p":12,"f":22,"c":12},"details":[{"name":"Помидоры","quantity":4,"unit":"piece","note":"крупным кубиком"},{"name":"Огурцы","quantity":2,"unit":"piece","note":""},{"name":"Красный перец","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":0.5,"unit":"piece","note":"тонкими кольцами"},{"name":"Брынза","quantity":200,"unit":"g","note":"натереть мелко"},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Подсолнечное масло","quantity":4,"unit":"tbsp","note":""},{"name":"Красный винный уксус","quantity":2,"unit":"tbsp","note":""},{"name":"Оливки","quantity":null,"unit":"toTaste","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обожгите перец на открытом огне до чёрной кожи, сложите в закрытую посуду на десять минут и очистите.\nНарежьте помидоры и огурцы крупным кубиком в два сантиметра, перец — полосками.\nСмешайте овощи с луком и петрушкой, заправьте маслом, уксусом и солью.\nВыложите горкой в блюдо и засыпьте тёртой брынзой сверху, не перемешивая. Украсьте оливками.","source":"UniTools"},{"id":"ut-banitsa","name":"Баница","country":"Болгария","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":75,"baseServings":8,"portionNutrition":{"k":520,"p":20,"f":32,"c":38},"details":[{"name":"Тесто фило","quantity":500,"unit":"g","note":""},{"name":"Брынза","quantity":500,"unit":"g","note":"раскрошить"},{"name":"Яйца","quantity":5,"unit":"piece","note":""},{"name":"Йогурт","quantity":250,"unit":"g","note":""},{"name":"Сода","quantity":0.5,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":"растопить"},{"name":"Подсолнечное масло","quantity":60,"unit":"ml","note":""}],"steps":"Разомните брынзу вилкой, вмешайте четыре яйца — начинка должна остаться рассыпчатой, а не превратиться в пасту.\nСмешайте растопленное масло с подсолнечным — так листы будут и хрустеть, и не гореть.\nРазложите два листа фило внахлёст, смажьте маслом, рассыпьте начинку крошкой вдоль длинной стороны и сверните неплотной колбаской.\nУложите колбаску спиралью в круглую форму от центра к краям, оставляя между витками пару миллиметров.\nВзбейте йогурт с оставшимся яйцом и содой и вылейте на баницу, стараясь попасть в щели между витками.\nВыпекайте при 180 °C сорок пять минут до тёмно-золотого цвета. Накройте полотенцем на десять минут после духовки.","source":"UniTools"},{"id":"ut-lohikeitto","name":"Лохикейтто","country":"Финляндия","category":"soup","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":520,"p":32,"f":32,"c":26},"details":[{"name":"Филе лосося","quantity":500,"unit":"g","note":"кубиком 3 см"},{"name":"Голова и хребет лосося","quantity":500,"unit":"g","note":""},{"name":"Восковой картофель","quantity":500,"unit":"g","note":"кубиком"},{"name":"Лук-порей","quantity":1,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Сливки 20 %","quantity":250,"unit":"ml","note":""},{"name":"Душистый перец горошком","quantity":8,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Укроп","quantity":40,"unit":"g","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте голову и хребет полутора литрами воды, добавьте душистый перец и лавровый лист и варите двадцать пять минут, снимая пену. Процедите.\nОбжарьте порей с морковью в масле пять минут, не давая им темнеть.\nВлейте процеженный бульон, заложите картофель и варите пятнадцать минут до мягкости.\nВлейте сливки и прогрейте, не доводя до кипения. Посолите.\nОпустите кусочки лосося и держите на слабом огне ровно пять минут. Рыба должна остаться цельными кусками.\nРазлейте по тарелкам, в каждую положите кусочек сливочного масла и щедрую горсть укропа.","source":"UniTools"},{"id":"ut-karjalanpiirakka","name":"Карельские пирожки","country":"Финляндия","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":85,"baseServings":8,"portionNutrition":{"k":240,"p":6,"f":10,"c":32},"details":[{"name":"Ржаная мука","quantity":250,"unit":"g","note":""},{"name":"Вода","quantity":150,"unit":"ml","note":""},{"name":"Круглый рис","quantity":150,"unit":"g","note":""},{"name":"Молоко","quantity":700,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":"варёные вкрутую"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Сварите рис в молоке на слабом огне сорок минут до состояния жидковатой каши. Посолите и остудите.\nЗамесите тесто из ржаной муки, воды и соли, вымешивайте пять минут. Оно будет плотным и не липким.\nРазделите на шестнадцать шариков и раскатайте каждый в овал толщиной в полмиллиметра. Подпыляйте ржаной мукой, а не пшеничной.\nВыложите ложку каши по центру, оставив свободными края, и защипните края гофрировкой, оставив начинку открытой.\nВыпекайте при 250 °C пятнадцать минут — коротко и очень горячо, иначе тонкое тесто высохнет.\nРастопите половину масла с равным количеством горячей воды и окуните горячие пирожки. Накройте полотенцем на десять минут.\nРазомните варёные яйца с оставшимся мягким маслом и солью — это мунавой, яичное масло. Подавайте им пирожки.","source":"UniTools"},{"id":"ut-irish-stew","name":"Ирландское рагу","country":"Ирландия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":170,"baseServings":6,"portionNutrition":{"k":620,"p":42,"f":28,"c":48},"details":[{"name":"Баранья шея или лопатка","quantity":1.2,"unit":"kg","note":"на кости, крупными кусками"},{"name":"Рассыпчатый картофель","quantity":500,"unit":"g","note":"первая партия"},{"name":"Восковой картофель","quantity":700,"unit":"g","note":"вторая партия"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Бараний или овощной бульон","quantity":1.2,"unit":"l","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Уложите мясо в кастрюлю сырым, добавьте лук, морковь и первую партию картофеля, нарезанную крупно.\nЗалейте бульоном, доведите до кипения, снимите пену и томите под крышкой полтора часа на самом слабом огне.\nРазомните разварившийся картофель о стенку кастрюли — бульон загустеет и станет молочно-белым.\nДобавьте вторую партию картофеля крупными кусками и варите ещё сорок минут.\nПосолите, поперчите и дайте постоять пятнадцать минут. Посыпьте петрушкой перед подачей.","source":"UniTools"},{"id":"ut-soda-bread","name":"Содовый хлеб","country":"Ирландия","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":55,"baseServings":8,"portionNutrition":{"k":260,"p":9,"f":2,"c":52},"details":[{"name":"Мука","quantity":350,"unit":"g","note":""},{"name":"Цельнозерновая мука","quantity":150,"unit":"g","note":""},{"name":"Пахта","quantity":400,"unit":"ml","note":""},{"name":"Сода","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""},{"name":"Овсяные хлопья","quantity":2,"unit":"tbsp","note":"для посыпки"}],"steps":"Разогрейте духовку до 220 °C заранее. Хлеб должен отправиться в неё сразу после замеса, ждать он не может.\nСмешайте обе муки, соду и соль в миске и хорошо перемешайте, чтобы сода разошлась равномерно.\nВлейте пахту и перемешайте ножом или рукой ровно до соединения. Тесто будет липким и неровным — так и надо.\nВыложите на присыпанный мукой противень, придайте форму круглой буханки и прорежьте глубокий крест почти до дна.\nПосыпьте овсяными хлопьями и выпекайте пятнадцать минут при 220 °C, затем тридцать при 190 °C.\nГотовый хлеб звучит глухо, если постучать по дну. Остудите на решётке минимум час: горячий содовый хлеб не режется.","source":"UniTools"},{"id":"ut-crni-rizot","name":"Чёрный ризотто","country":"Хорватия","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":75,"baseServings":4,"portionNutrition":{"k":540,"p":34,"f":18,"c":62},"details":[{"name":"Каракатица","quantity":700,"unit":"g","note":"кольцами"},{"name":"Чернила каракатицы","quantity":3,"unit":"tbsp","note":""},{"name":"Рис арборио","quantity":320,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Белое сухое вино","quantity":150,"unit":"ml","note":""},{"name":"Рыбный бульон","quantity":1,"unit":"l","note":""},{"name":"Томатная паста","quantity":1,"unit":"tbsp","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук с чесноком в оливковом масле до мягкости, добавьте каракатицу и жарьте пять минут — она выпустит воду.\nВлейте половину вина, добавьте томатную пасту и тушите двадцать пять минут под крышкой, подливая бульон, пока каракатица не станет мягкой.\nВсыпьте рис и обжаривайте две минуты, пока зёрна не станут прозрачными по краям. Влейте оставшееся вино.\nПодливайте горячий бульон половниками, помешивая, восемнадцать минут. Каждую порцию добавляйте, когда предыдущая почти впиталась.\nЗа пять минут до готовности вмешайте чернила. Ризотто станет чёрным за секунды.\nСнимите с огня, вмешайте ложку оливкового масла и петрушку, накройте на две минуты и подавайте.","source":"UniTools"},{"id":"ut-zagorski-strukli","name":"Загорски штрукли","country":"Хорватия","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":620,"p":28,"f":36,"c":44},"details":[{"name":"Мука","quantity":300,"unit":"g","note":""},{"name":"Тёплая вода","quantity":150,"unit":"ml","note":""},{"name":"Растительное масло","quantity":2,"unit":"tbsp","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Сухой творог","quantity":600,"unit":"g","note":""},{"name":"Яйца в начинку","quantity":2,"unit":"piece","note":""},{"name":"Сметана","quantity":200,"unit":"g","note":""},{"name":"Сливки","quantity":250,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, тёплой воды, масла, яйца и соли и вымешивайте десять минут до эластичности. Смажьте маслом и оставьте на полчаса.\nРазомните творог вилкой с яйцами, сметаной и солью. Начинка должна быть плотной, а не текучей.\nРастяните тесто на полотенце руками до прозрачности, смажьте растопленным маслом и разложите начинку по трети поверхности.\nСверните рулетом, поднимая полотенце, и нарежьте на куски по восемь сантиметров, прижимая края ребром ладони, чтобы они запечатались.\nОтварите в подсоленной воде пять минут после всплытия и выньте шумовкой.\nУложите в форму, залейте сливками, полейте растопленным маслом и запекайте при 200 °C двадцать пять минут до румяной корочки.","source":"UniTools"},{"id":"ut-gravlaks","name":"Гравлакс","country":"Норвегия","category":"snack","diets":["pescatarian","gluten-free"],"slots":["snack"],"time":20,"baseServings":8,"portionNutrition":{"k":280,"p":26,"f":18,"c":4},"details":[{"name":"Филе лосося с кожей","quantity":1,"unit":"kg","note":"средняя часть"},{"name":"Крупная соль","quantity":100,"unit":"g","note":""},{"name":"Сахар","quantity":90,"unit":"g","note":""},{"name":"Укроп","quantity":100,"unit":"g","note":""},{"name":"Белый перец горошком","quantity":1,"unit":"tbsp","note":"раздавить"},{"name":"Аквавит или водка","quantity":2,"unit":"tbsp","note":"по желанию"},{"name":"Горчица для соуса","quantity":3,"unit":"tbsp","note":""},{"name":"Уксус для соуса","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло для соуса","quantity":100,"unit":"ml","note":""}],"steps":"Проверьте филе на кости пальцами и выньте пинцетом. Кожу не снимайте — она держит форму при посоле.\nСмешайте соль, сахар и раздавленный перец. Сбрызните рыбу аквавитом и вотрите смесь в мякоть.\nУложите половину укропа на дно формы, сверху рыбу кожей вниз, засыпьте оставшимся укропом.\nЗатяните плёнкой, поставьте сверху доску и груз в килограмм и уберите в холодильник на сорок восемь часов.\nКаждые двенадцать часов сливайте выделившийся рассол и переворачивайте рыбу.\nСоскоблите смесь, обсушите и нарежьте под углом тонкими ломтями, не доходя до кожи. Подавайте с горчичным соусом из горчицы, сахара, уксуса и масла.","source":"UniTools"},{"id":"ut-farikal","name":"Форикол","country":"Норвегия","category":"main","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":640,"p":46,"f":34,"c":34},"details":[{"name":"Баранина на кости","quantity":1.5,"unit":"kg","note":"крупными кусками"},{"name":"Белокочанная капуста","quantity":1.5,"unit":"kg","note":"крупными дольками"},{"name":"Чёрный перец горошком","quantity":2,"unit":"tbsp","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":"по желанию, для густоты"},{"name":"Вода","quantity":500,"unit":"ml","note":""},{"name":"Отварной картофель","quantity":1,"unit":"kg","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Уложите на дно кастрюли слой мяса жиром вниз, посолите и посыпьте горошинами перца.\nСверху слой капусты, снова соль и перец, если хотите — присыпьте мукой. Чередуйте слои, пока не кончится всё.\nВлейте воду по стенке — она должна доходить до половины высоты, не выше.\nДоведите до кипения, накройте и томите два часа на самом слабом огне. Не перемешивайте: слои должны остаться слоями.\nГотово, когда мясо отходит от кости. Подавайте с отварным картофелем, поливая бульоном из кастрюли.","source":"UniTools"},{"id":"ut-moules-marinieres","name":"Мидии по-мариньерски","country":"Бельгия","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":620,"p":38,"f":26,"c":52},"details":[{"name":"Мидии","quantity":2,"unit":"kg","note":"живые, в раковинах"},{"name":"Шалот","quantity":4,"unit":"piece","note":""},{"name":"Стебель сельдерея","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Белое сухое вино","quantity":300,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Тимьян и лавровый лист","quantity":3,"unit":"sprig","note":""},{"name":"Картофель фри","quantity":800,"unit":"g","note":""},{"name":"Чёрный перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Переберите мидии: выбросьте разбитые и те, что не закрываются при постукивании. Оборвите бороду и промойте под краном.\nРастопите масло в широкой кастрюле, обжарьте шалот, сельдерей и чеснок пять минут до мягкости, не давая им темнеть.\nВлейте вино, добавьте тимьян и лавровый лист и доведите до кипения.\nВысыпьте мидии, сразу накройте крышкой и держите на сильном огне пять минут, встряхнув кастрюлю пару раз.\nСнимите крышку: раковины должны быть открыты. Закрытые выбросьте. Посыпьте петрушкой, поперчите и подавайте с картофелем фри и бульоном в отдельной чашке.","source":"UniTools"},{"id":"ut-carbonade-flamande","name":"Фламандская карбонада","country":"Бельгия","category":"main","diets":[],"slots":["lunch","dinner"],"time":205,"baseServings":6,"portionNutrition":{"k":640,"p":48,"f":30,"c":32},"details":[{"name":"Говяжья лопатка","quantity":1.2,"unit":"kg","note":"крупными кусками"},{"name":"Лук","quantity":800,"unit":"g","note":"полукольцами"},{"name":"Тёмное бельгийское пиво","quantity":500,"unit":"ml","note":""},{"name":"Ломоть хлеба","quantity":2,"unit":"slice","note":""},{"name":"Горчица","quantity":2,"unit":"tbsp","note":""},{"name":"Яблочный или тёмный сироп","quantity":1,"unit":"tbsp","note":""},{"name":"Винный уксус","quantity":1,"unit":"tbsp","note":""},{"name":"Тимьян и лавровый лист","quantity":4,"unit":"sprig","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обсушите мясо и обжарьте в масле партиями до тёмной корочки. Выложите.\nВ том же жире томите лук двадцать минут до мягкости и золотистого цвета — он даст соусу сладость и густоту.\nВерните мясо, влейте пиво, добавьте сироп, уксус, тимьян и лавровый лист. Жидкость должна почти покрывать мясо.\nНамажьте хлеб горчицей и уложите горчицей вниз поверх мяса. Не размешивайте.\nНакройте и томите три часа на самом слабом огне или в духовке при 150 °C. Хлеб разойдётся сам.\nРазмешайте соус, попробуйте на баланс сладкого и кислого и подавайте с картофелем фри.","source":"UniTools"},{"id":"ut-fondue-moitie-moitie","name":"Сырное фондю","country":"Швейцария","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":880,"p":48,"f":52,"c":48},"details":[{"name":"Грюйер","quantity":400,"unit":"g","note":"натереть крупно"},{"name":"Вашрен фрибуржуа","quantity":400,"unit":"g","note":"натереть крупно"},{"name":"Белое сухое вино","quantity":300,"unit":"ml","note":""},{"name":"Кукурузный крахмал","quantity":2,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":1,"unit":"clove","note":""},{"name":"Кирш","quantity":2,"unit":"tbsp","note":""},{"name":"Лимонный сок","quantity":1,"unit":"tbsp","note":""},{"name":"Мускатный орех и перец","quantity":1,"unit":"pinch","note":""},{"name":"Хлеб с плотным мякишем","quantity":600,"unit":"g","note":"кубиками с коркой"}],"steps":"Натрите котелок изнутри разрезанной долькой чеснока и оставьте её внутри.\nПеремешайте оба тёртых сыра с крахмалом руками, пока каждый кусочек не покроется.\nПрогрейте вино с лимонным соком до появления пузырьков по краю, но не до кипения.\nДобавляйте сыр горстями, каждый раз размешивая восьмёркой до полного расплавления, прежде чем класть следующую.\nКогда масса станет однородной и потянется за ложкой, влейте кирш, приправьте мускатом и перцем.\nПеренесите на горелку и держите на самом слабом огне. Хлеб накалывают за корку, а не за мякиш.","source":"UniTools"},{"id":"ut-roesti","name":"Рёшти","country":"Швейцария","category":"side","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":420,"p":8,"f":22,"c":48},"details":[{"name":"Восковой картофель","quantity":1,"unit":"kg","note":"отварной накануне"},{"name":"Топлёное масло","quantity":60,"unit":"g","note":""},{"name":"Копчёный бекон","quantity":100,"unit":"g","note":"по желанию"},{"name":"Лук","quantity":1,"unit":"piece","note":"по желанию"},{"name":"Тёртый грюйер","quantity":100,"unit":"g","note":"по желанию"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите картофель в мундире двадцать минут — до состояния, когда нож входит с сопротивлением. Полностью остудите и оставьте на ночь в холодильнике.\nОчистите и натрите на крупной тёрке прямо в миску. Не промывайте и не отжимайте.\nПосолите, поперчите и, если используете, вмешайте обжаренные бекон с луком и сыр.\nРазогрейте половину масла в сковороде, выложите массу ровным слоем и придавите лопаткой один раз.\nЖарьте на среднем огне двенадцать минут, не трогая. Периодически потряхивайте сковороду — рёшти должен скользить целиком.\nНакройте тарелкой, переверните, добавьте оставшееся масло и жарьте вторую сторону ещё десять минут.","source":"UniTools"},{"id":"ut-ghapama","name":"Гапама","country":"Армения","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":470,"p":9,"f":18,"c":71},"details":[{"name":"Тыква","quantity":3,"unit":"kg","note":"круглая, с плотной кожурой"},{"name":"Рис","quantity":400,"unit":"g","note":"отварить до полуготовности"},{"name":"Курага","quantity":150,"unit":"g","note":""},{"name":"Чернослив","quantity":120,"unit":"g","note":""},{"name":"Изюм","quantity":100,"unit":"g","note":""},{"name":"Грецкие орехи","quantity":120,"unit":"g","note":""},{"name":"Миндаль","quantity":80,"unit":"g","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Мёд","quantity":3,"unit":"tbsp","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Срежьте у тыквы верхушку с хвостиком — это будет крышка. Ложкой выберите семена и рыхлую мякоть, оставив стенку в два пальца.\nОтварите рис в подсоленной воде семь минут — до полуготовности — и откиньте на дуршлаг.\nЗалейте сухофрукты кипятком на десять минут, откиньте и крупно нарежьте курагу и чернослив. Орехи порубите.\nСмешайте рис с сухофруктами, орехами, растопленным маслом, мёдом и корицей. Посолите — сладкая начинка без соли будет плоской.\nНаполните тыкву начинкой, не утрамбовывая, накройте срезанной крышкой и поставьте на противень.\nЗапекайте при 180 °C полтора часа. Готовность проверяют ножом сбоку: он должен входить в стенку без усилия.\nДайте постоять пятнадцать минут, вынесите целиком и разрежьте на дольки от макушки к дну.","source":"UniTools"},{"id":"ut-spas","name":"Спас","country":"Армения","category":"soup","diets":["vegetarian"],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":280,"p":14,"f":12,"c":30},"details":[{"name":"Мацун или натуральный йогурт","quantity":1,"unit":"l","note":""},{"name":"Дзавар (пшеничная крупа)","quantity":120,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Кинза","quantity":20,"unit":"g","note":""},{"name":"Мята сушёная","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите дзавар на ночь, затем отварите в литре воды до мягкости, минут двадцать пять. Воду не сливайте.\nВзбейте мацун с яйцом и мукой до полной однородности. Комков остаться не должно — каждый из них станет хлопьями в супе.\nПерелейте смесь в холодную кастрюлю и грейте на среднем огне, помешивая деревянной ложкой в одну сторону, пока не закипит.\nКак только пойдут первые пузыри, вмешайте крупу вместе с её водой и держите на слабом огне ещё пять минут.\nОбжарьте лук в сливочном масле до золотистого и вмешайте в суп вместе с сушёной мятой. Посолите.\nРазлейте по тарелкам и посыпьте кинзой. Кипятить повторно спас нельзя — разогревают только до горячего.","source":"UniTools"},{"id":"ut-shah-plov","name":"Шах-плов","country":"Азербайджан","category":"main","diets":[],"slots":["lunch","dinner"],"time":115,"baseServings":6,"portionNutrition":{"k":720,"p":30,"f":34,"c":75},"details":[{"name":"Рис басмати","quantity":600,"unit":"g","note":""},{"name":"Баранина","quantity":700,"unit":"g","note":"мякоть, кубиками"},{"name":"Тонкий лаваш","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Каштаны","quantity":200,"unit":"g","note":"очищенные"},{"name":"Курага","quantity":100,"unit":"g","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Топлёное масло","quantity":180,"unit":"g","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите рис в подсоленной воде на час, потом отварите семь минут в большом объёме воды и откиньте.\nЗалейте шафран тремя ложками кипятка и оставьте настаиваться — он даст и цвет, и запах.\nОбжарьте баранину до корочки, добавьте лук и жарьте до мягкости. Всыпьте каштаны, курагу, изюм и куркуму, тушите двадцать минут.\nСмажьте форму топлёным маслом и выстелите лавашем внахлёст, оставив края свисать наружу.\nВыложите слоями: рис, начинку, снова рис. Полейте шафранным настоем и оставшимся маслом.\nЗаверните края лаваша внутрь, накройте фольгой и запекайте при 180 °C сорок минут, потом снимите фольгу и держите ещё пятнадцать до румяности.\nДайте постоять десять минут, накройте блюдом и переверните. Режьте на столе.","source":"UniTools"},{"id":"ut-kufta-bozbash","name":"Кюфта-бозбаш","country":"Азербайджан","category":"soup","diets":[],"slots":["lunch","dinner"],"time":110,"baseServings":4,"portionNutrition":{"k":560,"p":34,"f":26,"c":46},"details":[{"name":"Баранина","quantity":500,"unit":"g","note":"фарш"},{"name":"Баранина на кости","quantity":400,"unit":"g","note":"для бульона"},{"name":"Рис","quantity":3,"unit":"tbsp","note":""},{"name":"Нут","quantity":150,"unit":"g","note":"замочить на ночь"},{"name":"Картофель","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Алыча сушёная","quantity":4,"unit":"piece","note":""},{"name":"Курага","quantity":4,"unit":"piece","note":""},{"name":"Мята сушёная","quantity":1,"unit":"tsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте мясо на кости холодной водой, доведите до кипения и снимайте пену. Добавьте нут и варите на слабом огне час.\nВмешайте в фарш тёртую луковицу, рис, соль и перец и вымешивайте пять минут, пока масса не начнёт тянуться за рукой.\nРазделите фарш на четыре части. В каждую спрячьте по алыче и кураге и слепите плотный шар без трещин.\nОпустите кюфту в едва кипящий бульон и варите тридцать минут, не мешая. Первые пять минут не трогайте вовсе.\nДобавьте картофель целиком и куркуму и варите ещё двадцать минут, пока картофель не станет мягким.\nВ каждую тарелку положите кюфту, картофелину и нут, залейте бульоном и разотрите над тарелкой сушёную мяту.","source":"UniTools"},{"id":"ut-beshbarmak","name":"Бешбармак","country":"Казахстан","category":"main","diets":[],"slots":["lunch","dinner"],"time":220,"baseServings":6,"portionNutrition":{"k":690,"p":45,"f":28,"c":63},"details":[{"name":"Говядина на кости","quantity":1.5,"unit":"kg","note":"грудинка или лопатка"},{"name":"Казы или конина","quantity":300,"unit":"g","note":"по желанию"},{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Яйцо","quantity":2,"unit":"piece","note":""},{"name":"Вода для теста","quantity":180,"unit":"ml","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Чёрный перец горошком","quantity":10,"unit":"piece","note":""},{"name":"Зелень","quantity":20,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте мясо холодной водой, доведите до кипения, снимите пену и варите на самом слабом огне два с половиной часа с перцем и лавром.\nЗамесите крутое тесто из муки, яиц, воды и соли и оставьте под плёнкой на сорок минут.\nРаскатайте тесто в пласт толщиной в миллиметр и нарежьте квадратами со стороной около восьми сантиметров.\nНарежьте лук кольцами, залейте половником горячего бульона и дайте постоять десять минут — это сорпа для подливы.\nВыньте мясо, снимите жир с бульона в отдельную миску и отварите в этом бульоне квадраты теста порциями по три-четыре минуты.\nРазберите мясо на тонкие пласты поперёк волокон. Выложите тесто на большое блюдо, сверху мясо, сверху лук с бульоном.\nОставшийся бульон подайте горячим в пиалах с зеленью — его пьют до или вместе с блюдом.","source":"UniTools"},{"id":"ut-baursaki","name":"Баурсаки","country":"Казахстан","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":55,"baseServings":8,"portionNutrition":{"k":330,"p":8,"f":14,"c":44},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Молоко","quantity":300,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Яйцо","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":"растопить"},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи и сахар в тёплом молоке и оставьте на десять минут до появления пены.\nВмешайте яйца, растопленное масло, соль и муку и замесите мягкое тесто. Оно должно чуть липнуть к рукам.\nНакройте и оставьте в тепле на час, пока тесто не удвоится.\nОбомните, раскатайте в пласт толщиной полтора сантиметра и нарежьте квадратами или ромбами по три сантиметра.\nДайте заготовкам постоять под полотенцем двадцать минут — второй подъём и есть причина пустоты внутри.\nРазогрейте масло до 170 °C и жарьте партиями по две-три минуты, переворачивая, до ровного золотистого цвета.\nВыкладывайте на бумагу и подавайте тёплыми — с чаем, сметаной или мёдом.","source":"UniTools"},{"id":"ut-bryndzove-halusky","name":"Брынзове галушки","country":"Словакия","category":"main","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":640,"p":24,"f":34,"c":58},"details":[{"name":"Картофель","quantity":1,"unit":"kg","note":"сырой, натереть мелко"},{"name":"Мука","quantity":250,"unit":"g","note":""},{"name":"Овечья брынза","quantity":400,"unit":"g","note":""},{"name":"Копчёная грудинка","quantity":200,"unit":"g","note":"кубиками"},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите картофель на мелкой тёрке и слегка отожмите — воды должно уйти немного, полностью сухая масса не свяжется.\nВмешайте муку, яйцо и соль. Масса должна медленно сползать с ложки, а не литься.\nОбжарьте грудинку на сухой сковороде до хруста и снимите, оставив жир.\nПродавите тесто в кипящую подсоленную воду через дуршлаг с крупными отверстиями. Клёцки готовы, когда всплывут — минуты через три.\nОткиньте клёцки, верните в тёплую кастрюлю и вмешайте брынзу с ложкой воды от варки. Огонь не включайте.\nРазложите по тарелкам, полейте горячим жиром и посыпьте шкварками.","source":"UniTools"},{"id":"ut-kapustnica","name":"Капустница","country":"Словакия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":480,"p":26,"f":30,"c":26},"details":[{"name":"Квашеная капуста","quantity":700,"unit":"g","note":"с рассолом"},{"name":"Копчёные рёбрышки","quantity":500,"unit":"g","note":""},{"name":"Копчёная колбаса","quantity":300,"unit":"g","note":"кружками"},{"name":"Сушёные белые грибы","quantity":30,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чернослив","quantity":100,"unit":"g","note":""},{"name":"Паприка сладкая","quantity":1,"unit":"tbsp","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Сметана","quantity":150,"unit":"ml","note":"к подаче"},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите грибы в стакане тёплой воды на двадцать минут. Воду сохраните.\nОтварите копчёные рёбрышки в двух литрах воды сорок минут с лавровым листом.\nОтожмите капусту, рассол отложите. Добавьте капусту, грибы с их водой и чернослив в бульон и варите тридцать минут.\nОбжарьте лук, снимите с огня, вмешайте паприку и муку и разведите половником бульона до однородности.\nВылейте заправку в кастрюлю, добавьте колбасу и варите ещё пятнадцать минут.\nСнимите мясо с костей, верните в суп и доведите кислоту рассолом по вкусу. Подавайте со сметаной.","source":"UniTools"},{"id":"ut-pastel-de-choclo","name":"Пастель-де-чокло","country":"Чили","category":"main","diets":[],"slots":["lunch","dinner"],"time":100,"baseServings":6,"portionNutrition":{"k":620,"p":34,"f":27,"c":62},"details":[{"name":"Кукуруза","quantity":1.2,"unit":"kg","note":"зёрна, свежие или замороженные"},{"name":"Говяжий фарш","quantity":700,"unit":"g","note":""},{"name":"Куриное бедро","quantity":400,"unit":"g","note":"отварное, кусками"},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":"варёные, половинками"},{"name":"Оливки чёрные","quantity":12,"unit":"piece","note":""},{"name":"Изюм","quantity":60,"unit":"g","note":""},{"name":"Базилик","quantity":20,"unit":"g","note":""},{"name":"Молоко","quantity":250,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Зира молотая","quantity":1,"unit":"tbsp","note":""},{"name":"Сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мелко нарезанный лук до прозрачности, добавьте фарш, зиру, соль и перец и жарьте до готовности. Дайте пино остыть — тёплое даст воду.\nПробейте кукурузу с базиликом и молоком в блендере до крупной, но однородной массы.\nУварите эту массу со сливочным маслом на среднем огне, помешивая, минут пятнадцать — до густоты, в которой ложка стоит.\nРазложите пино по глиняным формам, сверху — кусок курицы, половинка яйца и пара оливок с изюмом.\nЗакройте кукурузной массой слоем в два сантиметра, разровняйте и посыпьте сахаром.\nЗапекайте при 200 °C сорок минут, последние пять — под грилем, до тёмной карамельной корки.","source":"UniTools"},{"id":"ut-empanadas-de-pino","name":"Эмпанадас-де-пино","country":"Чили","category":"snack","diets":[],"slots":["snack"],"time":90,"baseServings":6,"portionNutrition":{"k":590,"p":26,"f":29,"c":55},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Топлёный свиной жир","quantity":120,"unit":"g","note":""},{"name":"Молоко","quantity":200,"unit":"ml","note":"тёплое"},{"name":"Говядина","quantity":600,"unit":"g","note":"нарезать кубиком, не молоть"},{"name":"Лук","quantity":5,"unit":"piece","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":"варёные"},{"name":"Оливки чёрные","quantity":12,"unit":"piece","note":""},{"name":"Изюм","quantity":60,"unit":"g","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте лук кубиком и томите в жире двадцать минут на слабом огне — он должен стать сладким, а не золотистым.\nДобавьте мясо, паприку и зиру и тушите двадцать минут. Лука по объёму должно быть не меньше, чем мяса.\nУберите начинку в холодильник минимум на три часа, лучше на ночь.\nЗамесите тесто из муки, растопленного жира, тёплого молока и соли. Вымешивайте десять минут и дайте отдохнуть полчаса.\nРаскатайте кругами диаметром двадцать сантиметров. На каждый — две ложки начинки, оливка, четвертинка яйца и щепоть изюма.\nСложите конвертом, защипните края и подверните их дважды. Проколите верх зубочисткой, чтобы вышел пар.\nСмажьте желтком и пеките при 200 °C двадцать пять минут до тёмно-золотого цвета.","source":"UniTools"},{"id":"ut-pabellon-criollo","name":"Пабельон-криольо","country":"Венесуэла","category":"main","diets":[],"slots":["lunch","dinner"],"time":180,"baseServings":4,"portionNutrition":{"k":780,"p":45,"f":24,"c":96},"details":[{"name":"Говяжья пашина","quantity":800,"unit":"g","note":""},{"name":"Чёрная фасоль","quantity":350,"unit":"g","note":"замочить на ночь"},{"name":"Рис длиннозёрный","quantity":350,"unit":"g","note":""},{"name":"Подорожник","quantity":2,"unit":"piece","note":"спелый, с чёрной кожурой"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Помидоры","quantity":400,"unit":"g","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите фасоль с половиной лука и чесноком до мягкости — час-полтора. Посолите в конце.\nОтварите говядину целым куском в подсоленной воде час двадцать. Выньте и остудите настолько, чтобы брать руками.\nРазберите мясо на волокна вдоль. Поперёк рвать нельзя — получится крошка.\nОбжарьте оставшийся лук, перец и чеснок, добавьте помидоры и зиру, потом мясо, и тушите двадцать минут с половником бульона.\nОтварите рис рассыпчатым, без масла и специй — он здесь нейтральная часть.\nНарежьте подорожник по диагонали и обжарьте на среднем огне до карамельного цвета с обеих сторон.\nСоберите тарелку секторами: рис, фасоль, мясо и бананы рядом, не смешивая.","source":"UniTools"},{"id":"ut-cachapas","name":"Качапас","country":"Венесуэла","category":"breakfast","diets":["vegetarian","gluten-free"],"slots":["breakfast"],"time":40,"baseServings":4,"portionNutrition":{"k":430,"p":16,"f":20,"c":48},"details":[{"name":"Кукуруза","quantity":800,"unit":"g","note":"зёрна с 6-8 початков"},{"name":"Мягкий белый сыр","quantity":300,"unit":"g","note":""},{"name":"Молоко","quantity":80,"unit":"ml","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Срежьте зёрна с початков и пробейте блендером с молоком, сахаром и солью до крупного, но текучего пюре.\nДайте тесту постоять десять минут. Крахмал набухнет, и оладьи будут держать форму.\nРазогрейте сковороду до среднего жара, смажьте маслом и вылейте половник теста, разровняв в круг сантиметр толщиной.\nЖарьте четыре минуты, пока края не подсохнут и низ не станет пятнистым, переверните и дайте ещё три.\nПоложите на горячую качапу кусок масла и сыр, сложите пополам и прижмите лопаткой.\nПодавайте сразу. Остывшая качапа теряет мягкость и становится похожа на плотный корж.","source":"UniTools"},{"id":"ut-saltenas","name":"Сальтеньяс","country":"Боливия","category":"snack","diets":[],"slots":["snack"],"time":120,"baseServings":6,"portionNutrition":{"k":560,"p":24,"f":26,"c":58},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Ачиоте или паприка","quantity":2,"unit":"tsp","note":""},{"name":"Говядина","quantity":500,"unit":"g","note":"мелким кубиком"},{"name":"Картофель","quantity":300,"unit":"g","note":"кубиком, отварной"},{"name":"Зелёный горошек","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Желатин","quantity":20,"unit":"g","note":""},{"name":"Говяжий бульон","quantity":500,"unit":"ml","note":""},{"name":"Перец ахи или острая паприка","quantity":2,"unit":"tsp","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":"варёные, дольками"},{"name":"Оливки","quantity":12,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук с ахи и зирой, добавьте мясо и жарьте до готовности. Влейте бульон и проварите десять минут.\nРаспустите желатин в паре ложек горячей воды и вмешайте в рагу вместе с картофелем и горошком.\nОстудите начинку и уберите в холодильник минимум на четыре часа — она должна стать плотным желе.\nЗамесите тесто из муки, размягчённого масла, сахара, ачиоте, соли и тёплой воды. Дайте отдохнуть полчаса.\nРаскатайте круги в пятнадцать сантиметров. На каждый — ложка холодного желе, долька яйца и оливка.\nЗащипните шов косичкой поверху и поставьте пирожки швом вверх. Любая щель — это вытекший бульон.\nПеките при 220 °C двадцать пять минут. Высокий жар нужен, чтобы тесто схватилось раньше, чем растает желе.","source":"UniTools"},{"id":"ut-silpancho","name":"Сильпанчо","country":"Боливия","category":"main","diets":[],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":810,"p":42,"f":36,"c":82},"details":[{"name":"Говядина","quantity":600,"unit":"g","note":"тонкие куски для отбивания"},{"name":"Панировочные сухари","quantity":200,"unit":"g","note":""},{"name":"Рис","quantity":300,"unit":"g","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":"отварить и нарезать кружками"},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Лук красный","quantity":1,"unit":"piece","note":""},{"name":"Свёкла","quantity":1,"unit":"piece","note":"отварная"},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отбейте мясо через плёнку до толщины три-четыре миллиметра. Работайте от центра к краям, иначе куски порвутся.\nПосолите, поперчите и обваляйте в сухарях, прижимая их ладонью. Яйцо для панировки здесь не используют.\nНарежьте помидоры, лук и свёклу мелким кубиком, смешайте с петрушкой, солью и ложкой масла.\nОбжарьте кружки варёного картофеля до румяности и держите в тепле.\nЖарьте отбивные по полторы минуты с каждой стороны в горячем масле — тонкое мясо готовится мгновенно.\nПожарьте яйца, оставив желток жидким.\nСоберите: рис, картофель, отбивная во всю тарелку, яйцо и сырая смесь сверху.","source":"UniTools"},{"id":"ut-encebollado","name":"Энсебольядо","country":"Эквадор","category":"soup","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":420,"p":40,"f":11,"c":42},"details":[{"name":"Тунец","quantity":700,"unit":"g","note":"свежий, куском"},{"name":"Юкка (маниок)","quantity":700,"unit":"g","note":"очистить, нарезать брусками"},{"name":"Лук красный","quantity":2,"unit":"piece","note":"тонкими перьями"},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте лук в соке двух лаймов с солью и оставьте минимум на пятнадцать минут.\nОбжарьте чеснок и помидоры с зирой пять минут, влейте полтора литра воды и доведите до кипения.\nОпустите тунца целым куском и варите пятнадцать минут на слабом огне. Бурного кипения рыба не терпит.\nВыньте рыбу, процедите бульон и верните на огонь. Отварите в нём юкку двадцать минут до мягкости.\nРазберите тунца на крупные хлопья, убрав тёмные части, и верните в кастрюлю на две минуты.\nРазлейте по тарелкам, сверху — маринованный лук с его соком и кинза. Подавайте с долькой лайма.","source":"UniTools"},{"id":"ut-llapingachos","name":"Льяпингачос","country":"Эквадор","category":"side","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":520,"p":20,"f":27,"c":50},"details":[{"name":"Картофель","quantity":1,"unit":"kg","note":"мучнистых сортов"},{"name":"Мягкий белый сыр","quantity":250,"unit":"g","note":""},{"name":"Ачиоте или паприка","quantity":2,"unit":"tsp","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Арахисовая паста","quantity":150,"unit":"g","note":""},{"name":"Молоко","quantity":250,"unit":"ml","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите картофель в мундире, очистите горячим и разомните в сухое пюре. Никакой жидкости не добавляйте.\nПрогрейте ачиоте в ложке масла минуту и вмешайте окрашенное масло в пюре вместе с солью.\nСлепите шарики, вдавите в каждый кубик сыра, закройте и приплюсните в лепёшку в сантиметр толщиной.\nОхладите лепёшки полчаса — так они держат форму на сковороде.\nДля соуса обжарьте лук, добавьте арахисовую пасту и молоко и проварите пять минут до густоты сливок.\nЖарьте лепёшки на среднем огне по четыре минуты с каждой стороны до румяной корки.\nПодавайте с яичницей, соусом и салатом из авокадо.","source":"UniTools"},{"id":"ut-masgouf","name":"Масгуф","country":"Ирак","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":105,"baseServings":4,"portionNutrition":{"k":480,"p":52,"f":27,"c":8},"details":[{"name":"Карп","quantity":2,"unit":"kg","note":"целый, разрезать вдоль спины"},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Тамариндовая паста","quantity":2,"unit":"tbsp","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Карри молотое","quantity":1,"unit":"tbsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разрежьте рыбу вдоль спины, не разделяя брюхо, выпотрошите и разверните книгой. Хребет оставьте на месте.\nСмешайте масло, куркуму, тамаринд, карри, соль и перец и смажьте мякоть. Кожу не трогайте.\nОставьте рыбу на полчаса при комнатной температуре — холодная будет готовиться неравномерно.\nРазожгите огонь и дайте ему прогореть до устойчивого пламени. Установите рыбу вертикально мякотью к огню в полуметре от него.\nГотовьте час, поворачивая по мере надобности. Мякоть должна побелеть и подсохнуть по краям, но не подгореть.\nПереложите рыбу кожей вниз на угли, выложите сверху лук и помидоры и держите ещё десять минут.\nПодавайте прямо на доске, с лепёшкой, лимоном и сырым луком.","source":"UniTools"},{"id":"ut-dolma-iraqi","name":"Иракская долма","country":"Ирак","category":"main","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":520,"p":20,"f":22,"c":62},"details":[{"name":"Виноградные листья","quantity":300,"unit":"g","note":""},{"name":"Рис круглозёрный","quantity":400,"unit":"g","note":""},{"name":"Баранина","quantity":400,"unit":"g","note":"фарш"},{"name":"Перец сладкий","quantity":4,"unit":"piece","note":""},{"name":"Лук крупный","quantity":3,"unit":"piece","note":""},{"name":"Баклажаны","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Гранатовый соус","quantity":3,"unit":"tbsp","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Петрушка","quantity":40,"unit":"g","note":""},{"name":"Бахарат","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис и смешайте с фаршем, рубленой петрушкой, томатной пастой, бахаратом, маслом, солью и перцем.\nСрежьте у перцев и помидоров крышечки, выньте мякоть. Разберите лук на слои, ошпарив его целиком.\nЗаверните начинку в виноградные листья плотными валиками — рис разбухнет вдвое, оставьте ему место.\nНаполните овощи начинкой на две трети и закройте срезанными крышечками.\nВыложите на дно кастрюли кружки помидора, затем слоями голубцы и фаршированные овощи, самые плотные — вниз.\nСмешайте воду с гранатовым соусом, лимонным соком и солью и залейте так, чтобы жидкость доходила до верхнего слоя.\nНакройте тарелкой с грузом и варите на слабом огне час пятнадцать. Подавайте, перевернув кастрюлю на блюдо.","source":"UniTools"},{"id":"ut-mansaf","name":"Мансаф","country":"Иордания","category":"main","diets":[],"slots":["lunch","dinner"],"time":190,"baseServings":8,"portionNutrition":{"k":820,"p":48,"f":38,"c":74},"details":[{"name":"Баранина на кости","quantity":2,"unit":"kg","note":"крупными кусками"},{"name":"Джамид","quantity":500,"unit":"g","note":"или 1 кг густого йогурта"},{"name":"Рис длиннозёрный","quantity":700,"unit":"g","note":""},{"name":"Тонкая лепёшка","quantity":4,"unit":"piece","note":""},{"name":"Миндаль","quantity":100,"unit":"g","note":""},{"name":"Кедровые орехи","quantity":60,"unit":"g","note":""},{"name":"Топлёное масло","quantity":100,"unit":"g","note":""},{"name":"Кардамон","quantity":6,"unit":"piece","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите джамид в тёплой воде на четыре часа, разомните руками и процедите через сито до однородной жидкости.\nОтварите баранину с кардамоном час двадцать, снимая пену. Бульон сохраните.\nВлейте разведённый джамид в кастрюлю с мясом и доводите до кипения, непрерывно помешивая в одном направлении.\nУбавьте огонь до минимума и томите сорок минут. Соус загустеет и станет кремовым.\nСварите рис на мясном бульоне с куркумой и ложкой топлёного масла.\nОбжарьте миндаль и кедровые орехи в топлёном масле до золотистого и отложите.\nВыстелите блюдо лепёшкой, смочите её соусом, выложите рис, сверху мясо, полейте соусом и посыпьте орехами и петрушкой.","source":"UniTools"},{"id":"ut-maqluba","name":"Маклюба","country":"Иордания","category":"main","diets":[],"slots":["lunch","dinner"],"time":135,"baseServings":6,"portionNutrition":{"k":690,"p":34,"f":30,"c":72},"details":[{"name":"Курица","quantity":1.2,"unit":"kg","note":"кусками"},{"name":"Рис длиннозёрный","quantity":500,"unit":"g","note":""},{"name":"Баклажаны","quantity":3,"unit":"piece","note":""},{"name":"Цветная капуста","quantity":500,"unit":"g","note":""},{"name":"Картофель","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Бахарат","quantity":1,"unit":"tbsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Кедровые орехи","quantity":60,"unit":"g","note":""},{"name":"Растительное масло","quantity":200,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу с луком, корицей и бахаратом сорок минут. Мясо выньте, бульон процедите.\nЗамочите рис в тёплой воде на двадцать минут и промойте до прозрачной воды.\nНарежьте баклажаны кружками, посолите и дайте постоять пятнадцать минут, потом обсушите и обжарьте до румяности.\nОбжарьте соцветия цветной капусты и кружки картофеля до золотистого и выложите на бумагу.\nВыложите на дно кастрюли картофель, затем баклажаны по стенкам, курицу, капусту и сверху рис. Не утрамбовывайте.\nЗалейте горячим бульоном на палец выше риса, доведите до кипения и варите под крышкой сорок минут на слабом огне.\nСнимите с огня, дайте постоять десять минут, накройте блюдом и переверните одним движением. Посыпьте орехами.","source":"UniTools"},{"id":"ut-brik","name":"Брик","country":"Тунис","category":"snack","diets":[],"slots":["snack"],"time":30,"baseServings":4,"portionNutrition":{"k":390,"p":20,"f":24,"c":24},"details":[{"name":"Листы малсука или фило","quantity":4,"unit":"piece","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Тунец консервированный","quantity":200,"unit":"g","note":""},{"name":"Картофель","quantity":2,"unit":"piece","note":"отварной, размятый"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Каперсы","quantity":2,"unit":"tbsp","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Харисса","quantity":1,"unit":"tsp","note":""},{"name":"Масло для жарки","quantity":500,"unit":"ml","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте размятый картофель с тунцом, рубленым луком, каперсами, петрушкой, хариссой, солью и перцем.\nРазогрейте масло до 180 °C. Проверьте кусочком теста — он должен всплыть сразу и зашипеть.\nПоложите лист на тарелку, выложите на половину две ложки начинки и сделайте в ней углубление.\nРазбейте яйцо в углубление, посолите и сразу же сложите лист пополам, прижав края.\nОпустите брик в масло и жарьте по сорок секунд с каждой стороны, придерживая шумовкой.\nВыложите на бумагу и подавайте немедленно с долькой лимона.","source":"UniTools"},{"id":"ut-shakshuka-tunisienne","name":"Тунисский лаблаби","country":"Тунис","category":"soup","diets":["vegetarian"],"slots":["lunch","dinner"],"time":105,"baseServings":4,"portionNutrition":{"k":520,"p":22,"f":22,"c":60},"details":[{"name":"Нут","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Чёрствый белый хлеб","quantity":300,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Харисса","quantity":3,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Оливки","quantity":80,"unit":"g","note":""},{"name":"Каперсы","quantity":2,"unit":"tbsp","note":""},{"name":"Тунец консервированный","quantity":150,"unit":"g","note":"по желанию"},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите нут в двух литрах воды с половиной чеснока полтора часа, пока он не станет мягким, но целым.\nРазотрите оставшийся чеснок с солью и тмином в пасту и вмешайте в бульон. Посолите.\nОтварите яйца всмятку — шесть минут от закипания — и очистите.\nНаломайте хлеб крупными кусками в глубокие миски, заполнив их наполовину.\nЗалейте хлеб горячим бульоном с нутом так, чтобы он полностью пропитался.\nПоложите сверху яйцо, ложку хариссы, оливки, каперсы и тунца, полейте оливковым маслом и лимоном.","source":"UniTools"},{"id":"ut-couscous-algerien","name":"Алжирский кускус","country":"Алжир","category":"main","diets":[],"slots":["lunch","dinner"],"time":160,"baseServings":6,"portionNutrition":{"k":760,"p":40,"f":30,"c":88},"details":[{"name":"Кускус","quantity":700,"unit":"g","note":""},{"name":"Баранина","quantity":1,"unit":"kg","note":"на кости, кусками"},{"name":"Нут","quantity":200,"unit":"g","note":"замочить на ночь"},{"name":"Морковь","quantity":4,"unit":"piece","note":""},{"name":"Репа","quantity":3,"unit":"piece","note":""},{"name":"Кабачки","quantity":3,"unit":"piece","note":""},{"name":"Тыква","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Рас-эль-ханут","quantity":1,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Харисса","quantity":2,"unit":"tbsp","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мясо с луком в нижнем ярусе кускусницы, добавьте томатную пасту, специи, нут и залейте водой. Варите час.\nСбрызните кускус водой с маслом и разотрите руками, чтобы крупинки разошлись. Пропарьте пятнадцать минут.\nВысыпьте крупу в широкое блюдо, снова сбрызните водой, разрыхлите и дайте остыть пять минут.\nВерните на пар ещё на пятнадцать минут. Тем временем добавьте в бульон морковь и репу.\nПовторите разрыхление третий раз, добавив сливочное масло, и пропарьте последние десять минут.\nЗаложите в бульон кабачки и тыкву на последние двадцать минут — они готовятся быстрее корнеплодов.\nВыложите кускус горкой, сверху мясо и овощи. Бульон подайте в отдельной миске, хариссу — в третьей.","source":"UniTools"},{"id":"ut-chorba-frik","name":"Чорба-фрик","country":"Алжир","category":"soup","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":420,"p":28,"f":18,"c":38},"details":[{"name":"Баранина","quantity":500,"unit":"g","note":"мелким кубиком"},{"name":"Фрик (зелёная пшеница)","quantity":150,"unit":"g","note":""},{"name":"Нут","quantity":150,"unit":"g","note":"замочить на ночь"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":400,"unit":"g","note":"тёртые"},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Сельдерей стеблевой","quantity":2,"unit":"piece","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Мята сушёная","quantity":2,"unit":"tsp","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":50,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мясо с луком и сельдереем в топлёном масле до румяности, десять минут.\nДобавьте тёртые помидоры, томатную пасту, корицу, соль и перец и тушите пять минут.\nЗалейте двумя литрами кипятка, добавьте нут и варите сорок минут на слабом огне.\nПромойте фрик, всыпьте в суп и варите ещё двадцать минут, помешивая — крупа оседает и пригорает.\nВмешайте кинзу за пять минут до конца и доведите густоту водой, если суп стал слишком плотным.\nРазлейте по тарелкам, разотрите сверху сушёную мяту и добавьте лимонный сок.","source":"UniTools"},{"id":"ut-cepelinai","name":"Цеппелинай","country":"Литва","category":"main","diets":[],"slots":["lunch","dinner"],"time":100,"baseServings":4,"portionNutrition":{"k":720,"p":28,"f":38,"c":68},"details":[{"name":"Картофель сырой","quantity":1.5,"unit":"kg","note":"натереть мелко"},{"name":"Картофель варёный","quantity":500,"unit":"g","note":""},{"name":"Свиной фарш","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Копчёное сало","quantity":200,"unit":"g","note":"кубиками"},{"name":"Сметана","quantity":200,"unit":"ml","note":""},{"name":"Картофельный крахмал","quantity":2,"unit":"tbsp","note":""},{"name":"Майоран","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите сырой картофель на мелкой тёрке и отожмите через полотенце. Жидкость соберите в миску.\nДайте жидкости постоять десять минут, слейте воду, а осевший крахмал вмешайте обратно в тёртую массу.\nРазомните варёный картофель и соедините с тёртым, добавив крахмал и соль. Масса должна лепиться и не липнуть.\nСмешайте фарш с половиной мелко нарезанного лука, майораном, солью и перцем и слепите четыре плотных шарика.\nВозьмите мокрыми руками ком теста, расплющите на ладони, положите начинку и залепите в удлинённый овал.\nОпустите в едва кипящую подсоленную воду и варите двадцать пять минут. Не мешайте — только качните кастрюлю в первую минуту.\nВытопите сало с оставшимся луком до шкварок, полейте цеппелинай и подайте со сметаной.","source":"UniTools"},{"id":"ut-saltibarsciai","name":"Шалтибарщяй","country":"Литва","category":"soup","diets":["vegetarian"],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":320,"p":14,"f":12,"c":40},"details":[{"name":"Свёкла","quantity":500,"unit":"g","note":"отварная, натёртая"},{"name":"Кефир","quantity":1,"unit":"l","note":"холодный"},{"name":"Огурцы","quantity":2,"unit":"piece","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":"варёные вкрутую"},{"name":"Укроп","quantity":40,"unit":"g","note":""},{"name":"Зелёный лук","quantity":40,"unit":"g","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":"к подаче, горячий"},{"name":"Сметана","quantity":150,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите свёклу до мягкости, остудите полностью и натрите на крупной тёрке.\nНарежьте огурцы соломкой, порубите укроп и зелёный лук.\nСмешайте свёклу, огурцы и зелень со сметаной и посолите — до кефира, чтобы соль разошлась.\nВлейте холодный кефир и размешайте. Суп станет ровного розового цвета.\nУберите в холодильник на час. Тёплый шалтибарщяй не имеет смысла.\nОтварите картофель и подайте горячим на отдельной тарелке. В суп положите половинки яиц.","source":"UniTools"},{"id":"ut-pelekie-zirni-ar-speki","name":"Серый горох со шпеком","country":"Латвия","category":"main","diets":[],"slots":["lunch","dinner"],"time":105,"baseServings":4,"portionNutrition":{"k":610,"p":28,"f":30,"c":54},"details":[{"name":"Серый горох","quantity":500,"unit":"g","note":"замочить на ночь"},{"name":"Копчёная грудинка","quantity":300,"unit":"g","note":"кубиками"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Кефир","quantity":300,"unit":"ml","note":"к подаче"},{"name":"Чёрный перец","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите горох на двенадцать часов в холодной воде, меняя её один раз.\nСлейте воду, залейте свежей на два пальца выше и варите час двадцать без соли до мягкости.\nНарежьте грудинку кубиком и вытопите на сухой сковороде до румяных шкварок.\nДобавьте нарезанный лук и жарьте в вытопившемся жире до мягкости и золотистого цвета.\nСлейте с гороха воду, оставив немного на дне, посолите и поперчите.\nВмешайте шкварки с луком и жиром в горох и подавайте горячим, с холодным кефиром в стакане.","source":"UniTools"},{"id":"ut-rupjmaizes-kartojums","name":"Слоёный ржаной десерт","country":"Латвия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":40,"baseServings":6,"portionNutrition":{"k":470,"p":6,"f":26,"c":54},"details":[{"name":"Ржаной хлеб","quantity":400,"unit":"g","note":"чёрствый, в крошку"},{"name":"Сливки 33%","quantity":500,"unit":"ml","note":""},{"name":"Клюквенное варенье","quantity":300,"unit":"g","note":""},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Ванильный сахар","quantity":1,"unit":"tsp","note":""},{"name":"Клюква","quantity":60,"unit":"g","note":"к подаче"}],"steps":"Раскрошите чёрствый хлеб в блендере или руками до крупной крошки.\nСмешайте крошку с сахаром и корицей и подсушите в духовке при 160 °C двенадцать минут, помешав дважды.\nПолностью остудите крошку. В тёплую сливки осядут, и слои смешаются.\nВзбейте холодные сливки с ванильным сахаром до устойчивых пиков.\nВыкладывайте в стаканы слоями: крошка, варенье, сливки, и так дважды. Заканчивайте сливками.\nУберите в холодильник минимум на четыре часа, лучше на ночь. Подавайте с клюквой сверху.","source":"UniTools"},{"id":"ut-mulgipuder","name":"Мульгипудер","country":"Эстония","category":"main","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":4,"portionNutrition":{"k":560,"p":18,"f":26,"c":64},"details":[{"name":"Перловая крупа","quantity":250,"unit":"g","note":"промыть"},{"name":"Картофель","quantity":1,"unit":"kg","note":""},{"name":"Копчёная грудинка","quantity":250,"unit":"g","note":"кубиками"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Молоко","quantity":150,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте перловку и варите в подсоленной воде час, пока она не станет мягкой.\nДобавьте в ту же кастрюлю крупно нарезанный картофель и варите ещё двадцать минут.\nВытопите грудинку до шкварок, добавьте лук и жарьте до золотистого.\nСлейте с крупы и картофеля почти всю воду, оставив полстакана.\nРазомните толкушкой с маслом и молоком, оставив зёрна перловки различимыми. Посолите и поперчите.\nРазложите по тарелкам и полейте шкварками с луком и вытопленным жиром.","source":"UniTools"},{"id":"ut-kama","name":"Кама","country":"Эстония","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":10,"baseServings":4,"portionNutrition":{"k":310,"p":12,"f":6,"c":52},"details":[{"name":"Мука кама","quantity":200,"unit":"g","note":""},{"name":"Кефир","quantity":600,"unit":"ml","note":""},{"name":"Сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Мёд","quantity":2,"unit":"tbsp","note":""},{"name":"Лесные ягоды","quantity":200,"unit":"g","note":""},{"name":"Сливки","quantity":100,"unit":"ml","note":"по желанию"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Взбейте кефир с сахаром и щепотью соли до полного растворения сахара.\nВсыпайте каму понемногу, размешивая венчиком, — всё сразу даст комки, которые уже не разбить.\nДайте постоять пятнадцать минут, чтобы мука набухла, и проверьте густоту — при необходимости добавьте кефира.\nВмешайте мёд и разлейте по стаканам.\nОхладите час и подавайте с ягодами и, если хотите, ложкой взбитых сливок.","source":"UniTools"},{"id":"ut-draniki","name":"Драники","country":"Беларусь","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":390,"p":8,"f":22,"c":42},"details":[{"name":"Картофель","quantity":1,"unit":"kg","note":"крахмалистых сортов"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Сметана","quantity":200,"unit":"ml","note":""},{"name":"Укроп","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите картофель и лук на мелкой тёрке в одну миску.\nДайте массе постоять три минуты и слейте отстоявшуюся сверху воду, не трогая осадок.\nПосолите и поперчите. Ничего больше не добавляйте.\nРазогрейте масло на среднем огне и выкладывайте массу столовой ложкой, приплющивая до толщины в полсантиметра.\nЖарьте по три-четыре минуты с каждой стороны до тёмно-золотой хрустящей корки.\nВыложите на бумагу и подавайте немедленно со сметаной и укропом.","source":"UniTools"},{"id":"ut-machanka","name":"Мачанка","country":"Беларусь","category":"main","diets":[],"slots":["lunch","dinner"],"time":75,"baseServings":4,"portionNutrition":{"k":780,"p":34,"f":46,"c":54},"details":[{"name":"Свиная шея","quantity":500,"unit":"g","note":"кубиками"},{"name":"Копчёная колбаса","quantity":250,"unit":"g","note":""},{"name":"Копчёные рёбрышки","quantity":250,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сметана","quantity":300,"unit":"ml","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Мука для блинов","quantity":250,"unit":"g","note":""},{"name":"Молоко","quantity":500,"unit":"ml","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте свинину до румяной корки, добавьте лук и жарьте до мягкости.\nДобавьте нарезанные колбасу и рёбрышки, влейте стакан воды, положите лавровый лист и тушите двадцать пять минут.\nРазмешайте муку со сметаной до однородности и влейте в кастрюлю, помешивая.\nТомите десять минут на слабом огне, пока подлива не загустеет до консистенции жидкой сметаны.\nЗамесите блинное тесто из муки, молока, яиц и соли и дайте постоять пятнадцать минут.\nИспеките тонкие пресные блины на сухой сковороде.\nПодайте мачанку в глубокой миске, блины стопкой рядом. Макают, отрывая по куску.","source":"UniTools"},{"id":"ut-mohinga","name":"Мохинга","country":"Мьянма","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":560,"p":32,"f":18,"c":68},"details":[{"name":"Сом или другая жирная рыба","quantity":800,"unit":"g","note":""},{"name":"Рисовая лапша тонкая","quantity":500,"unit":"g","note":""},{"name":"Лемонграсс","quantity":3,"unit":"piece","note":""},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Рисовая мука обжаренная","quantity":60,"unit":"g","note":""},{"name":"Нутовая мука","quantity":40,"unit":"g","note":""},{"name":"Рыбный соус","quantity":60,"unit":"ml","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":"варёные, к подаче"},{"name":"Жареный горох","quantity":100,"unit":"g","note":"к подаче"},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите рыбу с лемонграссом и куркумой пятнадцать минут, выньте и разберите на мясо, выбросив кости и кожу. Бульон процедите.\nРазотрите лук, чеснок и имбирь в пасту и обжарьте её в масле с паприкой до тёмного цвета и характерного запаха.\nРазомните рыбу вилкой и вмешайте в пасту, обжаривая пять минут — она должна распасться на волокна.\nПереложите всё в кастрюлю с бульоном, влейте рыбный соус и варите двадцать минут на слабом огне.\nРазведите рисовую и нутовую муку холодной водой до жидкой кашицы и вливайте в суп тонкой струйкой, помешивая.\nПроварите ещё двадцать минут, пока бульон не загустеет до консистенции жидких сливок.\nОтварите лапшу, разложите по мискам, залейте супом и подайте с яйцом, горохом, кинзой и лаймом.","source":"UniTools"},{"id":"ut-lahpet-thoke","name":"Лапет-тхоке","country":"Мьянма","category":"salad","diets":["vegetarian"],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":340,"p":14,"f":24,"c":20},"details":[{"name":"Ферментированные чайные листья","quantity":150,"unit":"g","note":""},{"name":"Арахис жареный","quantity":80,"unit":"g","note":""},{"name":"Жареные бобы","quantity":60,"unit":"g","note":""},{"name":"Кунжут","quantity":40,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":"тонкими пластинами"},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Капуста","quantity":200,"unit":"g","note":"тонкой соломкой"},{"name":"Перец чили","quantity":2,"unit":"piece","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Рыбный соус","quantity":2,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте пластины чеснока в масле до золотистого и сразу выньте — за лишние секунды он станет горьким.\nПодсушите кунжут на сухой сковороде до запаха, две минуты, помешивая.\nПромойте чайную пасту холодной водой, если она очень солёная, и отожмите.\nНарежьте капусту тонкой соломкой, помидоры дольками, чили кольцами.\nСоедините всё в миске, добавьте арахис, бобы, кунжут, чесночное масло, рыбный соус и сок лайма.\nПеремешайте руками непосредственно перед подачей и посыпьте жареным чесноком.","source":"UniTools"},{"id":"ut-fish-amok","name":"Фиш-амок","country":"Камбоджа","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":480,"p":32,"f":32,"c":14},"details":[{"name":"Белая рыба","quantity":600,"unit":"g","note":"филе, кусками"},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Кокосовые сливки","quantity":100,"unit":"ml","note":""},{"name":"Лемонграсс","quantity":3,"unit":"piece","note":""},{"name":"Галангал","quantity":30,"unit":"g","note":""},{"name":"Куркума свежая","quantity":20,"unit":"g","note":""},{"name":"Листья каффир-лайма","quantity":6,"unit":"piece","note":""},{"name":"Шалот","quantity":4,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Яйцо","quantity":2,"unit":"piece","note":""},{"name":"Рыбный соус","quantity":2,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Шпинат или молодая капуста","quantity":150,"unit":"g","note":""},{"name":"Банановые листья","quantity":4,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Растолките в ступке лемонграсс, галангал, куркуму, чеснок, шалот и половину листьев лайма в однородную пасту.\nПрогрейте пасту в сотейнике с половиной кокосового молока пять минут, до запаха.\nСнимите с огня, остудите до тёплого и вмешайте яйца, рыбный соус, пальмовый сахар и оставшееся молоко.\nСоедините с кусками рыбы и оставьте мариноваться пятнадцать минут.\nСложите из банановых листьев чашки или возьмите керамические формочки. На дно положите листья шпината.\nРазложите рыбу с соусом по формам, не заполняя доверху, и готовьте на пару двадцать минут.\nПолейте кокосовыми сливками, посыпьте нарезанными листьями лайма и подавайте с рисом.","source":"UniTools"},{"id":"ut-lok-lak","name":"Лок-лак","country":"Камбоджа","category":"main","diets":[],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":520,"p":42,"f":30,"c":18},"details":[{"name":"Говяжья вырезка","quantity":600,"unit":"g","note":"кубиками по 3 см"},{"name":"Устричный соус","quantity":2,"unit":"tbsp","note":""},{"name":"Соевый соус","quantity":2,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Чёрный перец молотый","quantity":2,"unit":"tsp","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Салат листовой","quantity":200,"unit":"g","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Огурец","quantity":1,"unit":"piece","note":""},{"name":"Лук красный","quantity":1,"unit":"piece","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте мясо в устричном и соевом соусах с чесноком, сахаром и половиной перца на двадцать минут.\nСмешайте сок лаймов с оставшимся перцем и щепотью соли — это соус для макания.\nВыложите на блюдо салат, кружки помидора, огурца и кольца красного лука.\nРаскалите сковороду до максимума и обжарьте мясо партиями по полторы минуты, не перемешивая постоянно.\nПожарьте яйца до жидкого желтка.\nВыложите мясо на овощи, сверху яичницу, соус подайте в маленьких мисках отдельно каждому.","source":"UniTools"},{"id":"ut-hainanese-chicken-rice","name":"Хайнаньский рис с курицей","country":"Сингапур","category":"main","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":4,"portionNutrition":{"k":690,"p":46,"f":26,"c":68},"details":[{"name":"Курица","quantity":1.6,"unit":"kg","note":""},{"name":"Рис жасминовый","quantity":400,"unit":"g","note":""},{"name":"Имбирь","quantity":80,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Зелёный лук","quantity":6,"unit":"piece","note":""},{"name":"Кунжутное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Соевый соус","quantity":4,"unit":"tbsp","note":""},{"name":"Перец чили","quantity":6,"unit":"piece","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Огурец","quantity":1,"unit":"piece","note":""},{"name":"Лист пандана","quantity":2,"unit":"piece","note":"по желанию"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите курицу солью снаружи и внутри, вложите в полость половину имбиря и зелёный лук.\nДоведите в кастрюле воду до кипения, опустите курицу целиком, снова доведите до кипения и сразу выключите огонь.\nДержите под крышкой сорок минут, не открывая. Готовность проверяют по прозрачному соку из бедра.\nПереложите курицу в ледяную воду на десять минут, затем обсушите и смажьте кунжутным маслом.\nСнимите с бульона жир, обжарьте в нём рубленый чеснок и имбирь, всыпьте промытый рис и жарьте три минуты.\nЗалейте рис бульоном в пропорции один к полутора, добавьте лист пандана и варите под крышкой пятнадцать минут.\nРастолките чили с чесноком, имбирём и лаймом в соус. Разберите курицу и подайте с рисом, огурцом, соусом и миской бульона.","source":"UniTools"},{"id":"ut-chilli-crab","name":"Краб в соусе чили","country":"Сингапур","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":620,"p":40,"f":28,"c":48},"details":[{"name":"Краб","quantity":1.5,"unit":"kg","note":"разделать на части"},{"name":"Томатный кетчуп","quantity":150,"unit":"ml","note":""},{"name":"Паста самбал","quantity":3,"unit":"tbsp","note":""},{"name":"Перец чили свежий","quantity":4,"unit":"piece","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Рисовый уксус","quantity":2,"unit":"tbsp","note":""},{"name":"Куриный бульон","quantity":300,"unit":"ml","note":""},{"name":"Кукурузный крахмал","quantity":2,"unit":"tbsp","note":""},{"name":"Булочки мантоу","quantity":8,"unit":"piece","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Кинза","quantity":20,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разделайте краба: снимите панцирь, разрубите тело на четыре части, клешни расколите тыльной стороной ножа.\nРастолките чеснок, имбирь и чили в пасту и обжарьте в масле три минуты до запаха.\nДобавьте самбал, кетчуп, сахар и уксус и прогрейте две минуты, чтобы соус потемнел.\nВлейте бульон, доведите до кипения и опустите куски краба. Тушите под крышкой восемь минут.\nРазведите крахмал холодной водой и вмешайте в соус до загустения.\nВыключите огонь и влейте взбитые яйца тонкой струйкой, размешивая один раз по кругу.\nПосыпьте кинзой и подавайте с обжаренными мантоу.","source":"UniTools"},{"id":"ut-lu-rou-fan","name":"Лу-жоу-фань","country":"Тайвань","category":"main","diets":[],"slots":["lunch","dinner"],"time":125,"baseServings":4,"portionNutrition":{"k":780,"p":32,"f":44,"c":62},"details":[{"name":"Свиная грудинка","quantity":700,"unit":"g","note":"мелким кубиком"},{"name":"Шалот","quantity":6,"unit":"piece","note":""},{"name":"Соевый соус","quantity":100,"unit":"ml","note":""},{"name":"Тёмный соевый соус","quantity":1,"unit":"tbsp","note":""},{"name":"Шаосинское вино","quantity":80,"unit":"ml","note":""},{"name":"Леденцовый сахар","quantity":30,"unit":"g","note":""},{"name":"Смесь пяти специй","quantity":1,"unit":"tsp","note":""},{"name":"Бадьян","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":"варёные, к подаче"},{"name":"Рис","quantity":400,"unit":"g","note":""},{"name":"Зелень бок-чой","quantity":300,"unit":"g","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте грудинку кубиком в сантиметр, не отделяя жир от мяса.\nОбжарьте нарезанный шалот в масле до тёмно-золотого хруста и выньте половину для подачи.\nВ том же масле обжарьте свинину до румяности, вытопив часть жира, десять минут.\nВлейте вино, дайте выпариться минуту, добавьте оба соевых соуса, сахар, специи и чеснок.\nЗалейте водой вровень с мясом, доведите до кипения и тушите под крышкой полтора часа на самом слабом огне.\nПоложите варёные яйца в соус на последние двадцать минут — они возьмут цвет и вкус.\nПодавайте на рисе, с половинкой яйца, отварной зеленью и жареным шалотом сверху.","source":"UniTools"},{"id":"ut-beef-noodle-soup-taiwan","name":"Тайваньский суп с говядиной","country":"Тайвань","category":"soup","diets":[],"slots":["lunch","dinner"],"time":175,"baseServings":4,"portionNutrition":{"k":680,"p":48,"f":24,"c":68},"details":[{"name":"Говяжья голяшка","quantity":1,"unit":"kg","note":"с сухожилиями"},{"name":"Пшеничная лапша","quantity":400,"unit":"g","note":""},{"name":"Паста доубаньцзян","quantity":3,"unit":"tbsp","note":""},{"name":"Соевый соус","quantity":100,"unit":"ml","note":""},{"name":"Шаосинское вино","quantity":100,"unit":"ml","note":""},{"name":"Имбирь","quantity":50,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Бадьян","quantity":3,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Леденцовый сахар","quantity":30,"unit":"g","note":""},{"name":"Бок-чой","quantity":300,"unit":"g","note":""},{"name":"Маринованная горчичная зелень","quantity":100,"unit":"g","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте мясо холодной водой, доведите до кипения, проварите две минуты и слейте — это уберёт муть.\nОбжарьте имбирь, чеснок и доубаньцзян в масле пять минут, пока масло не станет красным.\nДобавьте помидоры, вино и соевый соус, прогрейте три минуты и верните мясо в кастрюлю.\nЗалейте водой на два пальца выше мяса, положите бадьян, корицу и сахар и варите два часа на слабом огне.\nВыньте мясо, нарежьте толстыми ломтями и верните в бульон на десять минут.\nОтварите лапшу в отдельной кастрюле в чистой воде и ошпарьте бок-чой.\nРазложите лапшу по мискам, сверху мясо и зелень, залейте бульоном и добавьте маринованную горчичную зелень и зелёный лук.","source":"UniTools"},{"id":"ut-nyama-choma","name":"Ньяма-чома","country":"Кения","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":115,"baseServings":6,"portionNutrition":{"k":620,"p":52,"f":28,"c":42},"details":[{"name":"Козлятина","quantity":2,"unit":"kg","note":"нога или рёбра, крупными кусками"},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Лук красный","quantity":2,"unit":"piece","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Кукурузная мука","quantity":400,"unit":"g","note":"для угали"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите мясо солью, перцем, соком двух лимонов, растёртым чесноком и маслом. Оставьте на час.\nРазожгите угли и дайте им покрыться пеплом. Жар должен быть таким, чтобы ладонь над решёткой держалась пять секунд.\nПоложите мясо целыми кусками и жарьте, переворачивая каждые десять минут, час двадцать.\nСмешайте нарезанные кубиком помидоры, лук, кинзу и чили с соком лимона и солью — это качамбари.\nДля угали вскипятите литр воды, всыпайте муку, непрерывно размешивая деревянной ложкой, и вымешивайте пятнадцать минут до плотной массы.\nДайте мясу постоять десять минут, нарежьте мелко поперёк волокон и подайте с угали, качамбари и солью.","source":"UniTools"},{"id":"ut-sukuma-wiki","name":"Сукума-вики","country":"Кения","category":"side","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":180,"p":6,"f":12,"c":14},"details":[{"name":"Листовая капуста","quantity":700,"unit":"g","note":"тонкой соломкой"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Снимите с листьев жёсткие черешки, сверните листья в рулон и нарежьте тонкой соломкой.\nОбжарьте лук в масле до мягкости, добавьте чеснок и зиру и прогрейте минуту.\nПоложите нарезанные помидоры и тушите семь минут, пока они не разойдутся в пасту.\nДобавьте зелень, посолите и перемешайте. Она осядет вдвое за минуту.\nВлейте полстакана воды, накройте и тушите десять минут — зелень должна стать мягкой, но остаться зелёной.\nСбрызните лимоном и подавайте с угали или рисом.","source":"UniTools"},{"id":"ut-waakye","name":"Ваакье","country":"Гана","category":"main","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":100,"baseServings":6,"portionNutrition":{"k":560,"p":18,"f":12,"c":96},"details":[{"name":"Бобы вигна (чёрный глазок)","quantity":300,"unit":"g","note":"замочить на ночь"},{"name":"Рис длиннозёрный","quantity":500,"unit":"g","note":""},{"name":"Сухие листья сорго","quantity":10,"unit":"g","note":""},{"name":"Пищевая сода","quantity":1,"unit":"pinch","note":""},{"name":"Подорожник","quantity":2,"unit":"piece","note":"спелый, к подаче"},{"name":"Яйца","quantity":6,"unit":"piece","note":"варёные, к подаче"},{"name":"Гари (маниоковая крупа)","quantity":150,"unit":"g","note":"к подаче"},{"name":"Соус шито","quantity":100,"unit":"g","note":"к подаче"},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте листья сорго и отварите их в полутора литрах воды десять минут — вода станет тёмно-красной.\nВыньте листья, добавьте щепоть соды и бобы и варите сорок пять минут до почти готовности.\nПромойте рис до прозрачной воды и всыпьте в кастрюлю. Жидкости должно быть на палец выше уровня риса.\nПосолите, накройте и варите двадцать минут на слабом огне, не перемешивая.\nСнимите с огня и дайте постоять под крышкой десять минут, потом разрыхлите вилкой.\nОбжарьте кружки спелого подорожника до карамельного цвета.\nПодавайте с яйцом, гари, шито и подорожником, всё на одной тарелке.","source":"UniTools"},{"id":"ut-banku-with-tilapia","name":"Банку с тиляпией","country":"Гана","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":75,"baseServings":4,"portionNutrition":{"k":640,"p":38,"f":20,"c":78},"details":[{"name":"Кукурузная мука","quantity":400,"unit":"g","note":"ферментированная 3 дня"},{"name":"Маниоковое тесто","quantity":200,"unit":"g","note":""},{"name":"Тиляпия","quantity":4,"unit":"piece","note":"целая, потрошёная"},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Перец хабанеро","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте кукурузное и маниоковое тесто с литром воды и солью до однородной жидкой массы без комков.\nПоставьте на средний огонь и вымешивайте деревянной лопаткой не переставая. Масса начнёт густеть через пять минут.\nПродолжайте вымешивать двадцать минут, прижимая массу к стенкам, пока она не станет плотной и глянцевой.\nСформируйте влажными руками шары и заверните каждый в пищевую плёнку или банановый лист.\nНатрите рыбу солью, имбирём и чесноком и обжарьте на гриле или сковороде по восемь минут с каждой стороны.\nРазотрите в ступке помидоры, хабанеро, лук, соль и ложку масла в грубый соус.\nПодавайте шар банку, рыбу и миску соуса. Едят руками, отщипывая тесто и макая в соус.","source":"UniTools"},{"id":"ut-thieboudienne","name":"Тьебуджен","country":"Сенегал","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":140,"baseServings":6,"portionNutrition":{"k":720,"p":42,"f":22,"c":92},"details":[{"name":"Морской окунь или дорада","quantity":1.5,"unit":"kg","note":"стейками"},{"name":"Дроблёный рис","quantity":700,"unit":"g","note":""},{"name":"Петрушка","quantity":60,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Перец чили","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Маниок","quantity":400,"unit":"g","note":""},{"name":"Капуста","quantity":400,"unit":"g","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Баклажаны","quantity":2,"unit":"piece","note":""},{"name":"Окра","quantity":200,"unit":"g","note":""},{"name":"Тамаринд","quantity":2,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Растолките петрушку, чеснок, чили и соль в пасту роф и набейте ею надрезы в кусках рыбы.\nОбжарьте рыбу в масле по три минуты с каждой стороны и отложите.\nВ том же масле обжарьте лук до мягкости, добавьте томатную пасту и жарьте пять минут, пока она не потемнеет.\nВлейте два литра воды, добавьте тамаринд и овощи и варите двадцать пять минут.\nВерните рыбу в кастрюлю на десять минут, потом выньте её и овощи и держите в тепле.\nВсыпьте промытый рис в оставшийся бульон — жидкости должно быть вдвое больше риса — и варите под крышкой тридцать минут, не мешая.\nВыложите рис на большое блюдо, сверху рыбу и овощи. Пригоревший слой со дна распределите отдельно.","source":"UniTools"},{"id":"ut-yassa-poulet","name":"Ясса с курицей","country":"Сенегал","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":100,"baseServings":4,"portionNutrition":{"k":640,"p":42,"f":24,"c":62},"details":[{"name":"Курица","quantity":1.4,"unit":"kg","note":"кусками"},{"name":"Лук","quantity":1.5,"unit":"kg","note":"тонкими перьями"},{"name":"Лимон","quantity":5,"unit":"piece","note":""},{"name":"Дижонская горчица","quantity":3,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Куриный бульон","quantity":300,"unit":"ml","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте сок лимонов, горчицу, чеснок, соль и перец, залейте курицу и лук и уберите в холод минимум на четыре часа.\nВыньте курицу, обсушите и обжарьте в масле до румяной корки со всех сторон.\nВ том же сотейнике томите лук из маринада на среднем огне двадцать пять минут, пока он не станет золотистым и мягким.\nВлейте оставшийся маринад и бульон, положите лавровый лист и целый перец чили.\nВерните курицу, накройте и тушите тридцать минут на слабом огне.\nСнимите крышку и выпарите соус ещё десять минут до густоты. Перец выньте.\nПодавайте с отварным рисом, выложив лук поверх курицы.","source":"UniTools"},{"id":"ut-bobotie","name":"Бобóти","country":"ЮАР","category":"main","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":590,"p":34,"f":32,"c":40},"details":[{"name":"Говяжий фарш","quantity":900,"unit":"g","note":""},{"name":"Белый хлеб","quantity":2,"unit":"slice","note":""},{"name":"Молоко","quantity":400,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Карри молотое","quantity":2,"unit":"tbsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Курага","quantity":100,"unit":"g","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Абрикосовый чатни","quantity":3,"unit":"tbsp","note":""},{"name":"Уксус","quantity":2,"unit":"tbsp","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":4,"unit":"piece","note":""},{"name":"Миндаль","quantity":50,"unit":"g","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите хлеб в половине молока на десять минут и отожмите, молоко сохраните.\nОбжарьте лук в масле до мягкости, добавьте карри и куркуму и прогрейте минуту до запаха.\nДобавьте фарш и жарьте, разбивая комки, до потери розового цвета — десять минут.\nВмешайте хлеб, курагу, изюм, чатни, уксус, соль и перец и снимите с огня.\nВыложите в форму, разровняйте и запекайте при 180 °C сорок минут.\nВзбейте яйца с оставшимся молоком и вылейте сверху, воткните в заливку лавровые листья и посыпьте миндалём.\nВерните в духовку на двадцать минут, пока заливка не схватится и не станет золотистой.","source":"UniTools"},{"id":"ut-chakalaka","name":"Чакалака","country":"ЮАР","category":"side","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":40,"baseServings":6,"portionNutrition":{"k":220,"p":8,"f":10,"c":26},"details":[{"name":"Морковь","quantity":4,"unit":"piece","note":"натереть"},{"name":"Перец сладкий","quantity":3,"unit":"piece","note":"разных цветов"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Фасоль в томате","quantity":400,"unit":"g","note":""},{"name":"Помидоры","quantity":400,"unit":"g","note":"рубленые"},{"name":"Карри молотое","quantity":1,"unit":"tbsp","note":""},{"name":"Паприка","quantity":1,"unit":"tsp","note":""},{"name":"Перец чили","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Имбирь","quantity":20,"unit":"g","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите морковь на крупной тёрке, перец и лук нарежьте тонкой соломкой.\nОбжарьте лук с чесноком, имбирём и чили в масле до мягкости, пять минут.\nДобавьте карри и паприку и прогрейте минуту — специи должны раскрыться в масле.\nВсыпьте перец и морковь и жарьте пять минут на сильном огне, помешивая.\nВлейте помидоры, посолите и тушите семь минут, пока соус не загустеет.\nВмешайте фасоль, прогрейте три минуты и снимите с огня. Овощи должны остаться упругими.","source":"UniTools"},{"id":"ut-plokkfiskur","name":"Плоккфискюр","country":"Исландия","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":480,"p":38,"f":18,"c":42},"details":[{"name":"Треска","quantity":700,"unit":"g","note":"филе"},{"name":"Картофель","quantity":700,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Мука","quantity":40,"unit":"g","note":""},{"name":"Молоко","quantity":500,"unit":"ml","note":""},{"name":"Горчица","quantity":1,"unit":"tsp","note":""},{"name":"Ржаной хлеб","quantity":200,"unit":"g","note":"к подаче"},{"name":"Зелёный лук","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите картофель в мундире до мягкости, очистите и нарежьте крупными кусками.\nОтварите треску в подсоленной воде восемь минут, выньте и разберите руками на хлопья, убрав кости и кожу.\nОбжарьте лук в масле до мягкости, всыпьте муку и прогрейте две минуты, помешивая.\nВлейте молоко тонкой струйкой, непрерывно размешивая, и доведите соус до густоты сливок.\nВмешайте горчицу, соль и перец, добавьте рыбу и картофель и прогрейте всё вместе пять минут.\nРазомните вилкой до крупной неоднородной массы — куски должны угадываться — и посыпьте зелёным луком.","source":"UniTools"},{"id":"ut-kjotsupa","name":"Кьётсупа","country":"Исландия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":170,"baseServings":6,"portionNutrition":{"k":520,"p":36,"f":22,"c":42},"details":[{"name":"Баранина на кости","quantity":1.2,"unit":"kg","note":"лопатка или шея"},{"name":"Перловая крупа","quantity":120,"unit":"g","note":""},{"name":"Картофель","quantity":500,"unit":"g","note":""},{"name":"Морковь","quantity":4,"unit":"piece","note":""},{"name":"Брюква","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Капуста","quantity":300,"unit":"g","note":""},{"name":"Сушёные травы","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте мясо тремя литрами холодной воды, доведите до кипения и тщательно снимите пену.\nВарите на слабом огне полтора часа, не давая закипать бурно — бульон должен остаться прозрачным.\nДобавьте перловку и лук и варите ещё сорок минут.\nЗаложите морковь, брюкву и картофель, нарезанные крупными кусками, и варите двадцать минут.\nДобавьте капусту на последние десять минут, посолите и поперчите.\nРазложите мясо по тарелкам, залейте бульоном с овощами и подайте с ржаным хлебом.","source":"UniTools"},{"id":"ut-potica","name":"Потица","country":"Словения","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":150,"baseServings":12,"portionNutrition":{"k":560,"p":12,"f":32,"c":58},"details":[{"name":"Мука","quantity":700,"unit":"g","note":""},{"name":"Молоко","quantity":300,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Желтки","quantity":4,"unit":"piece","note":""},{"name":"Сахар","quantity":120,"unit":"g","note":""},{"name":"Грецкие орехи","quantity":600,"unit":"g","note":"молотые"},{"name":"Сливки","quantity":200,"unit":"ml","note":""},{"name":"Мёд","quantity":3,"unit":"tbsp","note":""},{"name":"Ром","quantity":2,"unit":"tbsp","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи в тёплом молоке с ложкой сахара и оставьте на десять минут до пены.\nЗамесите тесто из муки, опары, желтков, сахара, размягчённого масла, цедры и соли. Вымешивайте пятнадцать минут.\nОставьте в тепле на час двадцать, пока тесто не удвоится.\nПрогрейте сливки с мёдом, залейте ими молотые орехи, добавьте ром и корицу и остудите до тёплого.\nРаскатайте тесто в прямоугольник толщиной три миллиметра и намажьте начинкой, отступив от краёв два сантиметра.\nСверните плотным рулетом с длинной стороны, уложите в кольцевую форму швом вниз и дайте подойти сорок минут.\nПроколите рулет спицей в нескольких местах и пеките при 170 °C час до тёмно-золотого цвета.","source":"UniTools"},{"id":"ut-jota","name":"Йота","country":"Словения","category":"soup","diets":[],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":490,"p":26,"f":22,"c":46},"details":[{"name":"Квашеная репа или капуста","quantity":600,"unit":"g","note":""},{"name":"Фасоль","quantity":300,"unit":"g","note":"замочить на ночь"},{"name":"Картофель","quantity":500,"unit":"g","note":""},{"name":"Копчёные рёбрышки","quantity":400,"unit":"g","note":""},{"name":"Копчёная колбаса","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите замоченную фасоль в отдельной кастрюле до мягкости, час. Воду не сливайте.\nОтварите копчёные рёбрышки в полутора литрах воды сорок минут с лавровым листом.\nДобавьте квашеную репу или капусту вместе с частью рассола и варите двадцать минут.\nЗаложите нарезанный картофель и колбасу и варите ещё двадцать минут.\nОбжарьте лук с чесноком в масле до золотистого и вмешайте в суп.\nДобавьте фасоль с её водой, разомните часть картофеля прямо в кастрюле и проварите пять минут.\nСнимите мясо с костей, верните в суп, посолите и поперчите.","source":"UniTools"},{"id":"ut-bosanski-lonac","name":"Босански лонац","country":"Босния и Герцеговина","category":"main","diets":[],"slots":["lunch","dinner"],"time":280,"baseServings":6,"portionNutrition":{"k":660,"p":44,"f":32,"c":42},"details":[{"name":"Говядина","quantity":600,"unit":"g","note":"крупными кусками"},{"name":"Баранина","quantity":600,"unit":"g","note":"крупными кусками"},{"name":"Капуста","quantity":500,"unit":"g","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Морковь","quantity":4,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Корень петрушки","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":1,"unit":"piece","note":"целая головка"},{"name":"Копчёное сало","quantity":150,"unit":"g","note":""},{"name":"Белое сухое вино","quantity":200,"unit":"ml","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте все овощи крупными кусками — они должны выдержать четыре часа и не развалиться.\nВыложите на дно горшка кубики сала, сверху мясо, посолите и поперчите.\nУложите слоями лук, морковь, корень петрушки, картофель, перец, капусту и помидоры.\nВложите целую головку чеснока и лавровый лист, влейте вино и воду до половины высоты горшка.\nНакройте крышкой и поставьте в духовку на 150 °C на четыре часа. Не открывайте и не мешайте.\nПодавайте прямо из горшка, зачерпывая до дна, чтобы в тарелку попали все слои.","source":"UniTools"},{"id":"ut-burek-bosanski","name":"Боснийский бурек","country":"Босния и Герцеговина","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":690,"p":30,"f":38,"c":58},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода тёплая","quantity":280,"unit":"ml","note":""},{"name":"Говяжий фарш","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":"мелко нарезать"},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Уксус","quantity":1,"unit":"tsp","note":""},{"name":"Йогурт","quantity":400,"unit":"ml","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, тёплой воды, ложки масла, уксуса и соли и вымешивайте пятнадцать минут до эластичности.\nРазделите на четыре шара, смажьте маслом, накройте и оставьте на сорок минут.\nСмешайте сырой фарш с луком, солью, перцем и двумя ложками воды — вода нужна, чтобы начинка не пересохла.\nРастяните шар руками на застеленном скатертью столе до прозрачного листа, начиная от центра и двигаясь к краям.\nСбрызните лист маслом, выложите начинку полосой вдоль края и сверните в длинный тонкий рулет.\nУложите рулеты спиралью в круглую форму от центра, смажьте маслом и пеките при 200 °C сорок минут.\nСбрызните горячий бурек водой и накройте полотенцем на пять минут — корка станет мягче. Подавайте с йогуртом.","source":"UniTools"},{"id":"ut-tavce-gravce","name":"Тавче-гравче","country":"Северная Македония","category":"main","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":140,"baseServings":6,"portionNutrition":{"k":420,"p":20,"f":16,"c":52},"details":[{"name":"Белая фасоль","quantity":500,"unit":"g","note":"замочить на ночь"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Паприка сладкая","quantity":2,"unit":"tbsp","note":""},{"name":"Сушёный красный перец","quantity":3,"unit":"piece","note":""},{"name":"Мука","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Мята сушёная","quantity":1,"unit":"tsp","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Слейте воду с замоченной фасоли, залейте свежей, доведите до кипения и через десять минут снова слейте.\nЗалейте в третий раз, добавьте одну целую луковицу и варите час до мягкости, не солив.\nОбжарьте нарезанный лук в масле до золотистого, снимите с огня и вмешайте паприку и муку.\nСлейте с фасоли часть воды, оставив её вровень с бобами, посолите и вмешайте заправку.\nПереложите в глиняную сковороду, разложите сверху сушёные перцы и посыпьте мятой.\nЗапекайте при 200 °C сорок минут, пока сверху не образуется румяная корка.\nДайте постоять десять минут и подайте прямо в сковороде, посыпав петрушкой.","source":"UniTools"},{"id":"ut-selsko-meso","name":"Селско месо","country":"Северная Македония","category":"main","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":4,"portionNutrition":{"k":640,"p":44,"f":40,"c":16},"details":[{"name":"Свиная шея","quantity":700,"unit":"g","note":"кубиками"},{"name":"Шампиньоны","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Белое сухое вино","quantity":200,"unit":"ml","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Кашкавал","quantity":200,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте свинину крупными кубиками в масле до румяной корки со всех сторон.\nДобавьте лук и перец и жарьте до мягкости, семь минут.\nПоложите грибы и жарьте на сильном огне пять минут, пока не выпарится их вода.\nСнимите с огня, вмешайте паприку, чеснок и томатную пасту, влейте вино и верните на огонь на три минуты.\nРазложите по глиняным горшочкам, долейте воды до уровня мяса, посолите и накройте.\nЗапекайте при 180 °C пятьдесят минут.\nСнимите крышки, посыпьте тёртым кашкавалом и держите ещё десять минут до румяной сырной корки.","source":"UniTools"},{"id":"ut-lamingtons","name":"Ламингтоны","country":"Австралия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":75,"baseServings":12,"portionNutrition":{"k":420,"p":5,"f":20,"c":56},"details":[{"name":"Мука","quantity":250,"unit":"g","note":""},{"name":"Сахар","quantity":200,"unit":"g","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Молоко","quantity":120,"unit":"ml","note":""},{"name":"Разрыхлитель","quantity":2,"unit":"tsp","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Сахарная пудра","quantity":400,"unit":"g","note":""},{"name":"Какао-порошок","quantity":50,"unit":"g","note":""},{"name":"Горячее молоко","quantity":150,"unit":"ml","note":""},{"name":"Кокосовая стружка","quantity":250,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Взбейте масло с сахаром добела, вводите яйца по одному, затем вмешайте ваниль.\nВмешайте просеянную муку с разрыхлителем и солью попеременно с молоком.\nВылейте в квадратную форму и пеките при 180 °C двадцать восемь минут до сухой шпажки.\nПолностью остудите и оставьте бисквит на ночь незакрытым.\nНарежьте на кубики со стороной пять сантиметров.\nРазмешайте сахарную пудру с какао и горячим молоком до жидкой глазури, которая стекает с ложки струйкой.\nОбмакните каждый кубик на две вилки, дайте стечь и обваляйте в кокосовой стружке. Дайте застыть час.","source":"UniTools"},{"id":"ut-meat-pie-australian","name":"Австралийский мясной пирог","country":"Австралия","category":"main","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":720,"p":32,"f":42,"c":54},"details":[{"name":"Говядина","quantity":800,"unit":"g","note":"мелким кубиком или фарш"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Говяжий бульон","quantity":500,"unit":"ml","note":""},{"name":"Мука","quantity":3,"unit":"tbsp","note":""},{"name":"Вустерский соус","quantity":2,"unit":"tbsp","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Песочное тесто","quantity":500,"unit":"g","note":""},{"name":"Слоёное тесто","quantity":400,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":"для смазки"},{"name":"Томатный соус","quantity":100,"unit":"ml","note":"к подаче"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мясо порциями до румяной корки, чтобы оно не пустило сок, и отложите.\nОбжарьте лук до мягкости, всыпьте муку и прогрейте две минуты.\nВерните мясо, влейте бульон, добавьте вустерский соус и томатную пасту и тушите сорок минут до густоты.\nПолностью остудите начинку, лучше в холодильнике.\nВыстелите формочки песочным тестом, обрежьте края и наполните холодной начинкой.\nНакройте кругами слоёного теста, защипните края и сделайте прорезь по центру.\nСмажьте яйцом и пеките при 200 °C двадцать пять минут до тёмно-золотой крышки.","source":"UniTools"},{"id":"ut-pavlova","name":"Павлова","country":"Новая Зеландия","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":115,"baseServings":8,"portionNutrition":{"k":380,"p":4,"f":18,"c":52},"details":[{"name":"Белки","quantity":6,"unit":"piece","note":""},{"name":"Сахар мелкий","quantity":350,"unit":"g","note":""},{"name":"Кукурузный крахмал","quantity":2,"unit":"tsp","note":""},{"name":"Белый уксус","quantity":1,"unit":"tsp","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Сливки 33%","quantity":400,"unit":"ml","note":""},{"name":"Киви","quantity":4,"unit":"piece","note":""},{"name":"Ягоды","quantity":250,"unit":"g","note":""},{"name":"Маракуйя","quantity":2,"unit":"piece","note":""}],"steps":"Взбейте белки комнатной температуры до мягких пиков в идеально сухой и обезжиренной миске.\nВсыпайте сахар по столовой ложке, продолжая взбивать, пока масса не станет плотной и глянцевой.\nПроверьте пальцами: если чувствуются крупинки сахара, взбивайте дальше — иначе корка будет плакать сиропом.\nВмешайте лопаткой крахмал, уксус и ваниль в три движения, не больше.\nВыложите на пергамент круг диаметром двадцать два сантиметра, приподняв края и оставив углубление в центре.\nПеките при 120 °C полтора часа, потом выключите духовку и оставьте павлову внутри до полного остывания.\nВзбейте сливки, выложите в углубление и украсьте киви, ягодами и мякотью маракуйи прямо перед подачей.","source":"UniTools"},{"id":"ut-hangi-style-chicken","name":"Курица в стиле ханги","country":"Новая Зеландия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":180,"baseServings":6,"portionNutrition":{"k":620,"p":44,"f":24,"c":58},"details":[{"name":"Курица","quantity":1.8,"unit":"kg","note":"кусками"},{"name":"Батат","quantity":800,"unit":"g","note":""},{"name":"Картофель","quantity":700,"unit":"g","note":""},{"name":"Тыква","quantity":600,"unit":"g","note":""},{"name":"Капуста","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Копчёная соль","quantity":2,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Щепа для копчения","quantity":2,"unit":"tbsp","note":""},{"name":"Чёрный перец","quantity":1,"unit":"tsp","note":""}],"steps":"Натрите курицу копчёной солью и перцем и оставьте на полчаса.\nНарежьте батат, картофель и тыкву крупными кусками, капусту — четвертинками.\nЗаверните щепу в фольгу, сделайте несколько проколов и положите на дно глубокого противня.\nУложите на решётку над щепой овощи, сверху курицу, посыпьте солью и разложите кусочки масла.\nПлотно затяните противень двумя слоями фольги — пар не должен выходить.\nЗапекайте при 160 °C два часа, не открывая.\nСнимите фольгу и дайте курице подрумяниться десять минут при 200 °C.","source":"UniTools"},{"id":"ut-poutine","name":"Путин","country":"Канада","category":"snack","diets":[],"slots":["snack"],"time":70,"baseServings":4,"portionNutrition":{"k":780,"p":26,"f":42,"c":74},"details":[{"name":"Картофель","quantity":1.2,"unit":"kg","note":"крахмалистых сортов"},{"name":"Сырные зёрна чеддер","quantity":300,"unit":"g","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Мука","quantity":40,"unit":"g","note":""},{"name":"Говяжий бульон","quantity":400,"unit":"ml","note":""},{"name":"Куриный бульон","quantity":200,"unit":"ml","note":""},{"name":"Вустерский соус","quantity":1,"unit":"tbsp","note":""},{"name":"Яблочный уксус","quantity":1,"unit":"tsp","note":""},{"name":"Масло для фритюра","quantity":1.5,"unit":"l","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте картофель брусками в сантиметр и вымачивайте в холодной воде двадцать минут, чтобы ушёл крахмал.\nОбсушите бруски насухо. Мокрый картофель во фритюре брызгается и не даёт корки.\nРастопите масло, всыпьте муку и обжаривайте ру до орехового цвета, четыре минуты.\nВлейте оба бульона, добавьте вустерский соус и уксус и варите подливу пятнадцать минут до густоты.\nОбжарьте картофель при 150 °C шесть минут до мягкости и выложите на решётку остывать.\nПоднимите температуру до 190 °C и обжарьте второй раз три минуты до хрустящей корки. Посолите.\nВыложите фри в миску, разбросайте сырные зёрна и залейте кипящей подливой. Подавайте немедленно.","source":"UniTools"},{"id":"ut-tourtiere","name":"Туртьер","country":"Канада","category":"main","diets":[],"slots":["lunch","dinner"],"time":115,"baseServings":8,"portionNutrition":{"k":700,"p":30,"f":42,"c":50},"details":[{"name":"Свиной фарш","quantity":700,"unit":"g","note":""},{"name":"Говяжий фарш","quantity":300,"unit":"g","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":"отварной, размятый"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Гвоздика молотая","quantity":0.5,"unit":"tsp","note":""},{"name":"Душистый перец","quantity":1,"unit":"tsp","note":""},{"name":"Мускатный орех","quantity":0.5,"unit":"tsp","note":""},{"name":"Куриный бульон","quantity":250,"unit":"ml","note":""},{"name":"Песочное тесто","quantity":700,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":"для смазки"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук с чесноком до мягкости, добавьте оба фарша и жарьте, разбивая комки, десять минут.\nВсыпьте все специи, посолите, поперчите и влейте бульон.\nТушите на слабом огне сорок минут, пока жидкость почти не выпарится.\nВмешайте размятый картофель и полностью остудите начинку.\nВыстелите форму тестом, выложите холодную начинку и разровняйте.\nНакройте вторым пластом, защипните края, сделайте прорези и смажьте яйцом.\nПеките при 200 °C пятнадцать минут, затем при 180 °C ещё сорок, до тёмно-золотой корки.","source":"UniTools"},{"id":"ut-gallo-pinto","name":"Гальо-пинто","country":"Коста-Рика","category":"breakfast","diets":["vegetarian","vegan","gluten-free"],"slots":["breakfast"],"time":35,"baseServings":4,"portionNutrition":{"k":480,"p":18,"f":12,"c":76},"details":[{"name":"Варёный рис","quantity":600,"unit":"g","note":"вчерашний, холодный"},{"name":"Чёрная фасоль","quantity":400,"unit":"g","note":"варёная, с отваром"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Соус Лисано","quantity":3,"unit":"tbsp","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Подорожник","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мелко нарезанный лук, перец и чеснок в масле до мягкости, пять минут.\nДобавьте фасоль вместе с половником её отвара и прогрейте три минуты.\nВсыпьте холодный рис и перемешайте, разбивая комки лопаткой.\nВлейте соус Лисано, посолите и жарьте на среднем огне семь минут, изредка помешивая.\nВмешайте рубленую кинзу и снимите с огня.\nПодавайте с яичницей, жареным подорожником и, по желанию, сметаной или свежим сыром.","source":"UniTools"},{"id":"ut-casado","name":"Касадо","country":"Коста-Рика","category":"main","diets":[],"slots":["lunch","dinner"],"time":75,"baseServings":4,"portionNutrition":{"k":740,"p":48,"f":20,"c":92},"details":[{"name":"Куриное филе","quantity":600,"unit":"g","note":""},{"name":"Рис","quantity":350,"unit":"g","note":""},{"name":"Чёрная фасоль","quantity":400,"unit":"g","note":"варёная"},{"name":"Подорожник","quantity":2,"unit":"piece","note":"спелый"},{"name":"Чайот или кабачок","quantity":300,"unit":"g","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Капуста","quantity":200,"unit":"g","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Соус Лисано","quantity":2,"unit":"tbsp","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте курицу в соке лайма, чесноке, соусе Лисано, соли и перце на двадцать минут.\nСварите рис рассыпчатым и разогрейте фасоль с ложкой её отвара.\nНарежьте чайот и морковь мелким кубиком и потушите с чесноком десять минут — это пикадильо.\nОбжарьте курицу на среднем огне по шесть минут с каждой стороны.\nОбжарьте кружки спелого подорожника до карамельного цвета.\nСмешайте нашинкованную капусту с помидорами, кинзой, соком лайма и солью.\nСоберите тарелку секторами: рис, фасоль, курица, пикадильо, салат, бананы — не перемешивая.","source":"UniTools"},{"id":"ut-buuz","name":"Буузы","country":"Монголия","category":"main","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":6,"portionNutrition":{"k":620,"p":30,"f":34,"c":48},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Вода","quantity":280,"unit":"ml","note":""},{"name":"Баранина","quantity":800,"unit":"g","note":"рубить ножом"},{"name":"Курдючный жир","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, воды и соли и оставьте под плёнкой на сорок минут.\nПорубите баранину и жир ножом на кусочки размером с горошину.\nСмешайте мясо с мелко нарезанным луком, чесноком, солью, перцем и четвертью стакана воды.\nРаскатайте кружки диаметром десять сантиметров, оставляя середину толще краёв.\nПоложите ложку начинки и защипните края складками по кругу, оставив вверху отверстие.\nСмажьте решётку пароварки жиром и выложите буузы, не касаясь друг друга.\nВарите на пару восемнадцать минут. Тесто станет полупрозрачным, а внутри соберётся бульон.","source":"UniTools"},{"id":"ut-tsuivan","name":"Цуйван","country":"Монголия","category":"main","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":4,"portionNutrition":{"k":660,"p":32,"f":28,"c":72},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Вода","quantity":180,"unit":"ml","note":""},{"name":"Баранина","quantity":500,"unit":"g","note":"полосками"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Капуста","quantity":250,"unit":"g","note":""},{"name":"Картофель","quantity":2,"unit":"piece","note":""},{"name":"Курдючный жир или масло","quantity":80,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, воды и соли и дайте отдохнуть тридцать минут.\nРаскатайте тонко, смажьте жиром, сверните рулетом и нарежьте поперёк полосками в полсантиметра.\nРазберите полоски руками и разложите на доске, чтобы не слиплись.\nОбжарьте баранину в жире на сильном огне до корки, добавьте лук, морковь, картофель и капусту.\nВлейте стакан воды, посолите и поперчите, доведите до кипения.\nУложите лапшу ровным слоем поверх мяса, не перемешивая, накройте и держите двадцать минут на слабом огне.\nСнимите крышку, добавьте чеснок и перемешайте всё вместе. Подавайте сразу.","source":"UniTools"},{"id":"ut-beshbarmak-kyrgyz","name":"Кыргызский бешбармак","country":"Кыргызстан","category":"main","diets":[],"slots":["lunch","dinner"],"time":210,"baseServings":6,"portionNutrition":{"k":700,"p":44,"f":32,"c":58},"details":[{"name":"Баранина на кости","quantity":1.8,"unit":"kg","note":""},{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Вода для теста","quantity":170,"unit":"ml","note":""},{"name":"Лук","quantity":5,"unit":"piece","note":""},{"name":"Курдючный жир","quantity":100,"unit":"g","note":""},{"name":"Чёрный перец горошком","quantity":10,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте мясо холодной водой, доведите до кипения, снимите пену и варите два с половиной часа с перцем и лавром.\nЗамесите крутое тесто из муки, яиц, воды и соли и оставьте на сорок минут.\nРаскатайте в пласт в миллиметр и нарежьте ромбами со стороной шесть сантиметров.\nВытопите курдючный жир, обжарьте в нём нарезанный кольцами лук до мягкости.\nВлейте в лук два половника бульона и тушите десять минут до густой подливы — это чык.\nОтварите ромбы теста в процеженном бульоне порциями по четыре минуты и сразу выкладывайте на блюдо.\nРазберите мясо на пласты, выложите поверх теста, залейте чыком и посыпьте кинзой. Бульон подайте в пиалах.","source":"UniTools"},{"id":"ut-lagman","name":"Лагман","country":"Кыргызстан","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":4,"portionNutrition":{"k":720,"p":34,"f":32,"c":78},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода","quantity":230,"unit":"ml","note":""},{"name":"Говядина","quantity":500,"unit":"g","note":"соломкой"},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Стручковая фасоль","quantity":200,"unit":"g","note":""},{"name":"Редька зелёная","quantity":200,"unit":"g","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Кориандр молотый","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, тёплой солёной воды и вымешивайте пятнадцать минут до гладкости.\nРазделите на жгуты, обильно смажьте маслом, уложите в миску и оставьте на час под плёнкой.\nВытягивайте жгут, складывая вдвое и раскачивая, пока нити не станут толщиной со спичку.\nОбжарьте мясо в раскалённом масле до корки, добавьте лук, зиру и кориандр.\nЗакладывайте овощи по очереди: редьку, фасоль, перец, в конце помидоры и томатную пасту.\nВлейте стакан кипятка, посолите и тушите десять минут — овощи должны остаться упругими.\nОтварите лапшу в большом объёме кипятка три минуты, откиньте и разложите по тарелкам. Сверху ваджа и кинза.","source":"UniTools"},{"id":"ut-kurutob","name":"Курутоб","country":"Таджикистан","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":520,"p":18,"f":28,"c":50},"details":[{"name":"Курут","quantity":200,"unit":"g","note":"или 500 г густого йогурта"},{"name":"Слоёная лепёшка фатир","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Огурцы","quantity":2,"unit":"piece","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Рейхан (фиолетовый базилик)","quantity":20,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте курут горячей водой на двадцать минут и разотрите руками в однородную жидкость.\nПроцедите через сито, чтобы убрать нерастворившиеся крупинки. Жидкость должна быть как жидкая сметана.\nНарежьте лук кольцами и обжарьте в масле до золотистого, десять минут.\nНаломайте фатир крупными кусками в широкое блюдо.\nЗалейте хлеб курутом и дайте постоять пять минут, чтобы он пропитался.\nВыложите сверху жареный лук вместе с маслом, помидоры, огурцы и зелень.","source":"UniTools"},{"id":"ut-oshi-plov-tajik","name":"Таджикский оши палав","country":"Таджикистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":6,"portionNutrition":{"k":780,"p":34,"f":38,"c":76},"details":[{"name":"Баранина","quantity":800,"unit":"g","note":"с косточкой, крупными кусками"},{"name":"Курдючный жир","quantity":150,"unit":"g","note":""},{"name":"Рис девзира или круглозёрный","quantity":700,"unit":"g","note":""},{"name":"Морковь жёлтая","quantity":800,"unit":"g","note":"крупной соломкой"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":2,"unit":"piece","note":"целыми головками"},{"name":"Зира","quantity":2,"unit":"tsp","note":""},{"name":"Барбарис","quantity":2,"unit":"tbsp","note":""},{"name":"Нут","quantity":100,"unit":"g","note":"замочить на ночь"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис в семи водах и залейте тёплой подсоленной водой на час.\nВытопите курдючный жир в казане и выньте шкварки.\nОбжарьте мясо до тёмной корки, добавьте лук и жарьте до золотистого.\nВсыпьте морковь и жарьте десять минут, не перемешивая первые пять — она должна прогреться, а не пустить сок.\nВлейте кипяток на два пальца выше, добавьте нут, зиру, барбарис и соль и томите зирвак сорок минут.\nВыложите рис ровным слоем, вдавите головки чеснока и долейте кипятка на сантиметр выше риса.\nВарите на сильном огне до выпаривания воды, соберите рис горкой, проткните до дна, накройте и держите двадцать минут на минимальном огне.","source":"UniTools"},{"id":"ut-kabuli-pulao","name":"Кабули палав","country":"Афганистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":155,"baseServings":6,"portionNutrition":{"k":820,"p":38,"f":34,"c":96},"details":[{"name":"Баранина на кости","quantity":1,"unit":"kg","note":""},{"name":"Рис басмати","quantity":700,"unit":"g","note":""},{"name":"Морковь","quantity":500,"unit":"g","note":"тонкой соломкой"},{"name":"Изюм","quantity":150,"unit":"g","note":""},{"name":"Миндаль","quantity":80,"unit":"g","note":"лепестками"},{"name":"Фисташки","quantity":50,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":4,"unit":"tbsp","note":""},{"name":"Смесь специй чар масала","quantity":2,"unit":"tsp","note":""},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Кардамон","quantity":6,"unit":"piece","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите рис в подсоленной воде на два часа и промойте до прозрачной воды.\nОбжарьте лук в масле до тёмно-золотого, добавьте мясо и жарьте до корки.\nВлейте литр воды, добавьте кардамон и соль и варите час, пока мясо не станет мягким. Бульон процедите.\nРастопите две ложки сахара на сухой сковороде до тёмной карамели и осторожно разведите половником бульона.\nОбжарьте морковь с оставшимся сахаром пять минут до блеска, добавьте изюм и орехи и снимите с огня.\nОтварите рис в кипятке пять минут до полуготовности и откиньте.\nВыложите рис на мясо в казане, полейте карамельным бульоном, посыпьте чар масалой, проткните до дна и держите под крышкой тридцать минут на слабом огне. Подавайте с морковью и изюмом сверху.","source":"UniTools"},{"id":"ut-mantu-afghan","name":"Афганское манту","country":"Афганистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":5,"portionNutrition":{"k":640,"p":30,"f":26,"c":70},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода","quantity":230,"unit":"ml","note":""},{"name":"Говяжий фарш","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":"мелко нарезать"},{"name":"Жёлтый горох","quantity":200,"unit":"g","note":""},{"name":"Густой йогурт","quantity":500,"unit":"ml","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Кориандр молотый","quantity":1,"unit":"tsp","note":""},{"name":"Мята сушёная","quantity":2,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, воды и соли, вымешивайте десять минут и оставьте на сорок под плёнкой.\nСмешайте фарш с мелко нарезанным луком, солью, перцем и кориандром. Воду не добавляйте.\nОтварите жёлтый горох сорок минут до мягкости с ложкой томатной пасты и солью.\nРазотрите чеснок с солью и вмешайте в йогурт, разведя его водой до жидкой сметаны.\nРаскатайте тесто тонко и нарежьте квадратами восемь на восемь сантиметров.\nПоложите начинку и соедините углы крест-накрест, оставив четыре открытых уголка.\nВарите на пару двадцать пять минут. Выложите на слой йогурта, полейте гороховым соусом, ещё йогуртом и посыпьте мятой.","source":"UniTools"},{"id":"ut-fattoush","name":"Фаттуш","country":"Сирия","category":"salad","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":30,"baseServings":4,"portionNutrition":{"k":280,"p":6,"f":18,"c":26},"details":[{"name":"Лепёшка пита","quantity":2,"unit":"piece","note":"чёрствая"},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Огурцы","quantity":3,"unit":"piece","note":""},{"name":"Редис","quantity":8,"unit":"piece","note":""},{"name":"Салат ромэн","quantity":200,"unit":"g","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Петрушка","quantity":40,"unit":"g","note":""},{"name":"Мята свежая","quantity":20,"unit":"g","note":""},{"name":"Сумах","quantity":2,"unit":"tbsp","note":""},{"name":"Гранатовый соус","quantity":2,"unit":"tbsp","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Чеснок","quantity":2,"unit":"clove","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разорвите лепёшки руками на куски в два пальца и обжарьте в оливковом масле до румяности.\nВыложите хлеб на бумагу и посыпьте половиной сумаха, пока он ещё горячий.\nНарежьте помидоры, огурцы и редис крупными неровными кусками — салат должен быть грубым, а не аккуратным.\nНарвите салат руками, порубите зелень и зелёный лук.\nВзбейте заправку из лимонного сока, гранатового соуса, растёртого чеснока, оставшегося сумаха, масла и соли.\nСмешайте овощи с заправкой, добавьте хлеб и подавайте немедленно.","source":"UniTools"},{"id":"ut-kibbeh-bil-sanieh","name":"Киббе в противне","country":"Сирия","category":"main","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":8,"portionNutrition":{"k":560,"p":34,"f":28,"c":42},"details":[{"name":"Булгур мелкий","quantity":400,"unit":"g","note":""},{"name":"Постная говядина","quantity":500,"unit":"g","note":"для оболочки"},{"name":"Баранина","quantity":500,"unit":"g","note":"фарш, для начинки"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Кедровые орехи","quantity":80,"unit":"g","note":""},{"name":"Бахарат","quantity":1,"unit":"tbsp","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Оливковое масло","quantity":120,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте булгур холодной водой на двадцать минут и отожмите досуха.\nПробейте постную говядину с одной луковицей в комбайне до пасты и вмешайте булгур, соль и половину специй.\nВымешивайте массу пять минут, смачивая руки водой, пока она не станет гладкой и липкой.\nОбжарьте оставшийся лук, добавьте бараний фарш, специи и кедровые орехи и жарьте десять минут.\nВыложите половину массы в смазанный противень слоем в сантиметр, разровняйте мокрой ладонью.\nРаспределите начинку и накройте второй половиной массы, разровняв так же.\nНарежьте ромбами до дна, залейте оливковым маслом и пеките при 200 °C сорок минут до румяной корки.","source":"UniTools"},{"id":"ut-shuwa","name":"Шува","country":"Оман","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":520,"baseServings":8,"portionNutrition":{"k":780,"p":52,"f":36,"c":62},"details":[{"name":"Баранья нога","quantity":3,"unit":"kg","note":""},{"name":"Зира молотая","quantity":3,"unit":"tbsp","note":""},{"name":"Кориандр молотый","quantity":2,"unit":"tbsp","note":""},{"name":"Куркума","quantity":1,"unit":"tbsp","note":""},{"name":"Красный перец молотый","quantity":1,"unit":"tbsp","note":""},{"name":"Сушёный лайм","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Уксус","quantity":4,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Банановые листья или фольга","quantity":4,"unit":"piece","note":""},{"name":"Рис басмати","quantity":700,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разотрите чеснок, все специи, измельчённый сушёный лайм, уксус, масло и соль в густую пасту.\nСделайте в мясе глубокие надрезы до кости и вотрите пасту внутрь и снаружи.\nУберите в холодильник на ночь, минимум на двенадцать часов.\nЗаверните мясо в банановые листья, затем плотно в два слоя фольги. Ни одной щели остаться не должно.\nПоложите свёрток на противень, влейте на дно стакан воды и запекайте при 130 °C восемь часов.\nРазверните, слейте сок и отварите на нём рис. Мясо разберите на волокна руками.\nПодавайте мясо на рисе, из общего блюда, руками.","source":"UniTools"},{"id":"ut-omani-mishkak","name":"Мишкак","country":"Оман","category":"main","diets":[],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":540,"p":46,"f":26,"c":28},"details":[{"name":"Говядина или баранина","quantity":800,"unit":"g","note":"мелким кубиком"},{"name":"Тамариндовая паста","quantity":3,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Кориандр молотый","quantity":2,"unit":"tsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Красный перец молотый","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Лепёшка","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте тамаринд, растёртые чеснок и имбирь, все специи, масло и соль в маринад.\nНарежьте мясо кубиками в полтора сантиметра и залейте маринадом.\nУберите в холодильник минимум на четыре часа, лучше на ночь.\nНанижите куски вплотную на шпажки, не оставляя промежутков.\nРазожгите угли до сильного жара — ладонь над решёткой должна держаться не больше трёх секунд.\nЖарьте по полторы минуты с каждой стороны, четыре стороны, смазывая остатками маринада.\nСнимите с шпажек в лепёшку, добавьте сырой лук и подавайте сразу.","source":"UniTools"},{"id":"ut-ful-sudani","name":"Суданский фул","country":"Судан","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":105,"baseServings":4,"portionNutrition":{"k":480,"p":24,"f":24,"c":44},"details":[{"name":"Бобы фул (конские)","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Кунжутное масло","quantity":60,"unit":"ml","note":""},{"name":"Белый рассольный сыр","quantity":150,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":"варёные"},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Лепёшка","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Слейте воду с замоченных бобов, залейте свежей и варите полтора часа до полной мягкости.\nСлейте почти всю воду, оставив полстакана, посолите и разомните толкушкой примерно наполовину.\nРазотрите чеснок с солью и зирой и вмешайте в бобы.\nПереложите в широкую миску и полейте кунжутным маслом, не размешивая.\nРазложите сверху раскрошенный сыр, нарезанные помидоры, лук, чили и половинки яиц.\nПодайте с лимоном и лепёшкой. Едят руками из общей миски.","source":"UniTools"},{"id":"ut-asida-sudanese","name":"Асида с мулах","country":"Судан","category":"main","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":5,"portionNutrition":{"k":640,"p":32,"f":26,"c":72},"details":[{"name":"Мука из сорго или пшеничная","quantity":400,"unit":"g","note":""},{"name":"Баранина","quantity":600,"unit":"g","note":"кубиками"},{"name":"Сушёная бамия молотая","quantity":60,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Арахисовая паста","quantity":2,"unit":"tbsp","note":""},{"name":"Кориандр молотый","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мясо с луком и чесноком до румяности, добавьте томатную пасту и кориандр.\nЗалейте водой, посолите и тушите сорок минут до мягкости мяса.\nВмешайте арахисовую пасту и всыпайте молотую бамию тонкой струйкой, непрерывно размешивая.\nПроварите соус десять минут — он станет густым и тягучим.\nВскипятите литр подсоленной воды, оставьте стакан отдельно и всыпайте муку, размешивая палкой.\nВымешивайте пятнадцать минут, подливая отложенную воду, пока масса не станет плотной и гладкой.\nВыложите асиду на блюдо мокрой ложкой, сделайте углубление и налейте туда мулах.","source":"UniTools"},{"id":"ut-zanzibar-pilau","name":"Занзибарский пилау","country":"Танзания","category":"main","diets":[],"slots":["lunch","dinner"],"time":100,"baseServings":6,"portionNutrition":{"k":700,"p":38,"f":26,"c":82},"details":[{"name":"Говядина","quantity":800,"unit":"g","note":"кубиками"},{"name":"Рис басмати","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":"тонкими перьями"},{"name":"Гвоздика","quantity":10,"unit":"piece","note":""},{"name":"Кардамон","quantity":8,"unit":"piece","note":""},{"name":"Корица палочка","quantity":2,"unit":"piece","note":""},{"name":"Зира","quantity":2,"unit":"tsp","note":""},{"name":"Чёрный перец горошком","quantity":1,"unit":"tsp","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Картофель","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис до прозрачной воды и замочите на двадцать минут.\nОтварите говядину с половиной специй сорок минут до мягкости. Бульон сохраните.\nОбжарьте лук в масле на среднем огне двадцать минут — до тёмно-коричневого, почти чёрного цвета.\nДобавьте чеснок, имбирь и оставшиеся специи и прогрейте две минуты.\nПоложите варёное мясо и картофель кубиками, перемешайте и прогрейте пять минут.\nВсыпьте рис, влейте бульон в полтора раза больше объёма риса и посолите.\nДоведите до кипения, накройте и варите двадцать минут на слабом огне, не открывая. Дайте постоять десять минут.","source":"UniTools"},{"id":"ut-ndizi-nyama","name":"Ндизи ня ньяма","country":"Танзания","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":85,"baseServings":4,"portionNutrition":{"k":620,"p":34,"f":30,"c":56},"details":[{"name":"Говядина","quantity":600,"unit":"g","note":"кубиками"},{"name":"Зелёные бананы","quantity":8,"unit":"piece","note":""},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Карри молотое","quantity":1,"unit":"tbsp","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте говядину до румяности, добавьте лук, чеснок и имбирь и жарьте до мягкости.\nДобавьте помидоры и карри и тушите пять минут, пока помидоры не разойдутся.\nВлейте воду вровень с мясом, посолите и тушите тридцать минут под крышкой.\nОчистите бананы под струёй воды и нарежьте толстыми кружками.\nЗаложите бананы в кастрюлю и варите двадцать минут до мягкости.\nВлейте кокосовое молоко и прогрейте пять минут, не давая закипеть. Посыпьте кинзой.","source":"UniTools"},{"id":"ut-shorshe-ilish","name":"Шорше илиш","country":"Бангладеш","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":560,"p":38,"f":30,"c":34},"details":[{"name":"Хилса или сельдь","quantity":800,"unit":"g","note":"стейками"},{"name":"Семена горчицы","quantity":60,"unit":"g","note":"жёлтые и чёрные поровну"},{"name":"Зелёный чили","quantity":6,"unit":"piece","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Горчичное масло","quantity":80,"unit":"ml","note":""},{"name":"Чернушка (калонджи)","quantity":1,"unit":"tsp","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите семена горчицы в тёплой воде на двадцать минут.\nРазотрите их с двумя чили, щепотью соли и небольшим количеством воды в гладкую пасту.\nНатрите стейки куркумой и солью и оставьте на десять минут.\nПрогрейте горчичное масло до дымка, снимите с огня и остудите минуту — сырое масло горчит.\nВсыпьте чернушку, влейте горчичную пасту, разведённую половиной стакана воды, и прогрейте три минуты.\nУложите рыбу в один слой, разложите оставшиеся чили целиком, накройте и томите двенадцать минут.\nПолейте ложкой сырого горчичного масла, снимите с огня и подавайте с рисом.","source":"UniTools"},{"id":"ut-bhuna-khichuri","name":"Бхуна кхичури","country":"Бангладеш","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":65,"baseServings":5,"portionNutrition":{"k":540,"p":18,"f":18,"c":78},"details":[{"name":"Рис короткозёрный","quantity":400,"unit":"g","note":""},{"name":"Чечевица мунг","quantity":250,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Зелёный чили","quantity":5,"unit":"piece","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Кардамон","quantity":5,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Картофель","quantity":3,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Подсушите чечевицу мунг на сухой сковороде пять минут до орехового запаха и промойте.\nПромойте рис и обсушите. Мокрый не обжарится, а сварится в собственной воде.\nРазогрейте топлёное масло, обжарьте картофель до румяности и выньте.\nВ том же масле обжарьте лавровый лист, корицу и кардамон, затем лук и имбирь до золотистого.\nВсыпьте рис и чечевицу, добавьте куркуму и зиру и обжаривайте пять минут, помешивая.\nВлейте кипяток вдвое больше объёма крупы, верните картофель, посолите и добавьте целые чили.\nНакройте и варите двадцать минут на слабом огне, потом дайте постоять десять минут не открывая.","source":"UniTools"},{"id":"ut-larb-lao","name":"Лаап","country":"Лаос","category":"salad","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":420,"p":34,"f":22,"c":20},"details":[{"name":"Свинина","quantity":600,"unit":"g","note":"рубить ножом"},{"name":"Клейкий рис","quantity":3,"unit":"tbsp","note":"сырой, для порошка"},{"name":"Рыбный соус","quantity":4,"unit":"tbsp","note":""},{"name":"Лайм","quantity":4,"unit":"piece","note":""},{"name":"Хлопья жареного чили","quantity":2,"unit":"tsp","note":""},{"name":"Шалот","quantity":4,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Мята","quantity":30,"unit":"g","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Салат и сырые овощи","quantity":300,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте сырой клейкий рис на сухой сковороде десять минут до тёмно-золотого цвета, помешивая.\nСмелите остывший рис в ступке или мельнице в грубый порошок.\nПорубите свинину ножом мелко, но не в пасту — кусочки должны угадываться.\nГотовьте мясо в сковороде с двумя ложками воды на среднем огне пять минут, разбивая комки.\nСнимите с огня и дайте остыть до тёплого, минут пять.\nВмешайте рыбный соус, сок лайма, чили, шалот и рисовый порошок.\nДобавьте зелень, перемешайте и подавайте с клейким рисом и сырыми овощами.","source":"UniTools"},{"id":"ut-tam-mak-hoong","name":"Там мак хунг","country":"Лаос","category":"salad","diets":[],"slots":["lunch","dinner"],"time":25,"baseServings":4,"portionNutrition":{"k":160,"p":5,"f":2,"c":32},"details":[{"name":"Зелёная папайя","quantity":600,"unit":"g","note":"соломкой"},{"name":"Падэк или рыбный соус","quantity":4,"unit":"tbsp","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Перец чили","quantity":6,"unit":"piece","note":""},{"name":"Помидоры черри","quantity":150,"unit":"g","note":""},{"name":"Спаржевая фасоль","quantity":100,"unit":"g","note":""},{"name":"Пальмовый сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Тайские баклажаны","quantity":100,"unit":"g","note":"по желанию"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите папайю и нашинкуйте тонкой длинной соломкой ножом или тёркой для сом тама.\nРастолките в ступке чеснок и чили в грубую пасту.\nДобавьте нарезанную фасоль и слегка раздавите её пестиком.\nПоложите помидоры и раздавите их до выделения сока.\nВлейте падэк, сок лайма и пальмовый сахар и перемешайте пестиком с ложкой.\nВсыпьте папайю и работайте пестиком, подбрасывая ложкой, две минуты — волокна должны стать мягкими.\nПопробуйте и поправьте на кислоту, соль и остроту. Подавайте с клейким рисом.","source":"UniTools"},{"id":"ut-souvla","name":"Сувла","country":"Кипр","category":"main","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":720,"p":52,"f":42,"c":28},"details":[{"name":"Свиная лопатка","quantity":2.5,"unit":"kg","note":"кусками по 200 г"},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Орегано сушёный","quantity":2,"unit":"tbsp","note":""},{"name":"Кипрская пита","quantity":6,"unit":"piece","note":""},{"name":"Лук красный","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Петрушка","quantity":40,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте мясо крупными кусками граммов по двести, с жиром — он нужен.\nОбильно посолите и поперчите со всех сторон и оставьте на полчаса при комнатной температуре.\nРазожгите угли и разгребите их к краям, оставив центр свободным. Прямой жар под мясом не нужен.\nНанижите куски на вертел, оставляя между ними по сантиметру.\nВращайте вертел медленно и непрерывно два часа. Мясо должно потемнеть постепенно, а не схватиться коркой сразу.\nПосыпьте орегано за десять минут до конца и сбрызните лимоном.\nСнимите, нарежьте крупно и подавайте в пите с луком, помидорами и петрушкой.","source":"UniTools"},{"id":"ut-halloumi-grilled","name":"Жареный халуми с арбузом","country":"Кипр","category":"salad","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":30,"baseServings":4,"portionNutrition":{"k":380,"p":22,"f":26,"c":16},"details":[{"name":"Халуми","quantity":400,"unit":"g","note":""},{"name":"Арбуз","quantity":800,"unit":"g","note":"холодный, кубиками"},{"name":"Мята","quantity":20,"unit":"g","note":""},{"name":"Оливковое масло","quantity":50,"unit":"ml","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Мёд","quantity":1,"unit":"tbsp","note":""},{"name":"Руккола","quantity":80,"unit":"g","note":""},{"name":"Чёрный перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите халуми в холодной воде на пятнадцать минут, слейте и обсушите насухо.\nНарежьте сыр ломтями в сантиметр толщиной — тоньше он пересохнет, толще не прогреется.\nНарежьте холодный арбуз крупными кубиками и держите в холодильнике до подачи.\nРаскалите сухую сковороду и обжарьте халуми по две минуты с каждой стороны до тёмных полос.\nВзбейте оливковое масло с лимонным соком, мёдом и перцем.\nВыложите арбуз, рукколу и горячий сыр, полейте заправкой и посыпьте мятой. Подавайте сразу.","source":"UniTools"},{"id":"ut-maltese-rabbit-stew","name":"Кролик по-мальтийски","country":"Мальта","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":135,"baseServings":4,"portionNutrition":{"k":620,"p":48,"f":24,"c":44},"details":[{"name":"Кролик","quantity":1.5,"unit":"kg","note":"разделать на части"},{"name":"Красное сухое вино","quantity":500,"unit":"ml","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Лавровый лист","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Зелёный горошек","quantity":200,"unit":"g","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте разделанного кролика вином с половиной чеснока и лавровым листом и оставьте на сутки в холоде.\nВыньте мясо, обсушите и обжарьте в оливковом масле до румяной корки. Маринад сохраните.\nОбжарьте лук и оставшийся чеснок до мягкости, добавьте томатную пасту и прогрейте три минуты.\nВерните мясо, влейте маринад, посолите и тушите под крышкой час на слабом огне.\nДобавьте картофель и морковь и тушите ещё двадцать пять минут.\nВсыпьте горошек на последние десять минут.\nОтлейте часть соуса и заправьте им спагетти — это первая перемена. Мясо подайте следом.","source":"UniTools"},{"id":"ut-pastizzi","name":"Пастицци","country":"Мальта","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":125,"baseServings":8,"portionNutrition":{"k":480,"p":14,"f":30,"c":40},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода","quantity":250,"unit":"ml","note":""},{"name":"Смалец или маргарин","quantity":250,"unit":"g","note":""},{"name":"Рикотта","quantity":500,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Жёлтый горох","quantity":250,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, воды и соли, вымешивайте десять минут и оставьте на полчаса.\nОтварите горох с луком сорок минут до полной мягкости, разомните, посолите и поперчите.\nСмешайте рикотту с яйцами, петрушкой, солью и перцем.\nРаскатайте тесто очень тонко, смажьте жиром, сверните рулетом и оставьте в холоде на двадцать минут.\nНарежьте рулет на кусочки, каждый раскатайте в кружок — слои дадут ту самую слоистость.\nВыложите начинку и защипните: рикотту — лодочкой с открытым верхом, горох — ромбом.\nПеките при 220 °C тридцать минут до тёмно-золотого цвета и подавайте горячими.","source":"UniTools"},{"id":"ut-chivito","name":"Чивито","country":"Уругвай","category":"main","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":890,"p":52,"f":54,"c":46},"details":[{"name":"Говяжья вырезка","quantity":500,"unit":"g","note":"тонкими пластами"},{"name":"Булочки","quantity":4,"unit":"piece","note":""},{"name":"Ветчина","quantity":150,"unit":"g","note":""},{"name":"Бекон","quantity":150,"unit":"g","note":""},{"name":"Моцарелла","quantity":200,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Салат листовой","quantity":100,"unit":"g","note":""},{"name":"Зелёные оливки","quantity":60,"unit":"g","note":""},{"name":"Майонез","quantity":100,"unit":"g","note":""},{"name":"Растительное масло","quantity":30,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отбейте мясо через плёнку до толщины четыре миллиметра, посолите и поперчите.\nОбжарьте бекон до хруста и выложите на бумагу.\nРаскалите сковороду и обжарьте стейки по сорок пять секунд с каждой стороны.\nПоложите на мясо сыр прямо в сковороде и накройте на тридцать секунд, чтобы он подтаял.\nПожарьте яйца до жидкого желтка и подсушите разрезанные булочки на сухой сковороде.\nСмажьте обе половины майонезом, положите салат, помидор, мясо с сыром, ветчину, бекон и яйцо.\nЗакройте, воткните шпажку с оливкой и подавайте с картофелем фри.","source":"UniTools"},{"id":"ut-milanesa-a-la-napolitana","name":"Миланеса а-ля наполитана","country":"Уругвай","category":"main","diets":[],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":820,"p":54,"f":46,"c":48},"details":[{"name":"Говядина","quantity":700,"unit":"g","note":"тонкие куски для отбивания"},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Панировочные сухари","quantity":250,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Томатный соус","quantity":300,"unit":"ml","note":""},{"name":"Ветчина","quantity":200,"unit":"g","note":""},{"name":"Моцарелла","quantity":250,"unit":"g","note":""},{"name":"Орегано","quantity":1,"unit":"tsp","note":""},{"name":"Масло для жарки","quantity":250,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отбейте мясо до пяти миллиметров, посолите и поперчите.\nВзбейте яйца с растёртым чесноком и рубленой петрушкой — это уругвайская особенность панировки.\nОкуните куски в яйцо, затем плотно обваляйте в сухарях, прижимая ладонью.\nДайте панировке схватиться пятнадцать минут в холодильнике.\nОбжарьте в разогретом масле по три минуты с каждой стороны до золотистой корки и выложите на решётку.\nРазложите миланесы на противне, полейте томатным соусом, накройте ветчиной и сыром, посыпьте орегано.\nПоставьте под гриль на четыре минуты, пока сыр не расплавится и не подрумянится.","source":"UniTools"},{"id":"ut-pepian","name":"Пепиан","country":"Гватемала","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":640,"p":44,"f":28,"c":52},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Тыквенные семечки","quantity":120,"unit":"g","note":""},{"name":"Кунжут","quantity":60,"unit":"g","note":""},{"name":"Перец гуахильо","quantity":4,"unit":"piece","note":""},{"name":"Перец пасилья","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Томатильо","quantity":300,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Стручковая фасоль","quantity":200,"unit":"g","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Рис","quantity":350,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу с луковицей и солью сорок минут. Бульон сохраните.\nОбжарьте тыквенные семечки и кунжут на сухой сковороде до тёмно-золотого, помешивая.\nНа той же сковороде обожгите перцы, помидоры, томатильо и чеснок до чёрных пятен.\nПробейте всё в блендере с двумя половниками бульона и корицей до гладкого соуса.\nПроцедите соус через сито — в нём останутся шкурки перцев, которые портят текстуру.\nПроварите соус двадцать минут, помешивая, пока он не загустеет и не потемнеет.\nОпустите курицу, картофель и фасоль и тушите пятнадцать минут. Подавайте с рисом и кинзой.","source":"UniTools"},{"id":"ut-tamales-guatemaltecos","name":"Гватемальские тамалес","country":"Гватемала","category":"main","diets":[],"slots":["lunch","dinner"],"time":180,"baseServings":8,"portionNutrition":{"k":620,"p":26,"f":34,"c":54},"details":[{"name":"Кукурузная мука масека","quantity":700,"unit":"g","note":""},{"name":"Свинина","quantity":800,"unit":"g","note":"кусками"},{"name":"Смалец","quantity":200,"unit":"g","note":""},{"name":"Помидоры","quantity":500,"unit":"g","note":""},{"name":"Перец гуахильо","quantity":4,"unit":"piece","note":""},{"name":"Тыквенные семечки","quantity":80,"unit":"g","note":""},{"name":"Кунжут","quantity":40,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Банановые листья","quantity":16,"unit":"piece","note":""},{"name":"Оливки","quantity":16,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите свинину с луком и солью час. Бульон процедите и сохраните.\nОбжарьте семечки, кунжут, перцы и помидоры на сухой сковороде и пробейте в блендере с бульоном — это рекадо.\nПроварите рекадо двадцать минут до густоты и посолите.\nРазведите масеку тёплым бульоном, добавьте растопленный смалец и вымешивайте двадцать минут на слабом огне.\nПрогрейте банановые листья над огнём по десять секунд, чтобы они стали гибкими.\nНа лист выложите тесто, сверху кусок мяса, ложку рекадо, полоску перца и оливку. Заверните в два листа.\nУложите свёртки в кастрюлю швом вниз и варите на пару полтора часа.","source":"UniTools"},{"id":"ut-sancocho-dominicano","name":"Доминиканский санкочо","country":"Доминиканская Республика","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":165,"baseServings":8,"portionNutrition":{"k":680,"p":46,"f":26,"c":68},"details":[{"name":"Говядина на кости","quantity":600,"unit":"g","note":""},{"name":"Свинина","quantity":500,"unit":"g","note":""},{"name":"Курица","quantity":600,"unit":"g","note":""},{"name":"Юкка (маниок)","quantity":500,"unit":"g","note":""},{"name":"Яутия или таро","quantity":400,"unit":"g","note":""},{"name":"Батат","quantity":400,"unit":"g","note":""},{"name":"Подорожник зелёный","quantity":2,"unit":"piece","note":""},{"name":"Кукуруза","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Орегано сушёный","quantity":1,"unit":"tbsp","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте все виды мяса в соке лайма, растёртом чесноке, орегано, соли и перце на час.\nОбжарьте мясо порциями в большой кастрюле до румяной корки.\nДобавьте лук и перец, залейте тремя литрами воды и варите час на слабом огне.\nЗаложите юкку и яутию, нарезанные крупными кусками, и варите двадцать минут.\nДобавьте батат, подорожник и кукурузу и варите ещё двадцать минут.\nРазомните пару кусков юкки прямо в кастрюле, чтобы суп загустел.\nВмешайте кинзу, попробуйте на соль и подавайте с белым рисом и авокадо.","source":"UniTools"},{"id":"ut-mangu","name":"Мангу","country":"Доминиканская Республика","category":"breakfast","diets":[],"slots":["breakfast"],"time":50,"baseServings":4,"portionNutrition":{"k":720,"p":30,"f":42,"c":58},"details":[{"name":"Зелёный подорожник","quantity":4,"unit":"piece","note":""},{"name":"Лук красный","quantity":2,"unit":"piece","note":""},{"name":"Уксус","quantity":60,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Салями","quantity":200,"unit":"g","note":""},{"name":"Сыр для жарки","quantity":200,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите подорожник под водой, разрежьте пополам и отварите в подсоленной воде двадцать минут до мягкости.\nОтлейте стакан воды от варки и остудите её.\nЗамаринуйте нарезанный кольцами лук в уксусе с солью и оставьте на пятнадцать минут.\nРазомните горячий подорожник с маслом, подливая холодную воду, до гладкого пюре.\nОбжарьте ломти салями и сыра на сухой сковороде до румяности.\nПожарьте яйца и соберите тарелку: пюре, сверху лук с уксусом, рядом салями, сыр и яйцо.","source":"UniTools"},{"id":"ut-doubles","name":"Даблс","country":"Тринидад и Тобаго","category":"breakfast","diets":["vegetarian","vegan"],"slots":["breakfast"],"time":160,"baseServings":6,"portionNutrition":{"k":520,"p":18,"f":20,"c":68},"details":[{"name":"Мука","quantity":450,"unit":"g","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""},{"name":"Нут","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Зира молотая","quantity":2,"unit":"tsp","note":""},{"name":"Карри молотое","quantity":2,"unit":"tbsp","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Тамариндовый соус","quantity":100,"unit":"ml","note":"к подаче"},{"name":"Масло для жарки","quantity":600,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Растворите дрожжи с сахаром в тёплой воде, добавьте муку, куркуму и соль и замесите мягкое тесто.\nДайте тесту подойти в тепле час до удвоения.\nОтварите нут с чесноком час до полной мягкости.\nОбжарьте лук, добавьте карри и зиру, прогрейте минуту и вмешайте нут с половиной его отвара.\nРазомните треть нута прямо в кастрюле и потушите десять минут до густоты соуса.\nРазделите тесто на небольшие шарики, дайте им постоять двадцать минут и расплющите ладонью в лепёшки.\nЖарьте бары в горячем масле по двадцать секунд с каждой стороны — они должны остаться мягкими. Кладите нут между двумя барами и подавайте с тамариндом.","source":"UniTools"},{"id":"ut-callaloo","name":"Каллалу","country":"Тринидад и Тобаго","category":"soup","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":80,"baseServings":6,"portionNutrition":{"k":260,"p":7,"f":18,"c":20},"details":[{"name":"Листья таро или шпинат","quantity":600,"unit":"g","note":""},{"name":"Окра","quantity":250,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Тыква","quantity":300,"unit":"g","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Тимьян","quantity":4,"unit":"sprig","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте листья, снимите жёсткие черешки и крупно нарежьте.\nОбжарьте лук и чеснок в масле до мягкости.\nДобавьте листья, окру, тыкву, тимьян и целый скотч-боннет, залейте водой на два пальца.\nВарите сорок минут на слабом огне под крышкой. Меньше нельзя: сырые листья таро жгут рот.\nВыньте перец и тимьян, влейте кокосовое молоко и прогрейте пять минут не кипятя.\nРазбейте суп веничком или пестиком до состояния густого, но не идеально гладкого пюре.","source":"UniTools"},{"id":"ut-tave-kosi","name":"Таве коси","country":"Албания","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":620,"p":42,"f":38,"c":24},"details":[{"name":"Ягнёнок","quantity":1,"unit":"kg","note":"кусками"},{"name":"Густой йогурт","quantity":800,"unit":"ml","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Мука","quantity":60,"unit":"g","note":""},{"name":"Рис","quantity":80,"unit":"g","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Орегано сушёный","quantity":1,"unit":"tbsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите мясо солью, перцем, чесноком и орегано и запекайте при 190 °C сорок минут с кусочками масла.\nОтварите рис до полуготовности, семь минут, и откиньте.\nРастопите оставшееся масло, вмешайте муку и прогрейте две минуты до орехового запаха.\nВзбейте йогурт с яйцами и солью, влейте мучную смесь и размешайте до полной однородности.\nВмешайте рис. Он впитает часть влаги и не даст соусу расслоиться.\nРазложите мясо с соком в форме и залейте йогуртовой смесью.\nЗапекайте при 180 °C сорок пять минут, пока верх не подрумянится, а середина не будет чуть дрожать.","source":"UniTools"},{"id":"ut-byrek-me-spinaq","name":"Бюрек со шпинатом","country":"Албания","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":80,"baseServings":8,"portionNutrition":{"k":480,"p":16,"f":30,"c":38},"details":[{"name":"Тесто фило","quantity":500,"unit":"g","note":""},{"name":"Шпинат","quantity":1,"unit":"kg","note":""},{"name":"Брынза","quantity":400,"unit":"g","note":""},{"name":"Зелёный лук","quantity":6,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":180,"unit":"ml","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Ошпарьте шпинат кипятком, откиньте и отожмите руками досуха.\nНарежьте шпинат, смешайте с раскрошенной брынзой, зелёным луком, укропом и перцем. Соль добавляйте осторожно — брынза солёная.\nСмажьте форму маслом и уложите три листа фило, промазывая каждый.\nРаспределите треть начинки, накройте двумя листами с маслом и повторите ещё дважды.\nЗакройте тремя листами сверху, подверните края внутрь и щедро смажьте маслом.\nНарежьте квадратами до низа острым ножом — резать после выпечки не получится.\nПеките при 190 °C сорок пять минут до тёмно-золотой хрустящей корки.","source":"UniTools"},{"id":"ut-placinta","name":"Плацинда","country":"Молдова","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":90,"baseServings":6,"portionNutrition":{"k":440,"p":14,"f":22,"c":46},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода тёплая","quantity":260,"unit":"ml","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Брынза","quantity":400,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Тыква","quantity":400,"unit":"g","note":"для второй начинки"},{"name":"Сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Замесите мягкое тесто из муки, тёплой воды, ложки масла и соли и вымешивайте десять минут.\nРазделите на шесть шаров, обильно смажьте маслом и оставьте под плёнкой на сорок минут.\nРазомните брынзу с яйцом и укропом. Натрите тыкву и смешайте с сахаром для второй начинки.\nРастяните шар руками на смазанном маслом столе в тонкий круг, пока не станет просвечивать.\nВыложите начинку в центр и заверните края к середине, складывая в конверт или в круг.\nПриплющите ладонью до толщины полтора сантиметра.\nЖарьте на раскалённой сухой сковороде по четыре минуты с каждой стороны до пятнистой корки.","source":"UniTools"},{"id":"ut-zeama","name":"Зама","country":"Молдова","category":"soup","diets":[],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":380,"p":30,"f":12,"c":40},"details":[{"name":"Курица","quantity":1.2,"unit":"kg","note":"домашняя, кусками"},{"name":"Мука","quantity":250,"unit":"g","note":"для лапши"},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Борщ из отрубей","quantity":400,"unit":"ml","note":"или сок 2 лимонов"},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Картофель","quantity":3,"unit":"piece","note":""},{"name":"Любисток","quantity":30,"unit":"g","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте курицу тремя литрами холодной воды, доведите до кипения и снимите пену.\nВарите сорок минут на слабом огне с целой луковицей.\nЗамесите крутое тесто из муки и яиц, раскатайте тонко, подсушите и нарежьте тонкой лапшой.\nВыньте курицу, разберите на куски, а в бульон заложите морковь, перец и картофель.\nЧерез пятнадцать минут всыпьте лапшу и варите пять минут.\nВскипятите борщ отдельно, процедите и влейте в суп. Проварите пять минут.\nВерните мясо, посолите и вмешайте любисток с петрушкой. Дайте настояться десять минут.","source":"UniTools"},{"id":"ut-judd-mat-gaardebounen","name":"Копчёная шейка с бобами","country":"Люксембург","category":"main","diets":[],"slots":["lunch","dinner"],"time":140,"baseServings":4,"portionNutrition":{"k":740,"p":48,"f":40,"c":46},"details":[{"name":"Копчёная свиная шейка","quantity":1,"unit":"kg","note":""},{"name":"Бобы садовые","quantity":1,"unit":"kg","note":"в стручках"},{"name":"Копчёная грудинка","quantity":150,"unit":"g","note":"кубиками"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Сливки","quantity":200,"unit":"ml","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Чабер","quantity":2,"unit":"sprig","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":"к подаче"},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Вымочите мясо в холодной воде четыре часа, меняя воду дважды.\nЗалейте свежей водой, доведите до кипения, проварите десять минут и слейте.\nЗалейте снова, добавьте лавровый лист и варите час двадцать до мягкости. Бульон сохраните.\nВылущите бобы из стручков, ошпарьте кипятком на минуту и снимите плёнку с каждого.\nВытопите грудинку, обжарьте в жире лук, всыпьте муку и прогрейте две минуты.\nВлейте два половника бульона и сливки, добавьте чабер и бобы и тушите десять минут.\nНарежьте мясо толстыми ломтями и подайте с бобами и отварным картофелем.","source":"UniTools"},{"id":"ut-gromperekichelcher","name":"Громперекихельхер","country":"Люксембург","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":50,"baseServings":5,"portionNutrition":{"k":420,"p":8,"f":24,"c":44},"details":[{"name":"Картофель","quantity":1,"unit":"kg","note":"крахмалистых сортов"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Мука","quantity":60,"unit":"g","note":""},{"name":"Петрушка","quantity":50,"unit":"g","note":""},{"name":"Шалот","quantity":2,"unit":"piece","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Яблочное пюре","quantity":250,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите картофель, лук и шалот на крупной тёрке в одну миску.\nОтожмите массу через полотенце, но не досуха — немного влаги нужно.\nВмешайте яйца, муку, рубленую петрушку, соль и перец.\nРазогрейте масло до 175 °C. Слишком горячее сожжёт края раньше, чем прогреется середина.\nОпускайте массу ложкой, приплющивая до полусантиметра, и жарьте по три минуты с каждой стороны.\nВыложите на решётку, посолите и подавайте горячими с яблочным пюре.","source":"UniTools"},{"id":"ut-dograma","name":"Дограма","country":"Туркменистан","category":"soup","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":620,"p":42,"f":26,"c":52},"details":[{"name":"Баранина на кости","quantity":1.5,"unit":"kg","note":""},{"name":"Пресная лепёшка чурек","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":"по желанию"},{"name":"Чёрный перец","quantity":1,"unit":"tsp","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте баранину холодной водой, доведите до кипения и тщательно снимите пену.\nВарите два часа на слабом огне с лавровым листом, пока мясо не начнёт отходить от кости.\nВыньте мясо, остудите и разберите руками на волокна, выбросив кости и жилы.\nРаскрошите лепёшку руками на кусочки размером с ноготь. Ножом не режьте.\nНарежьте лук тонкими перьями и разомните руками с щепотью соли, чтобы он смягчился.\nСмешайте хлеб, мясо и лук в большой миске насухо, посолите и поперчите.\nРазложите по тарелкам и залейте кипящим процеженным бульоном непосредственно перед подачей.","source":"UniTools"},{"id":"ut-ichlekli","name":"Ишлекли","country":"Туркменистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":8,"portionNutrition":{"k":660,"p":32,"f":34,"c":56},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Вода","quantity":280,"unit":"ml","note":""},{"name":"Баранина","quantity":800,"unit":"g","note":"мелким кубиком"},{"name":"Лук","quantity":5,"unit":"piece","note":"мелко нарезать"},{"name":"Курдючный жир","quantity":100,"unit":"g","note":""},{"name":"Картофель","quantity":2,"unit":"piece","note":"по желанию"},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое пресное тесто из муки, воды и соли и оставьте под полотенцем на тридцать минут.\nНарежьте баранину и жир мелким кубиком ножом, лук — как можно мельче.\nСмешайте мясо, жир, лук, зиру, соль и перец. Воду не добавляйте — сок даст лук.\nРазделите тесто на две части, большую раскатайте в круг и уложите в смазанную форму с запасом по краям.\nВыложите начинку ровным слоем, накройте вторым пластом и защипните края плотным жгутом.\nСделайте в центре небольшое отверстие для пара, смажьте маслом и накройте фольгой.\nПеките при 180 °C час под фольгой, потом снимите её и держите ещё десять минут до румяности.","source":"UniTools"},{"id":"ut-kabsa","name":"Кабса","country":"Саудовская Аравия","category":"main","diets":[],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":720,"p":44,"f":28,"c":78},"details":[{"name":"Курица","quantity":1.6,"unit":"kg","note":"кусками"},{"name":"Рис басмати","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Сушёный лайм","quantity":3,"unit":"piece","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Бахарат для кабсы","quantity":1,"unit":"tbsp","note":""},{"name":"Кардамон","quantity":6,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Изюм","quantity":60,"unit":"g","note":""},{"name":"Миндаль","quantity":60,"unit":"g","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис до прозрачной воды и замочите на двадцать минут.\nОбжарьте лук в топлёном масле до золотистого, добавьте чеснок, кардамон и корицу.\nОбжарьте курицу со всех сторон, добавьте томатную пасту, помидоры, морковь и бахарат.\nПроколите сушёные лаймы и опустите в кастрюлю, залейте водой и варите тридцать минут.\nВыньте курицу, обсушите и поставьте под гриль на десять минут до румяной корки.\nВсыпьте рис в бульон — жидкости должно быть в полтора раза больше — посолите и варите двадцать минут под крышкой.\nОбжарьте миндаль и изюм в масле, выложите рис на блюдо, сверху курицу, посыпьте орехами.","source":"UniTools"},{"id":"ut-jareesh","name":"Джариш","country":"Саудовская Аравия","category":"main","diets":[],"slots":["lunch","dinner"],"time":170,"baseServings":6,"portionNutrition":{"k":580,"p":34,"f":26,"c":54},"details":[{"name":"Дроблёная пшеница джариш","quantity":400,"unit":"g","note":"замочить на 2 часа"},{"name":"Баранина на кости","quantity":800,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Йогурт","quantity":200,"unit":"ml","note":""},{"name":"Бахарат","quantity":2,"unit":"tsp","note":""},{"name":"Сушёный лайм","quantity":2,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите дроблёную пшеницу в холодной воде на два часа и промойте.\nОбжарьте одну луковицу в топлёном масле, добавьте мясо и жарьте до румяности.\nДобавьте помидоры, бахарат и проколотые лаймы, залейте водой и варите сорок минут.\nВсыпьте пшеницу, долейте воды на два пальца выше и варите полтора часа на слабом огне, помешивая.\nВыньте кости, вмешайте йогурт и взбейте кашу ложкой или миксером до кремовой однородности.\nОбжарьте оставшийся лук до тёмно-коричневого и выложите на джариш вместе с маслом.","source":"UniTools"},{"id":"ut-saltah","name":"Сальта","country":"Йемен","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":4,"portionNutrition":{"k":620,"p":38,"f":32,"c":44},"details":[{"name":"Семена пажитника","quantity":60,"unit":"g","note":"замочить на ночь"},{"name":"Баранина","quantity":600,"unit":"g","note":"кубиками"},{"name":"Картофель","quantity":300,"unit":"g","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Соус жуг","quantity":3,"unit":"tbsp","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Рис","quantity":150,"unit":"g","note":"варёный"},{"name":"Лепёшка","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Слейте воду с замоченного пажитника, промойте несколько раз и смелите в пасту.\nВзбивайте пасту с холодной водой венчиком или миксером десять минут, пока она не станет белой пеной.\nОбжарьте лук и чеснок, добавьте мясо и жарьте до румяности.\nДобавьте помидоры и картофель, залейте водой, посолите и тушите час до мягкости мяса.\nРаскалите каменный или чугунный горшок и перелейте в него кипящее рагу.\nВбейте яйца прямо в кипящее рагу и размешайте — они схватятся нитями.\nВыложите сверху хульбу и ложку жуга и несите на стол, пока кипит. Подавайте с лепёшкой и рисом.","source":"UniTools"},{"id":"ut-bint-al-sahn","name":"Бинт ас-сахн","country":"Йемен","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":115,"baseServings":8,"portionNutrition":{"k":620,"p":9,"f":34,"c":70},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Молоко тёплое","quantity":200,"unit":"ml","note":""},{"name":"Топлёное масло","quantity":300,"unit":"g","note":""},{"name":"Мёд","quantity":250,"unit":"g","note":""},{"name":"Чернушка (калонджи)","quantity":2,"unit":"tsp","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи с сахаром в тёплом молоке и оставьте на десять минут.\nЗамесите мягкое тесто из муки, яиц, опары, соли и двух ложек топлёного масла и вымешивайте пятнадцать минут.\nДайте подойти в тепле час до удвоения.\nРазделите на десять шаров, смажьте маслом и оставьте на двадцать минут под плёнкой.\nРастяните первый шар руками до размера формы и уложите на дно, обильно смазав топлёным маслом.\nПовторите с остальными, промазывая каждый слой. Верхний тоже смажьте и посыпьте чернушкой.\nПеките при 190 °C тридцать пять минут и залейте мёдом сразу, пока хлеб горячий.","source":"UniTools"},{"id":"ut-machboos","name":"Мачбус","country":"ОАЭ","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":75,"baseServings":5,"portionNutrition":{"k":640,"p":42,"f":20,"c":78},"details":[{"name":"Креветки","quantity":800,"unit":"g","note":"крупные, очищенные"},{"name":"Рис басмати","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Сушёный лайм луми","quantity":3,"unit":"piece","note":""},{"name":"Смесь бизар","quantity":1,"unit":"tbsp","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Зелёный чили","quantity":2,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис до прозрачной воды и замочите на двадцать минут.\nОбжарьте лук в топлёном масле до тёмно-золотого, пятнадцать минут, и треть отложите.\nДобавьте чеснок, имбирь, бизар и куркуму и прогрейте минуту до запаха.\nПоложите помидоры и проколотые лаймы, залейте водой в полтора раза больше объёма риса и посолите.\nДоведите до кипения, всыпьте рис, накройте и варите пятнадцать минут на слабом огне.\nРазложите креветки поверх риса, накройте и держите ещё пять минут — они дойдут паром.\nДайте постоять десять минут, посыпьте отложенным луком, кинзой и чили.","source":"UniTools"},{"id":"ut-luqaimat","name":"Лукаймат","country":"ОАЭ","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":95,"baseServings":6,"portionNutrition":{"k":420,"p":6,"f":16,"c":64},"details":[{"name":"Мука","quantity":300,"unit":"g","note":""},{"name":"Кукурузный крахмал","quantity":50,"unit":"g","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Йогурт","quantity":100,"unit":"ml","note":""},{"name":"Вода тёплая","quantity":280,"unit":"ml","note":""},{"name":"Сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Кардамон молотый","quantity":1,"unit":"tsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Финиковый сироп дибс","quantity":200,"unit":"ml","note":""},{"name":"Кунжут","quantity":30,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Залейте шафран ложкой тёплой воды и оставьте настаиваться.\nСмешайте муку, крахмал, дрожжи, сахар, кардамон и соль.\nВлейте йогурт, тёплую воду и шафранный настой и взбейте до гладкого жидкого теста.\nОставьте в тепле на час — тесто должно подняться и покрыться пузырями.\nРазогрейте масло до 170 °C и опускайте тесто чайной ложкой, смачивая её в воде.\nЖарьте партиями по три-четыре минуты, помешивая шумовкой, до тёмно-золотого цвета.\nВыложите на бумагу, полейте финиковым сиропом и посыпьте кунжутом. Подавайте сразу.","source":"UniTools"},{"id":"ut-murabyan","name":"Мурабьян","country":"Кувейт","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":85,"baseServings":5,"portionNutrition":{"k":660,"p":46,"f":20,"c":80},"details":[{"name":"Креветки","quantity":1,"unit":"kg","note":"неочищенные"},{"name":"Рис басмати","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Укроп","quantity":80,"unit":"g","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Сушёный лайм","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Смесь бизар","quantity":1,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите креветки, панцири и головы сохраните.\nОбжарьте панцири в ложке масла пять минут, залейте литром воды и варите двадцать минут. Процедите.\nПромойте рис и замочите на двадцать минут.\nОбжарьте лук в топлёном масле до золотистого, добавьте чеснок, куркуму и бизар.\nПоложите помидоры, проколотые лаймы и половину укропа, влейте креветочный бульон и посолите.\nВсыпьте рис, накройте и варите пятнадцать минут на слабом огне, не открывая.\nРазложите креветки и оставшийся укроп сверху, накройте и держите пять минут. Дайте постоять десять и подавайте.","source":"UniTools"},{"id":"ut-harees","name":"Харис","country":"Кувейт","category":"main","diets":[],"slots":["lunch","dinner"],"time":230,"baseServings":6,"portionNutrition":{"k":600,"p":38,"f":28,"c":52},"details":[{"name":"Цельная пшеница","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Баранина на кости","quantity":900,"unit":"g","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Кардамон","quantity":4,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":100,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":"для подачи"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите пшеницу на ночь в холодной воде и промойте.\nЗалейте мясо тремя литрами воды, доведите до кипения и снимите пену.\nДобавьте пшеницу, корицу и кардамон и варите два часа на слабом огне.\nВыньте кости и специи, посолите и варите ещё час, помешивая и подливая кипяток.\nВзбейте массу деревянной ложкой или миксером до полной гладкости — двадцать минут работы.\nВыложите в блюдо, сделайте углубление, залейте растопленным маслом и посыпьте жареным луком.","source":"UniTools"},{"id":"ut-ndole","name":"Ндоле","country":"Камерун","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":680,"p":42,"f":42,"c":34},"details":[{"name":"Листья ндоле или шпинат","quantity":700,"unit":"g","note":""},{"name":"Арахис","quantity":300,"unit":"g","note":"сырой, очищенный"},{"name":"Говядина","quantity":600,"unit":"g","note":"кубиками"},{"name":"Креветки","quantity":300,"unit":"g","note":""},{"name":"Сушёные креветки","quantity":50,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Перец чили","quantity":2,"unit":"piece","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Подорожник","quantity":3,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите листья в подсоленной воде десять минут, отожмите и повторите ещё дважды со свежей водой.\nОтварите арахис двадцать минут до мягкости и пробейте в блендере с водой в густую пасту.\nОбжарьте говядину до румяности, добавьте лук, чеснок, имбирь и чили.\nЗалейте водой, добавьте сушёные креветки и тушите сорок минут до мягкости мяса.\nВмешайте арахисовую пасту и проварите пятнадцать минут, помешивая — она легко пригорает.\nДобавьте отжатые листья и свежие креветки и потушите ещё десять минут.\nПодавайте с жареным подорожником или варёным маниоком.","source":"UniTools"},{"id":"ut-poulet-dg","name":"Пуле DG","country":"Камерун","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":75,"baseServings":5,"portionNutrition":{"k":720,"p":42,"f":34,"c":62},"details":[{"name":"Курица","quantity":1.4,"unit":"kg","note":"кусками"},{"name":"Подорожник","quantity":4,"unit":"piece","note":"спелый, но плотный"},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Стручковая фасоль","quantity":200,"unit":"g","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Тимьян","quantity":3,"unit":"sprig","note":""},{"name":"Масло для жарки","quantity":300,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте курицу в растёртых чесноке, имбире, тимьяне, соли и перце на полчаса.\nОбжарьте курицу в масле до румяной корки со всех сторон и выньте.\nНарежьте подорожник крупными кусками и обжарьте в том же масле до карамельных краёв.\nСлейте почти всё масло, обжарьте лук, помидоры и перец до мягкости.\nВерните курицу, добавьте морковь, фасоль и целый скотч-боннет, влейте стакан воды и тушите двадцать минут.\nВыньте перец, вмешайте подорожник и прогрейте три минуты. Подавайте сразу.","source":"UniTools"},{"id":"ut-attieke-poisson","name":"Атьеке с рыбой","country":"Кот-д'Ивуар","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":560,"p":40,"f":20,"c":58},"details":[{"name":"Атьеке","quantity":500,"unit":"g","note":""},{"name":"Тиляпия или дорада","quantity":4,"unit":"piece","note":"целая, потрошёная"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Перец чили","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Бульонный кубик","quantity":1,"unit":"piece","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разотрите чеснок, имбирь, чили, бульонный кубик, соль и масло в пасту.\nСделайте на рыбе надрезы по бокам и вотрите пасту внутрь и снаружи. Оставьте на двадцать минут.\nРазрыхлите атьеке руками, сбрызните горячей водой и посолите.\nНакройте и распаривайте десять минут — на пару или просто под крышкой в тёплом месте.\nНарежьте лук, помидоры и чили и смешайте с соком лимона, солью и ложкой масла.\nЖарьте рыбу на углях или в сковороде-гриль по семь минут с каждой стороны.\nПодайте атьеке, рыбу и салат на одной тарелке, с долькой лимона.","source":"UniTools"},{"id":"ut-kedjenou","name":"Кеджену","country":"Кот-д'Ивуар","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":100,"baseServings":4,"portionNutrition":{"k":520,"p":44,"f":20,"c":42},"details":[{"name":"Курица","quantity":1.4,"unit":"kg","note":"кусками"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":5,"unit":"piece","note":""},{"name":"Африканские баклажаны","quantity":200,"unit":"g","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Тимьян","quantity":3,"unit":"sprig","note":""},{"name":"Атьеке или рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте лук, помидоры, баклажаны и перец крупными кусками.\nСложите курицу и все овощи в горшок, добавьте чеснок, имбирь, тимьян, лавровый лист, соль и перец.\nПоложите сверху целый скотч-боннет, не разрезая.\nЗакройте крышкой и запечатайте стык полоской теста из муки с водой или обмотайте фольгой.\nПоставьте на самый слабый огонь или в духовку на 160 °C на час двадцать.\nКаждые пятнадцать минут встряхивайте горшок, держа крышку. Не открывайте ни разу.\nСнимите печать, выньте перец и подавайте с атьеке или рисом.","source":"UniTools"},{"id":"ut-matapa","name":"Матапа","country":"Мозамбик","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":115,"baseServings":5,"portionNutrition":{"k":580,"p":32,"f":34,"c":40},"details":[{"name":"Листья маниока или шпинат","quantity":700,"unit":"g","note":""},{"name":"Арахис","quantity":200,"unit":"g","note":"молотый"},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Креветки","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Перец пири-пири","quantity":2,"unit":"piece","note":""},{"name":"Рис","quantity":350,"unit":"g","note":"к подаче"},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте листья, снимите жёсткие черешки и растолките в ступке до пасты.\nОбжарьте лук и чеснок в масле до мягкости, добавьте помидоры.\nВмешайте листья, залейте водой вровень и варите сорок минут на слабом огне.\nВсыпьте молотый арахис и варите ещё двадцать минут, помешивая.\nДобавьте креветки, целый пири-пири и соль и потушите десять минут.\nВлейте кокосовое молоко и прогрейте пять минут, не давая закипеть.\nПодавайте с рисом или кашей шима из кукурузной муки.","source":"UniTools"},{"id":"ut-frango-piri-piri","name":"Курица пири-пири","country":"Мозамбик","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":620,"p":52,"f":42,"c":8},"details":[{"name":"Курица","quantity":1.6,"unit":"kg","note":""},{"name":"Перец пири-пири","quantity":8,"unit":"piece","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Паприка копчёная","quantity":1,"unit":"tbsp","note":""},{"name":"Оливковое масло","quantity":100,"unit":"ml","note":""},{"name":"Уксус","quantity":3,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Орегано","quantity":1,"unit":"tbsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разрежьте курицу вдоль хребта, разверните и придавите, чтобы она легла плоско.\nПробейте в блендере чили, чеснок, сок двух лимонов, паприку, уксус, орегано, масло и соль.\nОтлейте половину соуса в отдельную миску — она пойдёт на смазывание.\nОбмажьте курицу оставшимся соусом, втирая под кожу, и уберите в холод на ночь.\nРазожгите угли и разгребите к краям — жар должен быть непрямым.\nЖарьте курицу кожей вверх тридцать минут, потом переверните и держите ещё пятнадцать.\nПоследние пять минут смазывайте отложенным соусом с растопленным маслом. Подавайте с лимоном.","source":"UniTools"},{"id":"ut-romazava","name":"Ромазава","country":"Мадагаскар","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":100,"baseServings":5,"portionNutrition":{"k":520,"p":42,"f":16,"c":52},"details":[{"name":"Говядина","quantity":500,"unit":"g","note":"кубиками"},{"name":"Свинина","quantity":300,"unit":"g","note":"кубиками"},{"name":"Брэд-мафана или кресс-салат","quantity":300,"unit":"g","note":""},{"name":"Шпинат","quantity":300,"unit":"g","note":""},{"name":"Листовая горчица","quantity":200,"unit":"g","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук, чеснок и имбирь в масле до мягкости, пять минут.\nДобавьте оба вида мяса и помидоры и прогрейте, не добиваясь корки.\nЗалейте полутора литрами воды, посолите и варите час на слабом огне.\nПромойте зелень и крупно нарежьте, убрав жёсткие стебли.\nЗаложите листовую горчицу и шпинат и варите десять минут.\nДобавьте мафану на последние пять минут — от долгой варки её эффект слабеет.\nПодавайте в глубоких тарелках с большой порцией отварного риса.","source":"UniTools"},{"id":"ut-ravitoto","name":"Равитуту","country":"Мадагаскар","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":115,"baseServings":5,"portionNutrition":{"k":700,"p":32,"f":48,"c":38},"details":[{"name":"Толчёные листья маниока","quantity":700,"unit":"g","note":""},{"name":"Свиная грудинка","quantity":700,"unit":"g","note":"крупными кусками"},{"name":"Кокосовое молоко","quantity":300,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте свинину крупными кусками до румяности со всех сторон.\nДобавьте лук, чеснок и имбирь и жарьте до мягкости.\nВмешайте листья маниока, залейте водой вровень и посолите.\nТушите под крышкой час на слабом огне, помешивая каждые пятнадцать минут.\nСнимите крышку и выпарите лишнюю жидкость — блюдо должно быть густым, а не жидким.\nВлейте кокосовое молоко и прогрейте пять минут не кипятя. Подавайте с рисом.","source":"UniTools"},{"id":"ut-baleadas","name":"Балеадас","country":"Гондурас","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":60,"baseServings":4,"portionNutrition":{"k":520,"p":18,"f":24,"c":58},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Смалец или растительный жир","quantity":60,"unit":"g","note":""},{"name":"Вода горячая","quantity":220,"unit":"ml","note":""},{"name":"Красная фасоль","quantity":400,"unit":"g","note":"варёная"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Густая сметана","quantity":200,"unit":"ml","note":""},{"name":"Солёный белый сыр","quantity":150,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":"по желанию"},{"name":"Авокадо","quantity":1,"unit":"piece","note":"по желанию"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разотрите муку с жиром и солью в крошку, влейте горячую воду и замесите мягкое тесто.\nРазделите на восемь шаров, смажьте маслом и дайте отдохнуть двадцать минут под полотенцем.\nОбжарьте лук в масле, добавьте варёную фасоль с частью отвара и разомните в гладкое пюре.\nЖарьте пюре на среднем огне десять минут, пока оно не станет держать форму на ложке.\nРаскатайте шары в тонкие круги двадцати сантиметров.\nЖарьте на сухой раскалённой сковороде по минуте с каждой стороны — до пятен, но без сухости.\nНамажьте фасоль на половину лепёшки, добавьте сметану и сыр, сложите пополам и подавайте горячей.","source":"UniTools"},{"id":"ut-sopa-de-caracol","name":"Суп из ракушек","country":"Гондурас","category":"soup","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":95,"baseServings":5,"portionNutrition":{"k":560,"p":34,"f":28,"c":46},"details":[{"name":"Мясо конха или кальмар","quantity":700,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":600,"unit":"ml","note":""},{"name":"Юкка (маниок)","quantity":400,"unit":"g","note":""},{"name":"Подорожник зелёный","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Ачиоте","quantity":1,"unit":"tsp","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отбейте мясо конха молотком и нарежьте небольшими кусками. Сбрызните лаймом.\nОбжарьте лук, чеснок и перец в масле с ачиоте до мягкости.\nВлейте половину кокосового молока, разбавленного водой, и доведите до кипения.\nОпустите мясо и варите на слабом огне сорок минут до мягкости.\nДобавьте юкку, подорожник и морковь крупными кусками и варите двадцать минут.\nВлейте оставшееся густое кокосовое молоко и прогрейте пять минут не кипятя.\nПосыпьте кинзой и подавайте с лаймом и жареным подорожником.","source":"UniTools"},{"id":"ut-gallo-pinto-nicaraguense","name":"Никарагуанский гальо-пинто","country":"Никарагуа","category":"breakfast","diets":["vegetarian","vegan","gluten-free"],"slots":["breakfast"],"time":35,"baseServings":4,"portionNutrition":{"k":480,"p":18,"f":14,"c":72},"details":[{"name":"Варёный рис","quantity":600,"unit":"g","note":"вчерашний, холодный"},{"name":"Красная фасоль","quantity":400,"unit":"g","note":"варёная, с отваром"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Кинза","quantity":20,"unit":"g","note":""},{"name":"Сыр куахада","quantity":150,"unit":"g","note":"к подаче"},{"name":"Подорожник","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук, чеснок и перец в масле до мягкости, пять минут.\nДобавьте фасоль с половником её отвара и прогрейте три минуты.\nВсыпьте холодный рис и перемешайте, разбивая комки лопаткой.\nЖарьте на сильном огне восемь минут, не перемешивая последние три — снизу должна образоваться корочка.\nПосолите, поперчите и вмешайте кинзу.\nПодавайте с жареным подорожником, сыром куахада и яичницей.","source":"UniTools"},{"id":"ut-nacatamal","name":"Накатамаль","country":"Никарагуа","category":"breakfast","diets":[],"slots":["breakfast"],"time":270,"baseServings":8,"portionNutrition":{"k":720,"p":30,"f":40,"c":64},"details":[{"name":"Кукурузная мука масека","quantity":800,"unit":"g","note":""},{"name":"Свинина","quantity":1,"unit":"kg","note":"крупными кусками"},{"name":"Смалец","quantity":250,"unit":"g","note":""},{"name":"Рис","quantity":150,"unit":"g","note":"замоченный"},{"name":"Картофель","quantity":500,"unit":"g","note":"кружками"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Ачиоте","quantity":2,"unit":"tbsp","note":""},{"name":"Кислый апельсин или лайм","quantity":3,"unit":"piece","note":""},{"name":"Мята свежая","quantity":20,"unit":"g","note":""},{"name":"Оливки","quantity":16,"unit":"piece","note":""},{"name":"Банановые листья","quantity":16,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте свинину в соке кислых апельсинов, ачиоте, чесноке, соли и перце на ночь.\nЗамочите рис на два часа и слейте воду.\nРазведите масеку тёплой водой, добавьте растопленный смалец, ачиоте и соль и вымешивайте пятнадцать минут до гладкости.\nПрогрейте банановые листья над огнём, чтобы они стали гибкими.\nНа лист выложите большую ложку теста, сверху свинину, рис, кружки картофеля, лук, перец, помидор, оливку и лист мяты.\nЗаверните в два листа плотным свёртком и перевяжите бечёвкой крест-накрест.\nВарите в большой кастрюле с водой три часа, подливая кипяток по мере выкипания.","source":"UniTools"},{"id":"ut-sancocho-panameno","name":"Панамский санкочо","country":"Панама","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":115,"baseServings":6,"portionNutrition":{"k":520,"p":40,"f":14,"c":62},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"домашняя, кусками"},{"name":"Ньяме (ямс)","quantity":800,"unit":"g","note":""},{"name":"Кулантро или кинза","quantity":40,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Кукуруза","quantity":2,"unit":"piece","note":""},{"name":"Орегано сушёный","quantity":1,"unit":"tbsp","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Рис","quantity":350,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите курицу солью, чесноком, орегано и соком лайма и оставьте на двадцать минут.\nЗалейте курицу тремя литрами холодной воды, доведите до кипения и снимите пену.\nДобавьте лук и половину кулантро и варите час на слабом огне.\nОчистите ньяме, нарежьте крупными кусками и заложите в кастрюлю вместе с кукурузой.\nВарите двадцать пять минут, пока ньяме не станет мягким.\nРазомните пару кусков ньяме прямо в бульоне, чтобы суп загустел.\nВмешайте оставшийся кулантро, посолите и подавайте с отдельной тарелкой белого риса.","source":"UniTools"},{"id":"ut-ropa-vieja-panamena","name":"Панамская ропа вьеха","country":"Панама","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":145,"baseServings":5,"portionNutrition":{"k":580,"p":46,"f":24,"c":46},"details":[{"name":"Говяжья пашина","quantity":900,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":500,"unit":"g","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Зелёные оливки","quantity":80,"unit":"g","note":""},{"name":"Каперсы","quantity":2,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Орегано","quantity":1,"unit":"tsp","note":""},{"name":"Кулантро или кинза","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Рис","quantity":350,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите мясо целым куском в подсоленной воде с лавровым листом полтора часа. Бульон сохраните.\nОстудите мясо и разберите руками на длинные волокна вдоль.\nОбжарьте лук, перец и чеснок в масле до мягкости, восемь минут.\nДобавьте помидоры, томатную пасту, зиру и орегано и тушите десять минут до густоты.\nВмешайте мясо, оливки и каперсы и тушите двадцать минут, подливая бульон по столовой ложке.\nВыпарите лишнюю жидкость на открытом огне — соус должен обволакивать волокна.\nПосыпьте кулантро и подавайте с рисом и жареным подорожником.","source":"UniTools"},{"id":"ut-sopa-paraguaya","name":"Парагвайский суп","country":"Парагвай","category":"side","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":80,"baseServings":8,"portionNutrition":{"k":540,"p":22,"f":32,"c":42},"details":[{"name":"Кукурузная мука","quantity":400,"unit":"g","note":""},{"name":"Парагвайский сыр или брынза","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Молоко","quantity":400,"unit":"ml","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":""},{"name":"Смалец или сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Кукуруза","quantity":200,"unit":"g","note":"зёрна"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте лук тонко и томите в жире на слабом огне двадцать минут до полной мягкости и сладости.\nЗалейте лук молоком, снимите с огня и остудите до тёплого.\nРазотрите сыр и смешайте с кукурузной мукой и зёрнами кукурузы.\nВмешайте луково-молочную смесь и желтки, посолите с осторожностью — сыр уже солёный.\nВзбейте белки до устойчивых пиков и вмешайте лопаткой в три приёма.\nВыложите в смазанную форму слоем в четыре сантиметра.\nПеките при 190 °C пятьдесят минут до тёмно-золотой корки. Дайте постоять двадцать минут перед нарезкой.","source":"UniTools"},{"id":"ut-chipa","name":"Чипа","country":"Парагвай","category":"bread","diets":["vegetarian","gluten-free"],"slots":["breakfast","snack"],"time":50,"baseServings":8,"portionNutrition":{"k":420,"p":14,"f":22,"c":44},"details":[{"name":"Маниоковый крахмал","quantity":500,"unit":"g","note":""},{"name":"Парагвайский сыр или брынза","quantity":400,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Смалец или сливочное масло","quantity":120,"unit":"g","note":""},{"name":"Молоко","quantity":120,"unit":"ml","note":""},{"name":"Анис","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Разогрейте духовку до 220 °C заранее — тесто должно попасть в горячую.\nРазотрите размягчённый жир с яйцами и солью до однородности.\nВмешайте тёртый сыр и анис, растирая массу руками, пока сыр не разойдётся равномерно.\nВсыпайте крахмал понемногу, подливая молоко, пока тесто не станет плотным и пластичным.\nСкатайте колбаски и соедините концы в кольца диаметром восемь сантиметров.\nПеките двадцать пять минут до румяных пятен. Подавайте тёплыми.","source":"UniTools"},{"id":"ut-flia","name":"Флия","country":"Косово","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":120,"baseServings":8,"portionNutrition":{"k":480,"p":10,"f":26,"c":52},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Вода","quantity":900,"unit":"ml","note":""},{"name":"Сметана","quantity":400,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Йогурт","quantity":300,"unit":"ml","note":"к подаче"},{"name":"Мёд","quantity":100,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":2,"unit":"tsp","note":""}],"steps":"Взбейте муку с водой и солью в жидкое тесто без комков — гуще блинного, но текучее.\nРазведите сметану холодной водой до консистенции жидких сливок и посолите.\nСмажьте круглую форму маслом и налейте тесто полосами от центра к краям, как спицы колеса.\nПоставьте под верхний гриль на четыре минуты, пока слой не схватится и не пойдёт пятнами.\nСбрызните разведённой сметаной и налейте следующий слой в промежутки между предыдущими полосами.\nПовторяйте, чередуя направление полос, пока тесто не кончится — обычно двадцать-двадцать пять слоёв.\nПолейте растопленным маслом, дайте постоять десять минут и подавайте с йогуртом или мёдом.","source":"UniTools"},{"id":"ut-tave-elbasani","name":"Таве Эльбасани","country":"Косово","category":"main","diets":[],"slots":["lunch","dinner"],"time":125,"baseServings":6,"portionNutrition":{"k":680,"p":44,"f":38,"c":40},"details":[{"name":"Ягнёнок","quantity":1,"unit":"kg","note":"кусками"},{"name":"Рис","quantity":200,"unit":"g","note":""},{"name":"Густой йогурт","quantity":700,"unit":"ml","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Мука","quantity":60,"unit":"g","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Орегано сушёный","quantity":1,"unit":"tbsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите мясо солью, перцем, чесноком и орегано и запекайте при 190 °C сорок минут.\nОтварите рис до полуготовности, семь минут, и откиньте на дуршлаг.\nРастопите масло, вмешайте муку и прогрейте две минуты до орехового запаха.\nВзбейте йогурт с яйцами и солью до полной гладкости и влейте мучную смесь.\nВыложите рис ровным слоем в глиняную форму, сверху мясо с его соками.\nЗалейте йогуртовой смесью так, чтобы она покрыла всё на палец.\nЗапекайте при 180 °C пятьдесят минут, пока верх не подрумянится, а середина не будет чуть дрожать.","source":"UniTools"},{"id":"ut-njeguski-steak","name":"Негушский стейк","country":"Черногория","category":"main","diets":[],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":820,"p":54,"f":48,"c":44},"details":[{"name":"Свиная корейка","quantity":800,"unit":"g","note":"толстыми кусками"},{"name":"Негушский пршут","quantity":150,"unit":"g","note":""},{"name":"Негушский сыр или качкавал","quantity":200,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Мука","quantity":100,"unit":"g","note":""},{"name":"Панировочные сухари","quantity":250,"unit":"g","note":""},{"name":"Масло для жарки","quantity":300,"unit":"ml","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":"к подаче"},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разрежьте каждый кусок вдоль, не доходя до противоположного края, и раскройте книжкой.\nСлегка отбейте раскрытое мясо через плёнку, посолите и поперчите изнутри.\nВложите пласт пршута и ломоть сыра, закройте и прижмите края.\nОбваляйте в муке, яйце и сухарях, затем повторите яйцо и сухари ещё раз.\nУберите в холодильник на двадцать минут — панировка схватится и не слезет при жарке.\nЖарьте в масле на среднем огне по шесть минут с каждой стороны до тёмно-золотого цвета.\nВыложите на решётку, дайте отдохнуть пять минут и подавайте с жареным картофелем и лимоном.","source":"UniTools"},{"id":"ut-kacamak","name":"Качамак","country":"Черногория","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":720,"p":24,"f":44,"c":58},"details":[{"name":"Кукурузная мука","quantity":300,"unit":"g","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Молодой солёный сыр","quantity":300,"unit":"g","note":""},{"name":"Каймак","quantity":200,"unit":"g","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Молоко","quantity":200,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите нарезанный картофель в подсоленной воде двадцать минут до полной мягкости.\nНе сливая воду, всыпайте кукурузную муку тонкой струйкой, непрерывно размешивая.\nВарите на слабом огне пятнадцать минут, помешивая деревянной лопаткой — каша быстро пригорает.\nРазомните картофель прямо в кастрюле вместе с кашей до однородности.\nВмешайте раскрошенный сыр и каймак, подливая горячее молоко, и работайте лопаткой пять минут.\nВыложите в миску, сделайте углубление и залейте растопленным маслом. Подавайте сразу.","source":"UniTools"},{"id":"ut-ema-datshi","name":"Эма датши","country":"Бутан","category":"main","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":380,"p":16,"f":24,"c":26},"details":[{"name":"Зелёный чили","quantity":400,"unit":"g","note":"крупный, не жгучий сорт"},{"name":"Свежий сыр датши или фета","quantity":300,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Помидор","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":30,"unit":"g","note":""},{"name":"Красный рис","quantity":350,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разрежьте чили вдоль на четвертинки. Семена оставляют — в Бутане их не вычищают.\nСложите чили, нарезанный лук, чеснок и помидор в кастрюлю и залейте водой вровень.\nДоведите до кипения и варите десять минут, пока чили не станет мягким.\nРаскрошите сыр в кастрюлю, убавьте огонь и не мешайте две минуты — он должен начать расходиться сам.\nПеремешайте до кремового соуса, добавьте масло и посолите с осторожностью — сыр солёный.\nПодавайте с красным рисом, который в Бутане варят до состояния чуть липкого.","source":"UniTools"},{"id":"ut-jasha-maroo","name":"Джаша мару","country":"Бутан","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":520,"p":42,"f":22,"c":40},"details":[{"name":"Курица","quantity":1,"unit":"kg","note":"рубить с костями"},{"name":"Имбирь","quantity":60,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Зелёный чили","quantity":6,"unit":"piece","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Красный рис","quantity":350,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разрубите курицу на куски размером со спичечный коробок, вместе с костями.\nРазотрите имбирь и чеснок в грубую пасту.\nОбжарьте лук в масле до мягкости, добавьте пасту и прогрейте две минуты.\nДобавьте курицу и жарьте пять минут, пока она не побелеет со всех сторон.\nПоложите помидоры и чили, залейте водой на палец выше и посолите.\nВарите двадцать минут на слабом огне — бульон должен остаться жидким.\nВмешайте кинзу и подавайте в глубоких мисках с красным рисом.","source":"UniTools"},{"id":"ut-mas-huni","name":"Мас хуни","country":"Мальдивы","category":"breakfast","diets":["pescatarian"],"slots":["breakfast"],"time":35,"baseServings":4,"portionNutrition":{"k":520,"p":34,"f":20,"c":52},"details":[{"name":"Тунец копчёный или консервированный","quantity":400,"unit":"g","note":""},{"name":"Кокос тёртый","quantity":200,"unit":"g","note":"свежий"},{"name":"Лук красный","quantity":2,"unit":"piece","note":""},{"name":"Перец чили","quantity":3,"unit":"piece","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Листья карри","quantity":10,"unit":"piece","note":""},{"name":"Мука для роши","quantity":300,"unit":"g","note":""},{"name":"Вода","quantity":160,"unit":"ml","note":""},{"name":"Растительное масло","quantity":30,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, воды, ложки масла и соли и оставьте на двадцать минут.\nНарежьте лук, чили и листья карри как можно мельче.\nПеретрите лук, чили и соль руками, пока лук не пустит сок и не станет мягким.\nДобавьте тёртый кокос и разобранный тунец и продолжайте перетирать пальцами до однородности.\nВыжмите сок лаймов и перемешайте ещё раз. Попробуйте и поправьте на соль и кислоту.\nРаскатайте тесто в тонкие лепёшки и жарьте на сухой сковороде по минуте с каждой стороны.\nПодавайте мас хуни с горячими роши и чёрным чаем.","source":"UniTools"},{"id":"ut-garudhiya","name":"Гарудия","country":"Мальдивы","category":"soup","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":420,"p":44,"f":6,"c":46},"details":[{"name":"Свежий тунец","quantity":800,"unit":"g","note":"крупными кусками"},{"name":"Листья карри","quantity":10,"unit":"piece","note":""},{"name":"Лист пандана","quantity":1,"unit":"piece","note":""},{"name":"Лук красный","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Перец чили","quantity":4,"unit":"piece","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте тунца крупными кусками и промойте под холодной водой.\nЗалейте полутора литрами холодной воды, посолите и доведите до кипения.\nСнимайте пену первые пять минут — от этого зависит прозрачность бульона.\nПоложите листья карри и пандан и варите двадцать минут на самом слабом огне.\nВыньте листья, попробуйте на соль и снимите с огня.\nПодавайте с рисом, нарезанным луком, чили и лаймом — каждый добавляет их сам в тарелку.","source":"UniTools"},{"id":"ut-matoke","name":"Матоке","country":"Уганда","category":"side","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":110,"baseServings":5,"portionNutrition":{"k":340,"p":6,"f":10,"c":62},"details":[{"name":"Зелёные бананы матоке","quantity":12,"unit":"piece","note":""},{"name":"Банановые листья","quantity":6,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Арахисовая паста","quantity":100,"unit":"g","note":"для соуса"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите бананы, смазав руки маслом — их сок оставляет на коже чёрные пятна.\nПрогрейте банановые листья над огнём десять секунд, чтобы они стали гибкими.\nВыстелите дно кастрюли черешками листьев — они не дадут свёртку касаться воды.\nЗаверните бананы в листья плотным свёртком и уложите на эту подставку.\nВлейте воды на два пальца, накройте и держите на пару час двадцать, подливая кипяток.\nНе разворачивая, разомните свёрток через листья до однородного пюре и верните на пар на десять минут.\nПодавайте с арахисовым соусом или тушёной говядиной, разложив прямо на листе.","source":"UniTools"},{"id":"ut-rolex-uganda","name":"Ролекс","country":"Уганда","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":65,"baseServings":4,"portionNutrition":{"k":560,"p":20,"f":30,"c":52},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Вода тёплая","quantity":240,"unit":"ml","note":""},{"name":"Яйца","quantity":8,"unit":"piece","note":""},{"name":"Капуста","quantity":200,"unit":"g","note":"тонкой соломкой"},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите мягкое тесто из муки, тёплой воды, ложки масла и соли и оставьте на двадцать минут.\nРаскатайте шар тонко, смажьте маслом, сверните жгутом, закрутите улиткой и раскатайте снова.\nЖарьте чапати на среднем огне по полторы минуты с каждой стороны и держите под полотенцем.\nНашинкуйте капусту, морковь, лук, помидоры и чили как можно тоньше.\nВзбейте яйца с овощами, солью и перцем — овощи должны быть внутри омлета, а не сверху.\nВылейте порцию яиц на сковороду, дайте схватиться и положите сверху чапати, прижав лопаткой.\nПереверните вместе, снимите на доску омлетом вверх и сверните плотным рулетом.","source":"UniTools"},{"id":"ut-sadza-ne-nyama","name":"Садза с мясом","country":"Зимбабве","category":"main","diets":[],"slots":["lunch","dinner"],"time":125,"baseServings":5,"portionNutrition":{"k":640,"p":42,"f":24,"c":66},"details":[{"name":"Кукурузная мука","quantity":500,"unit":"g","note":""},{"name":"Говядина","quantity":800,"unit":"g","note":"с косточкой, кусками"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Листовая капуста","quantity":400,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Арахисовая паста","quantity":2,"unit":"tbsp","note":"для зелени"},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мясо до румяности, добавьте лук и чеснок и жарьте до мягкости.\nПоложите помидоры, залейте водой вровень, посолите и тушите час двадцать под крышкой.\nНарежьте зелень тонкой соломкой и потушите с помидором и арахисовой пастой пятнадцать минут.\nРазведите четверть кукурузной муки холодной водой и влейте в литр кипятка, размешивая.\nВарите жидкую кашу десять минут, помешивая деревянной лопаткой.\nВсыпайте оставшуюся муку понемногу, вымешивая с усилием, пятнадцать минут до плотной массы.\nВыложите садзу мокрой ложкой на тарелки и подавайте с мясом и зеленью.","source":"UniTools"},{"id":"ut-muriwo-unedovi","name":"Зелень в арахисовом соусе","country":"Зимбабве","category":"side","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":40,"baseServings":4,"portionNutrition":{"k":320,"p":12,"f":24,"c":18},"details":[{"name":"Листовая капуста","quantity":700,"unit":"g","note":"тонкой соломкой"},{"name":"Арахисовая паста","quantity":150,"unit":"g","note":"несладкая"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Снимите с листьев жёсткие черешки, сверните листья рулоном и нарежьте тонкой соломкой.\nОбжарьте лук и чеснок в масле до мягкости, пять минут.\nДобавьте нарезанные помидоры и тушите семь минут, пока они не разойдутся в пасту.\nРазведите арахисовую пасту стаканом горячей воды до однородности без комков.\nВмешайте зелень и разведённую пасту, посолите и тушите под крышкой двенадцать минут.\nСнимите крышку и выпарите лишнюю жидкость — соус должен держаться на листьях.","source":"UniTools"},{"id":"ut-poulet-moambe","name":"Курица моамбе","country":"ДР Конго","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":95,"baseServings":5,"portionNutrition":{"k":720,"p":44,"f":42,"c":44},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Мякоть пальмовых плодов","quantity":800,"unit":"g","note":"консервированная"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Перец пили-пили","quantity":2,"unit":"piece","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Баклажаны","quantity":2,"unit":"piece","note":""},{"name":"Шпинат","quantity":200,"unit":"g","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите курицу солью, перцем, чесноком и соком лимона и оставьте на двадцать минут.\nОбжарьте курицу в масле до румяной корки со всех сторон и выньте.\nОбжарьте лук с имбирём до мягкости, добавьте пальмовую мякоть и разведите стаканом воды.\nПроварите соус двадцать минут, помешивая, пока сверху не выступит слой красного масла.\nВерните курицу, добавьте баклажаны и целый пили-пили и тушите тридцать минут.\nВмешайте шпинат на последние пять минут и выньте перец.\nПодавайте с рисом или с кашей фуфу из маниока.","source":"UniTools"},{"id":"ut-liboke-de-poisson","name":"Либоке с рыбой","country":"ДР Конго","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":65,"baseServings":4,"portionNutrition":{"k":480,"p":44,"f":12,"c":46},"details":[{"name":"Тиляпия или карп","quantity":4,"unit":"piece","note":"целая, потрошёная"},{"name":"Банановые листья","quantity":12,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Перец пили-пили","quantity":2,"unit":"piece","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Маниок","quantity":500,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Сделайте на рыбе надрезы по бокам и натрите солью, перцем и соком лимона.\nРазотрите чеснок, имбирь и чили в пасту и вотрите в надрезы и брюшко.\nПрогрейте банановые листья над огнём, чтобы они стали гибкими и не ломались.\nРазложите на листе кружки помидора и лука, сверху рыбу, снова помидоры и зелёный лук.\nЗаверните в три листа плотным свёртком и перевяжите полоской того же листа.\nПоложите свёртки на угли и запекайте по пятнадцать минут с каждой стороны.\nПодавайте прямо в листе, с варёным маниоком или рисом.","source":"UniTools"},{"id":"ut-tigadegena","name":"Тигадегена","country":"Мали","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":115,"baseServings":6,"portionNutrition":{"k":780,"p":44,"f":44,"c":54},"details":[{"name":"Говядина или баранина","quantity":900,"unit":"g","note":"кусками"},{"name":"Арахисовая паста","quantity":350,"unit":"g","note":"несладкая"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Капуста","quantity":300,"unit":"g","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Баклажаны","quantity":2,"unit":"piece","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Рис","quantity":450,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мясо в масле до румяной корки, добавьте лук и жарьте до мягкости.\nВмешайте томатную пасту и прогрейте пять минут, пока она не потемнеет.\nЗалейте полутора литрами воды, посолите и варите сорок минут.\nРазведите арахисовую пасту двумя половниками бульона до однородности без комков.\nВлейте пасту в кастрюлю тонкой струйкой, непрерывно размешивая.\nДобавьте овощи крупными кусками и целый чили и тушите тридцать минут, помешивая.\nДождитесь, пока сверху выступит арахисовое масло, выньте перец и подавайте с рисом.","source":"UniTools"},{"id":"ut-capitaine-braise","name":"Капитан на углях","country":"Мали","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":105,"baseServings":4,"portionNutrition":{"k":620,"p":56,"f":26,"c":42},"details":[{"name":"Нильский окунь или судак","quantity":2,"unit":"kg","note":"целый, потрошёный"},{"name":"Лук","quantity":5,"unit":"piece","note":""},{"name":"Горчица","quantity":2,"unit":"tbsp","note":""},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Перец чили","quantity":2,"unit":"piece","note":""},{"name":"Бульонный кубик","quantity":1,"unit":"piece","note":""},{"name":"Подорожник","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Сделайте на рыбе глубокие надрезы до кости с обеих сторон, через каждые три сантиметра.\nРазотрите чеснок, имбирь, чили, бульонный кубик, сок лимона и масло в пасту и вотрите в надрезы.\nОставьте рыбу мариноваться час в холоде.\nНарежьте лук перьями и томите в масле на слабом огне тридцать минут до карамельного цвета.\nВмешайте в лук горчицу и сок лимона, посолите — это соус йет.\nЖарьте рыбу на углях с непрямым жаром по двадцать минут с каждой стороны.\nОбжарьте подорожник и подавайте рыбу под луковым соусом, с бананом и лимоном.","source":"UniTools"},{"id":"ut-osso-buco-alla-milanese","name":"Оссобуко по-милански","country":"Италия","category":"main","diets":[],"slots":["lunch","dinner"],"time":160,"baseServings":4,"portionNutrition":{"k":620,"p":48,"f":32,"c":18},"details":[{"name":"Телячья голяшка","quantity":4,"unit":"piece","note":"поперечными кусками по 4 см"},{"name":"Мука","quantity":60,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Сельдерей стеблевой","quantity":2,"unit":"piece","note":""},{"name":"Белое сухое вино","quantity":250,"unit":"ml","note":""},{"name":"Мясной бульон","quantity":500,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":2,"unit":"clove","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обвяжите каждый кусок кулинарной нитью по окружности, чтобы мясо не отошло от кости.\nНадрежьте плёнку по краю в двух-трёх местах — иначе куски свернутся при обжарке.\nОбваляйте в муке и обжарьте в масле до тёмной корки с обеих сторон, по четыре минуты.\nВыньте мясо, обжарьте мелко нарезанные лук, морковь и сельдерей до мягкости.\nВлейте вино и выпарите наполовину, соскребая со дна пригоревшее.\nВерните мясо, влейте бульон до половины высоты кусков и тушите под крышкой два часа на слабом огне.\nСмешайте рубленую цедру, чеснок и петрушку и посыпьте оссобуко перед подачей.","source":"UniTools"},{"id":"ut-melanzane-alla-parmigiana","name":"Пармиджана из баклажанов","country":"Италия","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":520,"p":24,"f":36,"c":24},"details":[{"name":"Баклажаны","quantity":1.5,"unit":"kg","note":""},{"name":"Томаты в собственном соку","quantity":800,"unit":"g","note":""},{"name":"Моцарелла","quantity":400,"unit":"g","note":""},{"name":"Пармезан","quantity":150,"unit":"g","note":""},{"name":"Базилик","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Оливковое масло","quantity":200,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте баклажаны вдоль ломтями в полсантиметра, посолите и оставьте под грузом на полчаса.\nОбсушите ломти насухо бумагой — на мокрых масло будет брызгать, а корка не образуется.\nОбжарьте баклажаны партиями в оливковом масле по две минуты с каждой стороны и выложите на решётку.\nОбжарьте чеснок, добавьте томаты и варите соус двадцать минут до густоты, посолив в конце.\nНарежьте моцареллу и оставьте на бумаге стекать десять минут.\nСобирайте слоями: соус, баклажаны, моцарелла, пармезан, базилик — и так четыре раза.\nЗапекайте при 190 °C сорок минут и дайте постоять двадцать перед нарезкой.","source":"UniTools"},{"id":"ut-hong-shao-rou","name":"Хун шао жоу","country":"Китай","category":"main","diets":[],"slots":["lunch","dinner"],"time":110,"baseServings":4,"portionNutrition":{"k":780,"p":32,"f":56,"c":32},"details":[{"name":"Свиная грудинка","quantity":900,"unit":"g","note":"кубиками 3 см, со шкурой"},{"name":"Леденцовый сахар","quantity":50,"unit":"g","note":""},{"name":"Светлый соевый соус","quantity":60,"unit":"ml","note":""},{"name":"Тёмный соевый соус","quantity":1,"unit":"tbsp","note":""},{"name":"Шаосинское вино","quantity":100,"unit":"ml","note":""},{"name":"Имбирь","quantity":40,"unit":"g","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Бадьян","quantity":2,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Растительное масло","quantity":30,"unit":"ml","note":""},{"name":"Рис","quantity":350,"unit":"g","note":"к подаче"}],"steps":"Опустите кубики грудинки в кипяток на две минуты, слейте и промойте холодной водой.\nОбсушите мясо насухо. Мокрое будет брызгать в карамели и остудит её.\nРастопите сахар в масле на среднем огне до янтарного цвета, помешивая — на это уходит три-четыре минуты.\nВсыпьте мясо и переворачивайте две минуты, пока каждый кусок не покроется карамелью.\nВлейте вино, оба соевых соуса, добавьте имбирь, зелёный лук и специи.\nЗалейте горячей водой вровень с мясом и тушите под крышкой час на слабом огне.\nСнимите крышку и выпарите соус на сильном огне до глазури, обливая ею мясо.","source":"UniTools"},{"id":"ut-qingzheng-yu","name":"Рыба на пару по-кантонски","country":"Китай","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":35,"baseServings":4,"portionNutrition":{"k":340,"p":40,"f":18,"c":4},"details":[{"name":"Сибас или дорада","quantity":800,"unit":"g","note":"целая, потрошёная"},{"name":"Имбирь","quantity":60,"unit":"g","note":"тонкой соломкой"},{"name":"Зелёный лук","quantity":6,"unit":"piece","note":""},{"name":"Соевый соус для рыбы на пару","quantity":60,"unit":"ml","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Кинза","quantity":20,"unit":"g","note":""},{"name":"Шаосинское вино","quantity":2,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обсушите рыбу, сделайте два надреза с каждой стороны и натрите солью и вином.\nУложите на блюдо несколько стеблей зелёного лука и поставьте рыбу на них — так пар пойдёт и снизу.\nРазложите половину имбиря в надрезы и в брюшко.\nПоставьте блюдо в кипящую пароварку и готовьте восемь минут на сантиметр толщины.\nСлейте всю жидкость с блюда и выбросьте её — она горькая.\nРазложите сверху оставшийся имбирь, нарезанный соломкой лук и кинзу.\nРаскалите масло до дымка и полейте им зелень, затем влейте соевый соус с сахаром по краю блюда.","source":"UniTools"},{"id":"ut-rogan-josh","name":"Роган джош","country":"Индия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":125,"baseServings":5,"portionNutrition":{"k":720,"p":46,"f":40,"c":44},"details":[{"name":"Баранина на кости","quantity":1,"unit":"kg","note":"кусками"},{"name":"Йогурт","quantity":400,"unit":"ml","note":"взбитый"},{"name":"Кашмирский чили молотый","quantity":3,"unit":"tbsp","note":""},{"name":"Фенхель молотый","quantity":2,"unit":"tbsp","note":""},{"name":"Сухой имбирь молотый","quantity":1,"unit":"tbsp","note":""},{"name":"Асафетида","quantity":1,"unit":"pinch","note":""},{"name":"Чёрный кардамон","quantity":3,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Гвоздика","quantity":5,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":100,"unit":"g","note":""},{"name":"Рис басмати","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Прогрейте в топлёном масле кардамон, корицу и гвоздику до запаха, минуту.\nДобавьте асафетиду и сразу мясо и обжаривайте до румяности, десять минут.\nСнимите с огня, вмешайте кашмирский чили — на огне он горит за секунды и даёт горечь.\nВерните на слабый огонь и вводите взбитый йогурт по половнику, размешивая после каждого.\nВсыпьте фенхель и сухой имбирь, посолите и залейте стаканом горячей воды.\nТушите под крышкой час двадцать на слабом огне, пока мясо не станет отходить от кости.\nСнимите крышку и выпарите соус до состояния, когда сверху выступит масло. Подавайте с рисом.","source":"UniTools"},{"id":"ut-masala-dosa","name":"Масала доса","country":"Индия","category":"breakfast","diets":["vegetarian","vegan","gluten-free"],"slots":["breakfast"],"time":105,"baseServings":6,"portionNutrition":{"k":520,"p":14,"f":18,"c":76},"details":[{"name":"Рис","quantity":300,"unit":"g","note":"замочить на 6 часов"},{"name":"Чечевица урад","quantity":100,"unit":"g","note":"замочить на 6 часов"},{"name":"Семена пажитника","quantity":1,"unit":"tsp","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":"отварной"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Семена горчицы","quantity":1,"unit":"tsp","note":""},{"name":"Листья карри","quantity":12,"unit":"piece","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Зелёный чили","quantity":3,"unit":"piece","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите рис отдельно, а чечевицу с пажитником отдельно, на шесть часов каждое.\nСмелите чечевицу в лёгкую пышную пасту, затем рис — в чуть зернистую, и соедините.\nПосолите, накройте и оставьте в тепле на восемь-двенадцать часов, пока тесто не поднимется и не запахнет кисло.\nПрокалите в масле семена горчицы до треска, добавьте листья карри, лук, чили и имбирь.\nВсыпьте куркуму и размятый картофель, посолите и прогрейте пять минут — это начинка.\nРаскалите плоскую сковороду, протрите луковицей с маслом и вылейте половник теста, размазав спиралью от центра.\nСбрызните маслом по краю и жарьте до румяного низа, две минуты. Выложите начинку и сложите пополам.","source":"UniTools"},{"id":"ut-bouillabaisse","name":"Буйабес","country":"Франция","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":620,"p":52,"f":28,"c":38},"details":[{"name":"Мелкая костистая рыба","quantity":1,"unit":"kg","note":"для бульона"},{"name":"Крупная белая рыба","quantity":1.2,"unit":"kg","note":"три-четыре вида"},{"name":"Фенхель","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Лук-порей","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":500,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Цедра апельсина","quantity":1,"unit":"piece","note":""},{"name":"Картофель","quantity":500,"unit":"g","note":""},{"name":"Оливковое масло","quantity":150,"unit":"ml","note":""},{"name":"Желток","quantity":1,"unit":"piece","note":"для руя"},{"name":"Багет","quantity":1,"unit":"piece","note":"для гренок"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук, порей и фенхель в оливковом масле десять минут до мягкости.\nДобавьте мелкую рыбу целиком, помидоры, чеснок, цедру и шафран и жарьте пять минут.\nЗалейте двумя литрами воды, доведите до кипения и варите сорок минут, не накрывая.\nПротрите всё через сито, вдавливая мякоть, и верните бульон в кастрюлю.\nОтварите картофель в бульоне пятнадцать минут, потом опустите крупную рыбу порядком, начиная с самой плотной.\nВзбейте руй: желток, чеснок, шафран, щепоть кайенского перца и оливковое масло тонкой струйкой.\nПодайте бульон в тарелках с гренками и руем, а рыбу с картофелем — отдельным блюдом.","source":"UniTools"},{"id":"ut-tarte-tatin","name":"Тарт татен","country":"Франция","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":90,"baseServings":8,"portionNutrition":{"k":480,"p":4,"f":24,"c":64},"details":[{"name":"Яблоки плотных кислых сортов","quantity":1.5,"unit":"kg","note":""},{"name":"Сахар","quantity":200,"unit":"g","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":""},{"name":"Слоёное тесто","quantity":350,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Ваниль","quantity":1,"unit":"piece","note":""},{"name":"Сливки","quantity":200,"unit":"ml","note":"к подаче"},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Очистите яблоки, разрежьте пополам, удалите сердцевину и сбрызните лимоном.\nРастопите сахар в чугунной форме на среднем огне до янтарной карамели, не размешивая ложкой.\nСнимите с огня, вмешайте масло кусочками, ваниль и щепоть соли.\nУложите половинки яблок срезом вверх, плотно одна к другой, по кругу.\nГотовьте на плите двадцать минут на среднем огне, пока яблоки не осядут и не пропитаются карамелью.\nНакройте кругом слоёного теста, подвернув края внутрь формы, и проколите в нескольких местах.\nПеките при 200 °C сорок минут, дайте постоять пять и переверните на блюдо одним движением.","source":"UniTools"},{"id":"ut-nikujaga","name":"Никудзяга","country":"Япония","category":"main","diets":[],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":480,"p":24,"f":16,"c":56},"details":[{"name":"Говядина","quantity":300,"unit":"g","note":"очень тонкими ломтями"},{"name":"Картофель","quantity":700,"unit":"g","note":"крупными кусками"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Даси","quantity":400,"unit":"ml","note":""},{"name":"Соевый соус","quantity":60,"unit":"ml","note":""},{"name":"Мирин","quantity":60,"unit":"ml","note":""},{"name":"Саке","quantity":40,"unit":"ml","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Лапша ширатаки","quantity":200,"unit":"g","note":"по желанию"},{"name":"Растительное масло","quantity":20,"unit":"ml","note":""},{"name":"Стручковая фасоль","quantity":100,"unit":"g","note":""}],"steps":"Нарежьте картофель крупными кусками и вымочите десять минут в холодной воде, чтобы ушёл крахмал.\nОбжарьте лук в масле две минуты, добавьте тонко нарезанную говядину и жарьте до потери розового цвета.\nДобавьте картофель и морковь и перемешайте, чтобы они покрылись жиром от мяса.\nВлейте даси, саке и сахар, доведите до кипения и снимите пену.\nНакройте отосибутой или кругом фольги с дырочкой и тушите десять минут на среднем огне.\nВлейте соевый соус и мирин и тушите ещё пятнадцать минут, пока жидкости не останется на дне.\nДобавьте фасоль на последние три минуты, снимите с огня и дайте настояться двадцать минут.","source":"UniTools"},{"id":"ut-chawanmushi","name":"Тяванмуси","country":"Япония","category":"snack","diets":["pescatarian"],"slots":["snack"],"time":40,"baseServings":4,"portionNutrition":{"k":180,"p":18,"f":8,"c":5},"details":[{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Даси","quantity":480,"unit":"ml","note":""},{"name":"Светлый соевый соус","quantity":2,"unit":"tsp","note":""},{"name":"Мирин","quantity":1,"unit":"tsp","note":""},{"name":"Креветки","quantity":8,"unit":"piece","note":""},{"name":"Куриное филе","quantity":100,"unit":"g","note":""},{"name":"Грибы шиитаке","quantity":4,"unit":"piece","note":""},{"name":"Камабоко","quantity":4,"unit":"slice","note":""},{"name":"Мицуба или кинза","quantity":10,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Взбейте яйца палочками, не поднимая пены — движения должны быть режущими, а не круговыми.\nВлейте остывший даси, соевый соус, мирин и соль и размешайте, не взбивая.\nПроцедите смесь через мелкое сито дважды — это единственный способ добиться гладкости.\nРазложите по чашкам креветку, кусочек курицы, гриб и ломтик камабоко.\nЗалейте смесью, снимите пузыри с поверхности ложкой и накройте фольгой.\nГотовьте на слабом пару пятнадцать минут, приоткрыв крышку пароварки на сантиметр.\nПроверьте шпажкой: выступивший сок должен быть прозрачным. Посыпьте зеленью и подавайте горячим.","source":"UniTools"},{"id":"ut-mole-poblano","name":"Моле поблано","country":"Мексика","category":"main","diets":[],"slots":["lunch","dinner"],"time":195,"baseServings":8,"portionNutrition":{"k":780,"p":48,"f":46,"c":40},"details":[{"name":"Курица","quantity":2,"unit":"kg","note":"кусками"},{"name":"Перец анчо","quantity":6,"unit":"piece","note":""},{"name":"Перец пасилья","quantity":4,"unit":"piece","note":""},{"name":"Перец мулато","quantity":4,"unit":"piece","note":""},{"name":"Миндаль","quantity":80,"unit":"g","note":""},{"name":"Арахис","quantity":60,"unit":"g","note":""},{"name":"Кунжут","quantity":60,"unit":"g","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Томатильо","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Гвоздика","quantity":4,"unit":"piece","note":""},{"name":"Тёмный шоколад","quantity":60,"unit":"g","note":""},{"name":"Чёрствый хлеб","quantity":2,"unit":"slice","note":""},{"name":"Смалец","quantity":120,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу с луковицей и чесноком сорок минут. Бульон процедите и сохраните.\nОчистите перцы от семян и обжарьте на сухой сковороде по десять секунд с каждой стороны, не давая почернеть.\nЗалейте перцы кипятком на двадцать минут, чтобы размякли.\nОбжарьте по очереди миндаль, арахис, кунжут, изюм и хлеб в смальце, каждый отдельно.\nОбожгите помидоры, томатильо и чеснок на сухой сковороде до чёрных пятен.\nПробейте всё в блендере с бульоном партиями и протрите через сито дважды.\nВарите соус час на слабом огне, помешивая, вмешайте шоколад и соль, опустите курицу и прогрейте.","source":"UniTools"},{"id":"ut-cochinita-pibil","name":"Кочинита пибиль","country":"Мексика","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":275,"baseServings":8,"portionNutrition":{"k":680,"p":46,"f":38,"c":36},"details":[{"name":"Свиная лопатка","quantity":2.5,"unit":"kg","note":"крупными кусками"},{"name":"Паста ачиоте (рекадо рохо)","quantity":100,"unit":"g","note":""},{"name":"Апельсины","quantity":4,"unit":"piece","note":""},{"name":"Грейпфрут","quantity":2,"unit":"piece","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Орегано мексиканский","quantity":1,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Банановые листья","quantity":6,"unit":"piece","note":""},{"name":"Лук красный","quantity":3,"unit":"piece","note":"для маринования"},{"name":"Перец хабанеро","quantity":2,"unit":"piece","note":""},{"name":"Кукурузные тортильи","quantity":16,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разведите пасту ачиоте соком двух апельсинов, грейпфрута и лайма до жидкой кашицы.\nДобавьте растёртый чеснок, орегано, зиру, соль и перец и перемешайте до однородности.\nЗалейте свинину маринадом, перемешайте руками и уберите в холод на ночь.\nПрогрейте банановые листья над огнём и выстелите ими глубокую форму внахлёст, с запасом по краям.\nВыложите мясо с маринадом, заверните листья сверху и затяните форму фольгой в два слоя.\nЗапекайте при 150 °C четыре часа, не открывая.\nЗамаринуйте нарезанный красный лук с хабанеро в соке оставшихся апельсинов. Разберите мясо на волокна и подавайте с тортильями.","source":"UniTools"},{"id":"ut-iskender-kebab","name":"Искендер-кебаб","country":"Турция","category":"main","diets":[],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":820,"p":46,"f":48,"c":52},"details":[{"name":"Баранина","quantity":700,"unit":"g","note":"тонкими ломтями"},{"name":"Лепёшка пиде","quantity":400,"unit":"g","note":""},{"name":"Томатное пюре","quantity":400,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":""},{"name":"Густой йогурт","quantity":300,"unit":"ml","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Паста из красного перца","quantity":1,"unit":"tbsp","note":""},{"name":"Орегано","quantity":1,"unit":"tsp","note":""},{"name":"Зелёный перец","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте баранину очень тонкими ломтями, посолите, поперчите и оставьте на двадцать минут.\nОбжарьте лук и чеснок в масле, добавьте пасту из перца и прогрейте минуту.\nВлейте томатное пюре, добавьте орегано и варите соус пятнадцать минут до густоты.\nНарежьте пиде кубиками и подсушите в духовке при 180 °C восемь минут.\nОбжарьте ломти баранины на очень сильном огне партиями по полторы минуты.\nРазложите хлеб по тарелкам, полейте частью соуса, сверху мясо и остальной соус.\nРастопите масло до шипения и полейте им мясо. Положите йогурт сбоку и подавайте с жареным перцем.","source":"UniTools"},{"id":"ut-manti-turkish","name":"Турецкие манты","country":"Турция","category":"main","diets":[],"slots":["lunch","dinner"],"time":125,"baseServings":5,"portionNutrition":{"k":640,"p":28,"f":30,"c":62},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Вода","quantity":180,"unit":"ml","note":""},{"name":"Баранина","quantity":300,"unit":"g","note":"фарш"},{"name":"Лук","quantity":1,"unit":"piece","note":"тёртый"},{"name":"Густой йогурт","quantity":500,"unit":"ml","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Мята сушёная","quantity":1,"unit":"tbsp","note":""},{"name":"Сумах","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, яиц, воды и соли и вымешивайте пятнадцать минут.\nНакройте и оставьте отдыхать на сорок минут — иначе тесто будет пружинить при раскатке.\nСмешайте фарш с тёртым луком, солью и перцем и отожмите лишний сок.\nРаскатайте тесто в пласт толщиной в миллиметр и нарежьте квадратами по два сантиметра.\nНа каждый квадрат положите начинку на кончике ножа и защипните четыре угла вверх в узелок.\nОтварите манты в подсоленной воде восемь минут и откиньте, сохранив половник отвара.\nВзбейте йогурт с чесноком, разложите манты, залейте йогуртом, полейте маслом с паприкой и мятой.","source":"UniTools"},{"id":"ut-fabada-asturiana","name":"Фабада астурийская","country":"Испания","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":200,"baseServings":6,"portionNutrition":{"k":780,"p":38,"f":44,"c":56},"details":[{"name":"Фасоль фабес","quantity":600,"unit":"g","note":"замочить на ночь"},{"name":"Чорисо","quantity":250,"unit":"g","note":""},{"name":"Морсилья","quantity":200,"unit":"g","note":""},{"name":"Копчёная грудинка","quantity":200,"unit":"g","note":""},{"name":"Кость от хамона","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Паприка сладкая","quantity":1,"unit":"tsp","note":""},{"name":"Оливковое масло","quantity":50,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите фасоль на двенадцать часов в холодной воде и слейте.\nСложите фасоль, копчёности, лук, чеснок и оливковое масло в кастрюлю и залейте холодной водой на три пальца.\nДоведите до кипения, снимите пену и убавьте огонь до едва заметного дрожания поверхности.\nВарите два с половиной часа, подливая по полстакана холодной воды каждые тридцать минут.\nВыньте луковицу и чеснок, разотрите их с шафраном и паприкой и верните в кастрюлю.\nПосолите в самом конце и дайте настояться полчаса перед подачей.\nВыньте копчёности, нарежьте и подайте на отдельном блюде, фасоль — в супнице.","source":"UniTools"},{"id":"ut-pulpo-a-feira","name":"Осьминог по-галисийски","country":"Испания","category":"snack","diets":["pescatarian","gluten-free"],"slots":["snack"],"time":75,"baseServings":4,"portionNutrition":{"k":420,"p":42,"f":18,"c":26},"details":[{"name":"Осьминог","quantity":2,"unit":"kg","note":"замороженный и размороженный"},{"name":"Картофель","quantity":800,"unit":"g","note":""},{"name":"Паприка копчёная","quantity":2,"unit":"tbsp","note":""},{"name":"Паприка острая","quantity":1,"unit":"tsp","note":""},{"name":"Оливковое масло","quantity":100,"unit":"ml","note":""},{"name":"Соль крупная","quantity":2,"unit":"tsp","note":""},{"name":"Лавровый лист","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""}],"steps":"Вскипятите большую кастрюлю воды с луковицей и лавровым листом. Соль не добавляйте.\nВозьмите осьминога за голову и опустите щупальца в кипяток на пять секунд, потом выньте. Повторите трижды.\nОпустите осьминога целиком и варите при слабом кипении сорок минут.\nПроверьте вилкой в самой толстой части щупальца: она должна входить без усилия.\nВыключите огонь и оставьте осьминога в воде на пятнадцать минут — он дойдёт и станет мягче.\nОтварите картофель в том же бульоне и нарежьте кружками.\nНарежьте щупальца ножницами на кусочки в сантиметр, выложите на картофель, посыпьте паприкой и солью, полейте маслом.","source":"UniTools"},{"id":"ut-khao-soi","name":"Кхао сой","country":"Таиланд","category":"soup","diets":[],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":820,"p":42,"f":46,"c":62},"details":[{"name":"Яичная лапша","quantity":500,"unit":"g","note":""},{"name":"Куриные голени","quantity":800,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":800,"unit":"ml","note":""},{"name":"Красная паста карри","quantity":4,"unit":"tbsp","note":""},{"name":"Карри молотое","quantity":1,"unit":"tbsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Шалот","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Маринованная горчичная зелень","quantity":100,"unit":"g","note":"к подаче"},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Масло для фритюра","quantity":500,"unit":"ml","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""}],"steps":"Отложите пятую часть лапши, разберите на пряди и обжарьте во фритюре до золотистого хруста.\nПрогрейте густую часть кокосового молока в сотейнике, не мешая, пока не отделится масло.\nОбжарьте в этом масле пасту карри, порошок карри и куркуму три минуты до глубокого запаха.\nПоложите курицу и обваляйте в пасте, чтобы она покрылась со всех сторон.\nВлейте оставшееся кокосовое молоко и воду, добавьте рыбный соус и сахар и варите тридцать минут.\nОтварите оставшуюся лапшу и разложите по мискам.\nЗалейте карри с курицей, сверху положите жареную лапшу, шалот, маринованную зелень, кинзу и дольку лайма.","source":"UniTools"},{"id":"ut-massaman-curry","name":"Массаман карри","country":"Таиланд","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":115,"baseServings":5,"portionNutrition":{"k":780,"p":44,"f":44,"c":56},"details":[{"name":"Говядина","quantity":900,"unit":"g","note":"крупными кусками"},{"name":"Паста массаман","quantity":5,"unit":"tbsp","note":""},{"name":"Кокосовое молоко","quantity":800,"unit":"ml","note":""},{"name":"Картофель","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Арахис жареный","quantity":100,"unit":"g","note":""},{"name":"Тамариндовая паста","quantity":3,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Кардамон","quantity":4,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Рис жасминовый","quantity":400,"unit":"g","note":"к подаче"}],"steps":"Прогрейте густую часть кокосового молока, не мешая, пока не отделится масло.\nОбжарьте пасту массаман в этом масле четыре минуты, пока она не потемнеет и не запахнет.\nДобавьте говядину и обваляйте в пасте, потом положите корицу, кардамон и лавровый лист.\nВлейте оставшееся кокосовое молоко и тушите на слабом огне час, пока мясо не станет мягким.\nЗаложите картофель и лук крупными кусками и варите ещё двадцать минут.\nВмешайте тамаринд, пальмовый сахар и рыбный соус и попробуйте: должно быть сладко, кисло и солёно разом.\nДобавьте арахис, прогрейте пять минут и подавайте с жасминовым рисом.","source":"UniTools"},{"id":"ut-gemista","name":"Гемиста","country":"Греция","category":"main","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":125,"baseServings":6,"portionNutrition":{"k":480,"p":8,"f":24,"c":60},"details":[{"name":"Помидоры крупные","quantity":8,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":4,"unit":"piece","note":""},{"name":"Рис круглозёрный","quantity":300,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Петрушка","quantity":50,"unit":"g","note":""},{"name":"Мята","quantity":20,"unit":"g","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Оливковое масло","quantity":200,"unit":"ml","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Срежьте у помидоров крышечки и выберите мякоть ложкой, не повредив стенки.\nПробейте мякоть блендером и добавьте сахар — он уберёт кислоту помидоров.\nОбжарьте лук в оливковом масле десять минут до мягкости и сладости.\nСмешайте сырой рис с луком, зеленью, половиной томатного пюре, солью и перцем.\nНаполните овощи на две трети, накройте крышечками и поставьте в форму.\nРазложите между ними картофель дольками, залейте оставшимся пюре и щедро полейте маслом.\nЗапекайте под фольгой при 180 °C час, потом снимите фольгу и держите ещё двадцать минут.","source":"UniTools"},{"id":"ut-avgolemono","name":"Авголемоно","country":"Греция","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":80,"baseServings":5,"portionNutrition":{"k":420,"p":38,"f":16,"c":28},"details":[{"name":"Курица","quantity":1.3,"unit":"kg","note":"целая"},{"name":"Рис круглозёрный","quantity":120,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Сельдерей стеблевой","quantity":2,"unit":"piece","note":""},{"name":"Укроп","quantity":20,"unit":"g","note":""},{"name":"Оливковое масло","quantity":30,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте курицу двумя с половиной литрами холодной воды, доведите до кипения и снимите пену.\nДобавьте лук, морковь и сельдерей и варите на слабом огне сорок пять минут.\nВыньте курицу, процедите бульон и верните его на огонь. Отварите в нём рис пятнадцать минут.\nРазберите мясо на волокна, выбросив кожу и кости.\nВзбейте яйца с соком лимонов до однородной пены в отдельной миске.\nВливайте горячий бульон в яично-лимонную смесь половником, непрерывно взбивая, пока миска не станет тёплой.\nВлейте смесь обратно в кастрюлю на снятом огне, верните мясо и прогрейте, не доводя до кипения.","source":"UniTools"},{"id":"ut-pelmeni","name":"Пельмени","country":"Россия","category":"main","diets":[],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":680,"p":34,"f":32,"c":62},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Вода ледяная","quantity":220,"unit":"ml","note":""},{"name":"Говядина","quantity":400,"unit":"g","note":""},{"name":"Свинина","quantity":400,"unit":"g","note":"жирная"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Лёд колотый","quantity":50,"unit":"g","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Сметана","quantity":200,"unit":"ml","note":"к подаче"},{"name":"Уксус","quantity":30,"unit":"ml","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, яиц, ледяной воды и соли и вымешивайте пятнадцать минут.\nЗаверните в плёнку и уберите в холодильник на сорок минут.\nПорубите мясо ножом или пропустите через крупную решётку, смешайте с тёртым луком, солью и перцем.\nВмешайте колотый лёд в фарш и уберите его в холод на двадцать минут.\nРаскатайте тесто в пласт толщиной в миллиметр и вырежьте кружки диаметром шесть сантиметров.\nНа каждый кружок положите чайную ложку фарша, сложите полумесяцем, защипните и соедините концы кольцом.\nВарите в кипящем подсоленном бульоне с лавровым листом четыре минуты после всплытия, подавайте с маслом и сметаной.","source":"UniTools"},{"id":"ut-beef-stroganoff","name":"Бефстроганов","country":"Россия","category":"main","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":620,"p":44,"f":42,"c":14},"details":[{"name":"Говяжья вырезка","quantity":700,"unit":"g","note":"соломкой поперёк волокон"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Шампиньоны","quantity":300,"unit":"g","note":""},{"name":"Сметана","quantity":300,"unit":"ml","note":""},{"name":"Горчица","quantity":1,"unit":"tbsp","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Говяжий бульон","quantity":200,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Растительное масло","quantity":30,"unit":"ml","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте мясо поперёк волокон соломкой толщиной в сантиметр, обсушите бумагой и поперчите.\nРаскалите сковороду и обжарьте мясо порциями по полторы минуты, не переворачивая часто.\nВыньте мясо, обжарьте грибы на сильном огне до испарения их воды.\nДобавьте масло и лук и жарьте до мягкости и золотистого цвета.\nВсыпьте муку, прогрейте минуту и влейте бульон, размешивая до гладкости.\nСнимите с огня, вмешайте сметану и горчицу и посолите.\nВерните мясо с выделившимся соком, прогрейте минуту не кипятя и посыпьте петрушкой.","source":"UniTools"},{"id":"ut-schweinshaxe","name":"Швайнсхаксе","country":"Германия","category":"main","diets":[],"slots":["lunch","dinner"],"time":205,"baseServings":4,"portionNutrition":{"k":880,"p":58,"f":56,"c":34},"details":[{"name":"Свиная рулька","quantity":2,"unit":"piece","note":"по 1 кг"},{"name":"Тёмное пиво","quantity":1,"unit":"l","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Корень сельдерея","quantity":200,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Тмин","quantity":2,"unit":"tsp","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Квашеная капуста","quantity":600,"unit":"g","note":"к подаче"},{"name":"Картофель","quantity":800,"unit":"g","note":"к подаче"},{"name":"Соль крупная и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Надрежьте шкуру ромбами через полтора сантиметра, доходя до жира, но не до мяса.\nНатрите рульки крупной солью, перцем, тмином и чесноком, втирая всё в надрезы.\nУложите в кастрюлю с луком, морковью, сельдереем и лавровым листом, залейте пивом и водой.\nВарите на слабом огне час, не давая бурно кипеть.\nПереложите рульки на противень, обсушите шкуру бумагой и запекайте при 180 °C час двадцать.\nКаждые двадцать минут поливайте пивом из кастрюли и жиром с противня.\nПоднимите температуру до 240 °C на последние десять минут, пока корка не вздуется пузырями.","source":"UniTools"},{"id":"ut-schwarzwaelder-kirschtorte","name":"Шварцвальдский торт","country":"Германия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":110,"baseServings":12,"portionNutrition":{"k":520,"p":7,"f":34,"c":46},"details":[{"name":"Мука","quantity":150,"unit":"g","note":""},{"name":"Какао-порошок","quantity":50,"unit":"g","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Сахар","quantity":200,"unit":"g","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Сливки 33%","quantity":800,"unit":"ml","note":""},{"name":"Желатин","quantity":10,"unit":"g","note":""},{"name":"Вишня","quantity":600,"unit":"g","note":"с сиропом"},{"name":"Кирш","quantity":80,"unit":"ml","note":""},{"name":"Тёмный шоколад","quantity":150,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":60,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Взбейте яйца с сахаром на водяной бане до тёплого, затем миксером десять минут до плотной светлой пены.\nПросейте муку с какао и вмешайте лопаткой в три приёма, затем растопленное масло.\nИспеките бисквит при 175 °C тридцать пять минут и полностью остудите, лучше за ночь.\nРазрежьте бисквит на три коржа и пропитайте каждый вишнёвым сиропом с киршем.\nРаспустите желатин, взбейте сливки с пудрой и вмешайте желатин тонкой струйкой.\nСобирайте: корж, сливки, вишня, снова сливки — и так три раза, заканчивая сливками.\nОбсыпьте бока и верх шоколадной стружкой, украсьте вишней и охладите четыре часа.","source":"UniTools"},{"id":"ut-pulled-pork","name":"Раздёрганная свинина","country":"США","category":"main","diets":[],"slots":["lunch","dinner"],"time":630,"baseServings":10,"portionNutrition":{"k":620,"p":48,"f":38,"c":22},"details":[{"name":"Свиная лопатка","quantity":4,"unit":"kg","note":"с костью"},{"name":"Паприка копчёная","quantity":4,"unit":"tbsp","note":""},{"name":"Коричневый сахар","quantity":4,"unit":"tbsp","note":""},{"name":"Горчичный порошок","quantity":2,"unit":"tbsp","note":""},{"name":"Чесночный порошок","quantity":2,"unit":"tbsp","note":""},{"name":"Кайенский перец","quantity":1,"unit":"tsp","note":""},{"name":"Горчица","quantity":3,"unit":"tbsp","note":"как связка для смеси"},{"name":"Яблочный уксус","quantity":250,"unit":"ml","note":""},{"name":"Яблочный сок","quantity":250,"unit":"ml","note":""},{"name":"Щепа гикори или яблони","quantity":300,"unit":"g","note":""},{"name":"Булочки","quantity":10,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте паприку, сахар, горчичный и чесночный порошок, кайенский перец, соль и чёрный перец.\nОбмажьте лопатку горчицей — она нужна как связка — и обваляйте в сухой смеси со всех сторон.\nОставьте мясо в холодильнике на ночь, накрыв плёнкой.\nВыведите коптильню или духовку на 110 °C и достаньте мясо за час до готовки, чтобы оно согрелось.\nКоптите жирной стороной вверх шесть часов, сбрызгивая смесью уксуса и яблочного сока каждый час.\nКогда температура внутри дойдёт до 75 °C и остановится, заверните мясо в фольгу и верните в жар.\nДержите до 95 °C внутри, ещё часа четыре, дайте отдохнуть час в фольге и разберите руками на волокна.","source":"UniTools"},{"id":"ut-key-lime-pie","name":"Пирог с лаймом","country":"США","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":50,"baseServings":8,"portionNutrition":{"k":520,"p":8,"f":30,"c":56},"details":[{"name":"Крекеры грэм или песочное печенье","quantity":250,"unit":"g","note":""},{"name":"Сливочное масло","quantity":110,"unit":"g","note":"растопить"},{"name":"Сахар","quantity":50,"unit":"g","note":""},{"name":"Сгущённое молоко","quantity":400,"unit":"g","note":""},{"name":"Желтки","quantity":4,"unit":"piece","note":""},{"name":"Лайм","quantity":8,"unit":"piece","note":""},{"name":"Сливки 33%","quantity":300,"unit":"ml","note":""},{"name":"Сахарная пудра","quantity":30,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Измельчите крекеры в мелкую крошку и смешайте с растопленным маслом, сахаром и щепотью соли.\nУтрамбуйте крошку в форму, поднимая по бортам, и запеките при 175 °C десять минут.\nВзбейте желтки с цедрой двух лаймов до посветления — минуты три.\nВлейте сгущённое молоко и взбивайте ещё три минуты, пока смесь не станет густой.\nВливайте сок лаймов тонкой струйкой при работающем миксере — смесь загустеет прямо в миске.\nВылейте начинку в основу и запекайте при 160 °C пятнадцать минут, пока края не схватятся, а центр не будет дрожать.\nОстудите и охладите четыре часа, затем украсьте взбитыми сливками с пудрой.","source":"UniTools"},{"id":"ut-bun-cha","name":"Бун ча","country":"Вьетнам","category":"main","diets":[],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":720,"p":42,"f":32,"c":66},"details":[{"name":"Свиная грудинка","quantity":400,"unit":"g","note":"тонкими ломтями"},{"name":"Свиной фарш","quantity":400,"unit":"g","note":""},{"name":"Рисовая вермишель","quantity":400,"unit":"g","note":""},{"name":"Рыбный соус","quantity":100,"unit":"ml","note":""},{"name":"Сахар","quantity":4,"unit":"tbsp","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Шалот","quantity":4,"unit":"piece","note":""},{"name":"Зелёная папайя или редька","quantity":200,"unit":"g","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Перец чили","quantity":2,"unit":"piece","note":""},{"name":"Мята, перилла, кинза","quantity":100,"unit":"g","note":""},{"name":"Салат листовой","quantity":200,"unit":"g","note":""},{"name":"Чёрный перец","quantity":1,"unit":"tsp","note":""}],"steps":"Замаринуйте ломтики грудинки и фарш отдельно в рыбном соусе, сахаре, шалоте, чесноке и перце на час.\nСлепите из фарша плоские котлетки толщиной в сантиметр — они прожарятся быстро и равномерно.\nНарежьте папайю и морковь тонкими ломтиками и замаринуйте в уксусе с сахаром на двадцать минут.\nСмешайте рыбный соус, сахар, сок лайма, воду, чеснок и чили и прогрейте до тёплого — это ныок чам.\nОтварите вермишель две минуты, промойте холодной водой и разложите по тарелкам.\nЖарьте грудинку и котлетки на углях по три минуты с каждой стороны до карамельных краёв.\nОпустите горячее мясо прямо в тёплый соус с маринованными овощами и подайте с лапшой, салатом и травами.","source":"UniTools"},{"id":"ut-goi-cuon","name":"Гой куон","country":"Вьетнам","category":"snack","diets":[],"slots":["snack"],"time":65,"baseServings":4,"portionNutrition":{"k":420,"p":28,"f":16,"c":44},"details":[{"name":"Рисовая бумага","quantity":16,"unit":"piece","note":""},{"name":"Креветки","quantity":400,"unit":"g","note":""},{"name":"Свиная грудинка","quantity":300,"unit":"g","note":""},{"name":"Рисовая вермишель","quantity":150,"unit":"g","note":""},{"name":"Салат листовой","quantity":150,"unit":"g","note":""},{"name":"Мята","quantity":30,"unit":"g","note":""},{"name":"Зелёный лук","quantity":30,"unit":"g","note":""},{"name":"Арахисовая паста","quantity":4,"unit":"tbsp","note":""},{"name":"Соус хойсин","quantity":4,"unit":"tbsp","note":""},{"name":"Арахис жареный","quantity":50,"unit":"g","note":""},{"name":"Чеснок","quantity":2,"unit":"clove","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите грудинку в подсоленной воде тридцать минут, остудите и нарежьте тонкими ломтями.\nОтварите креветки две минуты, остудите и разрежьте каждую вдоль пополам.\nОтварите вермишель, промойте холодной водой и хорошо обсушите.\nРазведите арахисовую пасту с хойсином, чесноком и водой до консистенции жидких сливок.\nСмочите лист рисовой бумаги в тёплой воде на две секунды и положите на влажное полотенце.\nУложите две половинки креветки срезом вниз в верхней трети, ниже — салат, лапшу, мясо и травы.\nЗаверните низ, подверните бока и скатайте плотным рулетом. Подавайте с арахисовым соусом.","source":"UniTools"},{"id":"ut-galbijjim","name":"Кальбиччим","country":"Корея","category":"main","diets":[],"slots":["lunch","dinner"],"time":165,"baseServings":5,"portionNutrition":{"k":780,"p":48,"f":46,"c":40},"details":[{"name":"Говяжьи рёбра","quantity":1.5,"unit":"kg","note":""},{"name":"Соевый соус","quantity":150,"unit":"ml","note":""},{"name":"Корейская груша","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Кунжутное масло","quantity":2,"unit":"tbsp","note":""},{"name":"Мирин","quantity":60,"unit":"ml","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Дайкон","quantity":300,"unit":"g","note":""},{"name":"Грибы шиитаке","quantity":150,"unit":"g","note":""},{"name":"Каштаны","quantity":150,"unit":"g","note":"очищенные"},{"name":"Финики жужуб","quantity":8,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":3,"unit":"piece","note":""}],"steps":"Вымочите рёбра в холодной воде час, меняя воду дважды, пока она не станет прозрачной.\nОпустите рёбра в кипяток на пять минут, слейте и промойте под холодной водой.\nПробейте грушу, лук, чеснок и имбирь в блендере до однородного пюре.\nСмешайте пюре с соевым соусом, сахаром, мирином и кунжутным маслом и залейте им рёбра.\nДоведите до кипения, снимите пену и тушите под крышкой полтора часа на слабом огне.\nДобавьте морковь, дайкон, грибы, каштаны и финики и тушите ещё двадцать пять минут.\nСнимите крышку и выпарите соус до глянца, поливая им рёбра. Посыпьте зелёным луком.","source":"UniTools"},{"id":"ut-samgyetang","name":"Самгетан","country":"Корея","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":105,"baseServings":4,"portionNutrition":{"k":620,"p":52,"f":24,"c":46},"details":[{"name":"Цыплёнок","quantity":4,"unit":"piece","note":"по 500-700 г"},{"name":"Клейкий рис","quantity":200,"unit":"g","note":"замочить на 2 часа"},{"name":"Корень женьшеня","quantity":4,"unit":"piece","note":""},{"name":"Финики жужуб","quantity":8,"unit":"piece","note":""},{"name":"Чеснок","quantity":16,"unit":"clove","note":""},{"name":"Каштаны","quantity":8,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите клейкий рис в холодной воде на два часа и откиньте на сито.\nПромойте цыплят, удалите лишний жир у полости и обсушите.\nНаполните каждую полость рисом на две трети, добавив корень женьшеня, чеснок, каштан и финик.\nСкрестите ножки и заправьте одну в надрез на другой — так полость закроется без ниток.\nУложите цыплят в кастрюлю плотно и залейте холодной водой, чтобы она едва покрывала.\nДоведите до кипения, снимите пену и варите на слабом огне час с четвертью.\nПодавайте каждого цыплёнка в своей миске с бульоном, с солью и перцем отдельно на блюдце.","source":"UniTools"},{"id":"ut-roast-beef-yorkshire","name":"Ростбиф с йоркширским пудингом","country":"Великобритания","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":780,"p":56,"f":42,"c":46},"details":[{"name":"Говяжий отруб","quantity":2,"unit":"kg","note":"толстый край или огузок"},{"name":"Мука","quantity":140,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Молоко","quantity":200,"unit":"ml","note":""},{"name":"Говяжий жир","quantity":100,"unit":"g","note":""},{"name":"Картофель","quantity":1,"unit":"kg","note":""},{"name":"Морковь","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Говяжий бульон","quantity":400,"unit":"ml","note":""},{"name":"Красное вино","quantity":150,"unit":"ml","note":""},{"name":"Английская горчица","quantity":2,"unit":"tbsp","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Взбейте муку, яйца, молоко и соль в гладкое тесто и оставьте отдыхать час в холодильнике.\nДостаньте мясо из холодильника за час до готовки и обсушите, посолите и поперчите.\nОбжарьте отруб на сковороде со всех сторон до тёмной корки, по две минуты на грань.\nУложите на овощи в противень и запекайте при 200 °C двадцать минут, потом при 160 °C ещё сорок для розового центра.\nВыньте мясо, накройте фольгой и дайте отдохнуть двадцать минут — оно продолжит доходить.\nРаскалите формы для пудинга с ложкой жира в каждой при 220 °C, пока жир не задымит.\nРазлейте холодное тесто по формам наполовину и пеките двадцать минут, не открывая дверцу.","source":"UniTools"},{"id":"ut-sticky-toffee-pudding","name":"Финиковый пудинг с ирисочным соусом","country":"Великобритания","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":65,"baseServings":8,"portionNutrition":{"k":640,"p":6,"f":34,"c":80},"details":[{"name":"Финики","quantity":250,"unit":"g","note":"без косточек"},{"name":"Сода","quantity":1,"unit":"tsp","note":""},{"name":"Мука","quantity":200,"unit":"g","note":""},{"name":"Сливочное масло","quantity":200,"unit":"g","note":""},{"name":"Тёмный тростниковый сахар","quantity":300,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Разрыхлитель","quantity":1,"unit":"tsp","note":""},{"name":"Сливки 33%","quantity":300,"unit":"ml","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Залейте нарезанные финики стаканом кипятка с содой и оставьте на пятнадцать минут.\nРазомните финики вилкой в грубую пасту вместе с их водой.\nВзбейте сто граммов масла со ста пятьюдесятью граммами сахара добела и введите яйца по одному.\nВмешайте муку с разрыхлителем, затем финиковую пасту — тесто получится жидким, и это нормально.\nВылейте в смазанную форму и пеките при 180 °C тридцать пять минут до влажной шпажки с крошками.\nРастопите оставшееся масло с оставшимся сахаром и сливками и варите соус пять минут до густоты.\nНаколите тёплый кекс шпажкой, полейте половиной соуса и подавайте с остальным в кувшине.","source":"UniTools"},{"id":"ut-bigos","name":"Бигос","country":"Польша","category":"main","diets":[],"slots":["lunch","dinner"],"time":280,"baseServings":10,"portionNutrition":{"k":620,"p":38,"f":40,"c":24},"details":[{"name":"Квашеная капуста","quantity":1,"unit":"kg","note":""},{"name":"Капуста свежая","quantity":1,"unit":"kg","note":""},{"name":"Свиная лопатка","quantity":600,"unit":"g","note":""},{"name":"Колбаса копчёная","quantity":400,"unit":"g","note":""},{"name":"Копчёная грудинка","quantity":300,"unit":"g","note":""},{"name":"Говядина","quantity":400,"unit":"g","note":""},{"name":"Сушёные белые грибы","quantity":50,"unit":"g","note":""},{"name":"Чернослив","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Красное сухое вино","quantity":250,"unit":"ml","note":""},{"name":"Можжевельник","quantity":8,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":4,"unit":"piece","note":""},{"name":"Душистый перец","quantity":6,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите сушёные грибы в стакане тёплой воды на полчаса и нарежьте, воду процедите и сохраните.\nОтожмите квашеную капусту, нашинкуйте свежую и потушите обе в отдельных кастрюлях по тридцать минут.\nОбжарьте грудинку до шкварок, в её жире подрумяньте свинину и говядину кусками, затем лук.\nСоедините обе капусты, мясо, колбасу, грибы с их водой, чернослив, томатную пасту и специи в большой кастрюле.\nВлейте вино, доведите до кипения и тушите два часа на самом слабом огне, помешивая изредка.\nПолностью остудите и оставьте на сутки в холоде, потом снова доведите до кипения и тушите час.\nПовторите цикл ещё раз на третий день. Подавайте с ржаным хлебом и рюмкой водки.","source":"UniTools"},{"id":"ut-sernik","name":"Сырник польский","country":"Польша","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":115,"baseServings":12,"portionNutrition":{"k":480,"p":18,"f":26,"c":44},"details":[{"name":"Творог твёрдый","quantity":1,"unit":"kg","note":""},{"name":"Мука","quantity":250,"unit":"g","note":""},{"name":"Сливочное масло","quantity":200,"unit":"g","note":""},{"name":"Сахар","quantity":250,"unit":"g","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Картофельный крахмал","quantity":50,"unit":"g","note":""},{"name":"Сметана","quantity":150,"unit":"ml","note":""},{"name":"Ваниль","quantity":1,"unit":"piece","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Разрыхлитель","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Разотрите муку со ста граммами холодного масла, ложкой сахара, желтком и разрыхлителем в крошку и замесите тесто.\nУтрамбуйте тесто в форму и запеките при 180 °C пятнадцать минут до бледно-золотого цвета.\nПротрите творог через сито дважды — от этого зависит вся гладкость начинки.\nВзбейте оставшееся масло с сахаром добела, введите желтки по одному, затем творог, сметану, крахмал, ваниль и цедру.\nВзбейте белки с щепотью соли до устойчивых пиков и вмешайте лопаткой в три приёма.\nВмешайте изюм, вылейте начинку на основу и разровняйте.\nПеките при 160 °C пятьдесят пять минут, затем выключите духовку и оставьте пирог внутри с приоткрытой дверцей на час.","source":"UniTools"},{"id":"ut-moqueca-baiana","name":"Мокека баиана","country":"Бразилия","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":65,"baseServings":5,"portionNutrition":{"k":620,"p":48,"f":32,"c":34},"details":[{"name":"Белая рыба","quantity":1,"unit":"kg","note":"плотное филе, крупными кусками"},{"name":"Креветки","quantity":300,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Пальмовое масло денде","quantity":60,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":"разных цветов"},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите рыбу солью, перцем, растёртым чесноком и соком лаймов и оставьте на двадцать минут.\nНарежьте лук, помидоры и перец кольцами одинаковой толщины.\nВыстелите дно глиняного горшка половиной колец лука, помидора и перца.\nУложите рыбу в один слой, сверху креветки и оставшиеся овощи, посолите.\nВлейте кокосовое молоко и масло денде по краю, не заливая рыбу сверху.\nНакройте и тушите двадцать минут на среднем огне, покачивая горшок, но не размешивая.\nПосыпьте кинзой и зелёным луком и подавайте прямо в горшке, с рисом и фарофой.","source":"UniTools"},{"id":"ut-coxinha","name":"Кошинья","country":"Бразилия","category":"snack","diets":[],"slots":["snack"],"time":115,"baseServings":8,"portionNutrition":{"k":520,"p":24,"f":26,"c":48},"details":[{"name":"Куриное филе","quantity":600,"unit":"g","note":""},{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Куриный бульон","quantity":700,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Сливочный сыр катупири","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Томатная паста","quantity":1,"unit":"tbsp","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Панировочные сухари","quantity":300,"unit":"g","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":1.5,"unit":"l","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу в подсоленной воде двадцать минут, выньте и разберите руками на волокна. Бульон сохраните.\nОбжарьте лук и чеснок, добавьте курицу, томатную пасту, петрушку и соль и потушите пять минут.\nДоведите бульон с маслом до кипения, всыпьте всю муку разом и вымешивайте на огне пять минут.\nВыложите тесто на стол и вымешивайте руками, пока оно не станет гладким и перестанет липнуть.\nРасплющите кусок теста на ладони, положите начинку и немного катупири, залепите и вытяните каплю с кончиком.\nОбваляйте в яйце и сухарях, повторите ещё раз и охладите двадцать минут.\nЖарьте партиями в масле при 175 °C по четыре минуты до тёмно-золотого цвета.","source":"UniTools"},{"id":"ut-aji-de-gallina","name":"Ахи де гальина","country":"Перу","category":"main","diets":[],"slots":["lunch","dinner"],"time":80,"baseServings":5,"portionNutrition":{"k":680,"p":48,"f":30,"c":56},"details":[{"name":"Куриная грудка","quantity":800,"unit":"g","note":""},{"name":"Паста ахи амарильо","quantity":5,"unit":"tbsp","note":""},{"name":"Белый хлеб","quantity":4,"unit":"slice","note":""},{"name":"Молоко","quantity":400,"unit":"ml","note":""},{"name":"Грецкие орехи","quantity":80,"unit":"g","note":""},{"name":"Пармезан","quantity":60,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":"отварной"},{"name":"Яйца","quantity":4,"unit":"piece","note":"варёные"},{"name":"Оливки чёрные","quantity":60,"unit":"g","note":""},{"name":"Рис","quantity":350,"unit":"g","note":"к подаче"},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите куриную грудку в подсоленной воде двадцать минут и разберите руками на тонкие волокна.\nЗамочите хлеб без корок в молоке на десять минут.\nОбжарьте лук с чесноком в масле до мягкости, добавьте пасту ахи и куркуму и жарьте пять минут.\nПробейте в блендере размоченный хлеб с молоком, орехами и обжаренным луком до гладкости.\nВерните смесь в сотейник и варите десять минут на слабом огне, помешивая.\nВмешайте курицу и пармезан, посолите и прогрейте пять минут до густоты сметаны.\nПодавайте на отварном картофеле и рисе, украсив яйцом и оливками.","source":"UniTools"},{"id":"ut-causa-limena","name":"Кауса лименья","country":"Перу","category":"salad","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":75,"baseServings":6,"portionNutrition":{"k":480,"p":22,"f":28,"c":38},"details":[{"name":"Картофель жёлтых сортов","quantity":1.2,"unit":"kg","note":""},{"name":"Паста ахи амарильо","quantity":4,"unit":"tbsp","note":""},{"name":"Лайм","quantity":4,"unit":"piece","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Тунец консервированный","quantity":400,"unit":"g","note":""},{"name":"Майонез","quantity":150,"unit":"g","note":""},{"name":"Лук красный","quantity":1,"unit":"piece","note":""},{"name":"Авокадо","quantity":2,"unit":"piece","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":"варёные"},{"name":"Оливки чёрные","quantity":60,"unit":"g","note":""},{"name":"Кинза","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите картофель в мундире до полной мягкости, очистите горячим и пропустите через пресс.\nВымешивайте пюре руками пять минут, пока оно не станет однородным и упругим.\nОстудите пюре до комнатной температуры, потом вмешайте пасту ахи, сок лаймов, масло и соль.\nСмешайте тунец с майонезом, мелко нарезанным красным луком и кинзой.\nВыложите в форму половину пюре слоем в полтора сантиметра и разровняйте.\nРаспределите начинку и ломтики авокадо, накройте второй половиной пюре.\nОхладите два часа, украсьте яйцом и оливками и подавайте холодной.","source":"UniTools"},{"id":"ut-fesenjan","name":"Фесенджан","country":"Иран","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":180,"baseServings":6,"portionNutrition":{"k":880,"p":44,"f":58,"c":52},"details":[{"name":"Утка или курица","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Грецкие орехи","quantity":500,"unit":"g","note":""},{"name":"Гранатовая патока","quantity":200,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Корица","quantity":0.5,"unit":"tsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Рис басмати","quantity":500,"unit":"g","note":"к подаче"},{"name":"Зёрна граната","quantity":100,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Подсушите орехи на сухой сковороде пять минут, остудите и смелите почти в пасту.\nОбжарьте лук в масле до золотистого, добавьте куркуму и мясо и подрумяньте со всех сторон.\nВыньте мясо, всыпьте ореховую пасту в кастрюлю и залейте литром горячей воды.\nВарите соус час на слабом огне, помешивая каждые десять минут — он начнёт темнеть и отдавать масло.\nВлейте гранатовую патоку, добавьте корицу, сахар и шафран и верните мясо в кастрюлю.\nТушите ещё час, пока соус не станет тёмно-коричневым и густым, а масло не выступит по краям.\nПопробуйте и поправьте баланс кислого и сладкого, подавайте с рисом и зёрнами граната.","source":"UniTools"},{"id":"ut-joojeh-kabab","name":"Джудже-кебаб","country":"Иран","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":55,"baseServings":5,"portionNutrition":{"k":680,"p":48,"f":30,"c":52},"details":[{"name":"Куриное бедро без кости","quantity":1.2,"unit":"kg","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Йогурт","quantity":150,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Помидоры","quantity":6,"unit":"piece","note":"к подаче"},{"name":"Рис басмати","quantity":500,"unit":"g","note":"к подаче"},{"name":"Сумах","quantity":1,"unit":"tbsp","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Растолките шафран с щепотью сахара и залейте тремя ложками тёплой воды на пятнадцать минут.\nНатрите лук на мелкой тёрке и отожмите сок через марлю, мякоть выбросьте.\nСмешайте луковый сок, половину шафранного настоя, сок двух лимонов, йогурт, масло, соль и перец.\nНарежьте курицу кусками по четыре сантиметра, залейте маринадом и уберите в холод на восемь часов.\nНанижите куски на плоские шампуры вплотную и разожгите угли до ровного сильного жара.\nЖарьте по восемь минут с каждой стороны, поворачивая шампур каждые две минуты.\nСмешайте растопленное масло с оставшимся шафраном и смажьте кебаб перед подачей. Подавайте с рисом, помидорами и сумахом.","source":"UniTools"},{"id":"ut-caldo-verde","name":"Калду верде","country":"Португалия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":55,"baseServings":5,"portionNutrition":{"k":420,"p":12,"f":24,"c":42},"details":[{"name":"Картофель","quantity":800,"unit":"g","note":""},{"name":"Капуста кале","quantity":300,"unit":"g","note":"нашинковать в нитку"},{"name":"Колбаса шоурису","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Оливковое масло","quantity":100,"unit":"ml","note":""},{"name":"Кукурузный хлеб","quantity":300,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук и чеснок в половине оливкового масла до мягкости, восемь минут.\nДобавьте нарезанный картофель, залейте полутора литрами воды и варите двадцать минут до полной мягкости.\nПробейте суп блендером до гладкого крема и посолите.\nОбжарьте ломтики шоурису на сухой сковороде до подрумянивания и выложите на бумагу.\nСверните листья капусты в тугой рулон и нарежьте поперёк в нитку.\nДоведите крем до кипения, всыпьте капусту и варите ровно три минуты.\nРазлейте по тарелкам, положите ломтики колбасы и полейте сырым оливковым маслом.","source":"UniTools"},{"id":"ut-sardinhas-assadas","name":"Сардины на углях","country":"Португалия","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":620,"p":48,"f":34,"c":34},"details":[{"name":"Сардины","quantity":1.5,"unit":"kg","note":"целые, крупные"},{"name":"Соль крупная","quantity":150,"unit":"g","note":""},{"name":"Деревенский хлеб","quantity":8,"unit":"slice","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":""},{"name":"Перец сладкий","quantity":3,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":100,"unit":"ml","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Винный уксус","quantity":3,"unit":"tbsp","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""}],"steps":"Промойте сардины, не потроша, и обсушите бумагой снаружи.\nЗасыпьте рыбу крупной солью со всех сторон и оставьте на полчаса при комнатной температуре.\nРазожгите угли и дайте им покрыться пеплом — прямое пламя сожжёт кожу за минуту.\nЗапеките перцы на углях до чёрной кожуры, очистите и заправьте маслом, чесноком и уксусом.\nСтряхните с рыбы лишнюю соль и уложите на раскалённую смазанную решётку.\nЖарьте по четыре минуты с каждой стороны, переворачивая ровно один раз.\nВыложите сардины на ломти хлеба и подавайте с варёным картофелем и перечным салатом.","source":"UniTools"},{"id":"ut-sate-ayam","name":"Сатэ аям","country":"Индонезия","category":"main","diets":[],"slots":["lunch","dinner"],"time":65,"baseServings":5,"portionNutrition":{"k":780,"p":52,"f":40,"c":50},"details":[{"name":"Куриное бедро без кости","quantity":900,"unit":"g","note":""},{"name":"Кечап манис","quantity":100,"unit":"ml","note":""},{"name":"Арахис жареный","quantity":250,"unit":"g","note":""},{"name":"Шалот","quantity":5,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Перец чили","quantity":3,"unit":"piece","note":""},{"name":"Кориандр молотый","quantity":2,"unit":"tsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Тамариндовая паста","quantity":2,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте курицу кубиками по два сантиметра и залейте смесью кечапа маниса, чеснока, кориандра и куркумы.\nОставьте мариноваться минимум два часа, лучше на ночь в холодильнике.\nСмелите арахис в крупную крошку, оставив немного целых орехов для подачи.\nОбжарьте шалот, чеснок и чили в масле до мягкости, добавьте молотый арахис и прогрейте три минуты.\nВлейте стакан воды, тамаринд, пальмовый сахар и кечап манис и варите соус десять минут до густоты.\nНанижите куски вплотную на замоченные шпажки, по пять-шесть на каждую.\nЖарьте на сильных углях по две минуты с каждой стороны, смазывая кечапом манисом. Подавайте с соусом и рисом.","source":"UniTools"},{"id":"ut-soto-ayam","name":"Сото аям","country":"Индонезия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":5,"portionNutrition":{"k":560,"p":44,"f":24,"c":42},"details":[{"name":"Курица","quantity":1.4,"unit":"kg","note":"целая"},{"name":"Шалот","quantity":8,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Куркума свежая","quantity":30,"unit":"g","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Орехи кемири или макадамия","quantity":4,"unit":"piece","note":""},{"name":"Лемонграсс","quantity":3,"unit":"piece","note":""},{"name":"Листья каффир-лайма","quantity":6,"unit":"piece","note":""},{"name":"Стеклянная лапша","quantity":150,"unit":"g","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":"варёные"},{"name":"Ростки маша","quantity":200,"unit":"g","note":""},{"name":"Капуста","quantity":200,"unit":"g","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу в двух литрах воды на слабом огне сорок минут, снимая пену первые десять.\nНарежьте половину шалота тонкими кольцами и обжарьте во фритюре до хруста, отложите на бумагу.\nРастолките оставшийся шалот, чеснок, куркуму, имбирь и орехи в пасту бумбу.\nОбжарьте пасту в масле пять минут с раздавленным лемонграссом и листьями лайма.\nПереложите пасту в бульон, посолите и варите двадцать минут на слабом огне.\nВыньте курицу, разберите на волокна, замочите лапшу и ошпарьте ростки с капустой.\nРазложите по мискам лапшу, курицу, овощи и половинку яйца, залейте бульоном и посыпьте жареным шалотом.","source":"UniTools"},{"id":"ut-salo-po-ukrainski","name":"Сало по-домашнему","country":"Украина","category":"snack","diets":[],"slots":["snack"],"time":30,"baseServings":10,"portionNutrition":{"k":780,"p":6,"f":82,"c":12},"details":[{"name":"Свиное сало","quantity":1.5,"unit":"kg","note":"со спины, со шкурой"},{"name":"Соль крупная","quantity":300,"unit":"g","note":""},{"name":"Чеснок","quantity":2,"unit":"piece","note":"головки"},{"name":"Чёрный перец горошком","quantity":2,"unit":"tbsp","note":""},{"name":"Лавровый лист","quantity":6,"unit":"piece","note":""},{"name":"Кориандр семена","quantity":1,"unit":"tbsp","note":""},{"name":"Паприка","quantity":2,"unit":"tbsp","note":"для обвалки"},{"name":"Ржаной хлеб","quantity":400,"unit":"g","note":"к подаче"}],"steps":"Промойте сало, обсушите насухо и нарежьте пластами шириной десять сантиметров.\nСделайте на каждом пласте глубокие надрезы через два сантиметра, не прорезая шкуру.\nВложите в каждый надрез по пластинке чеснока и горошине перца.\nРаздавите оставшиеся горошины и кориандр и смешайте с солью и раскрошенным лавровым листом.\nОбваляйте пласты в этой смеси со всех сторон, вдавливая её в надрезы.\nУложите в эмалированную посуду шкурой вниз, накройте и уберите в холодильник на неделю.\nСчистите лишнюю соль, обваляйте в паприке и храните в морозильнике. Режьте тонко, подавайте с ржаным хлебом.","source":"UniTools"},{"id":"ut-kyivskyi-tort","name":"Киевский торт","country":"Украина","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":240,"baseServings":12,"portionNutrition":{"k":620,"p":8,"f":38,"c":62},"details":[{"name":"Белки","quantity":8,"unit":"piece","note":"выдержанные сутки"},{"name":"Сахар","quantity":450,"unit":"g","note":""},{"name":"Кешью или фундук","quantity":250,"unit":"g","note":""},{"name":"Мука","quantity":50,"unit":"g","note":""},{"name":"Сливочное масло","quantity":300,"unit":"g","note":""},{"name":"Молоко","quantity":150,"unit":"ml","note":""},{"name":"Желтки","quantity":2,"unit":"piece","note":""},{"name":"Какао-порошок","quantity":20,"unit":"g","note":""},{"name":"Ванильный сахар","quantity":1,"unit":"tsp","note":""},{"name":"Коньяк","quantity":2,"unit":"tbsp","note":""}],"steps":"Оставьте белки в открытой миске при комнатной температуре на двенадцать часов.\nПодсушите орехи в духовке десять минут и порубите крупно, смешайте с мукой и частью сахара.\nВзбейте белки до пены, всыпая оставшийся сахар по ложке, до устойчивых блестящих пиков.\nВмешайте ореховую смесь лопаткой в три приёма и разложите массу по двум формам.\nСушите коржи при 150 °C два часа и оставьте в выключенной духовке до полного остывания.\nСварите сироп из молока, желтков и сахара до густоты, полностью остудите и взбейте с мягким маслом.\nРазделите крем: в большую часть добавьте ваниль и коньяк, в меньшую какао. Соберите торт и охладите шесть часов.","source":"UniTools"},{"id":"ut-chakhokhbili","name":"Чахохбили","country":"Грузия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":75,"baseServings":5,"portionNutrition":{"k":560,"p":46,"f":32,"c":20},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Помидоры","quantity":800,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Кинза","quantity":60,"unit":"g","note":""},{"name":"Базилик фиолетовый","quantity":40,"unit":"g","note":""},{"name":"Эстрагон","quantity":30,"unit":"g","note":""},{"name":"Петрушка","quantity":40,"unit":"g","note":""},{"name":"Хмели-сунели","quantity":1,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте куски курицы в сухой толстостенной кастрюле без масла до румяной корки.\nВыньте мясо, положите сливочное масло и обжарьте лук до мягкости в вытопившемся жире.\nСнимите с помидоров кожицу, натрите их на тёрке и добавьте к луку.\nВерните курицу, посолите, добавьте хмели-сунели и целый чили и накройте крышкой.\nТушите тридцать минут на слабом огне, ни разу не подливая воду.\nПорубите всю зелень и чеснок крупно, но не в кашу.\nВмешайте зелень с чесноком, накройте, снимите с огня и дайте настояться десять минут.","source":"UniTools"},{"id":"ut-satsivi","name":"Сациви","country":"Грузия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":135,"baseServings":8,"portionNutrition":{"k":780,"p":46,"f":58,"c":16},"details":[{"name":"Индейка или курица","quantity":2,"unit":"kg","note":""},{"name":"Грецкие орехи","quantity":700,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Хмели-сунели","quantity":2,"unit":"tbsp","note":""},{"name":"Имеретинский шафран","quantity":1,"unit":"tbsp","note":""},{"name":"Кориандр молотый","quantity":1,"unit":"tbsp","note":""},{"name":"Корица","quantity":0.5,"unit":"tsp","note":""},{"name":"Гвоздика молотая","quantity":0.5,"unit":"tsp","note":""},{"name":"Винный уксус","quantity":3,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите птицу в подсоленной воде час, выньте и запеките при 200 °C двадцать минут до румяности.\nПроцедите бульон, снимите жир и обжарьте в нём мелко нарезанный лук до полной мягкости.\nСмелите орехи дважды и отожмите руками выступившее масло в отдельную чашку.\nРазотрите чеснок с солью и специями и смешайте с ореховой массой.\nРазведите ореховую массу тёплым бульоном до консистенции жидкой сметаны и вмешайте в лук.\nПрогрейте соус двадцать минут на самом слабом огне, не давая закипеть, и вмешайте уксус.\nРазберите птицу на куски, залейте соусом и охладите не меньше шести часов. Полейте ореховым маслом перед подачей.","source":"UniTools"},{"id":"ut-sabich","name":"Сабих","country":"Израиль","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":105,"baseServings":4,"portionNutrition":{"k":620,"p":20,"f":36,"c":52},"details":[{"name":"Баклажаны","quantity":2,"unit":"piece","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Пита","quantity":4,"unit":"piece","note":""},{"name":"Амба","quantity":4,"unit":"tbsp","note":""},{"name":"Тахини","quantity":150,"unit":"g","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Огурцы","quantity":2,"unit":"piece","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Соус жуг","quantity":2,"unit":"tbsp","note":""},{"name":"Масло для жарки","quantity":200,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите яйца при самом слабом кипении час, потом остудите в холодной воде и очистите.\nНарежьте баклажаны кружками в сантиметр, посолите и оставьте под грузом на полчаса.\nОбсушите ломти насухо и обжарьте в масле до тёмно-золотого цвета с обеих сторон.\nВзбейте тахини с лимонным соком, водой и солью до консистенции жидкой сметаны.\nНарежьте помидоры и огурцы мелким кубиком, смешайте с петрушкой, лимоном и солью.\nПрогрейте питы, разрежьте карманом и смажьте изнутри тахини.\nУложите баклажаны, ломтики яйца и салат, полейте амбой, тахини и жугом.","source":"UniTools"},{"id":"ut-malabi","name":"Малаби","country":"Израиль","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":30,"baseServings":6,"portionNutrition":{"k":380,"p":8,"f":18,"c":48},"details":[{"name":"Молоко","quantity":1,"unit":"l","note":""},{"name":"Кукурузный крахмал","quantity":70,"unit":"g","note":""},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Розовая вода","quantity":2,"unit":"tbsp","note":""},{"name":"Сливки","quantity":200,"unit":"ml","note":""},{"name":"Малиновый или гранатовый сироп","quantity":150,"unit":"ml","note":""},{"name":"Фисташки","quantity":80,"unit":"g","note":""},{"name":"Кокосовая стружка","quantity":40,"unit":"g","note":""},{"name":"Арахис","quantity":60,"unit":"g","note":""}],"steps":"Разведите крахмал в стакане холодного молока до полного растворения без комков.\nДоведите остальное молоко со сливками и сахаром до горячего, не давая закипеть.\nВлейте крахмальную смесь тонкой струйкой, непрерывно размешивая венчиком.\nВарите на среднем огне пять минут, пока масса не загустеет до состояния густых сливок.\nСнимите с огня, вмешайте розовую воду и сразу разлейте по стаканам.\nНакройте плёнкой в контакт, чтобы не образовалась плёнка, и охладите четыре часа.\nПеред подачей полейте сиропом и посыпьте рублеными фисташками, арахисом и кокосом.","source":"UniTools"},{"id":"ut-fattet-hummus","name":"Фатте с нутом","country":"Ливан","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":110,"baseServings":5,"portionNutrition":{"k":620,"p":26,"f":34,"c":54},"details":[{"name":"Нут","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Пита","quantity":3,"unit":"piece","note":""},{"name":"Густой йогурт","quantity":700,"unit":"ml","note":""},{"name":"Тахини","quantity":4,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Кедровые орехи","quantity":60,"unit":"g","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Паприка","quantity":1,"unit":"tsp","note":""},{"name":"Масло для жарки","quantity":200,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите нут в несолёной воде полтора часа до полной мягкости, воду сохраните.\nРазорвите питы на куски в два пальца и обжарьте в масле до золотистого хруста.\nВзбейте йогурт с тахини, растёртым чесноком, лимонным соком и солью до гладкости.\nРазведите йогуртовую смесь парой ложек нутового отвара до консистенции густых сливок.\nОбжарьте кедровые орехи в топлёном масле до золотистого и снимите с огня.\nВыложите в блюдо жареный хлеб, сверху горячий нут с ложкой его отвара.\nЗалейте йогуртом, полейте маслом с орехами, посыпьте паприкой и петрушкой и подавайте немедленно.","source":"UniTools"},{"id":"ut-sfiha","name":"Сфиха","country":"Ливан","category":"snack","diets":[],"slots":["snack"],"time":100,"baseServings":6,"portionNutrition":{"k":560,"p":28,"f":28,"c":50},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Вода тёплая","quantity":280,"unit":"ml","note":""},{"name":"Баранина","quantity":600,"unit":"g","note":"фарш"},{"name":"Помидоры","quantity":400,"unit":"g","note":"тёртые"},{"name":"Лук","quantity":2,"unit":"piece","note":"тёртый"},{"name":"Гранатовый соус","quantity":3,"unit":"tbsp","note":""},{"name":"Тахини","quantity":2,"unit":"tbsp","note":""},{"name":"Бахарат","quantity":2,"unit":"tsp","note":""},{"name":"Кедровые орехи","quantity":50,"unit":"g","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Растворите дрожжи в тёплой воде, замесите мягкое тесто с мукой, маслом и солью и вымешивайте десять минут.\nОставьте тесто подходить в тепле час, пока оно не удвоится.\nНатрите помидоры и лук на тёрке и отожмите через сито, оставив немного сока.\nСмешайте фарш с тёртыми овощами, гранатовым соусом, тахини, бахаратом, солью и перцем.\nРазделите тесто на шарики и раскатайте в кружки диаметром десять сантиметров.\nРазложите начинку тонким слоем, оставив полсантиметра по краю, и посыпьте кедровыми орехами.\nПеките при 220 °C восемь минут, пока края не подрумянятся. Подавайте с лимоном.","source":"UniTools"},{"id":"ut-pastilla","name":"Пастилья","country":"Марокко","category":"main","diets":[],"slots":["lunch","dinner"],"time":150,"baseServings":8,"portionNutrition":{"k":720,"p":38,"f":44,"c":46},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Тесто варка или фило","quantity":400,"unit":"g","note":""},{"name":"Миндаль","quantity":250,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Имбирь молотый","quantity":1,"unit":"tsp","note":""},{"name":"Корица","quantity":2,"unit":"tbsp","note":""},{"name":"Сахарная пудра","quantity":100,"unit":"g","note":""},{"name":"Вода флёрдоранж","quantity":2,"unit":"tbsp","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Тушите курицу с луком, шафраном, имбирём, кинзой и небольшим количеством воды час до мягкости.\nВыньте мясо, разберите на волокна и уварите соус с луком до состояния густой пасты.\nВбейте яйца в горячую пасту и мешайте на слабом огне до крупных хлопьев, потом остудите.\nОбжарьте миндаль до золотистого, остудите и смелите с половиной сахарной пудры и ложкой корицы.\nВыстелите форму листами теста внахлёст, смазывая каждый растопленным маслом, с большим запасом по краям.\nУложите яично-луковую массу, сверху мясо, затем миндальный слой, сбрызните флёрдоранжем.\nЗаверните края внутрь, накройте ещё двумя листами, смажьте маслом и пеките при 190 °C сорок минут. Посыпьте пудрой и корицей.","source":"UniTools"},{"id":"ut-chebakia","name":"Марокканский чебакия","country":"Марокко","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":150,"baseServings":10,"portionNutrition":{"k":480,"p":8,"f":22,"c":66},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Кунжут","quantity":200,"unit":"g","note":""},{"name":"Миндаль","quantity":100,"unit":"g","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Анис","quantity":1,"unit":"tbsp","note":""},{"name":"Корица","quantity":1,"unit":"tbsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Вода флёрдоранж","quantity":60,"unit":"ml","note":""},{"name":"Уксус","quantity":1,"unit":"tbsp","note":""},{"name":"Сухие дрожжи","quantity":5,"unit":"g","note":""},{"name":"Мёд","quantity":800,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":1.5,"unit":"l","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Обжарьте сто пятьдесят граммов кунжута и миндаль на сухой сковороде и смелите в грубую пасту.\nСмешайте муку с ореховой пастой, анисом, корицей, шафраном, дрожжами и солью.\nДобавьте растопленное масло, флёрдоранж, уксус и тёплую воду и вымешивайте пятнадцать минут до гладкости.\nДайте тесту отдохнуть час под плёнкой.\nРаскатайте тонко, нарежьте прямоугольниками, сделайте в каждом четыре продольных надреза.\nПроденьте пальцы через надрезы через один и сверните заготовку в форму цветка, защипнув концы.\nЖарьте при 165 °C по четыре минуты до золотистого, сразу опускайте в тёплый мёд на пять минут и посыпайте кунжутом.","source":"UniTools"},{"id":"ut-molokhia","name":"Молохия","country":"Египет","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":90,"baseServings":5,"portionNutrition":{"k":520,"p":40,"f":22,"c":42},"details":[{"name":"Листья молохии","quantity":500,"unit":"g","note":"свежие или замороженные"},{"name":"Курица","quantity":1.2,"unit":"kg","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Кориандр молотый","quantity":2,"unit":"tbsp","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Кардамон","quantity":4,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Лимон","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу с луком, кардамоном и лавровым листом сорок пять минут и процедите бульон.\nМелко порубите листья молохии ножом-мезалуной или пробейте блендером до однородной зелёной массы.\nДоведите бульон до кипения, всыпьте листья и сразу убавьте огонь до минимума.\nДержите суп на грани кипения десять минут, помешивая, — он должен загустеть и стать тягучим.\nРазотрите чеснок с солью в пасту и обжарьте её в топлёном масле с кориандром до тёмно-золотого.\nВлейте зажарку в суп — она зашипит — и сразу накройте крышкой на минуту.\nПодавайте с отварным рисом, курицей и лимоном, каждому в отдельной тарелке.","source":"UniTools"},{"id":"ut-kunafa","name":"Кунафа","country":"Египет","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":80,"baseServings":10,"portionNutrition":{"k":680,"p":20,"f":38,"c":68},"details":[{"name":"Тесто катаифи","quantity":500,"unit":"g","note":""},{"name":"Сыр акави или моцарелла","quantity":700,"unit":"g","note":"несолёный"},{"name":"Топлёное масло","quantity":250,"unit":"g","note":""},{"name":"Сахар","quantity":400,"unit":"g","note":""},{"name":"Вода","quantity":250,"unit":"ml","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Розовая вода","quantity":1,"unit":"tbsp","note":""},{"name":"Вода флёрдоранж","quantity":1,"unit":"tbsp","note":""},{"name":"Фисташки","quantity":100,"unit":"g","note":""},{"name":"Краситель оранжевый","quantity":1,"unit":"pinch","note":"по желанию"}],"steps":"Сварите сироп из сахара, воды и лимонного сока десять минут, снимите с огня, добавьте цветочные воды и полностью остудите.\nВымочите солёный сыр в холодной воде два часа, меняя воду трижды, и нарежьте кубиками.\nРазберите тесто катаифи руками на отдельные нити и нарежьте ножницами покороче.\nПолейте тесто растопленным топлёным маслом и перетрите руками, пока каждая нить не заблестит.\nУтрамбуйте половину теста в смазанную форму, разложите сыр, не доходя до краёв, и накройте второй половиной.\nПеките при 190 °C сорок минут до глубокого золотистого цвета снизу — проверяйте, приподняв край лопаткой.\nПереверните на блюдо, залейте холодным сиропом сразу и посыпьте молотыми фисташками.","source":"UniTools"},{"id":"ut-asado-argentino","name":"Асадо","country":"Аргентина","category":"main","diets":[],"slots":["lunch","dinner"],"time":255,"baseServings":8,"portionNutrition":{"k":880,"p":62,"f":62,"c":18},"details":[{"name":"Говяжьи рёбра","quantity":2.5,"unit":"kg","note":"поперечной нарезки"},{"name":"Вырезка или пашина","quantity":1.5,"unit":"kg","note":""},{"name":"Колбаски чорисо","quantity":800,"unit":"g","note":""},{"name":"Кровяная колбаса морсилья","quantity":500,"unit":"g","note":""},{"name":"Соль крупная","quantity":100,"unit":"g","note":""},{"name":"Петрушка","quantity":80,"unit":"g","note":"для чимичурри"},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Орегано сушёный","quantity":2,"unit":"tbsp","note":""},{"name":"Красный винный уксус","quantity":100,"unit":"ml","note":""},{"name":"Оливковое масло","quantity":200,"unit":"ml","note":""},{"name":"Хлопья чили","quantity":1,"unit":"tbsp","note":""},{"name":"Хлеб","quantity":500,"unit":"g","note":"к подаче"}],"steps":"Разожгите дрова в стороне от решётки и дайте им прогореть до углей, минут сорок.\nСмешайте петрушку, чеснок, орегано, уксус, масло и хлопья чили — чимичурри должен постоять час.\nПодгребите тонкий слой углей под часть решётки и положите колбаски — они идут первыми.\nПосолите рёбра крупной солью со всех сторон и уложите костью вниз на умеренный жар.\nЖарьте рёбра костью вниз два часа, подгребая угли так, чтобы ладонь над решёткой держалась семь секунд.\nПереверните рёбра и дайте им сорок минут мясом вниз до корки.\nДобавьте пашину на последние двадцать минут, дайте мясу отдохнуть десять и подавайте с чимичурри.","source":"UniTools"},{"id":"ut-alfajores","name":"Альфахорес","country":"Аргентина","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":75,"baseServings":10,"portionNutrition":{"k":420,"p":5,"f":20,"c":56},"details":[{"name":"Кукурузный крахмал","quantity":300,"unit":"g","note":""},{"name":"Мука","quantity":200,"unit":"g","note":""},{"name":"Сливочное масло","quantity":200,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":150,"unit":"g","note":""},{"name":"Желтки","quantity":3,"unit":"piece","note":""},{"name":"Разрыхлитель","quantity":1,"unit":"tsp","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Коньяк","quantity":1,"unit":"tbsp","note":""},{"name":"Дульсе де лече","quantity":500,"unit":"g","note":""},{"name":"Кокосовая стружка","quantity":100,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Взбейте мягкое масло с сахарной пудрой добела, минуты четыре.\nВведите желтки по одному, затем ваниль, цедру и коньяк.\nПросейте крахмал с мукой, разрыхлителем и солью и вмешайте лопаткой, не вымешивая долго.\nЗаверните тесто в плёнку и уберите в холодильник на час.\nРаскатайте до толщины полсантиметра и вырежьте кружки диаметром четыре сантиметра.\nПеките при 170 °C двенадцать минут — коржики должны остаться бледными, лишь низ слегка золотится.\nПолностью остудите, соедините попарно дульсе де лече и обваляйте бока в кокосовой стружке.","source":"UniTools"},{"id":"ut-tafelspitz","name":"Тафельшпиц","country":"Австрия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":210,"baseServings":6,"portionNutrition":{"k":680,"p":58,"f":32,"c":38},"details":[{"name":"Говяжий огузок","quantity":1.8,"unit":"kg","note":"одним куском"},{"name":"Мозговые кости","quantity":500,"unit":"g","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Корень сельдерея","quantity":200,"unit":"g","note":""},{"name":"Лук-порей","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Чёрный перец горошком","quantity":10,"unit":"piece","note":""},{"name":"Хрен тёртый","quantity":100,"unit":"g","note":""},{"name":"Яблоки","quantity":2,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":30,"unit":"g","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Вскипятите три литра воды с кореньями, лавровым листом и перцем и опустите мясо в кипяток.\nСнимите пену и держите на грани кипения два с половиной часа, ни разу не давая забурлить.\nРазрежьте луковицы пополам и обожгите срезом на сухой сковороде до чёрного — они дадут бульону цвет.\nДобавьте обожжённый лук и мозговые кости в кастрюлю на последний час.\nНатрите яблоки и смешайте с хреном — это апфелькрен, и делать его нужно перед подачей.\nОтварите картофель, нарежьте кружками и обжарьте в масле до румяности.\nНарежьте мясо поперёк волокон, подайте бульон отдельно, мясо — с хреном, картофелем и зелёным луком.","source":"UniTools"},{"id":"ut-sachertorte","name":"Захер","country":"Австрия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":120,"baseServings":12,"portionNutrition":{"k":520,"p":7,"f":28,"c":62},"details":[{"name":"Тёмный шоколад","quantity":130,"unit":"g","note":"для бисквита"},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":110,"unit":"g","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Сахар","quantity":110,"unit":"g","note":""},{"name":"Мука","quantity":140,"unit":"g","note":""},{"name":"Абрикосовый конфитюр","quantity":250,"unit":"g","note":""},{"name":"Шоколад для глазури","quantity":200,"unit":"g","note":""},{"name":"Сахар для глазури","quantity":250,"unit":"g","note":""},{"name":"Вода","quantity":150,"unit":"ml","note":""},{"name":"Сливки","quantity":250,"unit":"ml","note":"к подаче"},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""}],"steps":"Растопите шоколад для бисквита на водяной бане и остудите до тёплого.\nВзбейте масло с сахарной пудрой и ванилью добела, введите желтки по одному, затем шоколад.\nВзбейте белки с сахаром до устойчивых пиков и вмешайте лопаткой попеременно с просеянной мукой.\nПеките при 170 °C сорок пять минут, первые пятнадцать с приоткрытой дверцей духовки.\nПолностью остудите, разрежьте бисквит на два коржа и промажьте протёртым тёплым конфитюром, обмазав и бока.\nСварите сироп из сахара и воды до 108 °C, снимите с огня и вмешайте шоколад до гладкости.\nОстудите глазурь до густоты сливок, вылейте на центр торта и распределите покачиванием. Дайте застыть два часа.","source":"UniTools"},{"id":"ut-halaszle","name":"Халасле","country":"Венгрия","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":480,"p":46,"f":14,"c":38},"details":[{"name":"Карп","quantity":1.5,"unit":"kg","note":"стейками"},{"name":"Мелкая речная рыба","quantity":800,"unit":"g","note":"для бульона"},{"name":"Лук","quantity":800,"unit":"g","note":""},{"name":"Паприка сладкая молотая","quantity":4,"unit":"tbsp","note":""},{"name":"Паприка острая","quantity":1,"unit":"tsp","note":""},{"name":"Острый перец","quantity":1,"unit":"piece","note":""},{"name":"Помидор","quantity":1,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Икра или молоки","quantity":150,"unit":"g","note":"по желанию"},{"name":"Белый хлеб","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте карпа стейками, посолите и уберите в холод на час — соль уплотнит мясо.\nСложите в котелок мелкую рыбу, головы, хребты и весь нарезанный лук и залейте водой.\nВарите час на среднем огне, пока рыба и лук полностью не разварятся.\nПротрите отвар через сито, вдавливая мякоть, и верните в котелок. Кости выбросьте.\nСнимите котелок с огня и вмешайте оба вида паприки, размешав до однородного цвета.\nВерните на огонь, добавьте помидор, перец и острый стручок и доведите до кипения.\nОпустите стейки карпа и икру и варите двенадцать минут, только покачивая котелок. Подавайте с белым хлебом.","source":"UniTools"},{"id":"ut-dobos-torta","name":"Торт Добош","country":"Венгрия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":135,"baseServings":12,"portionNutrition":{"k":560,"p":8,"f":34,"c":58},"details":[{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Сахар","quantity":150,"unit":"g","note":""},{"name":"Мука","quantity":150,"unit":"g","note":""},{"name":"Сливочное масло","quantity":250,"unit":"g","note":""},{"name":"Тёмный шоколад","quantity":200,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":150,"unit":"g","note":""},{"name":"Яйца для крема","quantity":2,"unit":"piece","note":""},{"name":"Сахар для карамели","quantity":200,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Фундук","quantity":100,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Взбейте яйца с сахаром на водяной бане до тёплого, затем миксером восемь минут до плотной пены.\nВмешайте просеянную муку лопаткой в три приёма, стараясь не осадить массу.\nНачертите на пергаменте шесть кругов и размажьте по каждому тонкий слой теста.\nПеките коржи при 200 °C по шесть минут до золотистых краёв и сразу снимайте с пергамента.\nВзбейте яйца с сахарной пудрой на водяной бане до густоты, остудите и соедините с мягким маслом и растопленным шоколадом.\nРастопите сахар для карамели с лимонным соком до янтарного и вылейте на самый ровный корж.\nРазрежьте карамельный корж горячим смазанным ножом на двенадцать секторов, соберите торт и уложите сектора сверху.","source":"UniTools"},{"id":"ut-vepro-knedlo-zelo","name":"Вепрево колено с кнедликами","country":"Чехия","category":"main","diets":[],"slots":["lunch","dinner"],"time":180,"baseServings":6,"portionNutrition":{"k":820,"p":48,"f":40,"c":68},"details":[{"name":"Свиная лопатка","quantity":1.5,"unit":"kg","note":""},{"name":"Мука","quantity":500,"unit":"g","note":"для кнедликов"},{"name":"Молоко","quantity":250,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Чёрствый хлеб","quantity":150,"unit":"g","note":"кубиками"},{"name":"Квашеная капуста","quantity":700,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Тмин","quantity":2,"unit":"tsp","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Смалец","quantity":60,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите свинину солью, перцем, тмином и чесноком и оставьте на час при комнатной температуре.\nОбжарьте мясо в смальце со всех сторон, добавьте лук и залейте водой до половины куска.\nТушите под крышкой при 160 °C полтора часа, поливая соком каждые двадцать минут.\nЗамесите тесто из муки, тёплого молока с дрожжами, яйца и соли и дайте подойти сорок минут.\nВмешайте кубики чёрствого хлеба, сформуйте два батона и варите в кипятке по десять минут с каждой стороны.\nПотушите квашеную капусту с луком, тмином и сахаром двадцать пять минут.\nНарежьте кнедлики ниткой, мясо ломтями и подайте с капустой, полив соусом из формы.","source":"UniTools"},{"id":"ut-kulajda","name":"Кулайда","country":"Чехия","category":"soup","diets":["vegetarian"],"slots":["lunch","dinner"],"time":55,"baseServings":5,"portionNutrition":{"k":420,"p":14,"f":26,"c":34},"details":[{"name":"Лесные грибы","quantity":400,"unit":"g","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Сметана","quantity":300,"unit":"ml","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Укроп","quantity":50,"unit":"g","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":""},{"name":"Уксус","quantity":3,"unit":"tbsp","note":""},{"name":"Тмин","quantity":1,"unit":"tsp","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите нарезанный картофель в полутора литрах воды с тмином и лавровым листом пятнадцать минут.\nОбжарьте нарезанные грибы в масле до испарения их воды и добавьте в кастрюлю.\nПроварите вместе десять минут, чтобы грибы отдали вкус бульону.\nРазмешайте сметану с мукой до однородности без комков.\nСнимите суп с огня, вмешайте сметанную смесь, верните на слабый огонь и прогрейте пять минут не кипятя.\nДобавьте уксус, сахар, соль, перец и почти весь укроп и попробуйте на баланс кислого и сливочного.\nСварите яйца-пашот в подкисленной воде и опустите по одному в каждую тарелку, посыпав оставшимся укропом.","source":"UniTools"},{"id":"ut-toast-skagen","name":"Тост Скаген","country":"Швеция","category":"snack","diets":["pescatarian"],"slots":["snack"],"time":30,"baseServings":4,"portionNutrition":{"k":480,"p":28,"f":32,"c":20},"details":[{"name":"Мелкие креветки","quantity":500,"unit":"g","note":"очищенные"},{"name":"Майонез","quantity":150,"unit":"g","note":""},{"name":"Сметана","quantity":100,"unit":"ml","note":""},{"name":"Укроп","quantity":40,"unit":"g","note":""},{"name":"Лук красный","quantity":1,"unit":"piece","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Белый хлеб","quantity":4,"unit":"slice","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Икра сиговая или форелевая","quantity":80,"unit":"g","note":""},{"name":"Хрен тёртый","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Откиньте креветки на сито и дайте им стечь не меньше десяти минут.\nСмешайте майонез со сметаной, рубленым укропом, хреном, соком лимона, солью и перцем.\nНарежьте красный лук как можно мельче и вмешайте в заправку.\nАккуратно соедините креветки с заправкой, стараясь их не размять.\nОбрежьте с хлеба корки и обжарьте ломти в сливочном масле до румяности с обеих сторон.\nВыложите на каждый тост горку креветок, сверху ложку икры и веточку укропа. Подавайте сразу.","source":"UniTools"},{"id":"ut-appelkaka","name":"Шведский яблочный пирог","country":"Швеция","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":75,"baseServings":8,"portionNutrition":{"k":520,"p":7,"f":28,"c":62},"details":[{"name":"Яблоки кислых сортов","quantity":1,"unit":"kg","note":""},{"name":"Мука","quantity":200,"unit":"g","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":"холодное"},{"name":"Сахар","quantity":150,"unit":"g","note":""},{"name":"Корица","quantity":2,"unit":"tsp","note":""},{"name":"Овсяные хлопья","quantity":80,"unit":"g","note":""},{"name":"Молоко","quantity":300,"unit":"ml","note":"для соуса"},{"name":"Сливки","quantity":200,"unit":"ml","note":"для соуса"},{"name":"Желтки","quantity":4,"unit":"piece","note":""},{"name":"Ваниль","quantity":1,"unit":"piece","note":""},{"name":"Кукурузный крахмал","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Очистите яблоки, нарежьте толстыми дольками и разложите в смазанной форме.\nПосыпьте яблоки половиной сахара и корицей и слегка перемешайте прямо в форме.\nРазотрите холодное масло с мукой, оставшимся сахаром и солью кончиками пальцев в крупную крошку.\nВмешайте овсяные хлопья и распределите крошку по яблокам, не приминая её.\nПеките при 190 °C сорок минут, пока верх не станет золотистым, а сок не начнёт булькать по краям.\nПрогрейте молоко со сливками и стручком ванили, не доводя до кипения.\nВзбейте желтки с крахмалом, вводите горячее молоко тонкой струйкой и варите соус до густоты, помешивая.","source":"UniTools"},{"id":"ut-stegt-flaesk","name":"Стегт флеск","country":"Дания","category":"main","diets":[],"slots":["lunch","dinner"],"time":60,"baseServings":4,"portionNutrition":{"k":880,"p":36,"f":62,"c":44},"details":[{"name":"Свиная грудинка","quantity":900,"unit":"g","note":"ломтями по 5 мм"},{"name":"Картофель","quantity":1,"unit":"kg","note":""},{"name":"Молоко","quantity":500,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Мука","quantity":50,"unit":"g","note":""},{"name":"Петрушка","quantity":100,"unit":"g","note":""},{"name":"Мускатный орех","quantity":0.5,"unit":"tsp","note":""},{"name":"Маринованная свёкла","quantity":200,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обсушите ломти грудинки бумагой и посолите с обеих сторон.\nВыложите на холодную сухую сковороду в один слой и включите средний огонь.\nЖарьте по восемь минут с каждой стороны, сливая вытопившийся жир в чашку.\nОтварите картофель в мундире до мягкости и очистите горячим.\nРастопите масло, вмешайте муку и прогрейте две минуты, не давая ей потемнеть.\nВлейте молоко тонкой струйкой, размешивая до гладкости, и варите соус пять минут.\nВмешайте гору рубленой петрушки, мускатный орех, соль и перец и подавайте с грудинкой, картофелем и свёклой.","source":"UniTools"},{"id":"ut-risalamande","name":"Рисаламанде","country":"Дания","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":85,"baseServings":8,"portionNutrition":{"k":560,"p":11,"f":34,"c":54},"details":[{"name":"Рис круглозёрный","quantity":200,"unit":"g","note":""},{"name":"Молоко","quantity":1,"unit":"l","note":""},{"name":"Сливки 33%","quantity":500,"unit":"ml","note":""},{"name":"Миндаль","quantity":150,"unit":"g","note":"очищенный"},{"name":"Сахар","quantity":80,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"piece","note":""},{"name":"Вишня","quantity":500,"unit":"g","note":"без косточек"},{"name":"Сахар для соуса","quantity":80,"unit":"g","note":""},{"name":"Кукурузный крахмал","quantity":2,"unit":"tsp","note":""},{"name":"Херес","quantity":2,"unit":"tbsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Промойте рис, залейте молоком с ванилью и солью и варите час на самом слабом огне, помешивая.\nОстудите кашу полностью — лучше поставить миску в холодную воду и мешать, чтобы не образовалась плёнка.\nОшпарьте миндаль, снимите шкурку и порубите крупно, оставив один орех целым.\nВмешайте в холодную кашу рубленый миндаль, сахар и херес.\nВзбейте сливки до мягких пиков и вмешайте лопаткой в три приёма, не осаживая.\nСпрячьте целый миндаль в массе и охладите пудинг не меньше трёх часов.\nПроварите вишню с сахаром десять минут, загустите разведённым крахмалом и подавайте соус горячим.","source":"UniTools"},{"id":"ut-erwtensoep","name":"Эртенсуп","country":"Нидерланды","category":"soup","diets":[],"slots":["lunch","dinner"],"time":175,"baseServings":6,"portionNutrition":{"k":680,"p":40,"f":32,"c":58},"details":[{"name":"Горох колотый","quantity":500,"unit":"g","note":""},{"name":"Свиные рёбрышки","quantity":500,"unit":"g","note":""},{"name":"Свиная грудинка","quantity":300,"unit":"g","note":""},{"name":"Копчёная колбаса рукворст","quantity":400,"unit":"g","note":""},{"name":"Корень сельдерея","quantity":300,"unit":"g","note":""},{"name":"Лук-порей","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Листья сельдерея","quantity":30,"unit":"g","note":""},{"name":"Ржаной хлеб","quantity":300,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте горох и залейте вместе с рёбрышками и грудинкой двумя с половиной литрами холодной воды.\nДоведите до кипения, снимите пену и варите на слабом огне час, пока горох не начнёт распадаться.\nДобавьте картофель, морковь, сельдерей и лук и варите ещё час, помешивая, чтобы не пригорело.\nВыньте мясо, снимите с костей и верните в суп кусками.\nДобавьте нарезанный порей и листья сельдерея и проварите двадцать минут.\nПолностью остудите и оставьте на ночь в холодильнике — суп загустеет.\nРазогрейте, положите нарезанную колбасу на пять минут и подавайте с ржаным хлебом.","source":"UniTools"},{"id":"ut-bitterballen","name":"Биттербаллен","country":"Нидерланды","category":"snack","diets":[],"slots":["snack"],"time":100,"baseServings":8,"portionNutrition":{"k":520,"p":24,"f":30,"c":38},"details":[{"name":"Говядина","quantity":500,"unit":"g","note":"для тушения"},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Мука","quantity":120,"unit":"g","note":""},{"name":"Говяжий бульон","quantity":600,"unit":"ml","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Мускатный орех","quantity":0.5,"unit":"tsp","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Панировочные сухари","quantity":250,"unit":"g","note":""},{"name":"Горчица","quantity":100,"unit":"g","note":"к подаче"},{"name":"Масло для фритюра","quantity":1.5,"unit":"l","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите говядину в бульоне полтора часа до полной мягкости и разберите на мелкие волокна.\nОбжарьте лук в масле, всыпьте муку и прогрейте три минуты, не давая ей потемнеть.\nВлейте горячий бульон тонкой струйкой и варите до состояния очень густой пасты, минут десять.\nВмешайте мясо, петрушку, мускатный орех, соль и перец, разровняйте в форме и охладите четыре часа.\nСкатайте из застывшей массы шарики размером с грецкий орех влажными руками.\nОбваляйте в муке, яйце и сухарях, охладите двадцать минут, затем повторите яйцо и сухари.\nЖарьте при 180 °C по три минуты до тёмно-золотого цвета и подавайте с горчицей.","source":"UniTools"},{"id":"ut-colcannon","name":"Колканнон","country":"Ирландия","category":"side","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":55,"baseServings":6,"portionNutrition":{"k":420,"p":8,"f":26,"c":42},"details":[{"name":"Картофель","quantity":1.2,"unit":"kg","note":"мучнистых сортов"},{"name":"Капуста или кале","quantity":500,"unit":"g","note":""},{"name":"Зелёный лук","quantity":8,"unit":"piece","note":""},{"name":"Молоко","quantity":250,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Сливки","quantity":100,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите картофель в мундире в подсоленной воде до полной мягкости, двадцать пять минут.\nПрогрейте молоко со сливками и нарезанным зелёным луком до горячего и оставьте настаиваться десять минут.\nНашинкуйте капусту и потушите в половине масла восемь минут до мягкости.\nОчистите картофель горячим и разомните толкушкой, не используя блендер.\nПроцедите горячее молоко в пюре и вымешайте до гладкости, посолите и поперчите.\nВмешайте тушёную капусту и настоянный зелёный лук из молока.\nВыложите горкой, сделайте в центре углубление и положите туда оставшееся масло.","source":"UniTools"},{"id":"ut-guinness-beef-stew","name":"Говядина в тёмном пиве","country":"Ирландия","category":"main","diets":[],"slots":["lunch","dinner"],"time":210,"baseServings":6,"portionNutrition":{"k":720,"p":52,"f":30,"c":52},"details":[{"name":"Говяжья лопатка","quantity":1.5,"unit":"kg","note":"крупными кусками"},{"name":"Тёмное пиво стаут","quantity":500,"unit":"ml","note":""},{"name":"Мука","quantity":60,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Морковь","quantity":4,"unit":"piece","note":""},{"name":"Картофель","quantity":700,"unit":"g","note":""},{"name":"Пастернак","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Говяжий бульон","quantity":400,"unit":"ml","note":""},{"name":"Тимьян","quantity":4,"unit":"sprig","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Мёд","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обсушите мясо, посолите, поперчите и обваляйте в муке со всех сторон.\nОбжарьте мясо порциями в раскалённом масле до тёмной корки и выньте.\nОбжарьте лук в том же жире до мягкости, добавьте томатную пасту и прогрейте три минуты.\nВлейте пиво, доведите до кипения и соскребите со дна всё пригоревшее — в нём весь вкус.\nВерните мясо, добавьте бульон, тимьян и лавровый лист и тушите под крышкой два часа при 160 °C.\nЗаложите морковь, пастернак и картофель и тушите ещё сорок пять минут.\nВмешайте мёд, попробуйте на баланс горечи и подавайте с содовым хлебом.","source":"UniTools"},{"id":"ut-shurpa","name":"Шурпа","country":"Узбекистан","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":145,"baseServings":6,"portionNutrition":{"k":520,"p":38,"f":24,"c":38},"details":[{"name":"Баранина на кости","quantity":1.2,"unit":"kg","note":""},{"name":"Картофель","quantity":6,"unit":"piece","note":"целиком"},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Нут","quantity":100,"unit":"g","note":"замочить на ночь"},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Райхон","quantity":20,"unit":"g","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте баранину тремя литрами холодной воды и медленно доведите до кипения.\nСнимайте пену первые двадцать минут, не давая бульону забурлить.\nДобавьте нут и варите на слабом огне сорок минут.\nЗаложите морковь пополам вдоль и лук четвертинками и варите двадцать минут.\nПоложите картофель целиком, помидоры и перец и варите ещё двадцать пять минут.\nВсыпьте зиру, посолите, положите целый чили и снимите с огня через пять минут.\nРазложите мясо и овощи по тарелкам, залейте бульоном и засыпьте горой рубленой зелени.","source":"UniTools"},{"id":"ut-chuchvara","name":"Чучвара","country":"Узбекистан","category":"soup","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":5,"portionNutrition":{"k":560,"p":28,"f":22,"c":62},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Вода","quantity":200,"unit":"ml","note":""},{"name":"Баранина","quantity":400,"unit":"g","note":"рубить ножом"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Мясной бульон","quantity":2,"unit":"l","note":""},{"name":"Сузьма или густой йогурт","quantity":300,"unit":"ml","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, яйца, воды и соли и вымешивайте пятнадцать минут.\nНакройте тесто и оставьте отдыхать сорок минут при комнатной температуре.\nПорубите баранину ножом мелко, смешайте с тёртым луком, зирой, солью и перцем.\nРаскатайте тесто в пласт толщиной в миллиметр и нарежьте квадратами по три сантиметра.\nПоложите на квадрат начинку с горошину, сложите треугольником и соедините два угла кольцом.\nДоведите бульон до кипения с помидорами и целым чили и опустите чучвару порциями.\nВарите пять минут после всплытия, разложите по пиалам с бульоном, добавьте сузьму и кинзу.","source":"UniTools"},{"id":"ut-armenian-tolma","name":"Пасуц толма","country":"Армения","category":"main","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":150,"baseServings":8,"portionNutrition":{"k":420,"p":16,"f":14,"c":58},"details":[{"name":"Листья квашеной капусты","quantity":800,"unit":"g","note":""},{"name":"Красная фасоль","quantity":150,"unit":"g","note":"замочить на ночь"},{"name":"Чечевица","quantity":150,"unit":"g","note":""},{"name":"Нут","quantity":100,"unit":"g","note":"замочить на ночь"},{"name":"Дроблёная пшеница","quantity":100,"unit":"g","note":""},{"name":"Рис","quantity":100,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите фасоль, нут и чечевицу по отдельности до мягкости — у каждой свой срок.\nОтварите дроблёную пшеницу и рис до полуготовности и откиньте.\nОбжарьте нарезанный лук в масле до золотистого, добавьте томатную пасту и паприку.\nСоедините все крупы и бобовые с луком, посолите, поперчите и вмешайте кинзу.\nПромойте капустные листья от лишнего рассола и срежьте толстые прожилки.\nЗаверните начинку в листья плотными свёртками, укладывая их слоями в кастрюлю.\nЗалейте водой до уровня верхнего слоя, накройте тарелкой с грузом и варите час на слабом огне. Полностью остудите.","source":"UniTools"},{"id":"ut-gata","name":"Гата","country":"Армения","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":115,"baseServings":10,"portionNutrition":{"k":520,"p":7,"f":28,"c":62},"details":[{"name":"Мука для теста","quantity":500,"unit":"g","note":""},{"name":"Сливочное масло","quantity":200,"unit":"g","note":""},{"name":"Сметана","quantity":200,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":5,"unit":"g","note":""},{"name":"Мука для начинки","quantity":250,"unit":"g","note":""},{"name":"Масло для начинки","quantity":150,"unit":"g","note":""},{"name":"Сахар","quantity":200,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Желток","quantity":1,"unit":"piece","note":"для смазки"},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Замесите тесто из муки, размягчённого масла, сметаны, дрожжей и соли и вымешивайте десять минут.\nЗаверните тесто в плёнку и охладите час.\nРазотрите муку для начинки с холодным маслом, сахаром и ванилью до влажной крошки.\nРаскатайте тесто прямоугольником, смажьте маслом, сложите втрое и охладите двадцать минут.\nПовторите раскатку и складывание ещё раз, потом раскатайте в пласт толщиной в сантиметр.\nРаспределите начинку по половине пласта, накройте второй половиной и защипните края.\nНанесите узор вилкой, смажьте желтком и пеките при 180 °C сорок минут до тёмно-золотого цвета.","source":"UniTools"},{"id":"ut-nasi-lemak","name":"Наси лемак","country":"Малайзия","category":"breakfast","diets":[],"slots":["breakfast"],"time":85,"baseServings":5,"portionNutrition":{"k":720,"p":26,"f":34,"c":82},"details":[{"name":"Рис жасминовый","quantity":500,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Лист пандана","quantity":2,"unit":"piece","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Сушёный чили","quantity":15,"unit":"piece","note":""},{"name":"Шалот","quantity":8,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Креветочная паста белачан","quantity":2,"unit":"tsp","note":""},{"name":"Тамариндовая паста","quantity":2,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Сушёные анчоусы икан билис","quantity":100,"unit":"g","note":""},{"name":"Арахис","quantity":100,"unit":"g","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":""},{"name":"Огурец","quantity":1,"unit":"piece","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рис до прозрачной воды и залейте кокосовым молоком, разбавленным водой, с солью и панданом.\nДобавьте ломтики имбиря и варите под крышкой пятнадцать минут, затем дайте постоять десять.\nЗамочите сушёный чили в кипятке двадцать минут и пробейте с шалотом, чесноком и белачаном в пасту.\nОбжаривайте пасту в масле двадцать минут на среднем огне, пока масло не выступит по краям.\nДобавьте тамаринд, пальмовый сахар и соль и потушите самбал ещё десять минут до густоты.\nОбжарьте анчоусы и арахис по отдельности до хруста и отварите яйца вкрутую.\nСоберите тарелку: горка риса, ложка самбала, анчоусы, арахис, половинка яйца и ломтики огурца.","source":"UniTools"},{"id":"ut-char-kway-teow","name":"Чар квай теу","country":"Малайзия","category":"main","diets":[],"slots":["lunch","dinner"],"time":35,"baseServings":2,"portionNutrition":{"k":780,"p":36,"f":34,"c":84},"details":[{"name":"Широкая рисовая лапша","quantity":400,"unit":"g","note":"свежая"},{"name":"Креветки","quantity":200,"unit":"g","note":""},{"name":"Ракушки или кальмар","quantity":150,"unit":"g","note":""},{"name":"Китайская колбаса лап чонг","quantity":80,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Ростки маша","quantity":150,"unit":"g","note":""},{"name":"Китайский лук-чеснок","quantity":60,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Тёмный соевый соус","quantity":1,"unit":"tbsp","note":""},{"name":"Светлый соевый соус","quantity":2,"unit":"tbsp","note":""},{"name":"Самбал","quantity":1,"unit":"tbsp","note":""},{"name":"Смалец","quantity":3,"unit":"tbsp","note":""},{"name":"Сахар","quantity":1,"unit":"tsp","note":""}],"steps":"Разберите свежую лапшу на отдельные полоски руками, стараясь их не порвать.\nПриготовьте все ингредиенты и соусы рядом с плитой — на готовку уйдёт четыре минуты, и отвлекаться будет некогда.\nРаскалите вок до дымка, растопите смалец и обжарьте чеснок и колбасу двадцать секунд.\nДобавьте креветки и ракушки и жарьте тридцать секунд, не перемешивая постоянно.\nСдвиньте всё к краю, разбейте яйца в центр и дайте им схватиться десять секунд, потом разбейте лопаткой.\nВсыпьте лапшу, влейте оба соевых соуса, самбал и сахар и жарьте, подбрасывая, полторы минуты.\nБросьте ростки и зелёный лук, перемешайте двадцать секунд и подавайте немедленно.","source":"UniTools"},{"id":"ut-kare-kare","name":"Каре-каре","country":"Филиппины","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":240,"baseServings":6,"portionNutrition":{"k":820,"p":44,"f":50,"c":48},"details":[{"name":"Говяжий хвост","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Арахисовая паста","quantity":250,"unit":"g","note":"несладкая"},{"name":"Рис","quantity":60,"unit":"g","note":"для обжарки и помола"},{"name":"Семена аннато","quantity":2,"unit":"tbsp","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Баклажаны","quantity":2,"unit":"piece","note":""},{"name":"Спаржевая фасоль","quantity":200,"unit":"g","note":""},{"name":"Пак-чой","quantity":300,"unit":"g","note":""},{"name":"Банановый цвет","quantity":200,"unit":"g","note":"по желанию"},{"name":"Паста багоонг","quantity":150,"unit":"g","note":"к подаче"},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"}],"steps":"Отварите хвост в воде три часа на слабом огне, снимая пену. Бульон сохраните.\nОбжарьте рис на сухой сковороде до коричневого цвета и смелите в мелкий порошок.\nПрогрейте семена аннато в масле три минуты и процедите — окрашенное масло и есть цвет блюда.\nОбжарьте лук и чеснок в ачиотовом масле, добавьте арахисовую пасту и разведите бульоном.\nВмешайте рисовую муку и варите соус пятнадцать минут, помешивая, до густоты сметаны.\nВерните хвост в соус и прогрейте десять минут, чтобы мясо пропиталось.\nОтварите овощи отдельно до упругости, разложите поверх мяса и подавайте с рисом и багоонгом.","source":"UniTools"},{"id":"ut-leche-flan","name":"Лече флан","country":"Филиппины","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":70,"baseServings":8,"portionNutrition":{"k":420,"p":11,"f":16,"c":58},"details":[{"name":"Желтки","quantity":10,"unit":"piece","note":""},{"name":"Сгущённое молоко","quantity":400,"unit":"g","note":""},{"name":"Концентрированное молоко","quantity":370,"unit":"ml","note":""},{"name":"Сахар для карамели","quantity":200,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Вода для карамели","quantity":60,"unit":"ml","note":""}],"steps":"Растопите сахар с водой до янтарной карамели и разлейте по формам, покачивая, чтобы покрыть дно.\nДайте карамели застыть в формах, пока готовите смесь.\nРазотрите желтки венчиком, не взбивая до пены — пузыри воздуха дадут дырки.\nВмешайте оба вида молока, ваниль и цедру, размешивая медленно.\nПроцедите смесь через мелкое сито дважды и снимите пену с поверхности ложкой.\nРазлейте по формам поверх карамели и плотно затяните каждую фольгой.\nГотовьте на пару сорок минут при слабом кипении, охладите четыре часа и переверните на блюдо.","source":"UniTools"},{"id":"ut-injera","name":"Ынджера","country":"Эфиопия","category":"bread","diets":["vegetarian","vegan","gluten-free"],"slots":["breakfast","snack"],"time":70,"baseServings":8,"portionNutrition":{"k":280,"p":9,"f":3,"c":56},"details":[{"name":"Мука тефф","quantity":500,"unit":"g","note":""},{"name":"Вода","quantity":1.2,"unit":"l","note":""},{"name":"Закваска ырша","quantity":100,"unit":"ml","note":"от прошлой партии"},{"name":"Соль","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":20,"unit":"ml","note":""}],"steps":"Смешайте муку тефф с водой до консистенции жидких сливок, без комков.\nНакройте тканью и оставьте при комнатной температуре на три дня, не перемешивая.\nСлейте отстоявшуюся сверху жидкость — она горчит, и оставлять её нельзя.\nОтберите стакан теста, заварите его в кипятке до густой пасты и вмешайте обратно.\nДайте тесту постоять ещё два часа и разведите водой до консистенции очень жидких сливок.\nРазогрейте широкую сковороду, слегка смажьте маслом и вылейте тесто спиралью от края к центру.\nНакройте крышкой на две минуты, пока по всей поверхности не выступят глазки, и снимите не переворачивая.","source":"UniTools"},{"id":"ut-kitfo","name":"Кытфо","country":"Эфиопия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":720,"p":46,"f":54,"c":12},"details":[{"name":"Говяжья вырезка","quantity":700,"unit":"g","note":"очень свежая"},{"name":"Сливочное масло","quantity":200,"unit":"g","note":"для нитер киббе"},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Кардамон","quantity":5,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Пажитник","quantity":1,"unit":"tsp","note":""},{"name":"Смесь мытмыта","quantity":2,"unit":"tbsp","note":""},{"name":"Сыр аиб или творог","quantity":200,"unit":"g","note":""},{"name":"Тушёная зелень","quantity":300,"unit":"g","note":""},{"name":"Ынджера","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Растопите масло на слабом огне с имбирём, чесноком, кардамоном, корицей и пажитником.\nТомите двадцать минут, не давая закипеть, пока пена не осядет и масло не станет прозрачным.\nПроцедите нитер киббе через марлю и держите тёплым.\nСрежьте с мяса все плёнки и жилы и порубите его ножом очень мелко, почти в пасту.\nВмешайте в мясо тёплое нитер киббе, мытмыту и соль, работая руками две минуты.\nПрогрейте массу на сковороде тридцать секунд до температуры тела, не давая ей побелеть.\nПодайте на ынджере с сыром аиб и тушёной зеленью, разложенными рядом.","source":"UniTools"},{"id":"ut-egusi-soup","name":"Суп эгуси","country":"Нигерия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":780,"p":48,"f":54,"c":22},"details":[{"name":"Семена эгуси молотые","quantity":300,"unit":"g","note":""},{"name":"Говядина","quantity":600,"unit":"g","note":"кусками"},{"name":"Вяленая рыба","quantity":200,"unit":"g","note":""},{"name":"Копчёная рыба","quantity":200,"unit":"g","note":""},{"name":"Пальмовое масло","quantity":150,"unit":"ml","note":""},{"name":"Шпинат или листья угву","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец скотч-боннет","quantity":3,"unit":"piece","note":""},{"name":"Молотые сушёные раки","quantity":3,"unit":"tbsp","note":""},{"name":"Бульонный кубик","quantity":2,"unit":"piece","note":""},{"name":"Ферментированные бобы иру","quantity":2,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите говядину с луком, бульонным кубиком и солью сорок минут. Бульон сохраните.\nЗамочите вяленую рыбу в кипятке на двадцать минут и разберите на куски, убрав кости.\nСмешайте молотый эгуси с небольшим количеством воды до густой пасты, которая держит форму.\nПрогрейте пальмовое масло до прозрачности, обжарьте лук и молотый скотч-боннет три минуты.\nОпускайте пасту эгуси в масло ложками, не размешивая, и дайте комкам схватиться пять минут.\nВлейте бульон, добавьте мясо, обе рыбы, раков и бобы иру и варите двадцать минут.\nВмешайте зелень на последние пять минут и подавайте с фуфу или эба.","source":"UniTools"},{"id":"ut-puff-puff","name":"Паф-паф","country":"Нигерия","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":50,"baseServings":8,"portionNutrition":{"k":320,"p":6,"f":12,"c":48},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Вода тёплая","quantity":400,"unit":"ml","note":""},{"name":"Мускатный орех","quantity":0.5,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""},{"name":"Масло для фритюра","quantity":1.5,"unit":"l","note":""},{"name":"Сахарная пудра","quantity":40,"unit":"g","note":"к подаче"}],"steps":"Растворите дрожжи с сахаром в тёплой воде и оставьте на десять минут до появления пены.\nВмешайте муку, мускатный орех и соль венчиком до гладкого жидкого теста без комков.\nНакройте и оставьте в тепле на час — тесто должно удвоиться и покрыться пузырями.\nРазогрейте масло до 170 °C и проверьте каплей теста — она должна всплыть за две секунды.\nНаберите тесто в ладонь и выдавите шарик между большим и указательным пальцем прямо в масло.\nЖарьте по три минуты, переворачивая шумовкой, до ровного золотисто-коричневого цвета.\nВыложите на бумагу и подавайте тёплыми, посыпав сахарной пудрой.","source":"UniTools"},{"id":"ut-arroz-con-pollo-cubano","name":"Аррос кон польо","country":"Куба","category":"main","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":720,"p":44,"f":26,"c":78},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Рис среднезёрный","quantity":500,"unit":"g","note":""},{"name":"Светлое пиво","quantity":350,"unit":"ml","note":""},{"name":"Куриный бульон","quantity":700,"unit":"ml","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Томатный соус","quantity":200,"unit":"ml","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Орегано","quantity":1,"unit":"tsp","note":""},{"name":"Зелёный горошек","quantity":200,"unit":"g","note":""},{"name":"Оливки","quantity":80,"unit":"g","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите курицу солью, перцем, зирой, орегано, чесноком и соком лайма и оставьте на полчаса.\nОбжарьте курицу в оливковом масле до румяной корки со всех сторон и выньте.\nТомите лук, перец и чеснок в том же масле двадцать минут до полной мягкости — это софрито.\nДобавьте томатный соус и шафран, размоченный в ложке тёплой воды, и прогрейте пять минут.\nВерните курицу, влейте пиво и бульон, доведите до кипения и посолите.\nВсыпьте рис ровным слоем, накройте и варите двадцать минут на слабом огне, не перемешивая.\nРазложите сверху горошек и оливки, накройте и дайте постоять десять минут перед подачей.","source":"UniTools"},{"id":"ut-tostones","name":"Тостонес","country":"Куба","category":"snack","diets":["vegetarian","vegan","gluten-free"],"slots":["snack"],"time":40,"baseServings":4,"portionNutrition":{"k":380,"p":3,"f":18,"c":54},"details":[{"name":"Зелёный подорожник","quantity":4,"unit":"piece","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Вода","quantity":500,"unit":"ml","note":""},{"name":"Масло для жарки","quantity":500,"unit":"ml","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Лайм","quantity":1,"unit":"piece","note":""},{"name":"Зира молотая","quantity":0.5,"unit":"tsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Надрежьте кожуру подорожника вдоль и снимите её, поддевая ножом — руками зелёный не очистить.\nНарежьте поперёк кусками в три сантиметра.\nРастолките половину чеснока с солью и разведите в полулитре тёплой воды.\nОбжарьте куски в масле при 160 °C четыре минуты, пока они не станут мягкими, но не золотыми.\nРасплющите каждый кусок дном стакана или прессом до толщины в сантиметр.\nОбмакните лепёшки в чесночную воду на секунду и обсушите бумагой.\nОбжарьте второй раз при 190 °C две минуты до хрустящей корки, посолите и подайте с мохо из оставшегося чеснока, оливкового масла и лайма.","source":"UniTools"},{"id":"ut-jamaican-patty","name":"Ямайские патти","country":"Ямайка","category":"snack","diets":[],"slots":["snack"],"time":120,"baseServings":8,"portionNutrition":{"k":580,"p":24,"f":36,"c":42},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Карри молотое","quantity":1,"unit":"tsp","note":""},{"name":"Смалец или маргарин","quantity":250,"unit":"g","note":"холодный"},{"name":"Ледяная вода","quantity":150,"unit":"ml","note":""},{"name":"Говяжий фарш","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Тимьян","quantity":4,"unit":"sprig","note":""},{"name":"Душистый перец молотый","quantity":1,"unit":"tsp","note":""},{"name":"Панировочные сухари","quantity":60,"unit":"g","note":""},{"name":"Говяжий бульон","quantity":250,"unit":"ml","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Смешайте муку с куркумой, карри и солью и вотрите холодный жир крупными кусками, не растирая в крошку.\nВлейте ледяную воду и соберите тесто в ком, не вымешивая, и охладите полчаса.\nРаскатайте, сложите втрое и повторите ещё дважды, охлаждая между складываниями.\nОбжарьте лук, зелёный лук, тимьян и рубленый скотч-боннет, добавьте фарш и жарьте до готовности.\nВлейте бульон, добавьте душистый перец и сухари и тушите десять минут до сочной, но не жидкой начинки.\nПолностью остудите начинку, раскатайте тесто и вырежьте круги диаметром пятнадцать сантиметров.\nВыложите начинку на половину круга, сложите, защипните вилкой и пеките при 200 °C тридцать минут.","source":"UniTools"},{"id":"ut-rice-and-peas","name":"Райс энд пис","country":"Ямайка","category":"side","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":110,"baseServings":6,"portionNutrition":{"k":480,"p":13,"f":14,"c":76},"details":[{"name":"Красная фасоль","quantity":250,"unit":"g","note":"замочить на ночь"},{"name":"Рис длиннозёрный","quantity":500,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Тимьян","quantity":6,"unit":"sprig","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Душистый перец","quantity":6,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите замоченную фасоль в полутора литрах воды час, пока она не станет мягкой.\nДобавьте кокосовое молоко, чеснок, зелёный лук, тимьян и душистый перец и доведите до кипения.\nПромойте рис до прозрачной воды и всыпьте в кастрюлю, разровняв ложкой.\nПоложите целый скотч-боннет сверху, посолите и убедитесь, что жидкость покрывает рис на палец.\nНакройте и варите двадцать минут на слабом огне, ни разу не открывая крышку.\nСнимите с огня и дайте постоять под крышкой десять минут.\nВыньте перец и веточки тимьяна, разрыхлите рис вилкой и подавайте.","source":"UniTools"},{"id":"ut-ruisleipa","name":"Руислейпя","country":"Финляндия","category":"bread","diets":["vegetarian","vegan"],"slots":["breakfast","snack"],"time":100,"baseServings":12,"portionNutrition":{"k":240,"p":7,"f":2,"c":48},"details":[{"name":"Ржаная мука","quantity":900,"unit":"g","note":""},{"name":"Ржаная закваска","quantity":200,"unit":"g","note":""},{"name":"Вода тёплая","quantity":700,"unit":"ml","note":""},{"name":"Соль","quantity":20,"unit":"g","note":""},{"name":"Ржаной солод","quantity":30,"unit":"g","note":"по желанию"},{"name":"Тмин","quantity":1,"unit":"tbsp","note":"по желанию"}],"steps":"Смешайте закваску с половиной воды и половиной муки и оставьте на ночь при комнатной температуре.\nУтром отберите двести граммов опары обратно в банку — это закваска на следующий раз.\nВмешайте оставшуюся муку, воду, соль, солод и тмин деревянной ложкой до однородности.\nНакройте и оставьте подходить три часа — тесто увеличится примерно вдвое и покроется трещинами.\nВыложите тесто мокрыми руками в смазанные формы, разровняв верх мокрой ложкой.\nДайте расстояться час, наколите верх вилкой в нескольких местах.\nПеките при 250 °C пятнадцать минут, потом при 180 °C ещё сорок пять и выдержите сутки перед нарезкой.","source":"UniTools"},{"id":"ut-poronkaristys","name":"Поронкяристюс","country":"Финляндия","category":"main","diets":[],"slots":["lunch","dinner"],"time":65,"baseServings":4,"portionNutrition":{"k":620,"p":46,"f":28,"c":42},"details":[{"name":"Оленина","quantity":700,"unit":"g","note":"замороженная, строганая"},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Тёмное пиво","quantity":250,"unit":"ml","note":""},{"name":"Вода","quantity":200,"unit":"ml","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Картофель","quantity":1,"unit":"kg","note":""},{"name":"Молоко","quantity":200,"unit":"ml","note":""},{"name":"Брусника","quantity":200,"unit":"g","note":"протёртая с сахаром"},{"name":"Солёные огурцы","quantity":150,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Достаньте оленину из морозильника и настрогайте острым ножом тонкими стружками.\nРастопите масло в чугунной сковороде и раскалите его до лёгкого дымка.\nВсыпьте замороженную стружку и жарьте на сильном огне, пока не выпарится вся вода.\nДобавьте нарезанный лук и жарьте ещё пять минут до румяности.\nВлейте пиво и воду, посолите, поперчите и тушите под крышкой полчаса.\nОтварите картофель и разомните с горячим молоком в гладкое пюре.\nПодавайте мясо на пюре с ложкой брусники и солёными огурцами.","source":"UniTools"},{"id":"ut-kjottkaker","name":"Чёттакакер","country":"Норвегия","category":"main","diets":[],"slots":["lunch","dinner"],"time":75,"baseServings":5,"portionNutrition":{"k":680,"p":44,"f":34,"c":48},"details":[{"name":"Говяжий фарш","quantity":800,"unit":"g","note":""},{"name":"Картофельный крахмал","quantity":3,"unit":"tbsp","note":""},{"name":"Ледяная вода","quantity":200,"unit":"ml","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":"тёртый"},{"name":"Имбирь молотый","quantity":0.5,"unit":"tsp","note":""},{"name":"Мускатный орех","quantity":0.5,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Мука","quantity":40,"unit":"g","note":""},{"name":"Говяжий бульон","quantity":600,"unit":"ml","note":""},{"name":"Зелёный горошек","quantity":300,"unit":"g","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":""},{"name":"Брусника","quantity":150,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Вымешайте фарш с крахмалом, солью, перцем, имбирём и мускатным орехом пять минут.\nВводите ледяную воду по ложке, продолжая вымешивать, пока масса не станет липкой и однородной.\nВмешайте тёртый лук и уберите фарш в холодильник на двадцать минут.\nСформуйте плоские овальные котлеты мокрыми руками, граммов по сто каждая.\nОбжарьте котлеты в масле по четыре минуты с каждой стороны и переложите в кастрюлю.\nВсыпьте муку в сковороду с оставшимся жиром и прогрейте до орехового цвета, потом влейте бульон.\nЗалейте котлеты соусом и тушите двадцать минут. Подавайте с картофелем, горошком и брусникой.","source":"UniTools"},{"id":"ut-skolebrod","name":"Школьная булочка","country":"Норвегия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":80,"baseServings":12,"portionNutrition":{"k":420,"p":8,"f":16,"c":60},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Молоко","quantity":300,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":""},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Кардамон молотый","quantity":2,"unit":"tsp","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Молоко для крема","quantity":400,"unit":"ml","note":""},{"name":"Желтки","quantity":3,"unit":"piece","note":""},{"name":"Кукурузный крахмал","quantity":30,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":200,"unit":"g","note":""},{"name":"Кокосовая стружка","quantity":80,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи в тёплом молоке с ложкой сахара и оставьте на десять минут.\nЗамесите тесто из муки, опары, сахара, кардамона, яйца, соли и мягкого масла и вымешивайте пятнадцать минут.\nДайте подойти в тепле час до удвоения.\nСварите крем из молока, желтков, крахмала, сахара и ванили и полностью остудите под плёнкой.\nРазделите тесто на двенадцать шаров, выложите на противень и дайте расстояться сорок минут.\nСделайте дном стакана углубление в каждой булочке и выложите туда ложку крема.\nПеките при 200 °C двенадцать минут, остудите, нанесите глазурь кольцом и посыпьте кокосом.","source":"UniTools"},{"id":"ut-waterzooi","name":"Ватерзой","country":"Бельгия","category":"soup","diets":[],"slots":["lunch","dinner"],"time":95,"baseServings":5,"portionNutrition":{"k":620,"p":42,"f":34,"c":34},"details":[{"name":"Курица","quantity":1.4,"unit":"kg","note":"кусками"},{"name":"Лук-порей","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Корень сельдерея","quantity":200,"unit":"g","note":""},{"name":"Картофель","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Сливки","quantity":250,"unit":"ml","note":""},{"name":"Желтки","quantity":3,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":2,"unit":"piece","note":""},{"name":"Тимьян","quantity":3,"unit":"sprig","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу с луком, лавровым листом и тимьяном сорок минут и процедите бульон.\nНарежьте порей, морковь и сельдерей тонкой соломкой одинаковой длины.\nПотомите овощи в масле десять минут, не давая им подрумяниться.\nВлейте бульон, добавьте картофель брусочками и варите пятнадцать минут.\nРазберите курицу на куски и верните в кастрюлю, снимите с огня.\nВзбейте желтки со сливками и вводите горячий бульон половником, размешивая, пока миска не станет тёплой.\nВлейте смесь обратно в кастрюлю на снятом огне, прогрейте не кипятя, добавьте лимон и петрушку.","source":"UniTools"},{"id":"ut-belgian-waffles","name":"Льежские вафли","country":"Бельгия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":125,"baseServings":10,"portionNutrition":{"k":480,"p":7,"f":24,"c":60},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Молоко","quantity":180,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сливочное масло","quantity":250,"unit":"g","note":"мягкое"},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Коричневый сахар","quantity":60,"unit":"g","note":""},{"name":"Жемчужный сахар","quantity":250,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Корица","quantity":0.5,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи в тёплом молоке и оставьте на десять минут до появления пены.\nЗамесите тесто из муки, опары, яиц, коричневого сахара, ванили, корицы и соли.\nВводите мягкое масло по частям, вымешивая, пока тесто не станет гладким и эластичным.\nДайте подойти в тепле полтора часа до удвоения.\nВмешайте жемчужный сахар руками, распределив его равномерно, но не вымешивая долго.\nРазделите тесто на десять комков и дайте им постоять пятнадцать минут.\nВыпекайте в вафельнице по три минуты до тёмно-золотого цвета с карамельной корочкой.","source":"UniTools"},{"id":"ut-zuercher-geschnetzeltes","name":"Цюрихское жаркое","country":"Швейцария","category":"main","diets":[],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":720,"p":46,"f":42,"c":38},"details":[{"name":"Телятина","quantity":700,"unit":"g","note":"соломкой"},{"name":"Шампиньоны","quantity":300,"unit":"g","note":""},{"name":"Шалот","quantity":3,"unit":"piece","note":""},{"name":"Белое сухое вино","quantity":150,"unit":"ml","note":""},{"name":"Сливки","quantity":250,"unit":"ml","note":""},{"name":"Телячий бульон","quantity":150,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Мука","quantity":1,"unit":"tbsp","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Картофель для рёшти","quantity":800,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте телятину тонкой соломкой поперёк волокон и обсушите бумагой.\nРаскалите сковороду с маслом и обжарьте мясо порциями по тридцать секунд, выкладывая на тарелку.\nОбжарьте шалот и грибы в той же сковороде до испарения их воды.\nВсыпьте муку, прогрейте минуту и влейте вино, выпарив его наполовину.\nДобавьте бульон и сливки и уварите соус до густоты, минут восемь.\nВерните мясо вместе с выделившимся соком, прогрейте минуту не кипятя и добавьте лимон.\nПосыпьте петрушкой и подавайте с рёшти, выложенным рядом, а не под мясом.","source":"UniTools"},{"id":"ut-birchermuesli","name":"Бирхермюсли","country":"Швейцария","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":20,"baseServings":4,"portionNutrition":{"k":480,"p":14,"f":22,"c":58},"details":[{"name":"Овсяные хлопья","quantity":200,"unit":"g","note":""},{"name":"Вода или яблочный сок","quantity":300,"unit":"ml","note":""},{"name":"Яблоки","quantity":3,"unit":"piece","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Сливки","quantity":150,"unit":"ml","note":""},{"name":"Йогурт","quantity":250,"unit":"ml","note":""},{"name":"Сгущённое молоко","quantity":3,"unit":"tbsp","note":""},{"name":"Фундук","quantity":80,"unit":"g","note":""},{"name":"Ягоды","quantity":200,"unit":"g","note":""},{"name":"Мёд","quantity":2,"unit":"tbsp","note":""}],"steps":"Залейте овсяные хлопья водой или яблочным соком и оставьте на ночь в холодильнике.\nУтром вмешайте йогурт, сливки и сгущённое молоко до однородности.\nНатрите яблоки вместе с кожурой на крупной тёрке прямо в миску.\nСразу сбрызните тёртое яблоко лимонным соком и перемешайте, чтобы оно не потемнело.\nПодсушите фундук на сухой сковороде пять минут и порубите крупно.\nВмешайте мёд, разложите по мискам и посыпьте орехами и ягодами.","source":"UniTools"},{"id":"ut-peka","name":"Пека","country":"Хорватия","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":210,"baseServings":6,"portionNutrition":{"k":820,"p":54,"f":44,"c":48},"details":[{"name":"Ягнёнок или телятина","quantity":2,"unit":"kg","note":"крупными кусками"},{"name":"Картофель","quantity":1.5,"unit":"kg","note":"крупными дольками"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Розмарин","quantity":4,"unit":"sprig","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Белое сухое вино","quantity":250,"unit":"ml","note":""},{"name":"Оливковое масло","quantity":150,"unit":"ml","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разожгите костёр из твёрдых дров и дайте ему прогореть до крупных углей, час.\nНатрите мясо солью, перцем, чесноком и розмарином и оставьте на полчаса.\nРазложите картофель, лук, морковь и помидоры по противню одним слоем.\nУложите мясо поверх овощей, полейте оливковым маслом и вином, добавьте лавровый лист.\nНакройте колпаком и засыпьте его углями полностью, так чтобы металла не было видно.\nГотовьте полтора часа, потом снимите колпак, переверните картофель и полейте всё соком со дна.\nВерните колпак и угли и держите ещё час двадцать. Подавайте прямо с противня.","source":"UniTools"},{"id":"ut-fritule","name":"Фритуле","country":"Хорватия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":55,"baseServings":8,"portionNutrition":{"k":380,"p":6,"f":16,"c":54},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Молоко","quantity":250,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":80,"unit":"g","note":""},{"name":"Изюм","quantity":150,"unit":"g","note":""},{"name":"Ракия или ром","quantity":3,"unit":"tbsp","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Цедра апельсина","quantity":1,"unit":"piece","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Сахарная пудра","quantity":50,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Замочите изюм в ракии на двадцать минут, чтобы он набух и отдал аромат.\nРастворите дрожжи в тёплом молоке с ложкой сахара и оставьте до пены.\nВзбейте яйца с оставшимся сахаром, цедрой, ванилью и солью.\nСоедините с опарой и мукой и размешайте венчиком до жидкого теста без комков.\nВмешайте изюм вместе с ракией и оставьте тесто подходить час в тепле.\nРазогрейте масло до 170 °C и опускайте тесто двумя чайными ложками, формуя неровные шарики.\nЖарьте по три минуты, переворачивая, до тёмно-золотого цвета, и посыпьте пудрой горячими.","source":"UniTools"},{"id":"ut-sarma-serbian","name":"Сарма","country":"Сербия","category":"main","diets":[],"slots":["lunch","dinner"],"time":210,"baseServings":8,"portionNutrition":{"k":620,"p":36,"f":38,"c":32},"details":[{"name":"Квашеный кочан капусты","quantity":1.5,"unit":"kg","note":""},{"name":"Свиной фарш","quantity":700,"unit":"g","note":""},{"name":"Говяжий фарш","quantity":300,"unit":"g","note":""},{"name":"Рис","quantity":120,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Копчёные рёбрышки","quantity":500,"unit":"g","note":""},{"name":"Копчёное сало","quantity":150,"unit":"g","note":""},{"name":"Паприка сладкая","quantity":2,"unit":"tbsp","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разберите кочан на листья, промойте от лишнего рассола и срежьте толстые прожилки.\nОбжарьте нарезанный лук в масле до мягкости и остудите.\nСмешайте оба фарша с сырым рисом, луком, ложкой паприки, солью и перцем.\nЗаверните начинку в листья плотными свёртками, подгибая края внутрь.\nВыстелите дно кастрюли рублеными обрезками капусты и половиной рёбрышек.\nУложите сарму слоями, перекладывая рёбрышками и салом, залейте водой вровень с верхним слоем.\nТушите два с половиной часа на слабом огне, в конце добавив заправку из муки, паприки и томатной пасты.","source":"UniTools"},{"id":"ut-gibanica","name":"Гибаница","country":"Сербия","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":80,"baseServings":10,"portionNutrition":{"k":520,"p":22,"f":34,"c":32},"details":[{"name":"Тесто фило","quantity":500,"unit":"g","note":""},{"name":"Брынза","quantity":400,"unit":"g","note":""},{"name":"Творог","quantity":400,"unit":"g","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Кефир","quantity":400,"unit":"ml","note":""},{"name":"Сметана","quantity":200,"unit":"ml","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Газированная вода","quantity":100,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Разомните оба сыра вилкой и смешайте с яйцами, кефиром, сметаной и половиной масла.\nВмешайте газированную воду — она даст заливке лёгкость и не даст ей стать плотной.\nПопробуйте заливку на соль: брынза бывает разной солёности, и досаливать нужно по вкусу.\nСмажьте форму маслом и уложите на дно два целых листа фило, не сминая их.\nОбмакивайте каждый следующий лист в заливку, сминайте гармошкой и укладывайте в форму.\nВылейте остатки заливки сверху, накройте двумя целыми листами и смажьте маслом.\nПеките при 190 °C пятьдесят минут, сбрызните водой и накройте полотенцем на десять минут.","source":"UniTools"},{"id":"ut-ciorba-de-burta","name":"Чорба де бурта","country":"Румыния","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":270,"baseServings":6,"portionNutrition":{"k":480,"p":38,"f":30,"c":12},"details":[{"name":"Говяжий рубец","quantity":1.2,"unit":"kg","note":"очищенный"},{"name":"Говяжьи кости","quantity":500,"unit":"g","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Корень сельдерея","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":12,"unit":"clove","note":""},{"name":"Желтки","quantity":4,"unit":"piece","note":""},{"name":"Сливки","quantity":300,"unit":"ml","note":""},{"name":"Уксус","quantity":100,"unit":"ml","note":""},{"name":"Чёрный перец горошком","quantity":10,"unit":"piece","note":""},{"name":"Острый перец","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рубец несколько раз в холодной воде и потрите его солью, потом снова промойте.\nОтварите рубец в воде с половиной уксуса десять минут и слейте первую воду.\nЗалейте свежей водой вместе с костями и кореньями и варите четыре часа на слабом огне.\nВыньте рубец, нарежьте тонкой соломкой и верните в процеженный бульон.\nРастолките чеснок с солью в пасту и разведите половником бульона.\nВзбейте желтки со сливками, вводите горячий бульон половником, непрерывно размешивая.\nВлейте смесь в снятую с огня кастрюлю, добавьте чеснок и оставшийся уксус, прогрейте не кипятя.","source":"UniTools"},{"id":"ut-papanasi","name":"Папанаши","country":"Румыния","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":60,"baseServings":6,"portionNutrition":{"k":620,"p":22,"f":32,"c":62},"details":[{"name":"Творог","quantity":500,"unit":"g","note":"отжатый"},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Мука","quantity":250,"unit":"g","note":""},{"name":"Манная крупа","quantity":50,"unit":"g","note":""},{"name":"Сахар","quantity":60,"unit":"g","note":""},{"name":"Сода","quantity":1,"unit":"tsp","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Сметана густая","quantity":300,"unit":"ml","note":""},{"name":"Варенье из чёрной смородины","quantity":250,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Отожмите творог через марлю и протрите через сито, чтобы убрать крупинки.\nСмешайте творог с яйцами, сахаром, цедрой, ванилью, содой и солью.\nВмешайте манку и муку понемногу, пока тесто не станет мягким, но перестанет липнуть к рукам.\nДайте тесту постоять двадцать минут — манка набухнет, и лепить станет проще.\nСлепите шесть колец диаметром десять сантиметров и шесть шариков размером с грецкий орех.\nЖарьте при 165 °C по три минуты с каждой стороны до золотистого цвета.\nВыложите кольцо на тарелку, залейте сметаной и вареньем, сверху положите шарик.","source":"UniTools"},{"id":"ut-tarator","name":"Таратор","country":"Болгария","category":"soup","diets":["vegetarian","gluten-free"],"slots":["lunch","dinner"],"time":20,"baseServings":4,"portionNutrition":{"k":260,"p":12,"f":18,"c":14},"details":[{"name":"Болгарский йогурт","quantity":700,"unit":"ml","note":""},{"name":"Огурцы","quantity":500,"unit":"g","note":""},{"name":"Грецкие орехи","quantity":80,"unit":"g","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Укроп","quantity":40,"unit":"g","note":""},{"name":"Подсолнечное масло","quantity":3,"unit":"tbsp","note":""},{"name":"Вода холодная","quantity":200,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите огурцы на крупной тёрке или нарежьте мелким кубиком и посолите.\nОставьте огурцы на десять минут, чтобы они отдали воду, но воду не сливайте.\nРастолките чеснок с солью в пасту, чтобы он не попадался кусочками.\nСмелите грецкие орехи в мелкую крошку, оставив немного крупных кусочков.\nВзбейте йогурт венчиком с холодной водой до однородности и добавьте чеснок и орехи.\nВмешайте огурцы с их соком, рубленый укроп и подсолнечное масло.\nОхладите час и подавайте с кубиком льда в каждой тарелке.","source":"UniTools"},{"id":"ut-kavarma","name":"Каварма","country":"Болгария","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":95,"baseServings":4,"portionNutrition":{"k":620,"p":46,"f":40,"c":16},"details":[{"name":"Свиная шея","quantity":700,"unit":"g","note":"кубиками"},{"name":"Шампиньоны","quantity":300,"unit":"g","note":""},{"name":"Перец сладкий","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Брынза","quantity":150,"unit":"g","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Чубрица","quantity":1,"unit":"tbsp","note":""},{"name":"Белое сухое вино","quantity":150,"unit":"ml","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Петрушка","quantity":20,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте свинину крупными кубиками в масле до румяной корки со всех сторон.\nДобавьте лук и перец и жарьте до мягкости, семь минут.\nПоложите грибы и жарьте на сильном огне, пока не выпарится их вода.\nСнимите с огня, вмешайте паприку и чубрицу, влейте вино и верните на огонь на три минуты.\nДобавьте нарезанные помидоры, посолите и поперчите, разложите по горшочкам.\nЗапекайте при 180 °C сорок пять минут под крышками.\nСнимите крышки, разбейте в каждый горшочек яйцо, посыпьте брынзой и держите ещё восемь минут.","source":"UniTools"},{"id":"ut-hoppers","name":"Хопперы","country":"Шри-Ланка","category":"breakfast","diets":["vegetarian","gluten-free"],"slots":["breakfast"],"time":80,"baseServings":6,"portionNutrition":{"k":380,"p":10,"f":16,"c":50},"details":[{"name":"Рисовая мука","quantity":400,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":500,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":5,"unit":"g","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Вода тёплая","quantity":250,"unit":"ml","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":"по желанию"},{"name":"Лук красный","quantity":2,"unit":"piece","note":"для самбола"},{"name":"Хлопья чили","quantity":2,"unit":"tsp","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Мальдивская рыба","quantity":2,"unit":"tbsp","note":"для самбола"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Растворите дрожжи с сахаром в тёплой воде и оставьте на десять минут до пены.\nСмешайте рисовую муку с опарой и половиной кокосового молока до гладкого теста.\nНакройте и оставьте бродить на ночь при комнатной температуре, часов на восемь.\nУтром вмешайте оставшееся кокосовое молоко и соль — тесто должно стать как жидкие сливки.\nСмешайте мелко нарезанный лук, хлопья чили, мальдивскую рыбу, сок лайма и соль — это лунумирис.\nРаскалите небольшой вок, смажьте маслом и налейте половник теста, сразу раскрутив сковороду.\nРазбейте яйцо в центр, накройте крышкой и готовьте три минуты до хрустящих краёв. Подавайте с лунумирисом.","source":"UniTools"},{"id":"ut-sri-lankan-fish-curry","name":"Шри-ланкийское рыбное карри","country":"Шри-Ланка","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":65,"baseServings":5,"portionNutrition":{"k":620,"p":48,"f":26,"c":48},"details":[{"name":"Тунец или скумбрия","quantity":900,"unit":"g","note":"стейками"},{"name":"Горака или тамаринд","quantity":3,"unit":"piece","note":""},{"name":"Кокосовое молоко","quantity":500,"unit":"ml","note":""},{"name":"Обжаренный порошок карри","quantity":3,"unit":"tbsp","note":""},{"name":"Молотый чили","quantity":2,"unit":"tsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Листья карри","quantity":15,"unit":"piece","note":""},{"name":"Лист пандана","quantity":1,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Семена пажитника","quantity":1,"unit":"tsp","note":""},{"name":"Красный рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите гораку в стакане тёплой воды на двадцать минут, воду сохраните.\nНатрите рыбу солью, куркумой и половиной порошка карри и оставьте на пятнадцать минут.\nОбжарьте лук, чеснок, имбирь, листья карри, пандан, корицу и пажитник до запаха.\nДобавьте оставшийся порошок карри и чили и прогрейте минуту, не давая им подгореть.\nВлейте разбавленное кокосовое молоко с водой от гораки и доведите до кипения.\nУложите стейки в один слой, добавьте гораку и тушите двенадцать минут, покачивая кастрюлю.\nВлейте густое кокосовое молоко и прогрейте пять минут не кипятя. Подавайте с красным рисом.","source":"UniTools"},{"id":"ut-sel-roti","name":"Сель роти","country":"Непал","category":"bread","diets":["vegetarian","gluten-free"],"slots":["breakfast","snack"],"time":100,"baseServings":8,"portionNutrition":{"k":380,"p":5,"f":14,"c":60},"details":[{"name":"Рис","quantity":600,"unit":"g","note":"замочить на ночь"},{"name":"Сахар","quantity":150,"unit":"g","note":""},{"name":"Топлёное масло","quantity":60,"unit":"g","note":""},{"name":"Молоко","quantity":150,"unit":"ml","note":""},{"name":"Банан","quantity":1,"unit":"piece","note":""},{"name":"Кардамон молотый","quantity":1,"unit":"tsp","note":""},{"name":"Гвоздика молотая","quantity":0.5,"unit":"tsp","note":""},{"name":"Масло для фритюра","quantity":1.5,"unit":"l","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Замочите рис в холодной воде на ночь, слейте и обсушите полотенцем.\nСмелите мокрый рис в блендере с молоком до гладкой густой пасты без крупинок.\nВмешайте сахар, растопленное топлёное масло, размятый банан, кардамон, гвоздику и соль.\nВзбивайте тесто рукой двадцать минут круговыми движениями, вбивая воздух.\nДайте тесту постоять час — оно слегка забродит и станет пузыристым.\nРазогрейте масло до 165 °C и вылейте тесто в масло кольцом одним непрерывным движением.\nЖарьте по две минуты с каждой стороны, переворачивая двумя палочками, до золотистого цвета.","source":"UniTools"},{"id":"ut-gundruk-soup","name":"Суп из гундрука","country":"Непал","category":"soup","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":320,"p":14,"f":14,"c":36},"details":[{"name":"Гундрук","quantity":80,"unit":"g","note":"или квашеная зелень"},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Соевые бобы","quantity":100,"unit":"g","note":"замочить на ночь"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":20,"unit":"g","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Сушёный чили","quantity":3,"unit":"piece","note":""},{"name":"Семена пажитника","quantity":1,"unit":"tsp","note":""},{"name":"Перец тимур","quantity":1,"unit":"tsp","note":""},{"name":"Горчичное масло","quantity":50,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите гундрук в тёплой воде на десять минут и отожмите, воду не выливайте.\nОбжарьте соевые бобы на сухой сковороде до тёмных пятен и растрескивания.\nПрогрейте горчичное масло до дымка, снимите с огня и остудите минуту — сырое горчит.\nОбжарьте лук, чеснок, имбирь и куркуму, добавьте помидоры и потушите пять минут.\nДобавьте гундрук, бобы и картофель, залейте водой от замачивания и литром воды.\nВарите двадцать пять минут, пока картофель и бобы не станут мягкими, посолите.\nПрокалите сушёный чили, пажитник и тимур в ложке масла и вылейте в суп с шипением.","source":"UniTools"},{"id":"ut-haleem","name":"Халим","country":"Пакистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":400,"baseServings":10,"portionNutrition":{"k":680,"p":42,"f":32,"c":58},"details":[{"name":"Говядина на кости","quantity":1.5,"unit":"kg","note":""},{"name":"Цельная пшеница","quantity":300,"unit":"g","note":"замочить на ночь"},{"name":"Перловая крупа","quantity":100,"unit":"g","note":""},{"name":"Дроблёный нут чана дал","quantity":150,"unit":"g","note":""},{"name":"Красная чечевица","quantity":100,"unit":"g","note":""},{"name":"Лук","quantity":5,"unit":"piece","note":""},{"name":"Паста из имбиря и чеснока","quantity":3,"unit":"tbsp","note":""},{"name":"Гарам масала","quantity":2,"unit":"tbsp","note":""},{"name":"Молотый чили","quantity":1,"unit":"tbsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Топлёное масло","quantity":250,"unit":"g","note":""},{"name":"Имбирь","quantity":60,"unit":"g","note":"к подаче, соломкой"},{"name":"Зелёный чили","quantity":6,"unit":"piece","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите пшеницу на ночь, а чана дал и перловку на четыре часа, и промойте.\nОбжарьте три луковицы в топлёном масле до тёмно-коричневого и отложите половину для подачи.\nОбжарьте мясо с оставшимся луком, пастой из имбиря и чеснока и всеми специями.\nЗалейте водой и тушите три часа, пока мясо не начнёт распадаться на волокна.\nОтварите пшеницу, перловку и оба вида дала в отдельной кастрюле три часа до полного распада.\nВыньте кости, соедините обе части и взбивайте деревянной колотушкой сорок минут до однородности.\nПодавайте с жареным луком, имбирём, чили, кинзой и лимоном, разложенными сверху.","source":"UniTools"},{"id":"ut-seekh-kebab","name":"Сикх-кебаб","country":"Пакистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":65,"baseServings":5,"portionNutrition":{"k":680,"p":46,"f":40,"c":32},"details":[{"name":"Говяжий фарш","quantity":1,"unit":"kg","note":"жирный, 20%"},{"name":"Лук","quantity":2,"unit":"piece","note":"отжать досуха"},{"name":"Паста из имбиря и чеснока","quantity":2,"unit":"tbsp","note":""},{"name":"Зелёный чили","quantity":4,"unit":"piece","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Гарам масала","quantity":1,"unit":"tbsp","note":""},{"name":"Кориандр молотый","quantity":1,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":1,"unit":"tbsp","note":""},{"name":"Паста из зелёной папайи","quantity":1,"unit":"tbsp","note":"как размягчитель"},{"name":"Нутовая мука","quantity":2,"unit":"tbsp","note":"обжаренная"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Лепёшка наан","quantity":5,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите лук на мелкой тёрке и отожмите через марлю досуха, сок вылейте.\nОбжарьте нутовую муку на сухой сковороде до орехового запаха и остудите.\nСмешайте фарш с луком, пастой из имбиря и чеснока, папайей, специями, кинзой и чили.\nВымешивайте массу десять минут, пока она не станет липкой и не начнёт тянуться за рукой.\nВмешайте нутовую муку и уберите фарш в холодильник минимум на час.\nМокрыми руками налепите фарш на плоские шампуры ровным слоем в два сантиметра.\nЖарьте на сильных углях по четыре минуты с каждой стороны, смазывая маслом. Подавайте с нааном.","source":"UniTools"},{"id":"ut-chapati-kenyan","name":"Кенийская чапати","country":"Кения","category":"bread","diets":["vegetarian","vegan"],"slots":["breakfast","snack"],"time":105,"baseServings":8,"portionNutrition":{"k":340,"p":7,"f":16,"c":44},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Вода тёплая","quantity":350,"unit":"ml","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Соль","quantity":1.5,"unit":"tsp","note":""}],"steps":"Смешайте муку с солью и сахаром, влейте тёплую воду и две ложки масла.\nВымешивайте тесто пятнадцать минут, пока оно не станет гладким и эластичным.\nНакройте влажным полотенцем и дайте отдохнуть час при комнатной температуре.\nРазделите на восемь шаров, раскатайте каждый в тонкий круг и щедро смажьте маслом.\nСверните круг в жгут, закрутите улиткой и придавите ладонью.\nДайте улиткам постоять пятнадцать минут и раскатайте каждую в круг заново.\nЖарьте на сухой сковороде по полторы минуты с каждой стороны, смазывая маслом, до румяных пятен.","source":"UniTools"},{"id":"ut-mandazi","name":"Мандази","country":"Кения","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":100,"baseServings":8,"portionNutrition":{"k":340,"p":6,"f":14,"c":48},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":250,"unit":"ml","note":""},{"name":"Сахар","quantity":80,"unit":"g","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Кардамон молотый","quantity":2,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":"растопить"},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Соль","quantity":0.5,"unit":"tsp","note":""}],"steps":"Подогрейте кокосовое молоко до тёплого и растворите в нём дрожжи с ложкой сахара.\nСмешайте муку с оставшимся сахаром, кардамоном и солью.\nВмешайте яйцо, растопленное масло и кокосовую опару и замесите мягкое тесто.\nДайте подойти в тепле час до удвоения.\nРазделите тесто на четыре части, раскатайте каждую в круг толщиной в сантиметр.\nРазрежьте каждый круг на четыре треугольника и дайте им постоять пятнадцать минут.\nЖарьте при 170 °C по две минуты с каждой стороны до золотистого цвета.","source":"UniTools"},{"id":"ut-bunny-chow","name":"Банни чау","country":"ЮАР","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":4,"portionNutrition":{"k":880,"p":48,"f":40,"c":82},"details":[{"name":"Баранина","quantity":900,"unit":"g","note":"на кости, кусками"},{"name":"Белый хлеб","quantity":2,"unit":"piece","note":"буханки"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Паста из имбиря и чеснока","quantity":3,"unit":"tbsp","note":""},{"name":"Дурбанский порошок карри","quantity":4,"unit":"tbsp","note":""},{"name":"Листья карри","quantity":15,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Кардамон","quantity":4,"unit":"piece","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Морковный салат","quantity":200,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте лук в масле до тёмно-золотого, добавьте корицу, кардамон и листья карри.\nВмешайте пасту из имбиря и чеснока и порошок карри и прогрейте две минуты.\nДобавьте баранину и обжарьте до румяности, обваливая её в специях.\nПоложите нарезанные помидоры, посолите и тушите под крышкой час на слабом огне.\nЗаложите картофель крупными кусками и тушите ещё двадцать пять минут.\nСнимите крышку и выпарите соус до густоты, при которой ложка оставляет след.\nРазрежьте буханки пополам, выньте мякиш, наполните карри и положите мякиш сверху.","source":"UniTools"},{"id":"ut-melktert","name":"Мелктерт","country":"ЮАР","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":80,"baseServings":10,"portionNutrition":{"k":380,"p":9,"f":16,"c":52},"details":[{"name":"Мука для основы","quantity":250,"unit":"g","note":""},{"name":"Сливочное масло","quantity":125,"unit":"g","note":""},{"name":"Сахар","quantity":200,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Молоко","quantity":1,"unit":"l","note":""},{"name":"Кукурузный крахмал","quantity":40,"unit":"g","note":""},{"name":"Мука для начинки","quantity":40,"unit":"g","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Корица молотая","quantity":2,"unit":"tsp","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Разотрите муку с холодным маслом, ложкой сахара и яйцом в тесто и охладите полчаса.\nВыстелите тестом форму и запеките вслепую при 180 °C пятнадцать минут до бледно-золотого.\nПрогрейте молоко с палочкой корицы до горячего и оставьте настояться десять минут.\nВзбейте оставшиеся яйца с сахаром, мукой, крахмалом, ванилью и солью до гладкости.\nВливайте горячее молоко тонкой струйкой, непрерывно размешивая, и верните на огонь.\nВарите на среднем огне восемь минут, пока начинка не загустеет до состояния густых сливок.\nВылейте начинку в основу, охладите три часа и посыпьте молотой корицей перед подачей.","source":"UniTools"},{"id":"ut-bandeja-paisa","name":"Бандеха пайса","country":"Колумбия","category":"main","diets":[],"slots":["lunch","dinner"],"time":210,"baseServings":4,"portionNutrition":{"k":1480,"p":78,"f":82,"c":108},"details":[{"name":"Красная фасоль","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Свиная грудинка со шкурой","quantity":600,"unit":"g","note":""},{"name":"Говяжий фарш","quantity":400,"unit":"g","note":""},{"name":"Колбаски чорисо","quantity":300,"unit":"g","note":""},{"name":"Рис","quantity":350,"unit":"g","note":""},{"name":"Зелёный подорожник","quantity":1,"unit":"piece","note":"для фасоли"},{"name":"Спелый подорожник","quantity":2,"unit":"piece","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Арепы","quantity":4,"unit":"piece","note":""},{"name":"Авокадо","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите фасоль с нарезанным зелёным подорожником полтора часа до мягкости и густоты.\nОтварите свиную грудинку в подсоленной воде сорок минут и полностью обсушите.\nОбжарьте грудинку шкурой вниз в глубоком масле, пока шкура не вздуется и не захрустит.\nПриготовьте огао: обжарьте лук с помидорами и зирой, добавьте фарш и жарьте до готовности.\nОбжарьте чорисо, отварите рис и пожарьте кружки спелого подорожника до карамельного цвета.\nИспеките арепы на сухой сковороде и пожарьте яйца до жидкого желтка.\nСоберите поднос: фасоль, рис, фарш, чичаррон, чорисо, яйцо, арепа, банан и авокадо рядом.","source":"UniTools"},{"id":"ut-sancocho-colombiano","name":"Колумбийский санкочо","country":"Колумбия","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":140,"baseServings":8,"portionNutrition":{"k":620,"p":44,"f":20,"c":68},"details":[{"name":"Курица","quantity":2,"unit":"kg","note":"домашняя, кусками"},{"name":"Юкка","quantity":600,"unit":"g","note":""},{"name":"Зелёный подорожник","quantity":2,"unit":"piece","note":""},{"name":"Кукуруза","quantity":3,"unit":"piece","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Зелёный лук","quantity":5,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Ачиоте","quantity":1,"unit":"tsp","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Авокадо","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мелко нарезанные лук, зелёный лук, помидоры и чеснок с зирой и ачиоте до пасты.\nПоложите курицу в кастрюлю, добавьте половину гуасо и залейте четырьмя литрами воды.\nДоведите до кипения, снимите пену и варите сорок минут на слабом огне.\nЗаложите кукурузу початками и юкку крупными кусками и варите двадцать минут.\nДобавьте подорожник и картофель и варите ещё двадцать пять минут.\nРазомните пару кусков юкки прямо в кастрюле, чтобы суп загустел, и вмешайте оставшийся гуасо.\nПосыпьте кинзой и подавайте с белым рисом и авокадо на отдельных тарелках.","source":"UniTools"},{"id":"ut-curanto-en-olla","name":"Куранто в кастрюле","country":"Чили","category":"main","diets":[],"slots":["lunch","dinner"],"time":100,"baseServings":6,"portionNutrition":{"k":880,"p":68,"f":42,"c":58},"details":[{"name":"Мидии","quantity":1.5,"unit":"kg","note":""},{"name":"Ракушки","quantity":1,"unit":"kg","note":""},{"name":"Свиные рёбрышки","quantity":800,"unit":"g","note":""},{"name":"Курица","quantity":800,"unit":"g","note":"кусками"},{"name":"Копчёная колбаса","quantity":400,"unit":"g","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":""},{"name":"Мука","quantity":200,"unit":"g","note":"для лепёшек"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Белое сухое вино","quantity":250,"unit":"ml","note":""},{"name":"Капустные листья","quantity":8,"unit":"piece","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Смалец","quantity":60,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте моллюсков в нескольких водах и выбросьте все раскрытые до готовки.\nОтварите половину картофеля, разомните и замесите с мукой и смальцем плотные лепёшки чапалеле.\nВыстелите дно кастрюли капустными листьями в два слоя.\nУложите моллюсков первым слоем, влейте вино и накройте новыми капустными листьями.\nРазложите рёбрышки, курицу, колбасу и лук вторым слоем и снова накройте листьями.\nПоложите сверху целый картофель и лепёшки, накройте листьями и плотно закройте крышкой.\nГотовьте на среднем огне час, не открывая. Подавайте слоями, с бульоном со дна в отдельных пиалах.","source":"UniTools"},{"id":"ut-completo-italiano","name":"Комплето","country":"Чили","category":"snack","diets":[],"slots":["snack"],"time":30,"baseServings":4,"portionNutrition":{"k":720,"p":18,"f":52,"c":46},"details":[{"name":"Сосиски","quantity":4,"unit":"piece","note":""},{"name":"Булочки для хот-дога","quantity":4,"unit":"piece","note":""},{"name":"Авокадо","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Майонез","quantity":200,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Квашеная капуста","quantity":150,"unit":"g","note":"по желанию"},{"name":"Соус ахи","quantity":50,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разомните авокадо вилкой с солью и соком лимона в грубое пюре, не пробивая до гладкости.\nНарежьте помидоры мелким кубиком, посолите и откиньте на сито, чтобы стекла лишняя вода.\nОтварите сосиски в воде на слабом огне пять минут, не давая им лопнуть.\nПрогрейте булочки на пару или в духовке две минуты — они должны быть мягкими и тёплыми.\nВложите сосиску в булочку и разложите сверху отжатые помидоры ровным слоем.\nВыложите горку авокадо поверх помидоров, закрыв их полностью.\nЗавершите щедрой полосой майонеза сверху и подайте с соусом ахи отдельно.","source":"UniTools"},{"id":"ut-kuyrdak","name":"Куырдак","country":"Казахстан","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":75,"baseServings":5,"portionNutrition":{"k":720,"p":48,"f":44,"c":32},"details":[{"name":"Курдючный жир","quantity":150,"unit":"g","note":""},{"name":"Баранина","quantity":400,"unit":"g","note":"кубиками"},{"name":"Печень","quantity":300,"unit":"g","note":""},{"name":"Сердце","quantity":300,"unit":"g","note":""},{"name":"Почки","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Зелень","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Вымочите почки в холодной воде час, меняя её дважды, и срежьте все протоки.\nВытопите курдючный жир в казане до шкварок и выньте их шумовкой.\nОбжарьте баранину на сильном огне до тёмной корки, пять минут.\nДобавьте сердце и жарьте ещё восемь минут, помешивая.\nПоложите почки, через три минуты печень и жарьте ещё три — печень не должна пережариться.\nВсыпьте лук и картофель кубиками, посолите, добавьте зиру и жарьте под крышкой пятнадцать минут.\nВмешайте чеснок и зелень, снимите с огня и подавайте прямо из казана с лепёшкой.","source":"UniTools"},{"id":"ut-shelpek","name":"Шелпек","country":"Казахстан","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":60,"baseServings":7,"portionNutrition":{"k":380,"p":8,"f":18,"c":48},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Кефир","quantity":300,"unit":"ml","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Сода","quantity":0.5,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":"растопить"},{"name":"Масло для жарки","quantity":500,"unit":"ml","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Смешайте кефир с содой и оставьте на пять минут — смесь запенится.\nДобавьте яйцо, сахар, соль и растопленное масло и размешайте до однородности.\nВмешайте муку понемногу и замесите мягкое тесто, которое чуть липнет к рукам.\nНакройте полотенцем и оставьте отдыхать полчаса при комнатной температуре.\nРазделите на семь шаров и раскатайте каждый в тонкий круг диаметром двадцать сантиметров.\nНаколите каждый круг вилкой в нескольких местах, чтобы он не вздулся пузырём целиком.\nЖарьте в разогретом масле по минуте с каждой стороны до золотистых пятен и выложите на бумагу.","source":"UniTools"},{"id":"ut-dolma-azerbaijani","name":"Азербайджанская долма","country":"Азербайджан","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":6,"portionNutrition":{"k":520,"p":26,"f":28,"c":40},"details":[{"name":"Виноградные листья","quantity":300,"unit":"g","note":""},{"name":"Баранина","quantity":600,"unit":"g","note":"фарш"},{"name":"Рис","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Мята свежая","quantity":50,"unit":"g","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Топлёное масло","quantity":60,"unit":"g","note":""},{"name":"Мацони или йогурт","quantity":400,"unit":"ml","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Корица","quantity":0.5,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Ошпарьте свежие листья кипятком на минуту, консервированные вымочите полчаса в холодной воде.\nПромойте рис и смешайте с фаршем, мелко нарезанным луком, солью, перцем и корицей.\nПорубите всю зелень мелко и вмешайте в начинку — её объём должен быть заметен.\nКладите на лист чайную ложку начинки, подверните бока и сверните плотным валиком в палец толщиной.\nВыстелите дно кастрюли рваными листьями и уложите долму плотными слоями швом вниз.\nРазложите сверху кусочки топлёного масла, залейте водой вровень с верхним слоем и накройте тарелкой с грузом.\nВарите час на слабом огне и подавайте с мацони, взбитым с растёртым чесноком и солью.","source":"UniTools"},{"id":"ut-pakhlava-baku","name":"Бакинская пахлава","country":"Азербайджан","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":145,"baseServings":16,"portionNutrition":{"k":520,"p":9,"f":32,"c":52},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Молоко","quantity":200,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Топлёное масло","quantity":300,"unit":"g","note":""},{"name":"Желтки","quantity":3,"unit":"piece","note":""},{"name":"Грецкие орехи","quantity":500,"unit":"g","note":"молотые"},{"name":"Сахар","quantity":400,"unit":"g","note":""},{"name":"Кардамон молотый","quantity":1,"unit":"tsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Мёд","quantity":200,"unit":"g","note":""},{"name":"Половинки орехов","quantity":40,"unit":"piece","note":"для украшения"},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Растворите дрожжи в тёплом молоке, замесите тесто с мукой, желтками, ложкой масла и солью.\nДайте тесту подойти час в тепле и разделите на восемь равных шаров.\nСмешайте молотые орехи с половиной сахара и кардамоном — это начинка.\nРаскатайте первый шар по размеру формы, уложите и обильно смажьте топлёным маслом.\nЧередуйте слои теста и ореховой начинки, промазывая маслом, пока не кончится тесто.\nНарежьте ромбами до самого дна, вдавите по половинке ореха и смажьте шафранным настоем.\nПеките при 180 °C сорок пять минут и залейте горячим сиропом из мёда и оставшегося сахара.","source":"UniTools"},{"id":"ut-iraqi-biryani","name":"Иракский бирьяни","country":"Ирак","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":780,"p":42,"f":32,"c":86},"details":[{"name":"Курица","quantity":1.2,"unit":"kg","note":"кусками"},{"name":"Рис басмати","quantity":600,"unit":"g","note":""},{"name":"Вермишель","quantity":100,"unit":"g","note":""},{"name":"Зелёный горошек","quantity":200,"unit":"g","note":""},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Картофель","quantity":2,"unit":"piece","note":""},{"name":"Миндаль","quantity":80,"unit":"g","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Бахарат","quantity":1,"unit":"tbsp","note":""},{"name":"Сушёный лайм","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Топлёное масло","quantity":100,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу с луком, проколотым чёрным лаймом и бахаратом сорок минут. Бульон сохраните.\nПромойте рис до прозрачной воды и замочите на двадцать минут.\nОбжарьте вермишель в топлёном масле до тёмно-коричневого цвета, помешивая.\nОбжарьте по отдельности картофель, морковь, миндаль и изюм и выложите на бумагу.\nРазберите курицу на куски и обжарьте их с томатной пастой до румяности.\nОтварите рис с обжаренной вермишелью в процеженном бульоне двадцать минут под крышкой.\nВыложите рис на блюдо, сверху курицу и все обжаренные добавки, не перемешивая.","source":"UniTools"},{"id":"ut-kleicha","name":"Клейча","country":"Ирак","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":85,"baseServings":12,"portionNutrition":{"k":420,"p":6,"f":20,"c":56},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Топлёное масло","quantity":250,"unit":"g","note":""},{"name":"Молоко","quantity":150,"unit":"ml","note":"тёплое"},{"name":"Сухие дрожжи","quantity":5,"unit":"g","note":""},{"name":"Финиковая паста","quantity":500,"unit":"g","note":""},{"name":"Кардамон молотый","quantity":2,"unit":"tsp","note":""},{"name":"Махлаб","quantity":1,"unit":"tsp","note":""},{"name":"Фенхель молотый","quantity":1,"unit":"tsp","note":""},{"name":"Чернушка","quantity":1,"unit":"tsp","note":""},{"name":"Желток","quantity":1,"unit":"piece","note":"для смазки"},{"name":"Кунжут","quantity":30,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи в тёплом молоке и оставьте на десять минут до появления пены.\nРазотрите муку с растопленным топлёным маслом, махлабом, фенхелем, чернушкой и солью.\nВлейте опару и замесите мягкое тесто, вымешивая десять минут.\nНакройте и дайте отдохнуть час при комнатной температуре.\nРазомните финиковую пасту с ложкой топлёного масла и кардамоном до мягкости.\nРаскатайте тесто прямоугольником, распределите пасту тонким слоем и сверните плотным рулетом.\nНарежьте рулет ломтиками в сантиметр, смажьте желтком, посыпьте кунжутом и пеките при 180 °C двадцать минут.","source":"UniTools"},{"id":"ut-shakshuka-tunisian","name":"Тунисская чакчука","country":"Тунис","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":65,"baseServings":4,"portionNutrition":{"k":380,"p":16,"f":24,"c":26},"details":[{"name":"Перец сладкий","quantity":5,"unit":"piece","note":""},{"name":"Помидоры","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Харисса","quantity":2,"unit":"tbsp","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Тмин молотый","quantity":1,"unit":"tsp","note":""},{"name":"Кориандр молотый","quantity":1,"unit":"tsp","note":""},{"name":"Яйца","quantity":6,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Каперсы","quantity":2,"unit":"tbsp","note":""},{"name":"Хлеб","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обожгите перцы на открытом огне до чёрной кожуры, накройте миской на десять минут и очистите.\nНарежьте очищенные перцы полосками, помидоры кубиком, лук перьями.\nОбжарьте лук и чеснок в оливковом масле до мягкости, восемь минут.\nВмешайте хариссу, томатную пасту, тмин и кориандр и прогрейте две минуты.\nДобавьте перцы и помидоры, посолите и тушите двадцать минут до густой пасты.\nСделайте в соусе углубления ложкой и вбейте в каждое яйцо.\nНакройте крышкой и держите шесть минут, пока белок не схватится, а желток не останется жидким.","source":"UniTools"},{"id":"ut-ojja-merguez","name":"Оджа с мергезом","country":"Тунис","category":"main","diets":[],"slots":["lunch","dinner"],"time":45,"baseServings":4,"portionNutrition":{"k":620,"p":34,"f":44,"c":22},"details":[{"name":"Колбаски мергез","quantity":500,"unit":"g","note":""},{"name":"Помидоры","quantity":600,"unit":"g","note":""},{"name":"Перец сладкий","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Харисса","quantity":2,"unit":"tbsp","note":""},{"name":"Томатная паста","quantity":1,"unit":"tbsp","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":""},{"name":"Тмин молотый","quantity":1,"unit":"tsp","note":""},{"name":"Оливковое масло","quantity":50,"unit":"ml","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Багет","quantity":1,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте мергез в оливковом масле до румяности со всех сторон и выньте на тарелку.\nВ том же жире обжарьте нарезанный перец и чеснок до мягкости.\nВмешайте хариссу, томатную пасту и тмин и прогрейте две минуты.\nДобавьте нарезанные помидоры, посолите и тушите пятнадцать минут до густоты.\nВерните колбаски, нарезанные кусками, и прогрейте три минуты.\nУбавьте огонь до минимума, вбейте яйца и размешивайте лопаткой три минуты до кремовой массы.\nПосыпьте петрушкой и подавайте прямо со сковороды с багетом.","source":"UniTools"},{"id":"ut-muhammara","name":"Мухаммара","country":"Сирия","category":"snack","diets":["vegetarian","vegan"],"slots":["snack"],"time":55,"baseServings":6,"portionNutrition":{"k":380,"p":8,"f":30,"c":22},"details":[{"name":"Красный сладкий перец","quantity":6,"unit":"piece","note":""},{"name":"Грецкие орехи","quantity":200,"unit":"g","note":""},{"name":"Панировочные сухари","quantity":80,"unit":"g","note":""},{"name":"Гранатовый соус","quantity":3,"unit":"tbsp","note":""},{"name":"Перец алеппо","quantity":1,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":100,"unit":"ml","note":""},{"name":"Пита","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обожгите перцы на открытом огне или под грилем до чёрной кожуры со всех сторон.\nСложите их в миску, накройте плёнкой на пятнадцать минут и снимите кожуру и семена.\nПодсушите грецкие орехи на сухой сковороде пять минут до орехового запаха.\nРастолките орехи в ступке или пробейте в блендере короткими импульсами до крупной крошки.\nПробейте перцы с чесноком, гранатовым соусом, лимоном, зирой и перцем алеппо.\nВмешайте орехи и сухари вручную и посолите, оставив массу зернистой.\nВлейте оливковое масло тонкой струйкой, размешивая, и охладите час перед подачей.","source":"UniTools"},{"id":"ut-shish-barak","name":"Шиш барак","country":"Сирия","category":"main","diets":[],"slots":["lunch","dinner"],"time":135,"baseServings":5,"portionNutrition":{"k":680,"p":38,"f":30,"c":64},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Вода","quantity":180,"unit":"ml","note":""},{"name":"Баранина","quantity":400,"unit":"g","note":"фарш"},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Кедровые орехи","quantity":50,"unit":"g","note":""},{"name":"Бахарат","quantity":1,"unit":"tsp","note":""},{"name":"Густой йогурт","quantity":1,"unit":"l","note":""},{"name":"Кукурузный крахмал","quantity":2,"unit":"tbsp","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Мята сушёная","quantity":2,"unit":"tbsp","note":""},{"name":"Топлёное масло","quantity":50,"unit":"g","note":""},{"name":"Рис","quantity":300,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, воды и соли и оставьте отдыхать сорок минут.\nОбжарьте лук с фаршем, бахаратом, солью и перцем, добавьте кедровые орехи и остудите.\nРаскатайте тесто тонко и вырежьте кружки диаметром четыре сантиметра.\nСлепите полумесяцы с начинкой и соедините концы кольцом, как тортеллини.\nЗапекайте пельмени при 200 °C двенадцать минут до румяного цвета.\nВзбейте йогурт с крахмалом, яйцом и солью и доводите до кипения, непрерывно мешая в одну сторону.\nОпустите пельмени в соус, варите десять минут и полейте маслом с чесноком и мятой.","source":"UniTools"},{"id":"ut-anzac-biscuits","name":"Печенье АНЗАК","country":"Австралия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":38,"baseServings":20,"portionNutrition":{"k":180,"p":2,"f":9,"c":23},"details":[{"name":"Овсяные хлопья","quantity":150,"unit":"g","note":""},{"name":"Мука","quantity":150,"unit":"g","note":""},{"name":"Кокосовая стружка","quantity":100,"unit":"g","note":""},{"name":"Коричневый сахар","quantity":150,"unit":"g","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Золотой сироп","quantity":3,"unit":"tbsp","note":""},{"name":"Сода","quantity":1,"unit":"tsp","note":""},{"name":"Кипяток","quantity":2,"unit":"tbsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Смешайте овсяные хлопья, муку, кокосовую стружку, сахар и соль в большой миске.\nРастопите масло с золотым сиропом на слабом огне, не давая закипеть.\nРазведите соду в кипятке и сразу влейте в масляную смесь — она вспенится.\nВылейте вспенившуюся смесь в сухие ингредиенты и размешайте до однородности.\nСкатайте шарики размером с грецкий орех и выложите на противень с большими промежутками.\nПриплющите каждый шарик ладонью до толщины в сантиметр — они ещё расплывутся при выпечке.\nПеките при 160 °C от двенадцати до восемнадцати минут и остудите на противне, а не на решётке.","source":"UniTools"},{"id":"ut-barramundi-on-the-barbie","name":"Барамунди на гриле","country":"Австралия","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":55,"baseServings":4,"portionNutrition":{"k":520,"p":48,"f":24,"c":28},"details":[{"name":"Барамунди или сибас","quantity":1.5,"unit":"kg","note":"целая, потрошёная"},{"name":"Лимонный мирт","quantity":1,"unit":"tsp","note":"или цедра лимона"},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Фенхель","quantity":1,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Сделайте на рыбе три надреза с каждой стороны и обсушите её насухо бумагой.\nРазотрите чеснок с маслом, лимонным миртом, цедрой лайма, солью и перцем.\nВотрите смесь в надрезы и в брюшко, вложите внутрь ломтики лайма и фенхеля.\nЗаверните рыбу в фольгу, оставив швы наверху, чтобы сок не вытекал.\nРазожгите угли и разгребите их к краям — жар под рыбой должен быть непрямым.\nГотовьте в фольге двадцать минут, переворачивая свёрток один раз на середине.\nРазверните, переложите рыбу на смазанную решётку над углями и держите по минуте с каждой стороны до корки.","source":"UniTools"},{"id":"ut-afghan-biscuits","name":"Афганское печенье","country":"Новая Зеландия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":45,"baseServings":16,"portionNutrition":{"k":240,"p":3,"f":13,"c":29},"details":[{"name":"Сливочное масло","quantity":200,"unit":"g","note":"мягкое"},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Мука","quantity":180,"unit":"g","note":""},{"name":"Какао-порошок","quantity":30,"unit":"g","note":""},{"name":"Кукурузные хлопья","quantity":60,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":200,"unit":"g","note":""},{"name":"Какао для глазури","quantity":20,"unit":"g","note":""},{"name":"Горячая вода","quantity":3,"unit":"tbsp","note":""},{"name":"Половинки грецких орехов","quantity":16,"unit":"piece","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Взбейте мягкое масло с сахаром до посветления, минуты четыре.\nПросейте муку с какао и солью и вмешайте лопаткой до однородного теста.\nВсыпьте кукурузные хлопья и перемешайте одним движением, стараясь их не сломать.\nВыкладывайте тесто столовой ложкой на противень и слегка прижимайте.\nПеките при 180 °C восемнадцать минут — печенье останется мягким на ощупь и схватится при остывании.\nПолностью остудите на противне, не пытаясь снять горячими.\nРазмешайте пудру с какао и горячей водой в густую глазурь, покройте печенье и вдавите половинку ореха.","source":"UniTools"},{"id":"ut-whitebait-fritters","name":"Оладьи из вайтбейта","country":"Новая Зеландия","category":"snack","diets":["pescatarian"],"slots":["snack"],"time":30,"baseServings":4,"portionNutrition":{"k":380,"p":32,"f":24,"c":12},"details":[{"name":"Вайтбейт или снеток","quantity":500,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Белый хлеб","quantity":4,"unit":"slice","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте вайтбейт в холодной воде и откиньте на сито на десять минут.\nОбсушите мальков полотенцем — лишняя вода не даст оладье схватиться.\nВзбейте яйца с мукой, солью и перцем до однородности без комков.\nВмешайте мальков в яичную смесь аккуратно, стараясь их не помять.\nРастопите масло на сковороде на среднем огне до лёгкого шипения.\nВылейте половник смеси и распределите тонким кругом сантиметровой толщины.\nЖарьте по полторы минуты с каждой стороны и подавайте с лимоном и хлебом с маслом.","source":"UniTools"},{"id":"ut-butter-tarts","name":"Масляные тарталетки","country":"Канада","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":67,"baseServings":12,"portionNutrition":{"k":420,"p":4,"f":24,"c":48},"details":[{"name":"Мука","quantity":300,"unit":"g","note":""},{"name":"Сливочное масло для теста","quantity":180,"unit":"g","note":"холодное"},{"name":"Ледяная вода","quantity":80,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":""},{"name":"Коричневый сахар","quantity":200,"unit":"g","note":""},{"name":"Кленовый сироп","quantity":120,"unit":"ml","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Уксус","quantity":1,"unit":"tsp","note":""},{"name":"Изюм","quantity":100,"unit":"g","note":"по желанию"},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Разотрите муку с холодным маслом в крупную крошку и соберите тесто ледяной водой.\nЗаверните в плёнку и охладите полчаса, не вымешивая тесто долго.\nРаскатайте тесто и выстелите им формочки для маффинов, подняв бортики до верха.\nРастопите масло, вмешайте сахар, кленовый сироп, уксус, ваниль и соль.\nОстудите смесь до тёплой и только потом вмешайте яйца — в горячую они свернутся.\nРазложите изюм по корзиночкам и залейте начинкой на две трети, не выше.\nПеките при 200 °C восемнадцать минут для текучей начинки или двадцать две для плотной.","source":"UniTools"},{"id":"ut-montreal-bagels","name":"Монреальские бейглы","country":"Канада","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":145,"baseServings":12,"portionNutrition":{"k":340,"p":10,"f":9,"c":56},"details":[{"name":"Мука сильная","quantity":700,"unit":"g","note":""},{"name":"Вода тёплая","quantity":300,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Сахар","quantity":60,"unit":"g","note":""},{"name":"Мёд","quantity":150,"unit":"g","note":"для варки"},{"name":"Кунжут","quantity":150,"unit":"g","note":""},{"name":"Мак","quantity":100,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи с сахаром в тёплой воде и оставьте на десять минут до пены.\nЗамесите тесто из муки, опары, яиц, масла и соли и вымешивайте пятнадцать минут до эластичности.\nДайте подойти в тепле час двадцать, пока тесто не удвоится.\nРазделите на двенадцать частей, раскатайте жгутами и соедините концы кольцом с крупным отверстием.\nВскипятите большую кастрюлю воды с мёдом и опускайте кольца по три-четыре штуки.\nВарите по минуте с каждой стороны и сразу обваливайте в кунжуте или маке.\nПеките при 230 °C двадцать минут до тёмно-золотой корки, перевернув один раз на середине.","source":"UniTools"},{"id":"ut-skyr-with-berries","name":"Скир с ягодами","country":"Исландия","category":"breakfast","diets":["vegetarian","gluten-free"],"slots":["breakfast"],"time":50,"baseServings":6,"portionNutrition":{"k":220,"p":20,"f":6,"c":22},"details":[{"name":"Обезжиренное молоко","quantity":4,"unit":"l","note":""},{"name":"Скир или йогурт как закваска","quantity":100,"unit":"g","note":""},{"name":"Сычужный фермент","quantity":2,"unit":"pinch","note":""},{"name":"Черника","quantity":400,"unit":"g","note":""},{"name":"Сливки","quantity":150,"unit":"ml","note":"к подаче"},{"name":"Сахар","quantity":60,"unit":"g","note":""},{"name":"Овсяные хлопья","quantity":100,"unit":"g","note":"к подаче"}],"steps":"Нагрейте молоко до 85 °C, помешивая, и держите десять минут, не давая закипеть.\nОстудите молоко до 40 °C, поставив кастрюлю в холодную воду.\nРазведите закваску половником тёплого молока и вмешайте обратно в кастрюлю.\nДобавьте сычужный фермент, размешайте несколько секунд и накройте крышкой.\nОставьте в тепле на двенадцать часов, пока масса не схватится в плотный сгусток.\nВыложите сгусток в ткань и подвесьте над миской на шесть часов, чтобы стекла сыворотка.\nВзбейте скир до гладкости и подавайте с черникой, сливками и овсяными хлопьями.","source":"UniTools"},{"id":"ut-rugbraud","name":"Исландский чёрный хлеб","country":"Исландия","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":740,"baseServings":12,"portionNutrition":{"k":320,"p":7,"f":4,"c":66},"details":[{"name":"Ржаная мука","quantity":500,"unit":"g","note":""},{"name":"Пшеничная мука","quantity":200,"unit":"g","note":""},{"name":"Молоко","quantity":600,"unit":"ml","note":""},{"name":"Золотой сироп или патока","quantity":150,"unit":"ml","note":""},{"name":"Коричневый сахар","quantity":100,"unit":"g","note":""},{"name":"Разрыхлитель","quantity":2,"unit":"tsp","note":""},{"name":"Сода","quantity":1,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Смешайте оба вида муки с сахаром, разрыхлителем, содой и солью в большой миске.\nПодогрейте молоко с сиропом до тёплого, чтобы сироп разошёлся.\nВлейте жидкость в сухие ингредиенты и размешайте ложкой до однородного густого теста.\nСмажьте форму маслом и вылейте тесто, заполнив её на две трети.\nЗатяните форму двумя слоями фольги и обвяжите бечёвкой, чтобы пар не выходил.\nПоставьте форму в глубокий противень с водой и запекайте при 100 °C двенадцать часов.\nПолностью остудите в форме и выдержите сутки перед нарезкой. Подавайте с маслом.","source":"UniTools"},{"id":"ut-laksa-singapore","name":"Катонг лакса","country":"Сингапур","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":105,"baseServings":4,"portionNutrition":{"k":780,"p":38,"f":44,"c":62},"details":[{"name":"Толстая рисовая лапша","quantity":400,"unit":"g","note":""},{"name":"Креветки","quantity":500,"unit":"g","note":"неочищенные"},{"name":"Ракушки","quantity":300,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":500,"unit":"ml","note":""},{"name":"Сушёный чили","quantity":12,"unit":"piece","note":""},{"name":"Шалот","quantity":8,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Лемонграсс","quantity":3,"unit":"piece","note":""},{"name":"Галангал","quantity":30,"unit":"g","note":""},{"name":"Куркума свежая","quantity":20,"unit":"g","note":""},{"name":"Креветочная паста белачан","quantity":2,"unit":"tsp","note":""},{"name":"Орехи кемири","quantity":5,"unit":"piece","note":""},{"name":"Сушёные креветки","quantity":40,"unit":"g","note":""},{"name":"Лист лаксы","quantity":20,"unit":"g","note":""},{"name":"Ростки маша","quantity":150,"unit":"g","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите креветки, панцири обжарьте и отварите в литре воды двадцать минут, затем процедите.\nЗамочите сушёный чили и сушёные креветки в кипятке на двадцать минут.\nПробейте чили, шалот, чеснок, лемонграсс, галангал, куркуму, орехи и белачан в пасту.\nОбжаривайте пасту в масле двадцать минут на среднем огне, пока масло не выступит по краям.\nВлейте креветочный бульон, добавьте лист лаксы и варите пятнадцать минут.\nВлейте кокосовое молоко, посолите и прогрейте пять минут, не давая закипеть.\nНарежьте отваренную лапшу короткими отрезками, разложите по мискам с креветками и ростками и залейте бульоном.","source":"UniTools"},{"id":"ut-kaya-toast","name":"Тост с кайей","country":"Сингапур","category":"breakfast","diets":["vegetarian"],"slots":["breakfast"],"time":70,"baseServings":4,"portionNutrition":{"k":520,"p":18,"f":32,"c":42},"details":[{"name":"Белый хлеб","quantity":8,"unit":"slice","note":""},{"name":"Яйца для кайи","quantity":4,"unit":"piece","note":""},{"name":"Кокосовое молоко","quantity":250,"unit":"ml","note":""},{"name":"Сахар","quantity":150,"unit":"g","note":""},{"name":"Листья пандана","quantity":3,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":"холодное"},{"name":"Яйца к подаче","quantity":8,"unit":"piece","note":""},{"name":"Тёмный соевый соус","quantity":4,"unit":"tsp","note":""},{"name":"Белый перец","quantity":1,"unit":"tsp","note":""}],"steps":"Завяжите листья пандана узлом и прогрейте с кокосовым молоком до горячего, не кипятя.\nВзбейте яйца с сахаром до растворения сахара и процедите через мелкое сито.\nВливайте тёплое кокосовое молоко в яйца тонкой струйкой, непрерывно размешивая.\nВарите смесь на водяной бане сорок минут, мешая деревянной ложкой, до густоты джема.\nВыньте листья пандана и полностью остудите кайю — она загустеет ещё сильнее.\nОтварите яйца ровно шесть минут и подайте в мисочке с соевым соусом и белым перцем.\nПодсушите хлеб до хруста, намажьте кайей и положите холодный ломтик масла между двумя кусками.","source":"UniTools"},{"id":"ut-gua-bao","name":"Гуа бао","country":"Тайвань","category":"snack","diets":[],"slots":["snack"],"time":220,"baseServings":8,"portionNutrition":{"k":620,"p":26,"f":34,"c":52},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Молоко тёплое","quantity":250,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Сахар","quantity":50,"unit":"g","note":""},{"name":"Свиная грудинка","quantity":900,"unit":"g","note":""},{"name":"Соевый соус","quantity":100,"unit":"ml","note":""},{"name":"Леденцовый сахар","quantity":40,"unit":"g","note":""},{"name":"Шаосинское вино","quantity":80,"unit":"ml","note":""},{"name":"Бадьян","quantity":2,"unit":"piece","note":""},{"name":"Маринованная горчичная зелень","quantity":200,"unit":"g","note":""},{"name":"Арахис жареный","quantity":100,"unit":"g","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Растворите дрожжи с ложкой сахара в тёплом молоке и оставьте на десять минут.\nЗамесите тесто из муки, опары, оставшегося сахара, масла и соли и вымешивайте пятнадцать минут.\nБланшируйте грудинку две минуты, промойте и тушите в соевом соусе, вине, сахаре и бадьяне полтора часа.\nДайте тесту подойти час, раскатайте в овалы и сложите каждый пополам с полоской пергамента внутри.\nДайте булочкам расстояться тридцать минут и готовьте на пару двенадцать минут.\nРастолките арахис с двумя ложками сахара в грубую крошку.\nРаскройте булочку, вложите ломоть грудинки, зелень, арахисовую крошку и кинзу.","source":"UniTools"},{"id":"ut-pineapple-cake","name":"Тайваньское ананасовое печенье","country":"Тайвань","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":180,"baseServings":16,"portionNutrition":{"k":320,"p":4,"f":14,"c":46},"details":[{"name":"Ананас","quantity":1,"unit":"kg","note":"очищенный"},{"name":"Зимняя дыня","quantity":500,"unit":"g","note":""},{"name":"Сахар","quantity":150,"unit":"g","note":""},{"name":"Мальтозный сироп","quantity":80,"unit":"g","note":""},{"name":"Мука","quantity":300,"unit":"g","note":""},{"name":"Сливочное масло","quantity":200,"unit":"g","note":""},{"name":"Сухое молоко","quantity":40,"unit":"g","note":""},{"name":"Тёртый твёрдый сыр","quantity":40,"unit":"g","note":""},{"name":"Сахарная пудра","quantity":60,"unit":"g","note":""},{"name":"Желтки","quantity":2,"unit":"piece","note":""},{"name":"Кукурузный крахмал","quantity":40,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Натрите ананас и зимнюю дыню на крупной тёрке и отожмите сок через марлю.\nУварите отжатый сок отдельно до половины объёма — он вернётся в начинку как концентрат.\nТушите мякоть с сахаром и мальтозой на слабом огне час, помешивая каждые пять минут.\nВлейте уваренный сок и доведите начинку до состояния, когда лопатка оставляет след на дне.\nВзбейте масло с сахарной пудрой, желтками, сухим молоком, сыром и солью, вмешайте муку и крахмал.\nОхладите тесто полчаса, разделите на шарики и расплющите каждый в ладони.\nЗаверните шарик начинки в тесто, вложите в квадратную форму и пеките при 170 °C двадцать пять минут, перевернув на середине.","source":"UniTools"},{"id":"ut-shan-noodles","name":"Шанская лапша","country":"Мьянма","category":"main","diets":[],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":620,"p":36,"f":24,"c":68},"details":[{"name":"Рисовая лапша","quantity":400,"unit":"g","note":""},{"name":"Куриный фарш","quantity":500,"unit":"g","note":""},{"name":"Помидоры","quantity":600,"unit":"g","note":""},{"name":"Шалот","quantity":5,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Куркума","quantity":1,"unit":"tsp","note":""},{"name":"Рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Маринованная горчичная зелень","quantity":150,"unit":"g","note":""},{"name":"Арахис жареный","quantity":80,"unit":"g","note":""},{"name":"Зелёный лук","quantity":4,"unit":"piece","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте нарезанный шалот в масле до тёмно-золотого и отложите половину для подачи.\nДобавьте чеснок, паприку и куркуму и прогрейте минуту до запаха.\nПоложите куриный фарш и жарьте, разбивая комки, пока он не побелеет.\nДобавьте нарезанные помидоры и рыбный соус и тушите двадцать пять минут до густой пасты.\nСмелите арахис в грубую крошку, оставив несколько целых орехов.\nОтварите рисовую лапшу, промойте и разложите по мискам.\nВыложите соус на лапшу, посыпьте арахисом, жареным шалотом, маринованной зеленью и кинзой.","source":"UniTools"},{"id":"ut-ohn-no-khao-swe","name":"Он но кхао свэ","country":"Мьянма","category":"soup","diets":[],"slots":["lunch","dinner"],"time":80,"baseServings":5,"portionNutrition":{"k":720,"p":42,"f":34,"c":66},"details":[{"name":"Пшеничная лапша","quantity":500,"unit":"g","note":""},{"name":"Куриное бедро","quantity":700,"unit":"g","note":"мелкими кусками"},{"name":"Кокосовое молоко","quantity":600,"unit":"ml","note":""},{"name":"Нутовая мука","quantity":60,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Куркума","quantity":2,"unit":"tsp","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":"варёные, к подаче"},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Хлопья чили","quantity":2,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Растолките лук, чеснок и имбирь в пасту и обжарьте её в масле с куркумой и паприкой.\nДобавьте курицу мелкими кусками и жарьте, пока она не побелеет со всех сторон.\nВлейте литр воды и рыбный соус и варите двадцать минут на слабом огне.\nРазведите нутовую муку в стакане холодной воды до полной гладкости без комков.\nВливайте разведённую муку в бульон тонкой струйкой, непрерывно размешивая венчиком.\nПроварите десять минут до густоты, влейте кокосовое молоко и прогрейте пять минут не кипятя.\nОтварите лапшу, разложите по мискам, залейте бульоном и подайте с яйцом, лаймом и чили.","source":"UniTools"},{"id":"ut-num-banh-chok","name":"Ном банчок","country":"Камбоджа","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":85,"baseServings":5,"portionNutrition":{"k":580,"p":38,"f":24,"c":58},"details":[{"name":"Тонкая рисовая лапша","quantity":500,"unit":"g","note":""},{"name":"Белая рыба","quantity":700,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":500,"unit":"ml","note":""},{"name":"Лемонграсс","quantity":4,"unit":"piece","note":""},{"name":"Галангал","quantity":40,"unit":"g","note":""},{"name":"Куркума свежая","quantity":30,"unit":"g","note":""},{"name":"Листья каффир-лайма","quantity":6,"unit":"piece","note":""},{"name":"Прахок или рыбный соус","quantity":3,"unit":"tbsp","note":""},{"name":"Банановый цвет","quantity":200,"unit":"g","note":""},{"name":"Ростки маша","quantity":200,"unit":"g","note":""},{"name":"Огурцы","quantity":2,"unit":"piece","note":""},{"name":"Спаржевая фасоль","quantity":150,"unit":"g","note":""},{"name":"Мята, базилик, кинза","quantity":100,"unit":"g","note":""},{"name":"Стебли водяной лилии","quantity":150,"unit":"g","note":"по желанию"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите рыбу в подсоленной воде десять минут, выньте и разберите руками, убрав все кости.\nРастолките в ступке лемонграсс, галангал, куркуму и листья лайма в пасту крыонг.\nРазотрите разобранную рыбу с пастой в ступке, оставляя волокна различимыми.\nПрогрейте рыбно-пряную массу в сотейнике пять минут, добавьте прахок и рыбный бульон.\nВлейте кокосовое молоко и прогрейте десять минут, не давая закипеть.\nНашинкуйте все овощи тонко и разложите горой на большом блюде.\nОтварите лапшу, промойте холодной водой и подавайте холодной, залив тёплым карри.","source":"UniTools"},{"id":"ut-samlor-korko","name":"Самло корко","country":"Камбоджа","category":"soup","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":480,"p":28,"f":22,"c":42},"details":[{"name":"Свинина","quantity":500,"unit":"g","note":"кубиками"},{"name":"Рис","quantity":60,"unit":"g","note":"для обжарки и помола"},{"name":"Лемонграсс","quantity":3,"unit":"piece","note":""},{"name":"Галангал","quantity":30,"unit":"g","note":""},{"name":"Куркума свежая","quantity":20,"unit":"g","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Прахок","quantity":2,"unit":"tbsp","note":""},{"name":"Тыква","quantity":300,"unit":"g","note":""},{"name":"Зелёная папайя","quantity":300,"unit":"g","note":""},{"name":"Баклажаны","quantity":200,"unit":"g","note":""},{"name":"Спаржевая фасоль","quantity":150,"unit":"g","note":""},{"name":"Листья моринги или шпинат","quantity":150,"unit":"g","note":""},{"name":"Рыбный соус","quantity":2,"unit":"tbsp","note":""},{"name":"Пальмовый сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте рис на сухой сковороде до тёмно-золотого и смелите в мелкий порошок.\nРастолките лемонграсс, галангал, куркуму и чеснок в пасту крыонг.\nОбжарьте пасту в масле пять минут, добавьте прахок и прогрейте ещё две.\nДобавьте свинину и обжарьте до румяности, потом залейте полутора литрами воды.\nВарите двадцать минут, затем заложите тыкву, папайю и баклажан.\nВсыпьте рисовый порошок, размешав его сначала в половнике бульона, и проварите десять минут.\nДобавьте фасоль и листья моринги на последние пять минут, доведите вкус рыбным соусом и сахаром.","source":"UniTools"},{"id":"ut-torta-frita","name":"Торта фрита","country":"Уругвай","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":65,"baseServings":8,"portionNutrition":{"k":380,"p":6,"f":18,"c":48},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода горячая","quantity":250,"unit":"ml","note":""},{"name":"Смалец","quantity":80,"unit":"g","note":"растопленный"},{"name":"Разрыхлитель","quantity":1,"unit":"tsp","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Сахар","quantity":50,"unit":"g","note":"к подаче"},{"name":"Дульсе де лече","quantity":200,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":1.5,"unit":"tsp","note":""}],"steps":"Смешайте муку с солью и разрыхлителем в большой миске.\nРастопите смалец и влейте в горячую воду, размешав до однородности.\nВлейте жидкость в муку и замесите тесто ложкой, пока оно не остынет достаточно для рук.\nВымешивайте руками десять минут до гладкого эластичного теста.\nНакройте и дайте отдохнуть двадцать минут при комнатной температуре.\nРазделите на восемь частей, раскатайте в круги толщиной полсантиметра и сделайте надрез в центре.\nЖарьте при 180 °C по полторы минуты с каждой стороны и подавайте с сахаром или дульсе де лече.","source":"UniTools"},{"id":"ut-buseca","name":"Бусека","country":"Уругвай","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":240,"baseServings":6,"portionNutrition":{"k":620,"p":44,"f":30,"c":42},"details":[{"name":"Говяжий рубец","quantity":1,"unit":"kg","note":"очищенный"},{"name":"Белая фасоль","quantity":300,"unit":"g","note":"замочить на ночь"},{"name":"Чорисо","quantity":250,"unit":"g","note":""},{"name":"Копчёная грудинка","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Сельдерей стеблевой","quantity":3,"unit":"piece","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Помидоры","quantity":400,"unit":"g","note":""},{"name":"Уксус","quantity":100,"unit":"ml","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Паприка","quantity":1,"unit":"tbsp","note":""},{"name":"Оливковое масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте рубец несколько раз, потрите солью и промойте снова до полной чистоты.\nПроварите рубец в воде с половиной уксуса десять минут и слейте первую воду.\nЗалейте свежей водой с лавровым листом и варите три часа до полной мягкости.\nОтварите фасоль отдельно до мягкости, час с четвертью, и отставьте с её отваром.\nОбжарьте грудинку и нарезанный чорисо, добавьте лук, морковь и сельдерей и потомите десять минут.\nВмешайте паприку и помидоры, добавьте нарезанный рубец с частью его бульона и картофель.\nВарите двадцать пять минут, вмешайте фасоль с отваром, посолите и прогрейте ещё десять.","source":"UniTools"},{"id":"ut-kak-ik","name":"Как-ик","country":"Гватемала","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":160,"baseServings":6,"portionNutrition":{"k":520,"p":52,"f":18,"c":32},"details":[{"name":"Индейка","quantity":2,"unit":"kg","note":"кусками с костью"},{"name":"Перец гуахильо","quantity":6,"unit":"piece","note":""},{"name":"Перец кобанеро","quantity":3,"unit":"piece","note":""},{"name":"Помидоры","quantity":500,"unit":"g","note":""},{"name":"Томатильо","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Кориандр семена","quantity":1,"unit":"tbsp","note":""},{"name":"Ачиоте","quantity":1,"unit":"tbsp","note":""},{"name":"Мускатный цвет","quantity":1,"unit":"tsp","note":""},{"name":"Самат или кинза","quantity":30,"unit":"g","note":""},{"name":"Мята","quantity":20,"unit":"g","note":""},{"name":"Тамалито из кукурузы","quantity":6,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите индейку с луковицей в трёх литрах воды полтора часа, снимая пену.\nОчистите перцы от семян и обожгите на сухой сковороде по десять секунд с каждой стороны.\nОбожгите помидоры, томатильо, лук и чеснок на той же сковороде до чёрных пятен.\nПодсушите кориандр, ачиоте и мускатный цвет на сухой сковороде до запаха.\nПробейте всё в блендере с двумя половниками бульона до гладкой красной массы.\nПроцедите массу через сито в кастрюлю с индейкой и варите двадцать пять минут.\nДобавьте самат и мяту на последние пять минут и подавайте с кукурузными тамалито.","source":"UniTools"},{"id":"ut-rellenitos","name":"Рельенитос","country":"Гватемала","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":90,"baseServings":6,"portionNutrition":{"k":480,"p":8,"f":16,"c":78},"details":[{"name":"Спелый подорожник","quantity":6,"unit":"piece","note":"с чёрной кожурой"},{"name":"Чёрная фасоль","quantity":300,"unit":"g","note":"варёная"},{"name":"Сахар","quantity":120,"unit":"g","note":""},{"name":"Тёмный шоколад","quantity":80,"unit":"g","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Гвоздика молотая","quantity":0.5,"unit":"tsp","note":""},{"name":"Мука","quantity":60,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":800,"unit":"ml","note":""},{"name":"Сахарная пудра","quantity":40,"unit":"g","note":"к подаче"},{"name":"Сметана","quantity":150,"unit":"ml","note":"к подаче"},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Отварите подорожник в кожуре двадцать минут, пока он не станет полностью мягким.\nОчистите горячим и разомните в гладкое пюре с щепотью соли и мукой.\nОхладите пюре в холодильнике полчаса — тёплое не слепится в шарики.\nРазомните варёную фасоль и уварите её с сахаром, корицей и гвоздикой до густой пасты.\nВмешайте шоколад в горячую фасолевую пасту и полностью остудите.\nРасплющите пюре на ладони, положите фасолевую начинку и залепите в плотный шарик.\nЖарьте при 170 °C по три минуты до румяной корки и подавайте с пудрой и сметаной.","source":"UniTools"},{"id":"ut-pollo-guisado-dominicano","name":"Польо гисадо","country":"Доминиканская Республика","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":80,"baseServings":5,"portionNutrition":{"k":680,"p":46,"f":26,"c":62},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"кусками"},{"name":"Сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Орегано сушёный","quantity":1,"unit":"tbsp","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Картофель","quantity":500,"unit":"g","note":""},{"name":"Оливки","quantity":60,"unit":"g","note":""},{"name":"Кинза","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте курицу с соком лайма, натрите орегано, чесноком, солью и перцем и оставьте на час.\nРастопите сахар в масле на среднем огне до цвета тёмного янтаря, не мешая ложкой.\nВыложите куски курицы в карамель и обжарьте до тёмной корки со всех сторон.\nДобавьте лук, перец и томатную пасту и прогрейте пять минут, помешивая.\nВлейте стакан воды, накройте и тушите двадцать пять минут на слабом огне.\nЗаложите картофель крупными кусками и тушите ещё двадцать минут до мягкости.\nВмешайте оливки и кинзу, выпарите соус до густоты и подавайте с белым рисом.","source":"UniTools"},{"id":"ut-habichuelas-con-dulce","name":"Сладкая фасоль","country":"Доминиканская Республика","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":115,"baseServings":8,"portionNutrition":{"k":480,"p":12,"f":18,"c":68},"details":[{"name":"Красная фасоль","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Кокосовое молоко","quantity":800,"unit":"ml","note":""},{"name":"Концентрированное молоко","quantity":370,"unit":"ml","note":""},{"name":"Батат","quantity":500,"unit":"g","note":""},{"name":"Сахар","quantity":250,"unit":"g","note":""},{"name":"Корица палочка","quantity":3,"unit":"piece","note":""},{"name":"Гвоздика","quantity":6,"unit":"piece","note":""},{"name":"Изюм","quantity":100,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Сухое печенье","quantity":150,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Отварите замоченную фасоль в свежей воде час, пока она не станет полностью мягкой.\nПробейте фасоль блендером с частью её отвара до гладкой массы.\nПроцедите массу через сито, вдавливая ложкой, и выбросьте оставшуюся кожуру.\nВерните на огонь, добавьте кокосовое и концентрированное молоко, корицу, гвоздику и сахар.\nВарите двадцать минут на слабом огне, помешивая, чтобы не пригорело.\nДобавьте батат кусками и изюм и варите ещё двадцать минут до мягкости батата.\nВмешайте ваниль, масло и щепоть соли, охладите и подавайте холодным с печеньем.","source":"UniTools"},{"id":"ut-trinidad-roti","name":"Тринидадская роти","country":"Тринидад и Тобаго","category":"bread","diets":["vegetarian","vegan"],"slots":["breakfast","snack"],"time":130,"baseServings":6,"portionNutrition":{"k":720,"p":38,"f":30,"c":76},"details":[{"name":"Мука","quantity":700,"unit":"g","note":""},{"name":"Вода тёплая","quantity":400,"unit":"ml","note":""},{"name":"Разрыхлитель","quantity":2,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":150,"unit":"ml","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Курица для карри","quantity":1,"unit":"kg","note":"кусками"},{"name":"Порошок карри","quantity":3,"unit":"tbsp","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Тимьян","quantity":4,"unit":"sprig","note":""},{"name":"Соль","quantity":2,"unit":"tsp","note":""}],"steps":"Замесите мягкое тесто из муки, разрыхлителя, соли и тёплой воды и вымешивайте десять минут.\nНакройте и дайте отдохнуть час — тесто должно стать податливым и не пружинить.\nЗамаринуйте курицу с карри, чесноком, тимьяном и солью и потушите с картофелем сорок минут.\nРазделите тесто на шесть шаров, раскатайте каждый тонко и смажьте маслом.\nСверните круг жгутом, закрутите спиралью и дайте постоять двадцать минут.\nРаскатайте спирали заново в круги и жарьте на сухой сковороде по полторы минуты с каждой стороны, смазывая топлёным маслом.\nСнимите лепёшку на доску и разбейте её двумя лопатками в мягкие лохмотья. Подавайте с карри.","source":"UniTools"},{"id":"ut-pelau","name":"Пелау","country":"Тринидад и Тобаго","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":720,"p":42,"f":26,"c":82},"details":[{"name":"Курица","quantity":1.2,"unit":"kg","note":"кусками"},{"name":"Рис длиннозёрный","quantity":500,"unit":"g","note":""},{"name":"Голубиный горох","quantity":300,"unit":"g","note":"полуготовый"},{"name":"Кокосовое молоко","quantity":400,"unit":"ml","note":""},{"name":"Коричневый сахар","quantity":3,"unit":"tbsp","note":""},{"name":"Зелёная приправа","quantity":4,"unit":"tbsp","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Тыква","quantity":200,"unit":"g","note":""},{"name":"Перец скотч-боннет","quantity":1,"unit":"piece","note":""},{"name":"Кетчуп","quantity":2,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Салат из капусты","quantity":300,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте курицу в зелёной приправе, кетчупе, соли и перце минимум на час.\nРазогрейте масло в казане и всыпьте сахар, не размешивая ложкой.\nДождитесь, пока сахар потемнеет почти до чёрного и начнёт дымиться, и сразу выложите курицу.\nОбжарьте курицу, обваливая в карамели, пока каждый кусок не станет тёмно-коричневым.\nДобавьте лук, морковь, тыкву и голубиный горох и прогрейте пять минут.\nВсыпьте промытый рис, влейте кокосовое молоко с водой на палец выше и положите целый чили.\nНакройте и варите двадцать пять минут на слабом огне, не открывая. Подавайте с салатом из капусты.","source":"UniTools"},{"id":"ut-hallaca","name":"Айяка","country":"Венесуэла","category":"main","diets":[],"slots":["lunch","dinner"],"time":240,"baseServings":10,"portionNutrition":{"k":720,"p":36,"f":38,"c":62},"details":[{"name":"Кукурузная мука масарепа","quantity":1,"unit":"kg","note":""},{"name":"Говядина","quantity":600,"unit":"g","note":"кубиками"},{"name":"Свинина","quantity":500,"unit":"g","note":"кубиками"},{"name":"Курица","quantity":500,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":3,"unit":"piece","note":""},{"name":"Семена аннато","quantity":3,"unit":"tbsp","note":""},{"name":"Оливки","quantity":150,"unit":"g","note":""},{"name":"Изюм","quantity":120,"unit":"g","note":""},{"name":"Каперсы","quantity":3,"unit":"tbsp","note":""},{"name":"Банановые листья","quantity":20,"unit":"piece","note":""},{"name":"Сладкое вино","quantity":150,"unit":"ml","note":""},{"name":"Смалец","quantity":250,"unit":"g","note":""},{"name":"Мясной бульон","quantity":1,"unit":"l","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Прогрейте семена аннато в смальце пять минут и процедите — окрашенный жир пойдёт и в тесто, и в гисо.\nОбжарьте лук и перец в ачиотовом жире, добавьте все три вида мяса и обжарьте до румяности.\nВлейте вино и бульон и тушите час, пока мясо не станет мягким, а соус густым.\nПолностью остудите гисо, лучше оставив его на ночь в холодильнике.\nЗамесите тесто из масарепы, тёплого бульона, ачиотового жира и соли до пластичности.\nПрогрейте банановые листья, разложите на каждый лепёшку теста, гисо, оливки, изюм и каперсы.\nЗаверните в два листа, перевяжите бечёвкой крест-накрест и варите в воде час двадцать.","source":"UniTools"},{"id":"ut-asado-negro","name":"Асадо негро","country":"Венесуэла","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":290,"baseServings":8,"portionNutrition":{"k":720,"p":54,"f":30,"c":52},"details":[{"name":"Говяжий огузок","quantity":2,"unit":"kg","note":"одним куском"},{"name":"Панела или коричневый сахар","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":2,"unit":"piece","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Лук-порей","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Помидоры","quantity":500,"unit":"g","note":""},{"name":"Красное вино","quantity":250,"unit":"ml","note":""},{"name":"Вустерский соус","quantity":3,"unit":"tbsp","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Рис","quantity":500,"unit":"g","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Наколите мясо ножом в нескольких местах, натрите солью, перцем и чесноком и оставьте на час.\nРастопите панелу в масле в казане до почти чёрного цвета, не размешивая ложкой.\nОпустите мясо в карамель и обжарьте со всех сторон до чёрной корки, минут пятнадцать.\nВыньте мясо, обжарьте в том же жире лук, перец, морковь и порей до мягкости.\nВерните мясо, добавьте помидоры, вино, вустерский соус и лавровый лист, залейте водой наполовину.\nТушите под крышкой четыре часа на самом слабом огне, переворачивая кусок каждый час.\nВыньте мясо, процедите соус, уварите его вдвое и нарежьте говядину поперёк волокон.","source":"UniTools"},{"id":"ut-pique-macho","name":"Пике мачо","country":"Боливия","category":"main","diets":[],"slots":["lunch","dinner"],"time":70,"baseServings":4,"portionNutrition":{"k":980,"p":48,"f":58,"c":68},"details":[{"name":"Говяжья вырезка","quantity":700,"unit":"g","note":"кубиками"},{"name":"Картофель","quantity":1.2,"unit":"kg","note":"брусочками"},{"name":"Сосиски","quantity":300,"unit":"g","note":""},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Перец локото или халапеньо","quantity":3,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Горчица","quantity":2,"unit":"tbsp","note":""},{"name":"Майонез","quantity":100,"unit":"g","note":""},{"name":"Кетчуп","quantity":100,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте картофель толстыми брусочками и вымочите в холодной воде двадцать минут.\nОбсушите картофель и обжарьте дважды: при 150 °C до мягкости, потом при 190 °C до хруста.\nОбжарьте говядину кубиками на сильном огне порциями по две минуты и отложите.\nОбжарьте нарезанные сосиски до румяности и добавьте лук с перцем на пять минут.\nВерните мясо в сковороду, добавьте помидоры и горчицу и прогрейте три минуты.\nПожарьте яйца до жидкого желтка и нарежьте локото тонкими кольцами.\nВыложите картофель горой, сверху мясо с овощами, яйца и кольца локото, полейте майонезом и кетчупом.","source":"UniTools"},{"id":"ut-api-morado","name":"Апи морадо","country":"Боливия","category":"drink","diets":["vegetarian","vegan","gluten-free"],"slots":[],"time":65,"baseServings":6,"portionNutrition":{"k":280,"p":4,"f":2,"c":64},"details":[{"name":"Фиолетовая кукуруза","quantity":400,"unit":"g","note":"замочить на ночь"},{"name":"Вода","quantity":2.5,"unit":"l","note":""},{"name":"Корица палочка","quantity":3,"unit":"piece","note":""},{"name":"Гвоздика","quantity":6,"unit":"piece","note":""},{"name":"Апельсиновая корка","quantity":1,"unit":"piece","note":""},{"name":"Сахар","quantity":200,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Сыр для пастель","quantity":200,"unit":"g","note":"к подаче"}],"steps":"Замочите фиолетовую кукурузу в холодной воде на ночь, не сливая воду утром.\nСмелите кукурузу вместе с водой в блендере до однородной фиолетовой жидкости.\nПроцедите через мелкое сито, вдавливая мякоть, и повторите процеживание ещё раз.\nВлейте оставшуюся воду, добавьте корицу, гвоздику и апельсиновую корку.\nВарите на среднем огне сорок минут, помешивая деревянной ложкой, пока не загустеет.\nДобавьте сахар и сок лимона и проварите ещё пять минут.\nВыньте специи и подавайте горячим в кружках, с жареным пирожком с сыром.","source":"UniTools"},{"id":"ut-ceviche-ecuatoriano","name":"Эквадорский севиче","country":"Эквадор","category":"salad","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":50,"baseServings":5,"portionNutrition":{"k":420,"p":40,"f":12,"c":38},"details":[{"name":"Креветки","quantity":900,"unit":"g","note":"неочищенные"},{"name":"Лук красный","quantity":3,"unit":"piece","note":""},{"name":"Лайм","quantity":8,"unit":"piece","note":""},{"name":"Апельсин","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Кетчуп","quantity":4,"unit":"tbsp","note":""},{"name":"Горчица","quantity":1,"unit":"tbsp","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Перец чили","quantity":1,"unit":"piece","note":""},{"name":"Попкорн","quantity":100,"unit":"g","note":"к подаче"},{"name":"Чипсы из подорожника","quantity":150,"unit":"g","note":"к подаче"},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите креветки, панцири отварите в литре воды двадцать минут и процедите бульон.\nОтварите креветки в этом бульоне ровно две минуты и сразу переложите в ледяную воду.\nПолностью охладите бульон — он станет основой заправки.\nНарежьте красный лук тонкими перьями, промойте холодной водой и замаринуйте в соке лаймов с солью.\nПробейте два помидора в пюре и смешайте с кетчупом, горчицей, соком апельсинов и холодным бульоном.\nСоедините креветки, маринованный лук, нарезанные помидоры и заправку.\nОхладите час, вмешайте кинзу и подавайте с попкорном и чипсами из подорожника.","source":"UniTools"},{"id":"ut-fanesca","name":"Фанеска","country":"Эквадор","category":"soup","diets":["pescatarian"],"slots":["lunch","dinner"],"time":210,"baseServings":10,"portionNutrition":{"k":680,"p":42,"f":28,"c":68},"details":[{"name":"Солёная треска","quantity":700,"unit":"g","note":"вымочить сутки"},{"name":"Молоко","quantity":1.5,"unit":"l","note":""},{"name":"Тыква","quantity":500,"unit":"g","note":""},{"name":"Кабачок","quantity":400,"unit":"g","note":""},{"name":"Кукуруза","quantity":200,"unit":"g","note":""},{"name":"Белая фасоль","quantity":150,"unit":"g","note":""},{"name":"Чочо (люпин)","quantity":150,"unit":"g","note":""},{"name":"Чечевица","quantity":150,"unit":"g","note":""},{"name":"Зелёный горошек","quantity":150,"unit":"g","note":""},{"name":"Бобы","quantity":150,"unit":"g","note":""},{"name":"Рис","quantity":100,"unit":"g","note":""},{"name":"Арахис","quantity":100,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сливки","quantity":250,"unit":"ml","note":""},{"name":"Свежий сыр","quantity":200,"unit":"g","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":"варёные, к подаче"},{"name":"Ачиоте","quantity":1,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Вымочите треску сутки, меняя воду четыре раза, и отварите в молоке двадцать минут.\nОтварите фасоль, чочо, бобы, чечевицу и горошек по отдельности до мягкости.\nСмелите арахис с молоком в гладкую массу — он будет загустителем супа.\nОбжарьте лук в ачиотовом масле, добавьте тыкву и кабачок и потушите двадцать минут.\nПробейте тыкву с кабачком блендером и верните в кастрюлю с молоком от трески.\nВмешайте все сваренные бобовые, рис, кукурузу и арахисовую массу и варите тридцать минут.\nДобавьте сливки, сыр и куски трески и подавайте с половинками яиц и жареным подорожником.","source":"UniTools"},{"id":"ut-carimanola","name":"Кариманьола","country":"Панама","category":"snack","diets":[],"slots":["snack"],"time":95,"baseServings":6,"portionNutrition":{"k":480,"p":20,"f":22,"c":52},"details":[{"name":"Юкка (маниок)","quantity":1.2,"unit":"kg","note":""},{"name":"Говяжий фарш","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Перец сладкий","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Томатная паста","quantity":1,"unit":"tbsp","note":""},{"name":"Зира молотая","quantity":1,"unit":"tsp","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Кулантро или кинза","quantity":30,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":1,"unit":"l","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Очистите юкку, удалите жёсткую сердцевину и отварите в подсоленной воде до полной мягкости.\nРазомните юкку горячей и вымешивайте с яйцом и солью до пластичного теста.\nОбжарьте лук, перец и чеснок, добавьте фарш, зиру и томатную пасту и жарьте до готовности.\nВмешайте кулантро в начинку и полностью её остудите.\nВозьмите ком теста мокрыми руками, расплющите на ладони и положите начинку в центр.\nЗалепите и вытяните в продолговатую форму с заострёнными концами.\nЖарьте при 175 °C по четыре минуты до тёмно-золотой корки и подавайте горячими.","source":"UniTools"},{"id":"ut-arroz-con-coco","name":"Рис с кокосом","country":"Панама","category":"side","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":60,"baseServings":6,"portionNutrition":{"k":520,"p":8,"f":24,"c":68},"details":[{"name":"Рис длиннозёрный","quantity":500,"unit":"g","note":""},{"name":"Кокосовое молоко","quantity":800,"unit":"ml","note":"жирное"},{"name":"Вода","quantity":400,"unit":"ml","note":""},{"name":"Сахар","quantity":2,"unit":"tbsp","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":"по желанию"},{"name":"Соль","quantity":1.5,"unit":"tsp","note":""}],"steps":"Влейте кокосовое молоко в казан и варите на среднем огне, помешивая.\nПродолжайте варить, пока молоко не разделится на масло и коричневые шкварки.\nКак только шкварки станут тёмно-коричневыми, сразу влейте воду, чтобы остановить карамелизацию.\nДобавьте сахар, соль и изюм и доведите до кипения.\nПромойте рис до прозрачной воды и всыпьте в кастрюлю ровным слоем.\nВарите на среднем огне без крышки, пока жидкость не сравняется с уровнем риса.\nНакройте, убавьте огонь до минимума и держите двадцать минут, ни разу не открывая.","source":"UniTools"},{"id":"ut-kugelis","name":"Кугелис","country":"Литва","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":8,"portionNutrition":{"k":480,"p":14,"f":26,"c":48},"details":[{"name":"Картофель","quantity":2,"unit":"kg","note":"крахмалистых сортов"},{"name":"Копчёная грудинка","quantity":300,"unit":"g","note":"кубиками"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Молоко","quantity":200,"unit":"ml","note":"горячее"},{"name":"Сметана","quantity":300,"unit":"ml","note":"к подаче"},{"name":"Майоран","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Вытопите грудинку до шкварок, добавьте нарезанный лук и жарьте до золотистого цвета.\nНатрите картофель на мелкой тёрке и слегка отожмите, собрав жидкость в миску.\nДайте жидкости отстояться десять минут, слейте воду и вмешайте осевший крахмал обратно.\nВлейте горячее молоко и горячий жир с луком и шкварками, размешивая быстро.\nВмешайте яйца, соль, перец и майоран до однородной густой массы.\nВылейте в смазанную форму слоем в четыре сантиметра и разровняйте.\nЗапекайте при 180 °C полтора часа до тёмно-золотой корки и дайте постоять двадцать минут.","source":"UniTools"},{"id":"ut-sakotis","name":"Шакотис","country":"Литва","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":135,"baseServings":16,"portionNutrition":{"k":420,"p":8,"f":26,"c":40},"details":[{"name":"Яйца","quantity":20,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":500,"unit":"g","note":""},{"name":"Сахар","quantity":400,"unit":"g","note":""},{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Картофельный крахмал","quantity":100,"unit":"g","note":""},{"name":"Сметана","quantity":200,"unit":"ml","note":""},{"name":"Ваниль","quantity":1,"unit":"tbsp","note":""},{"name":"Цедра лимона","quantity":2,"unit":"piece","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Отделите белки от желтков и взбейте белки с половиной сахара до устойчивых пиков.\nВзбейте мягкое масло с оставшимся сахаром добела, минут восемь.\nВводите желтки по одному, продолжая взбивать, затем вмешайте сметану, ваниль и цедру.\nПросейте муку с крахмалом и солью и вмешайте лопаткой в три приёма.\nВмешайте взбитые белки осторожно, чтобы не осадить массу — тесто должно остаться пышным.\nРазогрейте духовку до 190 °C и вылейте первый тонкий слой на смазанный вертел или в форму.\nЗапекайте каждый слой по три минуты до румяности и лейте следующий, пока тесто не кончится.","source":"UniTools"},{"id":"ut-sklandrausis","name":"Складраусис","country":"Латвия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":90,"baseServings":10,"portionNutrition":{"k":320,"p":7,"f":12,"c":46},"details":[{"name":"Ржаная мука","quantity":400,"unit":"g","note":""},{"name":"Вода тёплая","quantity":180,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":80,"unit":"g","note":""},{"name":"Картофель","quantity":500,"unit":"g","note":""},{"name":"Морковь","quantity":600,"unit":"g","note":""},{"name":"Сметана","quantity":200,"unit":"ml","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Сахар","quantity":80,"unit":"g","note":""},{"name":"Тмин","quantity":1,"unit":"tsp","note":""},{"name":"Корица","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Замесите тесто из ржаной муки, тёплой воды, растопленного масла и соли и дайте отдохнуть полчаса.\nОтварите картофель и морковь по отдельности до полной мягкости.\nРазомните картофель со сметаной, яйцом, тмином и солью в гладкое пюре.\nРазомните морковь со сметаной, яйцом, сахаром и корицей в отдельное пюре.\nРаскатайте тесто тонко, вырежьте круги и сформуйте бортики пальцами, подворачивая края.\nВыложите картофельное пюре первым слоем, сверху морковное, разровняйте ложкой.\nПеките при 200 °C двадцать пять минут и посыпьте корицей ещё горячими.","source":"UniTools"},{"id":"ut-skabu-putra","name":"Скабу путра","country":"Латвия","category":"soup","diets":["vegetarian"],"slots":["lunch","dinner"],"time":85,"baseServings":5,"portionNutrition":{"k":340,"p":14,"f":8,"c":54},"details":[{"name":"Перловая крупа","quantity":250,"unit":"g","note":""},{"name":"Вода","quantity":1.5,"unit":"l","note":""},{"name":"Простокваша или пахта","quantity":1,"unit":"l","note":""},{"name":"Сметана","quantity":150,"unit":"ml","note":""},{"name":"Зелёный лук","quantity":40,"unit":"g","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте перловку и замочите её в холодной воде на два часа.\nОтварите крупу в полутора литрах воды час, пока она не разварится полностью.\nПосолите кашу и полностью остудите её, помешивая, чтобы не образовалась плёнка.\nВмешайте простоквашу в холодную кашу постепенно, добиваясь консистенции густого супа.\nОставьте на четыре часа в холодном месте, чтобы вкус закислился и выровнялся.\nОтварите картофель в мундире и подайте его горячим отдельно.\nРазлейте по мискам, добавьте сметану и посыпьте зелёным луком и укропом.","source":"UniTools"},{"id":"ut-verivorst","name":"Веривёрст","country":"Эстония","category":"main","diets":[],"slots":["lunch","dinner"],"time":120,"baseServings":8,"portionNutrition":{"k":620,"p":26,"f":38,"c":42},"details":[{"name":"Свиная кровь","quantity":700,"unit":"ml","note":""},{"name":"Перловая крупа","quantity":400,"unit":"g","note":""},{"name":"Свиное сало","quantity":250,"unit":"g","note":"кубиками"},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Майоран","quantity":2,"unit":"tbsp","note":""},{"name":"Душистый перец молотый","quantity":1,"unit":"tsp","note":""},{"name":"Свиные кишки","quantity":300,"unit":"g","note":"около 3 метров"},{"name":"Брусничное варенье","quantity":300,"unit":"g","note":"к подаче"},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите перловку в подсоленной воде сорок минут до полуготовности и откиньте.\nВытопите сало до шкварок, добавьте лук и жарьте до золотистого цвета.\nПолностью остудите и крупу, и жир с луком, иначе кровь свернётся при смешивании.\nПроцедите кровь через сито и смешайте с крупой, жиром, майораном, душистым перцем и солью.\nПромойте кишки и набейте их массой на две трети, оставляя место для разбухания крупы.\nПеревяжите колбасы через каждые двадцать сантиметров и наколите иглой в нескольких местах.\nЗапекайте при 180 °C сорок пять минут с кусочками масла и подавайте с брусничным вареньем.","source":"UniTools"},{"id":"ut-kohuke","name":"Кохуке","country":"Эстония","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":50,"baseServings":12,"portionNutrition":{"k":320,"p":12,"f":20,"c":24},"details":[{"name":"Творог","quantity":600,"unit":"g","note":"сухой"},{"name":"Сливочное масло","quantity":100,"unit":"g","note":"мягкое"},{"name":"Сахарная пудра","quantity":120,"unit":"g","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Сливки","quantity":60,"unit":"ml","note":""},{"name":"Тёмный шоколад","quantity":300,"unit":"g","note":""},{"name":"Кокосовое масло","quantity":30,"unit":"g","note":""},{"name":"Изюм","quantity":60,"unit":"g","note":"по желанию"},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Протрите творог через мелкое сито дважды, чтобы не осталось ни одной крупинки.\nВзбейте мягкое масло с сахарной пудрой, ванилью и солью до пышности.\nСоедините творог с масляной смесью и вмешайте сливки до консистенции плотного крема.\nВмешайте изюм и сформуйте двенадцать батончиков размером с палец.\nРазложите батончики на пергаменте и заморозьте на два часа до полной твёрдости.\nРастопите шоколад с кокосовым маслом на водяной бане до гладкости и остудите до тёплого.\nОбмакните замороженные батончики на двух вилках, дайте стечь и выложите на пергамент застывать.","source":"UniTools"},{"id":"ut-kolduny","name":"Колдуны","country":"Беларусь","category":"main","diets":[],"slots":["lunch","dinner"],"time":80,"baseServings":5,"portionNutrition":{"k":620,"p":26,"f":38,"c":44},"details":[{"name":"Картофель","quantity":1.5,"unit":"kg","note":"крахмалистых сортов"},{"name":"Свиной фарш","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Сметана","quantity":300,"unit":"ml","note":""},{"name":"Сушёные грибы","quantity":30,"unit":"g","note":""},{"name":"Майоран","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":100,"unit":"ml","note":""},{"name":"Укроп","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замочите сушёные грибы в тёплой воде на двадцать минут и мелко нарежьте.\nОбжарьте две луковицы с фаршем и грибами, добавьте майоран, соль и перец и полностью остудите.\nНатрите картофель и оставшийся лук на мелкой тёрке в одну миску.\nДайте массе постоять три минуты и слейте отстоявшуюся воду, не трогая осадок.\nВмешайте яйцо, посолите и поперчите картофельную массу.\nВыложите ложку массы на ладонь, положите начинку и накройте второй ложкой массы, залепив края.\nОбжарьте по три минуты с каждой стороны, переложите в сотейник, залейте сметаной и тушите пятнадцать минут.","source":"UniTools"},{"id":"ut-kholodnik","name":"Халаднік","country":"Беларусь","category":"soup","diets":["vegetarian"],"slots":["lunch","dinner"],"time":70,"baseServings":5,"portionNutrition":{"k":320,"p":15,"f":12,"c":38},"details":[{"name":"Свёкла","quantity":500,"unit":"g","note":""},{"name":"Щавель","quantity":200,"unit":"g","note":""},{"name":"Кефир","quantity":1,"unit":"l","note":"холодный"},{"name":"Огурцы","quantity":3,"unit":"piece","note":""},{"name":"Яйца","quantity":5,"unit":"piece","note":"варёные вкрутую"},{"name":"Зелёный лук","quantity":50,"unit":"g","note":""},{"name":"Укроп","quantity":40,"unit":"g","note":""},{"name":"Сметана","quantity":200,"unit":"ml","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":"к подаче, горячий"},{"name":"Уксус","quantity":1,"unit":"tbsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите свёклу до мягкости с ложкой уксуса, чтобы она сохранила цвет, и полностью остудите.\nОтварите щавель в небольшом количестве воды пять минут, пока он не потемнеет, и остудите.\nНатрите остывшую свёклу на крупной тёрке, огурцы нарежьте соломкой.\nСмешайте свёклу, щавель с его отваром, огурцы и зелень со сметаной и посолите.\nВлейте холодный кефир и размешайте до ровного розового цвета.\nУберите в холодильник на час, чтобы суп настоялся и стал по-настоящему холодным.\nОтварите картофель и подайте горячим отдельно, а в суп положите половинки яиц.","source":"UniTools"},{"id":"ut-zemiakove-placky","name":"Земьякове плацки","country":"Словакия","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":50,"baseServings":4,"portionNutrition":{"k":380,"p":8,"f":22,"c":40},"details":[{"name":"Картофель","quantity":1,"unit":"kg","note":"крахмалистых сортов"},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Майоран","quantity":1,"unit":"tbsp","note":""},{"name":"Мука","quantity":60,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Молоко","quantity":60,"unit":"ml","note":""},{"name":"Масло для жарки","quantity":150,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите картофель на мелкой тёрке и слегка отожмите, оставив немного влаги.\nРастолките чеснок с солью в пасту и вмешайте в картофельную массу.\nДобавьте яйцо, молоко, майоран, перец и муку и размешайте до жидковатого теста.\nРазогрейте масло на среднем огне и вылейте половник теста, размазав его очень тонко.\nЖарьте по три минуты с каждой стороны до тёмно-золотой хрустящей корки.\nВыкладывайте на решётку, а не на бумагу, и подавайте сразу.","source":"UniTools"},{"id":"ut-sladke-buchty","name":"Бухты","country":"Словакия","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":135,"baseServings":12,"portionNutrition":{"k":380,"p":9,"f":14,"c":56},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Молоко тёплое","quantity":300,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сахар","quantity":80,"unit":"g","note":""},{"name":"Сливочное масло","quantity":150,"unit":"g","note":""},{"name":"Желтки","quantity":3,"unit":"piece","note":""},{"name":"Сливовое повидло","quantity":300,"unit":"g","note":""},{"name":"Творог","quantity":250,"unit":"g","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Сахарная пудра","quantity":40,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Растворите дрожжи с ложкой сахара в тёплом молоке и оставьте на пятнадцать минут до пены.\nЗамесите тесто из муки, опары, желтков, оставшегося сахара, цедры, соли и половины масла.\nДайте подойти в тепле час, пока тесто не удвоится в объёме.\nРазделите на двенадцать шаров и расплющите каждый в лепёшку на ладони.\nПоложите ложку повидла или творога, залепите шов и переверните швом вниз.\nОбмакните каждую булочку в растопленное масло и уложите вплотную в форму.\nДайте расстояться сорок минут, пеките при 180 °C тридцать пять минут и посыпьте пудрой.","source":"UniTools"},{"id":"ut-struklji","name":"Штрукли","country":"Словения","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":115,"baseServings":8,"portionNutrition":{"k":480,"p":20,"f":22,"c":50},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Вода тёплая","quantity":200,"unit":"ml","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Творог","quantity":700,"unit":"g","note":""},{"name":"Яйца","quantity":3,"unit":"piece","note":""},{"name":"Сметана","quantity":150,"unit":"ml","note":""},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Эстрагон","quantity":20,"unit":"g","note":"для солёной версии"},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Панировочные сухари","quantity":80,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Замесите мягкое тесто из муки, тёплой воды, масла и соли и вымешивайте пятнадцать минут.\nНакройте тёплой миской и оставьте отдыхать сорок минут — тесто должно стать податливым.\nРазотрите творог с яйцами, сметаной, сахаром и изюмом до однородности.\nРастяните тесто руками на скатерти до просвечивания, как для штруделя.\nРаспределите начинку по листу, оставив края свободными, и сверните рулетом с помощью скатерти.\nЗаверните рулет в чистую ткань свободно, завяжите концы и опустите в кипящую подсоленную воду.\nВарите сорок минут, разверните, нарежьте кружками и обжарьте в масле с сухарями.","source":"UniTools"},{"id":"ut-kranjska-klobasa","name":"Краньская колбаса","country":"Словения","category":"main","diets":[],"slots":["lunch","dinner"],"time":90,"baseServings":6,"portionNutrition":{"k":620,"p":32,"f":48,"c":22},"details":[{"name":"Свиная лопатка","quantity":1.6,"unit":"kg","note":""},{"name":"Свиное сало","quantity":400,"unit":"g","note":""},{"name":"Чеснок","quantity":8,"unit":"clove","note":""},{"name":"Нитритная соль","quantity":40,"unit":"g","note":""},{"name":"Чёрный перец молотый","quantity":2,"unit":"tsp","note":""},{"name":"Вода ледяная","quantity":150,"unit":"ml","note":""},{"name":"Свиные кишки","quantity":200,"unit":"g","note":""},{"name":"Хрен тёртый","quantity":100,"unit":"g","note":"к подаче"},{"name":"Горчица","quantity":100,"unit":"g","note":"к подаче"},{"name":"Хлеб","quantity":400,"unit":"g","note":"к подаче"}],"steps":"Нарежьте свинину и сало кубиками и охладите почти до заморозки.\nПропустите мясо через крупную решётку мясорубки, а сало через среднюю.\nВмешайте нитритную соль, растёртый чеснок, перец и ледяную воду и вымешивайте до липкости.\nОставьте фарш в холодильнике на сутки, чтобы соль распределилась и цвет закрепился.\nНабейте кишки плотно, но без пузырей, и перевяжите парами по двадцать сантиметров.\nПодсушите колбасы на воздухе два часа и подкоптите холодным дымом, если есть возможность.\nОпустите в воду 75 °C и держите двадцать пять минут, не давая закипеть. Подавайте с хреном и горчицей.","source":"UniTools"},{"id":"ut-begova-corba","name":"Бегова чорба","country":"Босния и Герцеговина","category":"soup","diets":[],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":520,"p":44,"f":30,"c":16},"details":[{"name":"Курица","quantity":1.5,"unit":"kg","note":"целая"},{"name":"Телятина","quantity":400,"unit":"g","note":"по желанию"},{"name":"Бамия","quantity":200,"unit":"g","note":"мелкая, целая"},{"name":"Морковь","quantity":2,"unit":"piece","note":""},{"name":"Корень сельдерея","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Желтки","quantity":3,"unit":"piece","note":""},{"name":"Сметана","quantity":250,"unit":"ml","note":""},{"name":"Мука","quantity":2,"unit":"tbsp","note":""},{"name":"Сливочное масло","quantity":50,"unit":"g","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите курицу и телятину с луком, морковью и сельдереем час, снимая пену.\nВыньте мясо, процедите бульон и разберите курицу на мелкие волокна.\nПромойте бамию под холодной водой и обсушите, не срезая шляпки.\nРастопите масло, вмешайте муку и прогрейте две минуты, не давая ей потемнеть.\nВлейте бульон в мучную заправку, добавьте бамию и варите пятнадцать минут.\nВзбейте желтки со сметаной и вводите горячий бульон половником, непрерывно размешивая.\nСнимите кастрюлю с огня, влейте смесь, верните мясо и прогрейте не кипятя. Добавьте лимон и петрушку.","source":"UniTools"},{"id":"ut-tufahije","name":"Туфахие","country":"Босния и Герцеговина","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":60,"baseServings":6,"portionNutrition":{"k":520,"p":8,"f":32,"c":54},"details":[{"name":"Яблоки плотных сортов","quantity":6,"unit":"piece","note":""},{"name":"Грецкие орехи","quantity":250,"unit":"g","note":"молотые"},{"name":"Сахар","quantity":300,"unit":"g","note":""},{"name":"Вода","quantity":700,"unit":"ml","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Сливки 33%","quantity":300,"unit":"ml","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Половинки орехов","quantity":6,"unit":"piece","note":"для украшения"}],"steps":"Очистите яблоки и выньте сердцевину, не прорезая насквозь, чтобы получилась чашечка.\nСварите сироп из воды, сахара, лимонного сока и корицы, доведя до кипения.\nОпустите яблоки в сироп и варите на слабом огне двадцать минут, поворачивая их.\nВыньте яблоки шумовкой и полностью остудите, не выливая сироп.\nСмешайте молотые орехи с тремя ложками сиропа до пластичной массы.\nНаполните яблоки ореховой массой с горкой и поставьте в креманки.\nПолейте оставшимся сиропом, украсьте взбитыми сливками и половинкой ореха.","source":"UniTools"},{"id":"ut-ohridska-pastrmka","name":"Охридская форель","country":"Северная Македония","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":520,"p":46,"f":24,"c":32},"details":[{"name":"Форель","quantity":4,"unit":"piece","note":"целая, потрошёная"},{"name":"Лимон","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Петрушка","quantity":40,"unit":"g","note":""},{"name":"Тимьян","quantity":4,"unit":"sprig","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Картофель","quantity":800,"unit":"g","note":""},{"name":"Белое сухое вино","quantity":150,"unit":"ml","note":""},{"name":"Паприка","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте форель, обсушите и сделайте по два надреза с каждой стороны.\nНатрите рыбу солью, перцем, паприкой и оливковым маслом снаружи и внутри.\nВложите в брюшко ломтики лимона, чеснок, петрушку и тимьян.\nНарежьте картофель тонкими кружками и разложите по смазанному противню внахлёст.\nУложите рыбу на картофель, полейте вином и оставшимся маслом.\nЗапекайте при 200 °C двадцать пять минут, пока кожа не подрумянится.\nПроверьте готовность у хребта и подавайте прямо с противня с долькой лимона.","source":"UniTools"},{"id":"ut-pastrmajlija","name":"Пастрмалия","country":"Северная Македония","category":"main","diets":[],"slots":["lunch","dinner"],"time":115,"baseServings":4,"portionNutrition":{"k":720,"p":38,"f":38,"c":58},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода тёплая","quantity":300,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Свиная шея","quantity":600,"unit":"g","note":"с жиром, кубиками"},{"name":"Яйца","quantity":4,"unit":"piece","note":""},{"name":"Паприка","quantity":2,"unit":"tsp","note":""},{"name":"Острый перец","quantity":2,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте свинину кубиками в сантиметр, посолите щедро и оставьте на два часа в холоде.\nРазведите дрожжи в тёплой воде и оставьте на десять минут до пены.\nЗамесите мягкое тесто из муки, опары, масла и соли и вымешивайте десять минут.\nДайте подойти час в тепле, пока тесто не удвоится.\nРазделите тесто на четыре части и растяните каждую в овал длиной в тридцать сантиметров.\nПодверните края внутрь, сделав бортик, и разложите мясо с паприкой по всей поверхности.\nПеките при 250 °C двадцать минут, разбейте сверху яйцо и допеките ещё пять.","source":"UniTools"},{"id":"ut-olla-de-carne","name":"Олья де карне","country":"Коста-Рика","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":215,"baseServings":6,"portionNutrition":{"k":620,"p":42,"f":20,"c":68},"details":[{"name":"Говяжья голяшка","quantity":1.2,"unit":"kg","note":"на кости"},{"name":"Юкка","quantity":500,"unit":"g","note":""},{"name":"Тыква","quantity":400,"unit":"g","note":""},{"name":"Кукуруза","quantity":2,"unit":"piece","note":"початками"},{"name":"Плантайн","quantity":2,"unit":"piece","note":"зелёный"},{"name":"Картофель","quantity":400,"unit":"g","note":""},{"name":"Морковь","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Сладкий перец","quantity":1,"unit":"piece","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Рис","quantity":400,"unit":"g","note":"к подаче"},{"name":"Лайм","quantity":2,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте голяшку холодной водой, доведите до кипения и тщательно снимите пену.\nДобавьте лук, перец и соль и варите на слабом огне два часа до мягкости мяса.\nНарежьте юкку крупными кусками, удалив жёсткую сердцевину, и заложите в бульон.\nЧерез двадцать минут добавьте кукурузу початками и морковь.\nЕщё через двадцать минут заложите картофель и тыкву крупными кусками.\nПоследним кладите плантайн и варите десять минут, не дольше.\nВыньте гущу шумовкой на блюдо, бульон разлейте в чашки и подайте с рисом, кинзой и лаймом.","source":"UniTools"},{"id":"ut-chorreadas","name":"Чорреадас","country":"Коста-Рика","category":"breakfast","diets":["vegetarian","gluten-free"],"slots":["breakfast"],"time":40,"baseServings":4,"portionNutrition":{"k":380,"p":12,"f":18,"c":44},"details":[{"name":"Свежая кукуруза","quantity":6,"unit":"piece","note":"початками"},{"name":"Сахар","quantity":40,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Кукурузная мука","quantity":30,"unit":"g","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Натилья или сметана","quantity":200,"unit":"ml","note":"к подаче"},{"name":"Свежий белый сыр","quantity":150,"unit":"g","note":"к подаче"},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Срежьте зёрна с початков ножом, ведя лезвие вдоль стержня.\nПеремелите зёрна в блендере короткими импульсами до крупитчатой массы.\nВмешайте яйцо, сахар, соль и кукурузную муку до консистенции густой сметаны.\nРазогрейте сковороду с маслом на среднем огне до лёгкого дымка.\nВылейте половник теста и разровняйте в круг диаметром пятнадцать сантиметров.\nЖарьте по три минуты с каждой стороны до румяных пятен и упругости в центре.\nПодавайте горячими с натильей и ломтиком свежего сыра.","source":"UniTools"},{"id":"ut-montucas","name":"Монтукас","country":"Гондурас","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":145,"baseServings":8,"portionNutrition":{"k":540,"p":28,"f":28,"c":46},"details":[{"name":"Свежая кукуруза","quantity":10,"unit":"piece","note":"початками, с листьями"},{"name":"Куриное бедро","quantity":800,"unit":"g","note":""},{"name":"Свиной жир","quantity":150,"unit":"g","note":""},{"name":"Сладкий перец","quantity":1,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Аннато","quantity":2,"unit":"tsp","note":""},{"name":"Оливки","quantity":80,"unit":"g","note":""},{"name":"Каперсы","quantity":40,"unit":"g","note":""},{"name":"Сахар","quantity":40,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Снимите листья с початков целыми и промойте их в тёплой воде.\nСрежьте зёрна и перемелите их в блендере вместе с выделившимся соком.\nВзбейте свиной жир с солью и сахаром и вмешайте кукурузную массу до однородности.\nОтварите курицу до мягкости, разберите на волокна и сохраните бульон.\nОбжарьте лук, перец и помидоры с аннато, добавьте курицу, оливки и каперсы.\nВыложите ложку теста на лист, сверху начинку, заверните и подверните концы вниз.\nПоставьте свёртки вертикально в кастрюлю и варите на пару час с четвертью.","source":"UniTools"},{"id":"ut-pastelitos-hondurenos","name":"Пастелитос","country":"Гондурас","category":"snack","diets":["gluten-free"],"slots":["snack"],"time":85,"baseServings":6,"portionNutrition":{"k":520,"p":20,"f":26,"c":52},"details":[{"name":"Кукурузная мука маса","quantity":500,"unit":"g","note":""},{"name":"Вода тёплая","quantity":400,"unit":"ml","note":""},{"name":"Говяжий фарш","quantity":400,"unit":"g","note":""},{"name":"Картофель","quantity":300,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Аннато","quantity":1,"unit":"tsp","note":""},{"name":"Капуста","quantity":300,"unit":"g","note":""},{"name":"Уксус","quantity":50,"unit":"ml","note":""},{"name":"Томатный соус","quantity":200,"unit":"ml","note":""},{"name":"Масло для фритюра","quantity":700,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте фарш с луком и аннато, добавьте мелко нарезанный картофель и тушите до мягкости.\nПосолите начинку, поперчите и полностью остудите.\nНашинкуйте капусту тонко и замаринуйте в уксусе с солью на полчаса.\nЗамесите масу с тёплой водой и солью до пластичного теста, не липнущего к рукам.\nРасплющите шарик теста между двумя листами плёнки в тонкий круг.\nПоложите ложку начинки на половину, сложите пополам и запечатайте края вилкой.\nЖарьте во фритюре при 180 °C по три минуты с каждой стороны и подайте с капустой и соусом.","source":"UniTools"},{"id":"ut-vigoron","name":"Вигорон","country":"Никарагуа","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":130,"baseServings":5,"portionNutrition":{"k":680,"p":24,"f":38,"c":62},"details":[{"name":"Юкка","quantity":1.2,"unit":"kg","note":""},{"name":"Свиная шкура с жиром","quantity":800,"unit":"g","note":""},{"name":"Капуста","quantity":500,"unit":"g","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Белый уксус","quantity":100,"unit":"ml","note":""},{"name":"Лайм","quantity":3,"unit":"piece","note":""},{"name":"Острый перец","quantity":1,"unit":"piece","note":""},{"name":"Банановый лист","quantity":5,"unit":"piece","note":"для подачи"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нашинкуйте капусту тонко, смешайте с помидорами, луком, уксусом, соком лайма и солью.\nОставьте курьидо мариноваться не меньше часа, изредка перемешивая.\nНарежьте свиную шкуру квадратами, посолите и оставьте на двадцать минут.\nВытапливайте шкуру в собственном жире на слабом огне сорок минут.\nУвеличьте огонь и жарьте ещё десять минут, пока шкварки не вздуются и не станут хрустящими.\nОтварите юкку в подсоленной воде до мягкости, вырезав жёсткую сердцевину.\nВыложите юкку на банановый лист, сверху курьидо и шкварки, добавьте острый перец.","source":"UniTools"},{"id":"ut-indio-viejo","name":"Индио вьехо","country":"Никарагуа","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":150,"baseServings":5,"portionNutrition":{"k":560,"p":42,"f":24,"c":44},"details":[{"name":"Говяжья грудинка","quantity":1,"unit":"kg","note":""},{"name":"Кукурузная мука маса","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сладкий перец","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Мята","quantity":30,"unit":"g","note":""},{"name":"Апельсиновый сок","quantity":150,"unit":"ml","note":"кислого апельсина"},{"name":"Аннато","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите грудинку с луковицей и солью полтора часа до полной мягкости.\nВыньте мясо, сохраните бульон и разберите говядину руками на тонкие волокна.\nОбжарьте лук, чеснок, перец и помидоры с аннато до густой основы.\nРазведите масу в холодном бульоне до гладкости, без единого комка.\nДобавьте волокна мяса в овощную основу и прогрейте пять минут.\nВлейте разведённую масу тонкой струёй, непрерывно размешивая, и варите двадцать минут.\nВлейте апельсиновый сок, вмешайте рубленую мяту и подавайте с рисом.","source":"UniTools"},{"id":"ut-vori-vori","name":"Вори вори","country":"Парагвай","category":"soup","diets":["gluten-free"],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":560,"p":38,"f":24,"c":46},"details":[{"name":"Курица","quantity":1.4,"unit":"kg","note":"кусками"},{"name":"Кукурузная мука","quantity":300,"unit":"g","note":""},{"name":"Свежий солёный сыр","quantity":250,"unit":"g","note":"натёртый"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Сладкий перец","quantity":1,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Морковь","quantity":1,"unit":"piece","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Аннато","quantity":1,"unit":"tsp","note":""},{"name":"Орегано","quantity":1,"unit":"tsp","note":""},{"name":"Петрушка","quantity":30,"unit":"g","note":""},{"name":"Растительное масло","quantity":50,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте куски курицы с аннато до румяной корки со всех сторон.\nДобавьте лук, перец, помидоры и морковь и потомите до мягкости овощей.\nЗалейте двумя литрами воды, посолите и варите сорок минут на слабом огне.\nСмешайте кукурузную муку с натёртым сыром, яйцом, орегано и щепотью соли.\nДобавьте пару ложек горячего бульона и вымесите плотное тесто, которое держит форму.\nСкатайте шарики размером с грецкий орех, уплотняя их между ладонями.\nОпустите шарики в кипящий бульон, не мешайте пять минут и варите двадцать. Посыпьте петрушкой.","source":"UniTools"},{"id":"ut-mbeju","name":"Мбеху","country":"Парагвай","category":"bread","diets":["vegetarian","gluten-free"],"slots":["breakfast","snack"],"time":45,"baseServings":6,"portionNutrition":{"k":460,"p":14,"f":24,"c":48},"details":[{"name":"Крахмал маниоки","quantity":500,"unit":"g","note":""},{"name":"Свежий солёный сыр","quantity":350,"unit":"g","note":"натёртый"},{"name":"Свиной жир или масло","quantity":120,"unit":"g","note":""},{"name":"Молоко","quantity":100,"unit":"ml","note":""},{"name":"Кукурузная мука","quantity":100,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Смешайте крахмал маниоки с кукурузной мукой и солью в широкой миске.\nВотрите мягкий жир в сухую смесь пальцами, пока она не станет похожа на влажный песок.\nВмешайте натёртый сыр, продолжая перетирать массу руками.\nДобавляйте молоко по ложке, пока крошка не начнёт слипаться при сжатии в кулаке.\nРазогрейте сухую сковороду на среднем огне, не добавляя ни капли масла.\nНасыпьте крошку слоем в сантиметр и прижмите лопаткой по всей поверхности.\nЖарьте пять минут, переверните тарелкой и доведите вторую сторону до румяности.","source":"UniTools"},{"id":"ut-musakhan","name":"Мусахан","country":"Иордания","category":"main","diets":[],"slots":["lunch","dinner"],"time":125,"baseServings":6,"portionNutrition":{"k":780,"p":44,"f":46,"c":48},"details":[{"name":"Курица","quantity":1.6,"unit":"kg","note":"кусками"},{"name":"Лук","quantity":1.5,"unit":"kg","note":""},{"name":"Сумах","quantity":60,"unit":"g","note":""},{"name":"Оливковое масло","quantity":250,"unit":"ml","note":""},{"name":"Лепёшки таббун","quantity":6,"unit":"piece","note":""},{"name":"Кедровые орехи","quantity":80,"unit":"g","note":""},{"name":"Душистый перец молотый","quantity":2,"unit":"tsp","note":""},{"name":"Кардамон молотый","quantity":1,"unit":"tsp","note":""},{"name":"Корица молотая","quantity":1,"unit":"tsp","note":""},{"name":"Йогурт","quantity":300,"unit":"ml","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите курицу солью, перцем, душистым перцем, кардамоном и корицей и оставьте на полчаса.\nНарежьте лук тонкими полукольцами — полтора килограмма займут минут двадцать.\nТомите лук в оливковом масле на слабом огне сорок минут, пока он не станет прозрачным и сладким.\nВмешайте в лук две трети сумаха и соль и потомите ещё пять минут.\nОбжарьте курицу до румяной корки и запеките при 200 °C двадцать пять минут.\nОбжарьте кедровые орехи на сухой сковороде до золотистого цвета, следя, чтобы не подгорели.\nВыложите лепёшку, на неё лук, сверху курицу, полейте маслом из противня и посыпьте сумахом и орехами.","source":"UniTools"},{"id":"ut-galayet-bandora","name":"Галает бандора","country":"Иордания","category":"main","diets":["vegetarian","vegan"],"slots":["lunch","dinner"],"time":50,"baseServings":4,"portionNutrition":{"k":380,"p":8,"f":26,"c":32},"details":[{"name":"Помидоры","quantity":1.2,"unit":"kg","note":"спелые"},{"name":"Оливковое масло","quantity":120,"unit":"ml","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Зелёный острый перец","quantity":3,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Лепёшки","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Сушёная мята","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте помидоры крупными дольками, не снимая кожуру и не удаляя семена.\nРазогрейте оливковое масло в широкой сковороде и обжарьте лук до мягкости.\nДобавьте раздавленный чеснок и зелёный перец целиком и прогрейте минуту.\nВыложите помидоры, посолите и тушите на среднем огне, изредка помешивая.\nРазомните помидоры ложкой, когда кожица начнёт отходить от мякоти.\nУваривайте ещё пятнадцать минут, пока масло не выступит по краям отдельным слоем.\nПосыпьте сушёной мятой и подайте прямо в сковороде с лепёшками.","source":"UniTools"},{"id":"ut-omani-halwa","name":"Оманская халва","country":"Оман","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":155,"baseServings":16,"portionNutrition":{"k":420,"p":3,"f":22,"c":56},"details":[{"name":"Кукурузный крахмал","quantity":300,"unit":"g","note":""},{"name":"Сахар","quantity":700,"unit":"g","note":""},{"name":"Вода","quantity":1.5,"unit":"l","note":""},{"name":"Топлёное масло","quantity":350,"unit":"g","note":""},{"name":"Розовая вода","quantity":60,"unit":"ml","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Кардамон молотый","quantity":2,"unit":"tsp","note":""},{"name":"Кешью","quantity":150,"unit":"g","note":""},{"name":"Мёд","quantity":100,"unit":"g","note":""}],"steps":"Разведите крахмал в половине холодной воды до полной гладкости, без комков.\nСварите сироп из сахара и оставшейся воды и доведите до кипения.\nВлейте крахмальную смесь в кипящий сироп тонкой струёй, непрерывно размешивая.\nЗамочите шафран в ложке горячей воды и влейте в массу вместе с кардамоном.\nМешайте на слабом огне полтора часа, добавляя топлёное масло понемногу.\nВмешайте мёд, розовую воду и обжаренные кешью, когда масса начнёт отставать от стенок.\nВыложите в форму слоем в три сантиметра, разровняйте и остудите шесть часов.","source":"UniTools"},{"id":"ut-maqdeed","name":"Макдид","country":"Оман","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":105,"baseServings":6,"portionNutrition":{"k":620,"p":52,"f":32,"c":34},"details":[{"name":"Баранина","quantity":1.5,"unit":"kg","note":"мякоть"},{"name":"Крупная соль","quantity":120,"unit":"g","note":""},{"name":"Куркума","quantity":3,"unit":"tbsp","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Сушёный острый перец","quantity":2,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":80,"unit":"g","note":""},{"name":"Зира","quantity":1,"unit":"tbsp","note":""},{"name":"Рис","quantity":500,"unit":"g","note":"к подаче"}],"steps":"Нарежьте баранину полосами шириной в два пальца вдоль волокон.\nНатрите полосы солью и куркумой со всех сторон, не жалея того и другого.\nРазвесьте мясо в тени на сквозняке и сушите от трёх до пяти дней до полной твёрдости.\nЗамочите вяленое мясо в холодной воде на два часа, сменив воду один раз.\nОтварите мясо сорок минут, пока оно не станет мягким и не начнёт разбираться на волокна.\nОбжарьте лук с чесноком, зирой и перцем в топлёном масле до золотистого цвета.\nДобавьте разобранное мясо и жарьте ещё десять минут до румяных краёв. Подавайте с рисом.","source":"UniTools"},{"id":"ut-zurbian","name":"Зурбиан","country":"Йемен","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":150,"baseServings":6,"portionNutrition":{"k":780,"p":44,"f":34,"c":78},"details":[{"name":"Баранина","quantity":1.2,"unit":"kg","note":"на кости"},{"name":"Рис басмати","quantity":600,"unit":"g","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Йогурт","quantity":300,"unit":"ml","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Смесь хавайдж","quantity":2,"unit":"tbsp","note":""},{"name":"Кардамон стручки","quantity":6,"unit":"piece","note":""},{"name":"Изюм","quantity":80,"unit":"g","note":""},{"name":"Топлёное масло","quantity":100,"unit":"g","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замаринуйте баранину в йогурте с хавайджем и солью на два часа.\nПромойте рис до прозрачной воды и замочите на тридцать минут.\nОбжарьте лук в топлёном масле до тёмно-золотого цвета и отложите половину.\nОбжарьте мясо с оставшимся луком, добавьте помидоры и кардамон и тушите час.\nОбжарьте картофель кружками до румяной корки на отдельной сковороде.\nОтварите рис в подсоленной воде семь минут до полуготовности и откиньте.\nСоберите слоями мясо, рис, картофель и изюм, полейте шафраном полосами и запекайте под крышкой тридцать минут.","source":"UniTools"},{"id":"ut-fahsa","name":"Фахса","country":"Йемен","category":"main","diets":[],"slots":["lunch","dinner"],"time":160,"baseServings":5,"portionNutrition":{"k":620,"p":48,"f":34,"c":30},"details":[{"name":"Баранина","quantity":1,"unit":"kg","note":"мякоть и немного кости"},{"name":"Пажитник молотый","quantity":60,"unit":"g","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":6,"unit":"clove","note":""},{"name":"Зелёный острый перец","quantity":3,"unit":"piece","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Смесь хавайдж","quantity":1,"unit":"tbsp","note":""},{"name":"Лимон","quantity":1,"unit":"piece","note":""},{"name":"Лепёшки","quantity":5,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Залейте молотый пажитник холодной водой и оставьте на шесть часов, дважды сменив воду.\nОтварите баранину с луком и солью полтора часа до мягкости, сохранив бульон.\nРазберите мясо на мелкие куски и верните в процеженный бульон.\nРастолките чеснок, чили и кинзу в пасту сахавик в ступке.\nДобавьте помидоры, хавайдж и половину пасты в рагу и уварите до густоты.\nСлейте воду с пажитника и взбейте его венчиком с ложкой холодной воды в белую пену.\nРазлейте рагу в раскалённые миски, выложите пену сверху и подайте кипящим с лепёшками.","source":"UniTools"},{"id":"ut-kuwaiti-jireesh","name":"Кувейтский гриш","country":"Кувейт","category":"main","diets":[],"slots":["lunch","dinner"],"time":155,"baseServings":6,"portionNutrition":{"k":680,"p":42,"f":26,"c":72},"details":[{"name":"Дроблёная пшеница","quantity":500,"unit":"g","note":""},{"name":"Курица","quantity":1.2,"unit":"kg","note":"кусками"},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Томатная паста","quantity":3,"unit":"tbsp","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Смесь бахарат","quantity":2,"unit":"tbsp","note":""},{"name":"Сушёный лайм лууми","quantity":2,"unit":"piece","note":""},{"name":"Топлёное масло","quantity":100,"unit":"g","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Промойте дроблёную пшеницу и замочите в холодной воде на час.\nОбжарьте две луковицы в топлёном масле до мягкости и добавьте бахарат.\nОбжарьте курицу с луком, добавьте помидоры, томатную пасту, корицу и проколотый лууми.\nЗалейте двумя литрами воды, посолите и варите сорок минут до мягкости курицы.\nВыньте курицу, всыпьте пшеницу в бульон и варите час на слабом огне.\nРазомните кашу толкушкой, пока зерно не распадётся в однородную массу.\nОбжарьте оставшийся лук до тёмно-коричневого цвета, выложите кашу с курицей и полейте луком с маслом.","source":"UniTools"},{"id":"ut-kuwaiti-darabeel","name":"Дарабиль","country":"Кувейт","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":120,"baseServings":12,"portionNutrition":{"k":380,"p":7,"f":12,"c":62},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Молоко тёплое","quantity":250,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":8,"unit":"g","note":""},{"name":"Сахар","quantity":60,"unit":"g","note":""},{"name":"Сливочное масло","quantity":120,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Финиковая паста","quantity":400,"unit":"g","note":""},{"name":"Кардамон молотый","quantity":2,"unit":"tsp","note":""},{"name":"Шафран","quantity":1,"unit":"pinch","note":""},{"name":"Кунжут","quantity":40,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Разведите дрожжи с сахаром в тёплом молоке и оставьте на десять минут до пены.\nЗамочите шафран в ложке горячей воды и замесите тесто с мукой, яйцом, половиной масла и кардамоном.\nДайте тесту подойти в тепле час, пока оно не удвоится.\nРазогрейте финиковую пасту с оставшимся маслом и кардамоном до мягкости.\nРаскатайте тесто в прямоугольник толщиной в полсантиметра и намажьте финиковой пастой.\nСверните тугим рулетом и нарежьте кружками толщиной в два сантиметра.\nРазложите срезом вверх, дайте расстояться двадцать минут и пеките при 180 °C двадцать пять минут.","source":"UniTools"},{"id":"ut-rechta","name":"Решта","country":"Алжир","category":"main","diets":[],"slots":["lunch","dinner"],"time":170,"baseServings":6,"portionNutrition":{"k":720,"p":42,"f":26,"c":82},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Вода","quantity":280,"unit":"ml","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Курица","quantity":1.4,"unit":"kg","note":"кусками"},{"name":"Репа","quantity":500,"unit":"g","note":""},{"name":"Нут","quantity":200,"unit":"g","note":"замоченный"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Белый перец","quantity":2,"unit":"tsp","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, воды, ложки масла и соли и вымешивайте пятнадцать минут.\nРаскатайте тесто в тонкий лист и нарежьте лапшой шириной в два миллиметра.\nРазложите лапшу на полотенце, присыпьте мукой и подсушите двадцать минут.\nОтварите курицу с луком, нутом, корицей и белым перцем в двух литрах воды сорок минут.\nДобавьте репу дольками и варите ещё двадцать минут до мягкости.\nПропарьте лапшу над бульоном пятнадцать минут, снимите, сбрызните маслом и перемешайте.\nПовторите пропаривание дважды, выложите лапшу горкой, сверху курицу и репу и залейте бульоном.","source":"UniTools"},{"id":"ut-makroud","name":"Макруд","country":"Алжир","category":"dessert","diets":["vegetarian","vegan"],"slots":["snack"],"time":105,"baseServings":14,"portionNutrition":{"k":420,"p":5,"f":16,"c":66},"details":[{"name":"Манная крупа","quantity":600,"unit":"g","note":"средняя"},{"name":"Оливковое масло","quantity":180,"unit":"ml","note":""},{"name":"Вода тёплая","quantity":180,"unit":"ml","note":""},{"name":"Финики","quantity":500,"unit":"g","note":"без косточек"},{"name":"Корица молотая","quantity":2,"unit":"tsp","note":""},{"name":"Цедра апельсина","quantity":1,"unit":"piece","note":""},{"name":"Апельсиновая вода","quantity":40,"unit":"ml","note":""},{"name":"Мёд","quantity":500,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":700,"unit":"ml","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Перетрите манную крупу с оливковым маслом и солью руками, пока она не станет влажной насквозь.\nОставьте смесь на полчаса, чтобы крупа впитала масло и набухла.\nДобавляйте тёплую воду с апельсиновой водой понемногу, собирая тесто без вымешивания.\nРаспарьте финики над паром и растолките с корицей и цедрой в однородную пасту.\nРаскатайте тесто в полосу, положите жгут финиковой пасты по центру и закройте краями.\nПрижмите полосу и нарежьте наискось ромбами шириной в четыре сантиметра.\nОбжарьте во фритюре при 170 °C до золотистого цвета и опустите горячими в холодный мёд на пять минут.","source":"UniTools"},{"id":"ut-gurasa","name":"Гураса","country":"Судан","category":"bread","diets":["vegetarian","vegan"],"slots":["breakfast","snack"],"time":110,"baseServings":6,"portionNutrition":{"k":320,"p":9,"f":7,"c":56},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода тёплая","quantity":550,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":7,"unit":"g","note":""},{"name":"Сахар","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Разведите дрожжи с сахаром в тёплой воде и оставьте на десять минут до пены.\nВсыпьте муку с солью и размешайте венчиком до гладкого жидкого теста без комков.\nВлейте масло и вымешайте ещё минуту, пока тесто не станет глянцевым.\nНакройте и оставьте в тепле на час, пока по поверхности не пойдут пузыри.\nРазогрейте сухую сковороду на среднем огне и вылейте половник теста.\nНакройте крышкой и жарьте пять минут, пока верх не схватится и не станет матовым.\nСнимите, не переворачивая, и складывайте стопкой под полотенце.","source":"UniTools"},{"id":"ut-salata-aswad","name":"Салата асвад","country":"Судан","category":"salad","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":50,"baseServings":5,"portionNutrition":{"k":380,"p":10,"f":30,"c":18},"details":[{"name":"Баклажаны","quantity":800,"unit":"g","note":""},{"name":"Арахисовая паста","quantity":150,"unit":"g","note":"без сахара"},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Помидоры","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Острый перец","quantity":1,"unit":"piece","note":""},{"name":"Масло для жарки","quantity":200,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте баклажаны кубиками, посолите и оставьте на двадцать минут, чтобы вышла горечь.\nОбсушите кубики бумажным полотенцем — мокрые будут стрелять в масле.\nОбжарьте баклажаны порциями до тёмно-коричневой корки и выложите на бумагу.\nРастолките чеснок с солью в ступке до пасты.\nРазведите арахисовую пасту лимонным соком, чесноком и водой до консистенции сметаны.\nНарежьте помидоры, лук и чили мелко и смешайте с остывшими баклажанами.\nЗалейте арахисовой заправкой, перемешайте и дайте постоять пятнадцать минут.","source":"UniTools"},{"id":"ut-mchuzi-wa-samaki","name":"Мчузи ва самаки","country":"Танзания","category":"main","diets":["pescatarian","gluten-free"],"slots":["lunch","dinner"],"time":60,"baseServings":5,"portionNutrition":{"k":520,"p":44,"f":30,"c":18},"details":[{"name":"Белая рыба","quantity":1,"unit":"kg","note":"стейками"},{"name":"Кокосовое молоко","quantity":600,"unit":"ml","note":""},{"name":"Тамариндовая паста","quantity":3,"unit":"tbsp","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":3,"unit":"piece","note":""},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Имбирь","quantity":30,"unit":"g","note":""},{"name":"Карри-порошок","quantity":2,"unit":"tbsp","note":""},{"name":"Острый перец","quantity":2,"unit":"piece","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Натрите стейки рыбы солью и половиной карри-порошка и оставьте на пятнадцать минут.\nОбжарьте рыбу по две минуты с каждой стороны до корки и снимите на тарелку.\nОбжарьте лук в той же сковороде до мягкости, добавьте чеснок и имбирь.\nВсыпьте оставшийся карри-порошок и прогрейте минуту, пока не пойдёт аромат.\nДобавьте помидоры и чили и уварите до густой основы без лишней жидкости.\nВлейте кокосовое молоко с тамариндом и прогрейте, не доводя до кипения.\nВерните рыбу в соус, потомите пять минут и подайте с рисом и кинзой.","source":"UniTools"},{"id":"ut-vitumbua","name":"Витумбуа","country":"Танзания","category":"breakfast","diets":["vegetarian","vegan","gluten-free"],"slots":["breakfast"],"time":70,"baseServings":8,"portionNutrition":{"k":320,"p":5,"f":12,"c":48},"details":[{"name":"Рис","quantity":400,"unit":"g","note":"замоченный на ночь"},{"name":"Кокосовое молоко","quantity":300,"unit":"ml","note":""},{"name":"Сахар","quantity":120,"unit":"g","note":""},{"name":"Сухие дрожжи","quantity":5,"unit":"g","note":""},{"name":"Кардамон молотый","quantity":1,"unit":"tsp","note":""},{"name":"Кокосовая стружка","quantity":60,"unit":"g","note":""},{"name":"Растительное масло","quantity":120,"unit":"ml","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Слейте воду с замоченного риса и перемелите его с кокосовым молоком в гладкое жидкое тесто.\nВмешайте дрожжи, сахар, кардамон, соль и кокосовую стружку.\nОставьте тесто бродить четыре часа в тепле, пока оно не покроется пузырями.\nРазмешайте тесто и проверьте густоту: оно должно литься лентой, а не падать комом.\nРазогрейте сковороду с лунками и смажьте каждую маслом с помощью кисти.\nНаполните лунки на три четверти и пеките три минуты, пока края не схватятся.\nПереверните оладьи шпажкой и допеките ещё три минуты до румяного шара.","source":"UniTools"},{"id":"ut-eru","name":"Эру","country":"Камерун","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":120,"baseServings":6,"portionNutrition":{"k":620,"p":42,"f":42,"c":14},"details":[{"name":"Лист эру","quantity":400,"unit":"g","note":"или шпинат"},{"name":"Водяной лист","quantity":800,"unit":"g","note":"или мангольд"},{"name":"Красное пальмовое масло","quantity":150,"unit":"ml","note":""},{"name":"Говядина","quantity":500,"unit":"g","note":""},{"name":"Рубец","quantity":300,"unit":"g","note":""},{"name":"Сушёная рыба","quantity":150,"unit":"g","note":""},{"name":"Молотые сушёные креветки","quantity":50,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Острый перец","quantity":2,"unit":"piece","note":""},{"name":"Бульонный кубик","quantity":2,"unit":"piece","note":""},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Отварите говядину и рубец с луком и бульонным кубиком час до мягкости.\nЗамочите сушёную рыбу в горячей воде на двадцать минут и разберите, удалив кости.\nНарежьте лист эру предельно тонко, собирая его в тугой рулет перед резкой.\nПромойте водяной лист и нарежьте крупно — он всё равно осядет при варке.\nВыложите водяной лист в кастрюлю с мясом и дайте ему осесть, отдав сок.\nДобавьте эру, рыбу, креветки и чили и тушите двадцать минут под крышкой.\nВлейте пальмовое масло, перемешайте и потомите ещё десять минут без крышки.","source":"UniTools"},{"id":"ut-koki-corn","name":"Коки","country":"Камерун","category":"main","diets":["vegetarian","vegan","gluten-free"],"slots":["lunch","dinner"],"time":190,"baseServings":6,"portionNutrition":{"k":520,"p":20,"f":32,"c":42},"details":[{"name":"Чёрноглазая фасоль","quantity":500,"unit":"g","note":""},{"name":"Красное пальмовое масло","quantity":200,"unit":"ml","note":""},{"name":"Острый перец","quantity":2,"unit":"piece","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Шпинат","quantity":200,"unit":"g","note":"по желанию"},{"name":"Молотые сушёные креветки","quantity":40,"unit":"g","note":"по желанию"},{"name":"Банановые листья","quantity":6,"unit":"piece","note":""},{"name":"Вода тёплая","quantity":400,"unit":"ml","note":""},{"name":"Соль","quantity":2,"unit":"tsp","note":""}],"steps":"Замочите фасоль на четыре часа, затем перетрите руками, чтобы сошла кожура.\nПромойте фасоль несколько раз, сливая всплывшую кожуру, до чистых белых зёрен.\nПеремелите фасоль с луком и чили в густую пасту, добавляя воду по ложке.\nВзбивайте массу руками или лопаткой десять минут, пока она не станет светлее и воздушнее.\nНагрейте пальмовое масло до тёплого и вмешайте в массу до ровного оранжевого цвета.\nПрогрейте банановые листья над огнём до эластичности и выложите на них массу с зеленью.\nЗаверните свёртки, перевяжите и варите на пару полтора часа до плотности.","source":"UniTools"},{"id":"ut-kleftiko","name":"Клефтико","country":"Кипр","category":"main","diets":["gluten-free"],"slots":["lunch","dinner"],"time":330,"baseServings":6,"portionNutrition":{"k":780,"p":52,"f":48,"c":34},"details":[{"name":"Баранья лопатка","quantity":2,"unit":"kg","note":"на кости"},{"name":"Картофель","quantity":1,"unit":"kg","note":""},{"name":"Чеснок","quantity":10,"unit":"clove","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Орегано сушёный","quantity":2,"unit":"tbsp","note":""},{"name":"Корица палочка","quantity":1,"unit":"piece","note":""},{"name":"Лавровый лист","quantity":3,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":100,"unit":"ml","note":""},{"name":"Халуми","quantity":200,"unit":"g","note":"по желанию"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Сделайте в баранине глубокие надрезы и вложите в каждый дольку чеснока.\nНатрите мясо солью, перцем, орегано, оливковым маслом и соком лимона.\nОставьте баранину мариноваться в холодильнике не меньше четырёх часов.\nНарежьте картофель крупными дольками и уложите на дно глиняной посуды.\nПоложите мясо на картофель, добавьте лавровый лист, корицу и половинки лимона.\nЗакройте крышкой и запечатайте стык полосой теста или двойной фольгой.\nЗапекайте при 160 °C пять часов, не открывая, и дайте постоять двадцать минут.","source":"UniTools"},{"id":"ut-koupepia","name":"Купепья","country":"Кипр","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":6,"portionNutrition":{"k":520,"p":28,"f":28,"c":40},"details":[{"name":"Виноградные листья","quantity":400,"unit":"g","note":"консервированные или свежие"},{"name":"Свиной фарш","quantity":400,"unit":"g","note":""},{"name":"Говяжий фарш","quantity":300,"unit":"g","note":""},{"name":"Рис круглозёрный","quantity":200,"unit":"g","note":"сырой"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Помидоры","quantity":4,"unit":"piece","note":"тёртые"},{"name":"Корица молотая","quantity":2,"unit":"tsp","note":""},{"name":"Сушёная мята","quantity":1,"unit":"tbsp","note":""},{"name":"Петрушка","quantity":40,"unit":"g","note":""},{"name":"Лимон","quantity":2,"unit":"piece","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обдайте виноградные листья кипятком на минуту и разложите на полотенце.\nСмешайте оба фарша с сырым рисом, тёртым луком, помидорами и зеленью.\nВмешайте корицу, мяту, соль, перец и половину оливкового масла.\nПоложите ложку начинки на лист, подверните бока и сверните плотным цилиндром.\nВыстелите дно кастрюли рваными листьями, чтобы свёртки не пригорели.\nУложите свёртки плотными слоями швом вниз и прижмите тарелкой.\nЗалейте водой с лимонным соком и маслом и варите на слабом огне час под крышкой.","source":"UniTools"},{"id":"ut-lampuki-pie","name":"Пирог с лампукой","country":"Мальта","category":"main","diets":["pescatarian"],"slots":["lunch","dinner"],"time":130,"baseServings":8,"portionNutrition":{"k":680,"p":36,"f":38,"c":48},"details":[{"name":"Корифена или дорада","quantity":1.2,"unit":"kg","note":"стейками"},{"name":"Песочное тесто","quantity":800,"unit":"g","note":""},{"name":"Шпинат","quantity":500,"unit":"g","note":""},{"name":"Цветная капуста","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Оливки","quantity":120,"unit":"g","note":""},{"name":"Каперсы","quantity":50,"unit":"g","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Изюм","quantity":60,"unit":"g","note":""},{"name":"Грецкие орехи","quantity":60,"unit":"g","note":""},{"name":"Оливковое масло","quantity":80,"unit":"ml","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":"для смазки"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обжарьте стейки рыбы по три минуты с каждой стороны и остудите.\nСнимите мясо с костей, тщательно выбрав все мелкие кости.\nОбжарьте лук, добавьте цветную капусту соцветиями и потомите десять минут.\nДобавьте шпинат, томатную пасту, оливки, каперсы, изюм и орехи и уварите досуха.\nПолностью остудите начинку и осторожно вмешайте в неё рыбу кусками.\nВыстелите форму тестом, выложите начинку и накройте вторым пластом, защипнув края.\nСмажьте яйцом, сделайте прорези и пеките при 190 °C сорок пять минут до золотой корки.","source":"UniTools"},{"id":"ut-imqaret","name":"Имарет","country":"Мальта","category":"dessert","diets":["vegetarian","vegan"],"slots":["snack"],"time":110,"baseServings":12,"portionNutrition":{"k":420,"p":5,"f":18,"c":62},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Маргарин или сало","quantity":180,"unit":"g","note":""},{"name":"Вода холодная","quantity":120,"unit":"ml","note":""},{"name":"Финики","quantity":600,"unit":"g","note":"без косточек"},{"name":"Анис","quantity":2,"unit":"tsp","note":""},{"name":"Цедра апельсина","quantity":1,"unit":"piece","note":""},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Анисовый ликёр","quantity":40,"unit":"ml","note":""},{"name":"Масло для фритюра","quantity":800,"unit":"ml","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Изрубите финики ножом и сложите в сотейник с цедрой, анисом и ликёром.\nВарите начинку на слабом огне двадцать минут до густой однородной пасты.\nПолностью остудите начинку — тёплая порвёт тесто при заворачивании.\nПорубите маргарин в муку с солью до состояния крошки и соберите тесто на холодной воде.\nРаскатайте тесто в длинную полосу шириной в двенадцать сантиметров.\nВыложите финиковый жгут по центру, закройте краями и прижмите шов.\nНарежьте наискось ромбами и обжарьте при 180 °C по две минуты с каждой стороны.","source":"UniTools"},{"id":"ut-fergese","name":"Фергесе","country":"Албания","category":"main","diets":["vegetarian"],"slots":["lunch","dinner"],"time":65,"baseServings":4,"portionNutrition":{"k":420,"p":22,"f":28,"c":18},"details":[{"name":"Зелёный сладкий перец","quantity":600,"unit":"g","note":""},{"name":"Помидоры","quantity":400,"unit":"g","note":""},{"name":"Творожный сыр джиза","quantity":350,"unit":"g","note":""},{"name":"Брынза","quantity":150,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Чеснок","quantity":3,"unit":"clove","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Мука","quantity":1,"unit":"tbsp","note":""},{"name":"Острый перец","quantity":1,"unit":"piece","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Обожгите перцы на открытом огне или под грилем до чёрной кожуры.\nСложите горячие перцы в пакет на десять минут и снимите кожуру.\nОбжарьте лук с чесноком в масле до мягкости и всыпьте ложку муки.\nДобавьте нарезанные помидоры и уварите до густой основы без жидкости.\nНарежьте очищенные перцы полосами и вмешайте в томатную основу.\nРазомните творожный сыр с брынзой вилкой и вмешайте в горячую массу.\nПереложите в глиняную сковороду и запекайте при 200 °C двадцать минут до пузырей.","source":"UniTools"},{"id":"ut-ballokume","name":"Баллокуме","country":"Албания","category":"dessert","diets":["vegetarian","gluten-free"],"slots":["snack"],"time":75,"baseServings":14,"portionNutrition":{"k":380,"p":4,"f":18,"c":52},"details":[{"name":"Кукурузная мука","quantity":600,"unit":"g","note":"крупного помола"},{"name":"Сливочное масло","quantity":300,"unit":"g","note":"мягкое"},{"name":"Сахар","quantity":400,"unit":"g","note":""},{"name":"Желтки","quantity":6,"unit":"piece","note":""},{"name":"Сода","quantity":1,"unit":"tsp","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"pinch","note":""}],"steps":"Взбивайте мягкое масло с сахаром деревянной ложкой двадцать минут до пышной светлой массы.\nВводите желтки по одному, продолжая взбивать в том же направлении.\nДобавьте ваниль, соль и соду и взбейте ещё пять минут.\nВсыпайте кукурузную муку понемногу, вымешивая до плотного, но пластичного теста.\nДайте тесту постоять пятнадцать минут, чтобы мука впитала влагу.\nСформуйте шары размером с грецкий орех и разложите на пергаменте с большим отступом.\nПеките при 170 °C двадцать минут до бледно-золотого края и остудите на противне.","source":"UniTools"},{"id":"ut-sarmale-moldovenesti","name":"Молдавские сармале","country":"Молдова","category":"main","diets":[],"slots":["lunch","dinner"],"time":270,"baseServings":8,"portionNutrition":{"k":520,"p":28,"f":30,"c":32},"details":[{"name":"Квашеная капуста кочаном","quantity":1.5,"unit":"kg","note":""},{"name":"Свиной фарш","quantity":700,"unit":"g","note":""},{"name":"Рис","quantity":150,"unit":"g","note":"сырой"},{"name":"Копчёные рёбра","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Томатный сок","quantity":500,"unit":"ml","note":""},{"name":"Укроп сушёный","quantity":2,"unit":"tbsp","note":""},{"name":"Чабрец","quantity":1,"unit":"tbsp","note":""},{"name":"Растительное масло","quantity":80,"unit":"ml","note":""},{"name":"Сметана","quantity":250,"unit":"ml","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Разберите кочан на листья и срежьте толстые прожилки у основания каждого.\nОбжарьте лук в масле до золотистого цвета и полностью остудите.\nСмешайте фарш с сырым рисом, луком, укропом, чабрецом, солью и перцем.\nРазрежьте крупные листья пополам и заворачивайте свёртки размером с большой палец.\nВыложите на дно казана обрезки листьев и куски копчёных рёбер.\nУложите сармале плотными кругами, перекладывая рёбрами каждый второй слой.\nЗалейте томатным соком с водой, накройте рваными листьями и томите при 150 °C три часа.","source":"UniTools"},{"id":"ut-mucenici","name":"Мученичи","country":"Молдова","category":"dessert","diets":["vegetarian"],"slots":["snack"],"time":125,"baseServings":12,"portionNutrition":{"k":420,"p":9,"f":16,"c":60},"details":[{"name":"Мука","quantity":600,"unit":"g","note":""},{"name":"Молоко тёплое","quantity":280,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сахар","quantity":100,"unit":"g","note":""},{"name":"Сливочное масло","quantity":100,"unit":"g","note":""},{"name":"Яйца","quantity":2,"unit":"piece","note":""},{"name":"Мёд","quantity":200,"unit":"g","note":""},{"name":"Грецкие орехи","quantity":200,"unit":"g","note":"молотые"},{"name":"Цедра лимона","quantity":1,"unit":"piece","note":""},{"name":"Ваниль","quantity":1,"unit":"tsp","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""}],"steps":"Разведите дрожжи с ложкой сахара в тёплом молоке и оставьте до пены.\nЗамесите тесто из муки, опары, яиц, сахара, цедры, ванили, соли и мягкого масла.\nДайте подойти в тепле час с четвертью, пока тесто не удвоится.\nРазделите тесто на двенадцать частей и раскатайте каждую в жгут длиной сорок сантиметров.\nСверните жгут восьмёркой, соединив концы, и уложите на противень.\nДайте расстояться тридцать минут и пеките при 180 °C двадцать минут до румяности.\nСмажьте горячие мученичи мёдом и обильно посыпьте молотыми орехами.","source":"UniTools"},{"id":"ut-kuurdak","name":"Куурдак","country":"Кыргызстан","category":"main","diets":[],"slots":["lunch","dinner"],"time":80,"baseServings":5,"portionNutrition":{"k":780,"p":44,"f":54,"c":28},"details":[{"name":"Баранина","quantity":1,"unit":"kg","note":"мякоть и субпродукты"},{"name":"Курдючный жир","quantity":200,"unit":"g","note":""},{"name":"Лук","quantity":4,"unit":"piece","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Зира","quantity":1,"unit":"tbsp","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Лепёшки","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Нарежьте курдючный жир кубиками и вытопите в казане до золотых шкварок.\nВыньте шкварки шумовкой и отложите — их вернут в самом конце.\nНарежьте мясо кусками с грецкий орех и обжарьте порциями до тёмной корки.\nВерните всё мясо в казан, посолите, добавьте зиру и накройте на пятнадцать минут.\nДобавьте лук крупными полукольцами и жарьте, пока он не станет прозрачным.\nПоложите картофель крупными кусками и жарьте ещё двадцать минут под крышкой.\nВерните шкварки, добавьте чеснок и кинзу и подайте прямо из казана с лепёшкой.","source":"UniTools"},{"id":"ut-boorsok","name":"Боорсок","country":"Кыргызстан","category":"bread","diets":["vegetarian"],"slots":["breakfast","snack"],"time":120,"baseServings":10,"portionNutrition":{"k":320,"p":7,"f":14,"c":42},"details":[{"name":"Мука","quantity":700,"unit":"g","note":""},{"name":"Молоко тёплое","quantity":350,"unit":"ml","note":""},{"name":"Сухие дрожжи","quantity":10,"unit":"g","note":""},{"name":"Сахар","quantity":40,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Сливочное масло","quantity":60,"unit":"g","note":""},{"name":"Масло для фритюра","quantity":900,"unit":"ml","note":""},{"name":"Соль","quantity":1,"unit":"tbsp","note":""}],"steps":"Разведите дрожжи с сахаром в тёплом молоке и оставьте на пятнадцать минут до пены.\nЗамесите мягкое тесто из муки, опары, яйца, растопленного масла и соли.\nДайте подойти в тепле час, пока тесто не удвоится в объёме.\nОбомните тесто и раскатайте пласт толщиной ровно в сантиметр.\nНарежьте ромбами со стороной в четыре сантиметра и дайте им отдохнуть двадцать минут.\nРазогрейте масло до 180 °C и опускайте ромбы небольшими партиями.\nЖарьте по полторы минуты с каждой стороны, переворачивая шумовкой, до золотистых шаров.","source":"UniTools"},{"id":"ut-tushbera","name":"Тушбера","country":"Таджикистан","category":"soup","diets":[],"slots":["lunch","dinner"],"time":140,"baseServings":5,"portionNutrition":{"k":620,"p":32,"f":30,"c":54},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Яйцо","quantity":1,"unit":"piece","note":""},{"name":"Вода","quantity":200,"unit":"ml","note":""},{"name":"Баранина","quantity":500,"unit":"g","note":"мякоть"},{"name":"Курдючный жир","quantity":100,"unit":"g","note":""},{"name":"Лук","quantity":3,"unit":"piece","note":""},{"name":"Бараний бульон","quantity":2,"unit":"l","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Катык или сметана","quantity":200,"unit":"ml","note":""},{"name":"Зира","quantity":1,"unit":"tsp","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите крутое тесто из муки, яйца, воды и соли и вымешивайте пятнадцать минут.\nНакройте тесто и оставьте отдыхать сорок минут — так оно станет податливым.\nПорубите баранину и курдючный жир ножом в мелкую крошку.\nСмешайте мясо с мелко нарезанным луком, зирой, солью и перцем.\nРаскатайте тесто до просвечивания и вырежьте кружки диаметром пять сантиметров.\nСлепите пельмени, соединив края и сведя два угла вместе в кольцо.\nОтварите в кипящем бульоне восемь минут и подайте в чашке с катыком и кинзой.","source":"UniTools"},{"id":"ut-chakka","name":"Чакка","country":"Таджикистан","category":"snack","diets":["vegetarian"],"slots":["snack"],"time":25,"baseServings":6,"portionNutrition":{"k":220,"p":12,"f":14,"c":10},"details":[{"name":"Катык или жирный кефир","quantity":1.5,"unit":"l","note":""},{"name":"Кинза","quantity":50,"unit":"g","note":""},{"name":"Укроп","quantity":40,"unit":"g","note":""},{"name":"Райхон","quantity":30,"unit":"g","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Зелёный лук","quantity":50,"unit":"g","note":""},{"name":"Растительное масло","quantity":40,"unit":"ml","note":""},{"name":"Лепёшки","quantity":4,"unit":"piece","note":"к подаче"},{"name":"Соль","quantity":null,"unit":"toTaste","note":""}],"steps":"Выстелите дуршлаг плотной тканью в два слоя и вылейте в него катык.\nСвяжите концы ткани узлом и подвесьте над миской в холодном месте.\nОставьте стекать сутки, пока масса не станет плотной, как мягкий творог.\nРастолките чеснок с щепотью соли в ступке до однородной пасты.\nПорубите кинзу, укроп, райхон и зелёный лук как можно мельче.\nВмешайте зелень и чеснок в откинутую массу лопаткой, не растирая.\nПосолите, разровняйте в миске, сделайте ложкой углубление и налейте в него масло.","source":"UniTools"},{"id":"ut-khuushuur","name":"Хуушуур","country":"Монголия","category":"snack","diets":[],"slots":["snack"],"time":105,"baseServings":6,"portionNutrition":{"k":620,"p":28,"f":34,"c":52},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода","quantity":220,"unit":"ml","note":""},{"name":"Баранина","quantity":600,"unit":"g","note":"жирная"},{"name":"Лук","quantity":2,"unit":"piece","note":""},{"name":"Чеснок","quantity":4,"unit":"clove","note":""},{"name":"Бульон или вода","quantity":150,"unit":"ml","note":""},{"name":"Капуста","quantity":150,"unit":"g","note":"по желанию"},{"name":"Масло для жарки","quantity":500,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите пресное тесто из муки, воды и соли и вымешивайте десять минут до гладкости.\nНакройте тесто и оставьте отдыхать тридцать минут.\nПорубите баранину ножом мелко, вместе с жиром, и смешайте с луком и чесноком.\nВлейте бульон в фарш и вымешайте до жидковатой, но не текучей массы.\nРазделите тесто на шарики и раскатайте каждый в круг диаметром двенадцать сантиметров.\nПоложите начинку на половину, сложите пополам и защипните край плотно и ровно.\nОбжарьте в масле слоем в сантиметр по три минуты с каждой стороны до пузырчатой корки.","source":"UniTools"},{"id":"ut-suutei-tsai","name":"Сутэй цай","country":"Монголия","category":"drink","diets":["vegetarian"],"slots":[],"time":30,"baseServings":6,"portionNutrition":{"k":140,"p":5,"f":9,"c":8},"details":[{"name":"Зелёный чай","quantity":20,"unit":"g","note":"лучше прессованный"},{"name":"Вода","quantity":1,"unit":"l","note":""},{"name":"Молоко","quantity":700,"unit":"ml","note":""},{"name":"Сливочное масло","quantity":40,"unit":"g","note":""},{"name":"Соль","quantity":1,"unit":"tsp","note":""},{"name":"Мука обжаренная","quantity":2,"unit":"tbsp","note":"по желанию"}],"steps":"Раскрошите прессованный чай и залейте его литром холодной воды в кастрюле.\nДоведите до кипения и варите пять минут, пока настой не станет тёмным.\nВлейте молоко и снова доведите до кипения, следя, чтобы не убежало.\nПосолите и варите ещё пять минут на слабом огне.\nЧерпайте чай половником и лейте обратно с высоты десяток раз.\nДобавьте сливочное масло и размешайте до полного растворения.\nПроцедите в пиалы и подавайте горячим, при желании с обжаренной мукой.","source":"UniTools"},{"id":"ut-ashak","name":"Ашак","country":"Афганистан","category":"main","diets":[],"slots":["lunch","dinner"],"time":130,"baseServings":5,"portionNutrition":{"k":620,"p":32,"f":28,"c":58},"details":[{"name":"Мука","quantity":400,"unit":"g","note":""},{"name":"Вода","quantity":180,"unit":"ml","note":""},{"name":"Зелёный лук","quantity":500,"unit":"g","note":""},{"name":"Говяжий фарш","quantity":400,"unit":"g","note":""},{"name":"Лук","quantity":1,"unit":"piece","note":""},{"name":"Йогурт","quantity":500,"unit":"ml","note":"густой"},{"name":"Чеснок","quantity":5,"unit":"clove","note":""},{"name":"Томатная паста","quantity":2,"unit":"tbsp","note":""},{"name":"Сушёная мята","quantity":2,"unit":"tbsp","note":""},{"name":"Хлопья чили","quantity":1,"unit":"tsp","note":""},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите тесто из муки, воды и соли и оставьте отдыхать сорок минут под плёнкой.\nНарежьте зелёный лук очень мелко, посолите и отожмите через ткань.\nОбжарьте лук с фаршем, добавьте томатную пасту и потомите двадцать минут.\nВзбейте йогурт с растёртым чесноком и солью и оставьте при комнатной температуре.\nРаскатайте тесто тонко и вырежьте кружки диаметром восемь сантиметров.\nПоложите луковую начинку, сложите полумесяцем и защипните край плотно.\nОтварите пельмени пять минут, выложите на йогурт, полейте соусом и посыпьте мятой с чили.","source":"UniTools"},{"id":"ut-bolani","name":"Болани","country":"Афганистан","category":"snack","diets":["vegetarian","vegan"],"slots":["snack"],"time":80,"baseServings":6,"portionNutrition":{"k":420,"p":10,"f":12,"c":68},"details":[{"name":"Мука","quantity":500,"unit":"g","note":""},{"name":"Вода тёплая","quantity":280,"unit":"ml","note":""},{"name":"Картофель","quantity":600,"unit":"g","note":""},{"name":"Зелёный лук","quantity":200,"unit":"g","note":""},{"name":"Кинза","quantity":40,"unit":"g","note":""},{"name":"Хлопья чили","quantity":1,"unit":"tsp","note":""},{"name":"Йогурт с чесноком","quantity":250,"unit":"ml","note":"к подаче"},{"name":"Растительное масло","quantity":60,"unit":"ml","note":""},{"name":"Соль и перец","quantity":null,"unit":"toTaste","note":""}],"steps":"Замесите мягкое тесто из муки, тёплой воды, ложки масла и соли.\nНакройте тесто и оставьте отдыхать тридцать минут.\nОтварите картофель до мягкости, слейте и разомните в пюре без молока.\nВмешайте в пюре зелёный лук, кинзу, чили, соль и перец.\nРазделите тесто на шесть частей и раскатайте каждую в тонкий круг.\nРазложите начинку тонким слоем на половину круга и накройте второй половиной, прижав край.\nЖарьте на сковороде, смазанной кистью, по четыре минуты с каждой стороны до пятен.","source":"UniTools"}];if(typeof module==='object'&&module.exports)module.exports=recipes;root.UNVRSLWorldRecipes=recipes;})(typeof window!=='undefined'?window:globalThis);
